INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (439, 372, 9, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2025-07-19', '<p><br></p>', '<p><br></p>', '<p><br></p>', '2025-06-19', '2026-06-19', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (442, 372, 9, 9, 'Asrori Masduki', 'Survey', 'Completed', 'complete', 'Taboneo Anchorage, Indonesia', '2025-06-17', '2025-07-19', '<p>During the survey, we found that the vessel is in satisfactory condition except :</p><p>UT Thickness Report was found not available on board ( had been provided)</p><p>Bollard without SWL marking (had been rectified)</p><p>Watertight doors were found without Open/ Close marking (had been rectified)</p><p><br></p>', '<p class="14F9EAC799584AFFBAB9133F3550B3BB" style="margin-left:1.6pt;text-align:njustify"><span lang="EN-SG" style="font-size:10.0pt;font-family:" arial="" narrow",sans-serif;="" mso-bidi-font-family:calibri;mso-bidi-theme-font:minor-latin"="">The survey wasncarried out on 17 June 2025, whilst she was anchored at Taboneo Anchorage, South Kalimantan â Indonesia. The vessel was operated to carry Loader and Dozer for STS cargo at Taboneo Anchorage only.&nbsp;</span></p><p class="14F9EAC799584AFFBAB9133F3550B3BB" style="margin-left:1.6pt;text-align:njustify"><span lang="EN-SG" style="font-size: 10pt; font-family: " arial="" narrow",="" sans-serif;"="">The vessel is a LCT (Landing Craft Tank) and was provided with Deck cargo. The vessel dimension is 46.82 m x 9.15 x 3.00n(m), was built in </span><span lang="EN-GB" style="font-size: 10pt; font-family: " arial="" narrow",="" sans-serif;"="">Galangan Kapal Tunas Harapan, Samarinda</span><span lang="EN-SG" style="font-size: 10pt; font-family: " arial="" narrow",="" sans-serif;"=""> in 2006, Port ofnRegistry of Samarinda, and under the Class of Biro Klasifikasi Indonesia (BKI). The vessel wasnpowered by 2 units Main Engine Caterpillar 3406 TA @ 410 HP x 2,100 Rpm and 3nunits Auxiliary Engine Mitsubishi 4 D 33 @&nbsp;135 HP.</span></p><p class="14F9EAC799584AFFBAB9133F3550B3BB" style="margin-left:1.6pt;text-align:njustify"><span style="font-family: " arial="" narrow",="" sans-serif;="" font-size:="" 10pt;"="">The Hull wasnfound in satisfactory condition, draft and plimsoll marks were found legible, Mainndeck, Fore and aft Deck plates were found in satisfactory condition. The Deck cargo was covered with wooden sheathing and full of cargo on board (Dozer and Loaders).&nbsp;</span></p><p class="14F9EAC799584AFFBAB9133F3550B3BB" style="margin-left:0cm;text-align:njustify"><span style="font-family: " arial="" narrow",="" sans-serif;="" font-size:="" 10pt;"="">ThenSuperstructure was found in satisfactory condition.</span></p><p class="14F9EAC799584AFFBAB9133F3550B3BB" style="margin-left:0cm;text-align:njustify"><span style="font-family: " arial="" narrow",="" sans-serif;="" font-size:="" 10pt;"="">The Navigationnand communication are in satisfactory condition.</span></p><p class="14F9EAC799584AFFBAB9133F3550B3BB" style="margin-left:0cm;text-align:njustify"><span style="font-family: " arial="" narrow",="" sans-serif;="" font-size:="" 10pt;"="">The Engine room was found clean and tidy, with sufficient lighting. The Main Engine,nAuxiliary Engines, and steering equipment were found in satisfactory condition.nBilge E/R was found reasonably.&nbsp;&nbsp;</span></p><p class="14F9EAC799584AFFBAB9133F3550B3BB" style="text-align:justify"><span style="font-family: " arial="" narrow",="" sans-serif;="" font-size:="" 10pt;"="">The Internal structure of Ballast tanks was inspected and found slightly rusty but in satisfactory condition. Several Ballast tanks were used as Fresh Water and/ or Void Tanks.</span></p><p class="14F9EAC799584AFFBAB9133F3550B3BB" style="text-align:justify"><span style="font-family: " arial="" narrow",="" sans-serif;="" font-size:="" 10pt;"="">Safety Equipment wasnfound in sufficient and satisfactory quantities. Hose test of Fire Hydrant hasnalso been carried out with satisfactory results.&nbsp;</span></p><p class="14F9EAC799584AFFBAB9133F3550B3BB" style="margin-left:0cm;text-align:njustify"><span style="font-family: " arial="" narrow",="" sans-serif;="" font-size:="" 10pt;"="">The crew wasnfound well-knowledge about the vessel and how to maintain the vessel and herncargo. The shipboard management was found in good order and well recorded.</span></p><p class="14F9EAC799584AFFBAB9133F3550B3BB" style="margin-left:0cm;text-align:njustify"><span style="font-family: " arial="" narrow",="" sans-serif;="" font-size:="" 10pt;"="">During thensurvey, the Master provided documents of the vessel i.e : Statutory,nClass Certificates but the Latest UT Steel Thickness Measurement Report was found notnavailable on board.</span></p>', '<p>Generally, the vessel structure is in satisfactory condition.&nbsp;</p>', '2025-06-19', '2026-06-19', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
