INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (472, 384, 3, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2025-12-19', NULL, NULL, NULL, '2025-11-19', '2026-11-19', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (473, 385, 13, 9, 'Wahono Eko P', 'Survey', 'Completed', 'complete', 'Tegal', '2025-12-19', '2025-12-19', '<p>1. MANNING</p><p>Lack of certificates onboard may affect verification of crew qualifications and compliance with manning requirements.<br></p><p>2. MAINTENANCE AND DOCUMENTATION</p><p>Limited PMS reminders and unavailability of statutory certificates may affect tracking of overdue maintenance and regulatory compliance.<br></p><p>3. SHIPâS HULL AND DECKS</p><p>- Corrosion, coating defects, and damaged ballast tank anodes may affect structural integrity and corrosion protection.</p><p>- Missing or defective floaters on vents and air/sounding pipes may compromise operational readiness and safety.</p><p>- Incomplete maintenance records for lifting appliances may limit verification of operational condition.</p><p>4. MACHINERY SPACES</p><p>- Missing calibration and lubricating oil analysis records may affect monitoring of engine performance and reliability.</p><p>- Absence of bilge water level alarms/sensors may pose a potential safety risk.</p><p>- Exhaust temperature and leakage verification not performed, condition of engines could not be fully assessed due to docking.</p><p>5. STERN TUBE AND PROPELLER</p><p>Stern tube seals and propeller condition could not be verified, may affect propulsion safety and operational readiness.</p><p>6. STEERING GEAR</p><p>Missing records of steering gear synchronization tests may affect verification of steering system readiness.</p><p>7. SAFETY</p><p>Absence of smoke detector and emergency fire pump test records may affect verification of safety system readiness.</p><p>8. BRIDGE, NAVIGATION, AND COMMUNICATION</p><p>No immediate concern.</p><p>9. CARGO SPACE INSPECTION</p><p>- Corrosion and coating breakdown in cargo hold steel structures may affect structural integrity.</p><p>- Bilge wells and suction tests not verified, may impact cargo hold bilge system reliability.</p>', '<p>The vessel was generally found to be in satisfactory condition with respect to hull, deck, machinery, cargo holds, safety equipment, and bridge/navigation systems. Certain inspections and verifications could not be carried out due to the vessel being in docking or documents being held by the shipâs agent. Minor corrosion, coating defects, and deficiencies in maintenance records were noted but did not indicate immediate operational or safety concerns.<br></p>', '<p>The vessel was inspected and found to be in generally satisfactory condition, with hull, machinery, safety systems, bridge equipment, and cargo spaces operational and records maintained or available. Minor corrosion, coating defects, damaged ballast tank anodes, and incomplete maintenance records were noted, while certain verifications, such as exhaust temperatures, engine leakages, bilge wells, stern tube seals, and propeller condition, could not be performed due to docking, and some certificates were held by the shipâs agent. These observations represent surveyor concerns that may affect operational readiness and compliance, and follow-up inspections and submission of pending documentation are recommended.<br></p>', '2025-11-19', '2026-11-19', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (474, 386, 3, 9, NULL, 'Survey', 'Completed', 'complete', NULL, NULL, '2025-12-19', NULL, NULL, NULL, '2025-11-19', '2026-11-19', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (475, 387, 9, 9, 'Sofran Reynaldi Akbar', 'Survey', 'Completed', 'complete', 'Jetty Dok Dua Satu Nusantara, Tanjung Priok, North Jakarta - Indonesia', '2025-10-02', '2026-01-16', '<p>Referring to the findings above, we hope that they will be repaired &amp; fitted immediately to ensure smooth ship operations and reduce things that could harm the crew and ship during the voyage.</p>', '<p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">Thensurvey was carried out on 02 October 2025, whilst she was moored at Jetty PT.nDock Dua Satu Nusantara, Tj. Priok, North Jakarta - Indonesia for completion of docking repair.<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">&nbsp;</span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">Thenvessel is a General Cargo vessel with 2 Cargo holds with the dimension 81.50 xn15.00 x 9.65 (m), was built in Kurushima Dockyard Co. Ltd â Japan in 1984, Portnof Registry Jakarta, Flag Indonesia and under Class of Biro KlasifikasinIndonesia.<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">&nbsp;</span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">Thenvessel was powered by 1 unit Main Engine Hansin Diesel 2,000 HP, 2 unitsnAuxiliary Engine Yanmar 4 Stroke / S165 L-T &amp; 1 unit Auxiliary EnginenMitsubishi 4 Stroke / 10DC11<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">&nbsp;</span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">ThenHull was found in satisfactory condition, draft and plimsoll marks were foundnlegible; Mostly main deck was found dirty &amp; messy condition with repair materials<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">&nbsp;</span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">ThenSuperstructure was found in satisfactory condition.<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">&nbsp;</span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">ThenNavigation and communications were found in satisfactory condition.<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">&nbsp;</span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">ThenMain Engine, the Auxiliary Engines and the steering equipment were found innsatisfactory condition except Engine room floor was found dirty with oil,nBilge E/R was found dirty with sludge and puddle of water &amp; not fitted highnlevel alarm.<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">&nbsp;</span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">&nbsp;As far as could be inspected, the FPT, APT,nWBT No. 2P &amp; 2S were in fair condition.<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">&nbsp;</span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">ThenSafety Equipment was found sufficient quantity and satisfactory</span><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">, except Emergency fire pump has not been tested due to electrical shore connection in unstable condition.<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">&nbsp;</span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"="">Thencrew was found well-knowledge about the vessel and how to maintain the vesselnand her cargo. The shipboard management was found in good order and wellnrecorded.</span></p><p class="MsoNormal" style="margin-bottom:0cm;margin-bottom:.0001pt;line-height:nnormal"><span lang="EN-SG" style="font-size:10.0pt;font-family:" roboto",serif"=""><br></span><span style="font-family: Roboto, serif; font-size: 10pt;">The SteelnThickness Measurement Report was found available on board and the maximum diminution of plating is still below 20%..</span></p>', 'The MV. SAHABAT SEJATI 8 vessel is requested to follow up and correct all findings listed in this report in accordance with applicable standards. A complete survey report, with details and photographs of the findings, has been submitted as an attachment.', '2025-12-17', '2026-12-17', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
