INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (508, 401, 3, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2025-10-27', NULL, NULL, NULL, '2025-09-27', '2026-09-27', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (509, 387, 9, 9, 'Sofran Reynaldi Akbar', 'Survey', 'Completed', 'complete', 'Jetty Dok Dua Satu Nusantara, Tanjung Priok, North Jakarta - Indonesia', '2025-10-02', '2026-07-26', '<p>Referring to the findings above, we hope that they will be repaired & fitted immediately to ensure smooth ship operations and reduce things that could harm the crew and ship during the voyage.</p>', '<p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">The survey was carried out on 02 October 2025, whilst she was moored at Jetty PT. Dock Dua Satu Nusantara, Tj. Priok, North Jakarta - Indonesia. During survey the ship finishing docking repair.<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">Â </span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">The vessel is a General Cargo vessel with 2 Cargo hold with dimension 81.50 m x 15.00 x 9.65 (m), was built in Kurushima Dockyard Co. Ltd â Japan in 1984, Port of Registry Jakarta, Flag Indonesia and under Class of Biro Klasifikasi Indonesia.<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">Â </span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">The vessel was powered by 1-unit Main Engine Hansin Diesel 2000HP, 2 units Auxiliary Engine Yanmar 4 Stroke / S165 L-T & 1 units Auxiliary Engine Mitsubishi 4 Stroke / 10DC11<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">Â </span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">The Hull was found in satisfactory condition, draft and plimsoll marks were found legible; Mostly main deck was found dirty & messy condition with remaining docking<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">Â </span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">The Superstructure was found in satisfactory condition.<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">Â </span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">The Navigation and communication in satisfactory condition.<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">Â </span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">The Main Engine, the Auxiliary Engines and the steering equipment were found in satisfactory condition. except, Engine room floor was found dirty with oily, Bilge E/R was found dirty with sludge and puddle of water & not fitted high level alarm.<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">Â </span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">Â As far as could be inspected, the FPT, APT, WBT No. 2P & 2S were in fair condition.<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">Â </span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">The Safety Equipment was found sufficient and satisfactory quantities, excepted Emergency fire pump not test due to electrical shore connection unstable<o:p></o:p></span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">Â </span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;">The crew was found well-knowledge about the vessel and how to maintained the vessel and her cargo. The shipboard management was found in good order and well recorded.</span></p><p class="MsoNormal" style="margin-bottom: 0.0001pt; line-height: normal;"><span lang="EN-SG" roboto",serif"="" style="font-size: 10pt;"><br></span><span style="font-family: Roboto, serif; font-size: 10pt;">Steel Thickness Measurement Report was found available on board.</span></p>', '<p>The MV. SAHABAT SEJATI 8 vessel is requested to follow up and correct all findings listed in this report in accordance with applicable standards. A complete survey report, with details and photographs of the findings, has been submitted as an attachment.</p>', '2026-06-26', '2027-06-26', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
