INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (594, 447, 3, 9, NULL, 'Survey', 'Completed', 'complete', NULL, NULL, '2025-12-27', NULL, NULL, NULL, '2025-11-27', '2026-11-27', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (595, 448, NULL, 9, NULL, 'Survey', 'Cancelled', 'draft', NULL, NULL, '2025-12-27', NULL, NULL, NULL, '2025-11-27', '2026-11-27', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
