INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (597, 450, 3, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2025-12-31', NULL, NULL, NULL, '2025-12-01', '2026-12-01', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (598, 451, 3, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-02-05', NULL, NULL, NULL, '2026-01-06', '2027-01-06', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (599, 452, 8, 9, 'FAJAR TRIHASTYANTO KUNCORO', 'Survey', 'Completed', 'complete', 'BIRINGKASSI ANCHORAGE, SOUTH SULAWESI - INDONESIA', '2026-01-31', '2026-01-06', '<p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Structural compliance with general marine industry standards</span></u></span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">SOPEP Locker was found obstructed with foreign materials</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Save-alls/ Drip tray was found not fitted on 1 of fuel air vent (P), LO air vents and sounding pipe</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Oil absorbents were found not available</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Ship''s name at stern was found faded</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Many doublers were found on Main deck</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">- Main deck was found rusty</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Top plate of Hatch coaming was found corroded</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Stanchions of Hatch coaming was found corroded</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Bulwark was found corroded</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Watertight door of Battery room was found corroded at lower side</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Watertight doors were found without Open/ Close marking</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Tank top was found rusty and cargo residue (not clean)</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Tween deck was found partly corroded</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Longitudinal stiffener on Port and Starboard side frames of Cargo hold was found heavy corroded and partly missing</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Several Web frames and Ordinary frames were found deformed</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Cargo hold bilges were found mud (not clean)</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Hatch covers were found rusty and partly corroded</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">- E</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">mergency generator was found in repair condition</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Bridge Management.<o:p></o:p></span></u></span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Implemented by shipâs crew but still can be improved.</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Navigational equipment</span></u></span><span style="font-weight: bolder;"><u><span lang="IN" style="font-size: 10pt; line-height: 20px;"><o:p></o:p></span></u></span></p><p class="MsoNormal" style="margin-left: 8.7pt; text-indent: -8.7pt; line-height: 21px;"><span lang="IN" style="font-size: 10pt; line-height: 20px;">&nbsp;&nbsp; The&nbsp;</span><span lang="EN-US" style="font-size: 10pt; line-height: 20px;">navigation and communication were&nbsp;</span><span lang="IN" style="font-size: 10pt; line-height: 20px;">found&nbsp;</span><span lang="EN-US" style="font-size: 10pt; line-height: 20px;">fitted</span><span lang="IN" style="font-size: 10pt; line-height: 20px;">&nbsp;on board</span><span lang="EN-US" style="font-size: 10pt; line-height: 20px;">&nbsp;and apparently in satisfactory condition. But Deviation card was found not available,&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">NTM/ BPI was found not supplied regularly, and&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Charts were found not updated as per latest NTM/ BPI.</span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">&nbsp;&nbsp;&nbsp;<u>Competent of Officers<o:p></o:p></u></span></span></p><p class="MsoNormal" style="text-indent: 7.1pt; line-height: 21px;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">The Officer and crew appeared to be competent; all certificates complied as per STCW standard.</span></p><p class="MsoNormal" style="text-indent: 7.1pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Interassociation of Officers and Crew<o:p></o:p></span></u></span></p><p></p><p class="MsoNormal"><span lang="EN-GB" style="font-size: 10pt;">&nbsp;&nbsp; All crew have good cooperation during the survey.</span></p>', '<p class="MsoHeader" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">The Wreck Removal &amp; Oil Pollution&nbsp;</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="line-height: 18px;">survey</span><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">&nbsp;of MV. âObelix</span><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">â was conducted on 31 January 2026, whilst she anchored at Biringkassi anchorage, South Sulawesi, Indonesia waiting for berthing schedule. During the survey, we were accompanied/ assisted by the Chief Officer, Chief Engineer and crew.</span><br></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">HULL</span><o:p></o:p></span></span></p><p class="MsoListParagraph" style="margin-left: 0cm; text-align: justify; line-height: 21px;"><span tahoma",sans-serif"="" style="line-height: 18px;">MV. Obelix is 41 years old vessel, t</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">he&nbsp;</span><span tahoma",sans-serif"="" style="line-height: 18px;">vessel</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="line-height: 18px;">&nbsp;was</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:en-gb"="" style="line-height: 18px;">&nbsp;</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">a</span><span tahoma",sans-serif"="" style="line-height: 18px;">&nbsp;single hull&nbsp;</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">steel</span><span tahoma",sans-serif"="" style="line-height: 18px;">&nbsp;General Cargo with dimension as per Ship particular is LOA = 71.41 m,&nbsp;</span><span style="line-height: 18px;">LPP = 67.00 m, B</span><span style="line-height: 18px;">&nbsp;</span><span style="line-height: 18px;">= 11.50 m, H = 6.80 m</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">, GT 1328 and NT 879.</span><span style="color: red; font-size: 14px;">&nbsp;</span><span style="font-size: 14px;">The Vessel was registered at Tanjung Priok and under Classification of Biro Klasifikasi Indonesia (BKI). The vessel&nbsp;</span></span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">was&nbsp;</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">built by Mategata Zosen Co,.Ltd, Japan</span><span style="color: red; font-size: 14px;">&nbsp;</span><span style="font-size: 14px;">in 1985.&nbsp;Reported, the vessel has a valid Class Certificate i.e: Hull &amp; Machinery</span></span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="line-height: 18px;">&nbsp;Class</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">&nbsp;Certificate, and Load Line Certificate as well as a Statutory Certificate.</span><span style="color: red; font-size: 14px;">&nbsp;</span></span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">The visible shell plating was found in good condition. But Ship''s name at stern was found faded.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">During the survey, we found that the&nbsp;</span><span style="font-size: 0.875rem;">Superstructure and accommodation space were found satisfactory.&nbsp;</span><span style="font-size: 0.875rem;">Main deck</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">&nbsp;was found&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">many doublers and&nbsp;</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">rusty.&nbsp;</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">Top plate and Stanchions of Hatch coaming were found corroded.&nbsp;</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">Bulwark was found corroded.&nbsp;</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">Watertight door of Battery room was found corroded at lower side and&nbsp;</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">Watertight doors were found without Open/ Close marking.</span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">CARGO HOLDS / COMPARTMENTS</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">The Vessel was fitted with 1 (one) Cargo Hold and equipped with 1 (one) unit Crawler crane at middle of cargo hold.&nbsp;</span><span style="font-size: 0.875rem; text-align: left; color: rgb(33, 37, 41);">Tween deck was found partly corroded.&nbsp;</span><span style="font-size: 0.875rem; text-align: left; color: rgb(33, 37, 41);">Longitudinal stiffener on Port and Starboard side frames of Cargo hold was found heavy corroded and partly missing.&nbsp;</span><span style="font-size: 0.875rem; text-align: left; color: rgb(33, 37, 41);">Several Web frames and Ordinary frames were found deformed</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">.&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Suction test has been carried out and found satisfactory, but&nbsp;</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">Cargo hold bilges were found mud (not clean).</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">&nbsp;The Cargo hold was fitted with Pontoon type&nbsp;</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">Hatch covers which found rusty and partly corroded.&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Hose test to the hatch covers has been carried out and were found no leakages to the cargo hold.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">NON-CARGO TANKS:</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">The&nbsp;</span><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">V</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">essel&nbsp;</span><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">fitted with 6 WBT (1 â 3 (P &amp; S)), Fore peak and After peak Tanks. The&nbsp;<span style="color: rgb(33, 37, 41); text-align: left;">Internal structures of WBT were found in fair condition</span>.&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Ballast tanks pressure test has been carried out and were found no leakages to the cargo hold.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">MACHINERY</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">The Vessel was equipped with 1 (one) unit of Hanshin Type 6 LUN 28-ARG with 1,300 HP x 375 Rpm and equipped with 1 (one) unit Auxiliary Engine Mitsubishi Type 6D22, 225 HP (on engine room), 1 (one) unit Auxiliary Engine with no data (in engine room),&nbsp;</span><span style="font-size: 0.875rem;">1 (one) unit Auxiliary Engine with no data (on steering gear room)</span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 0.875rem; line-height: 18px;">&nbsp;and 1</span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">&nbsp;(one) unit Emergency Generator (no data) on Aft Main deck which found in repair condition.</span><span style="color: red; font-size: 14px;">&nbsp;</span><span style="font-size: 14px;">The Engine Room was located in the aft area. Main Engine and Auxiliary Engine were reported in working order.&nbsp; &nbsp;</span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">POLLUTION</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Bunker manifolds and Fuel air vents were found in fair condition</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">. But&nbsp;</span><span style="font-size: 0.875rem; text-align: left; color: rgb(33, 37, 41);">Save-alls/ Drip tray was found not fitted on 1 of fuel air vent (P), LO air vents and sounding pipe.</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">&nbsp;</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">Scupper plugs were found available. </span><span style="font-size: 0.875rem; text-align: left; color: rgb(33, 37, 41);">SOPEP Locker was found obstructed with foreign materials</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">.&nbsp;</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">Oil absorbents</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">&nbsp;were found not available.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">NAVIGATION</span><o:p></o:p></span></span></p><p></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">Navigation and communication fitted on the Bridge such Gyro Compass, Magnetic Compass, Radar, AIS, Echo Sounder, GPS, VHF Radios etc. But Deviation card was found not available. Navigational Charts were sufficient for trading area but not updated as per last BPI and NTM / BPI was found supplied on board regularly. C</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">hangeover instructions for Emergency Steering were found posted/ displayed.</span></p>', '<p>The vessel was found in satisfactory structural condition but several items to be repaired/rectified.</p>', '2025-12-07', '2026-12-07', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (600, 354, 8, 9, 'FAJAR TRIHASTYANTO KUNCORO', 'Survey', 'Completed', 'complete', 'Tuban Anchorage, Tuban - Indonesia', '2026-01-02', '2025-12-31', '<p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Structural compliance with general marine industry standards</span></u></span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Bulwark was found corroded at forward area</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Starboard side main deck was found rusty</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Draft &amp; Plimsoll marks were found faded</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Change high deck/ tripping edges/ ladder was found not marked</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Aft mooring winches without save-alls</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Ship''s lifting appliances and gear maintenance record was found not available</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- FO &amp; LO air vent was found not fitted with save-alls/ drip tray</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Cargo hold bilge well was found fully with water</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Pontoon Hatch cover was found rusty</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Suction test has not been tested due to malfunction</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Air vent of WBT 1 below main deck was found leakage during overflow ballast test.</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><b style="font-size: 13.3333px; text-indent: -17.85pt;"><u>Engine Room</u></b></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px; text-indent: -17.85pt;">- Total running hours of ME since the last overhaul record was found not available.</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px; text-indent: -17.85pt;">- T</span><span style="font-size: 13.3333px; text-indent: -23.8px;">otal running hours of AE since the last overhaul record was found not available.</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px; text-indent: -23.8px;">- LO analysis record was found not available</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px; text-indent: -23.8px;">- Thermometer was found not available on engine room</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px; text-indent: -23.8px;">- Engine room bilges were found oily/ sludge</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px; text-indent: -23.8px;">- Engine room high level alarm bilges were found malfunction</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Last propeller shaft withdrawn a stern tube bearing inspected was found unknown</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Record of testing steering gear synchronization between steering gear room and the navigation room was found not available</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;"><b><u>LSA &amp; FFA</u></b></span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Smoke detector alarm test record was found not available</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Fire hydrant was found only 1-unit operational function</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Escape routes and assembly point on crew accommodation was found not available</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Emergency light on crew accommodation was found malfunction</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Bridge Management.<o:p></o:p></span></u></span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Implemented by shipâs crew but still can be improved.</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Navigational equipment</span></u></span><span style="font-weight: bolder;"><u><span lang="IN" style="font-size: 10pt; line-height: 20px;"><o:p></o:p></span></u></span></p><p class="MsoNormal" style="margin-left: 8.7pt; text-indent: -8.7pt; line-height: 21px;"><span lang="IN" style="font-size: 10pt; line-height: 20px;">&nbsp;&nbsp; The&nbsp;</span><span lang="EN-US" style="font-size: 10pt; line-height: 20px;">navigation and communication were&nbsp;</span><span lang="IN" style="font-size: 10pt; line-height: 20px;">found&nbsp;</span><span lang="EN-US" style="font-size: 10pt; line-height: 20px;">fitted</span><span lang="IN" style="font-size: 10pt; line-height: 20px;">&nbsp;on board</span><span lang="EN-US" style="font-size: 10pt; line-height: 20px;">&nbsp;and apparently in satisfactory condition. But Echo sounder was found malfunction, chart was found not updated as per latest BPI/NTM, Deviation card was found not available on board, and Passage planning was found not available and not recorded.</span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">&nbsp;&nbsp;&nbsp;<u>Competent of Officers<o:p></o:p></u></span></span></p><p class="MsoNormal" style="text-indent: 7.1pt; line-height: 21px;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">The Officer and crew appeared to be competent; all certificates complied as per STCW standard.</span></p><p class="MsoNormal" style="text-indent: 7.1pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Interassociation of Officers and Crew<o:p></o:p></span></u></span></p><p></p><p class="MsoNormal"><span lang="EN-GB" style="font-size: 10pt;">&nbsp;&nbsp; All crew have good cooperation during the survey, but Minimum Safe Manning Certificate was found not available on board</span></p>', '<p class="MsoHeader" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">The Hull &amp; Machinery&nbsp;</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">survey</span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">&nbsp;of MV. âAnugerah VIIIâ was conducted on 02 January 2026, whilst she anchored at Tuban anchorage, Tuban, Indonesia waiting for cargo loading operation. During the survey, we accompanied/ assisted by the Chief Officer, Chief Engineer and crew.</span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">HULL<o:p></o:p></span></span></p><p class="MsoListParagraph" style="margin-left: 0cm; text-align: justify; line-height: 21px;"><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">MV. Anugerah VIII is a 39 years old vessel, t</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">he&nbsp;</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">vessel</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">&nbsp;was</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:en-gb"="" style="font-size: 9pt; line-height: 18px;">&nbsp;</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">a</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">&nbsp;single hull double bottom&nbsp;</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">steel</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">&nbsp;General Cargo with dimension&nbsp;</span><span style="font-size: 9pt; line-height: 18px;">LPP = 56.50 m, B</span><span style="font-size: 9pt; line-height: 18px;">&nbsp;</span><span style="font-size: 9pt; line-height: 18px;">= 12.50 m</span><span style="font-size: 9pt; line-height: 18px;">&nbsp;</span><span style="font-size: 9pt; line-height: 18px;">H = 6.50 m</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">, GT 1,257 and NT 378.<span style="color: red;">&nbsp;</span>The Vessel was registered at Surabaya and under Classification of Biro Klasifikasi Indonesia (BKI). The vessel&nbsp;</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">was&nbsp;</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">built by Kochi Juko Co,.Ltd, Japan<span style="color: red;">&nbsp;</span>in 1987. Reported, the vessel has a valid Class Certificate i.e: Hull</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">&nbsp;Class</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">&nbsp;Certificate, Tonnage Certificate and Load Line Certificate as well as a Statutory Certificate.<span style="color: red;">&nbsp;</span></span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">The visible shell plating was found in satisfactory condition, but draft &amp; plimsoll mark was found faded and bulwark at forward area was found corroded.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">During the survey, we found that Main deck was found in satisfactory but rusty at starboard side area, Anchor &amp; Mooring Windlass was found in satisfactory condition, but Aft Mooring Winches was found without save-alls. &nbsp;Bollards, rollers, fairleads were found in satisfactory. The Superstructure and accommodation space were found satisfactory. Weathertight doors were found in satisfactory condition and fitted with rubber seal.&nbsp;</span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">CARGO HOLDS / COMPARTMENTS<o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">The Vessel was fitted with 1 (one) Cargo Hold and 1 (one) unit Crawler Crane at Forward of cargo hold. The internal structure and tank top were found in satisfactory condition. The Pontoon Hatch covers were found in rusty condition. The cargo hold bilge was found fully with water. Suction test of Bilge wells have not been tested due to malfunction. Air vent of WBT 1 below main deck was found leakage during overflow ballast test.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">NON-CARGO TANKS:<o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">The&nbsp;</span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">V</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">essel&nbsp;</span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">fitted with 6 WBT (1 â 3 (P &amp; S)), Fore peak and After peak Tanks. The internal structure of WBT was in satisfactory condition and fitted with zinc anode.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">MACHINERY<o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">The Vessel was equipped with 1 (one) unit of Hanshin Type 6 LU 32 G with 1,000 HP x 290 Rpm and equipped with 2 (two) units Auxiliary Engine i.e. Yanmar Type6 KFL @125 HP and 3 (Three) units Emergency</span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">&nbsp;Generator with no data on boat deck.<span style="color: red;">&nbsp;</span>The Engine Room was located in the aft area. Main Engine, Auxiliary Engines reported in working order. &nbsp;&nbsp;</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">POLLUTION<o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">SOPEP box with equipment was found available. FO &amp; LO Tank Air vents were found not fitted with save-alls.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">NAVIGATION<o:p></o:p></span></span></p><p></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">Navigation and communication fitted on the Bridge such Magnetic Compass, Radar, AIS, GPS, VHF Radios etc. Navigational Charts were sufficient for trading area but not updated as per last BPI. Echo sounder was found mal-function, Deviation card was found available.</span></p>', '<p>The vessel was found in satisfactory structural condition but several items to be repaired/rectified.&nbsp; Bridge equipment was found satisfactory but Echo sounder to be repaired, Crew and Ship Management are still can be improved. LSA &amp; FFA was found satisfactory but several items to be repaired/ rectified. Engine room was found in satisfactory condition, but some item to be provided and rectified.</p>', '2025-12-01', '2026-12-01', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (601, 374, 3, 9, NULL, 'Survey', 'Completed', 'complete', NULL, NULL, '2026-01-01', NULL, NULL, NULL, '2025-12-02', '2026-12-02', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (602, 453, 8, 9, 'FAJAR TRIHASTYANTO', 'Survey', 'Completed', 'complete', 'GRESIK ANCHORAGE', '2026-02-03', '2026-01-02', '<p class="MsoNormal" style="text-align:justify"><b><u><span lang="EN-GB">STRUCTURAL COMPLIANCE WITH GENERAL MARINEnINDUSTRY STANDARDS</span></u></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify">-&nbsp;SOPEP WAS FOUNDnINSUFFICIENT<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- BUNKER MANIFOLD WAS FOUND WITHnOBSTRUCTION MATERIAL<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- FO VENT WAS FOUND NOT MARKEDnWITH SERVED SPACE<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- LO &amp; FO VENTS, SOUNDINGnPIPES, AND AFT WINCH WERE FOUND WITHOUT SAVE ALLS<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- FORWARD WINCH SAVE ALLS WASnFOUND CORRODED<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- SCUPPER PLUG WAS FOUNDnUNAVAILABLE ON BOARD<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- OIL ABSORBENR WAS FOUNDnUNAVAILABLE ON BOARD<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- HULL WAS GENERALLY FOUND IN AnRUSTY CONDITION<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- DRAUGHT AND LOADLINES WEREnFOUND FADED<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- MAIN DECK WAS FOUND RUSTY<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- BULWARK WAS FOUND RUSTY ANDnPARTLY CORRODED<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- RAILING WAS FOUND PARTLYnMISSING<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- BOLLARD, ROLLER, &amp;nFAIRLEADS WERE FOUND WITHOUT SWL MARKING &amp; IN A RUSTY CONDITION<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- BOLLARD (STBD-FWD) WAS FOUNDnCORRODED<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- FORWARD &amp; AFT WINCHES WEREnFOUND RUSTY &amp; PARTLY CORRODED<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- COAMING STAY OF CH 1 &amp; 2nWERE FOUND RUSTY AND PARTLY CORRODED<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- WATERTIGHT DOORS WERE FOUNDnWITHOUT OPEN/CLOSE DIRECTION MARKING<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- FORWARD WATERTIGHT DOOR ACCESSnTO FORWARD STORE AND CH NO. 1 WAS FOUND CORRODED<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- CARGO HOLDS WERE FOUND RUSTY<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- TANKTOP OF CH NO. 1 WAS FOUNDnPARTLY CORRODED<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- CARGO HOLD BILGES WERE FOUNDnMUD (NOT CLEAN)<o:p></o:p></p><p>nnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnn</p><p class="MsoNormal" style="text-align:justify">- HATCH COVERS WERE FOUND RUSTY</p><p class="MsoNormal" style="text-align:justify"><b><u><span lang="EN-GB">BRIDGE MANAGEMENT.</span></u></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><span lang="EN-GB">IMPLEMENTED BY SHIPâS CREW BUT STILL CAN BEnIMPROVED.</span><o:p></o:p></p><p class="MsoNormal" style="text-align:justify">nnnn</p><p class="MsoNormal" style="text-align:justify"><b><u><span lang="EN-GB">NAVIGATIONAL EQUIPMENT</span></u></b></p><p class="MsoNormal" style="text-align:justify"><o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><span lang="IN">THE&nbsp;</span><span lang="EN-US">NAVIGATIONnAND COMMUNICATION WERE&nbsp;</span><span lang="IN">FOUND&nbsp;</span><span lang="EN-US">FITTED</span><span lang="IN">&nbsp;ON BOARD</span><span lang="EN-US">&nbsp;AND APPARENTLY IN SATISFACTORY CONDITION.nHOWEVER, THE ECHOSOUNDER WAS FOUND MALFUNCTION, THE DEVIATION CARD WAS NOT POSTED ON BRIDGE,&nbsp;</span>NTM/ BPI WAS NOT SUPPLIED REGULARLY,nAND&nbsp;CHARTS WERE NOT CORRECTED AS PER LATEST NTM/ BPI.</p><p class="MsoNormal" style="text-align:justify"><b><u><span lang="EN-GB">COMPETENT OF OFFICERS</span></u></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><span lang="EN-GB">THE OFFICER AND CREW APPEARED TO BE COMPETENT;nALL CERTIFICATES COMPLIED AS PER STCW STANDARD.</span><o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><b><u><span lang="EN-GB">INTERASSOCIATION OF OFFICERS AND CREW</span></u></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify">nnnnnn</p><p class="MsoNormal" style="text-align:justify"><span lang="EN-GB">ALL CREW HAVE GOOD COOPERATION DURING THEnSURVEY.</span><o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><o:p></o:p></p>', '<p class="MsoNormal" style="text-align:justify"><span lang="EN-US">The Wreck Removal &amp; Oil Pollution S</span><span lang="IN">urvey</span><span lang="EN-US">&nbsp;of MV. âSHINEIâ was conducted on 03nFebruary 2026, whilst she was anchored at Gresik anchorage, East Java,nIndonesia for waiting berthing schedule. During the survey, we werenaccompanied/ assisted by the Master, Chief Officer, Chief Engineer and Crew.</span><o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><b><span lang="EN-US">HULL</span></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify">MV. SHINEI is 39 years oldnvessel, t<span lang="IN">he&nbsp;</span>vessel<span lang="IN">&nbsp;was&nbsp;a</span>&nbsp;Steel Single Hull&nbsp;GeneralnCargo with dimension as per Ship particular is LOA = 81.35 m,&nbsp;LPP = 76.30nm, B&nbsp;= 12.20 m, H = 5.80 m, GT 1,605, NT 937, and 2,800 DWT.&nbsp;ThenVessel was registered at Tanjung Priok and under Classification of BironKlasifikasi Indonesia (BKI). The vessel&nbsp;<span lang="IN">was&nbsp;</span>built by MIURA SHIPBUILDING Co,. Ltd, in Japan&nbsp;in Junen1987.&nbsp;Reported, the vessel has a valid Class Certificate i.e: Hull &amp;nMachinery<span lang="IN">&nbsp;Class</span>&nbsp;Certificate,nand Load Line Certificate as well as a Statutory Certificate.&nbsp;<span lang="IN">The visible shell plating was found innRusty Condition and the Draught, &amp; Plimsol Mark were found faded.&nbsp;</span><o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><span lang="EN-US">During the survey, we found that the&nbsp;</span>Superstructurenand accommodation space were found satisfactory. The Main Deck was found Rusty.&nbsp;Topnplate and Stanchions of Hatch coaming / Coaming Stay were found rusty andnpartly corroded.&nbsp;Bulwarks were found partly corroded.&nbsp;Watertight Doornof Forward Store &amp; CH 1 Access was found corroded;&nbsp;Watertight doorsnwere found without Open/ Close marking. Anchor Winch were found rusty andnpartly corroded.&nbsp;<o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><b><span lang="EN-US">CARGO HOLDS / COMPARTMENTS</span></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><span lang="EN-US">The Vessel was fitted with 2 (two) Cargo Holdnand equipped with 1 (one) unit Crawler crane at middle of cargo hold</span>.&nbsp;ThenTanktop of CH No. 1 was found Partly Corroded to WBT 2 (P/S).&nbsp;The CargonHold was fitted by Pontoon Type Hatch Cover and Covered with Tarpaulins whichnfound rusty.&nbsp;Hose test to the hatch covers has been carried out and werenfound no leakages to the cargo hold.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><b><span lang="EN-US">NON-CARGO TANKS:</span></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><span lang="IN">The&nbsp;</span><span lang="EN-US">V</span><span lang="IN">essel&nbsp;</span><span lang="EN-US">fitted with 6 WBT (1 â 3 (P &amp; S)), Forenpeak and After peak Tanks. The&nbsp;Internal structures of WBT were found in rustynand possibly seriousness corrosion due to we found some contaminated oil in WBTnNo. 3 &amp; 4 and reported by crew that any bottom girder was broken before wenwere visit the vessel.&nbsp;</span>Ballast Pressure Test was not carried outndue to crew opened all of the manholes.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><b><span lang="EN-US">MACHINERY</span></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><span lang="EN-US">The Vessel was equipped with 1 (one) unit ofnHanshin Type 6 LUN 32-G with 900 HP x 280 Rpm and equipped with 2 (two) unitnAuxiliary Engine Yanmar Type 6-KFL, 2 x 145 HP (on engine room),&nbsp;andn1&nbsp;(one) unit Emergency Generator (no data) on &nbsp;steering gear room which found in repairncondition.&nbsp;The Engine Room was located in the aft area. Main Engine andnAuxiliary Engine were reported in working order.&nbsp; &nbsp;</span><o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><b><span lang="EN-US">POLLUTION</span></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify">Bunker manifolds and Fuel airnvents were found in fair condition. But&nbsp;Save-alls/ Drip tray was found notnfitted on FO, LO, Sounding Pipes and Aft Winch.&nbsp;Scupper plugs were found unavailable.&nbsp;SOPEPnLocker was found in insufficient.&nbsp;Oil absorbents&nbsp;were found notnavailable.</p><p class="MsoNormal" style="text-align:justify"><b><span lang="EN-US">NAVIGATION</span></b><o:p></o:p></p><p class="MsoHeader" style="text-align: justify; line-height: 21px;">nnnnnnnnnnnnnnnnnnnnnnnnnnnn</p><p class="MsoNormal" style="text-align:justify"><span lang="EN-US">Navigation and communication fitted on thenBridge such Gyro Compass, Magnetic Compass, Radar, AIS, GPS, VHF Radios etc. However,nEchosounder was found malfunction; Deviation card was found not posted onnbridge. Navigational Charts were sufficient for trading area but not correctednas per last BPI and NTM / BPI was found supplied on board regularly. C</span>hangeoverninstructions for Emergency Steering were found posted/ displayed.<o:p></o:p></p>', '<p class="MsoNormal" style="text-align:justify">THE VESSEL WAS FOUND IN FAIRnSTRUCTURAL CONDITION. HOWEVER, SEVERAL ITEMS NEED TO BE REPAIRED/RECTIFIED.<o:p></o:p></p>', '2025-12-03', '2026-12-03', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (603, 454, 8, 9, 'FAJAR TRIHASTYANTO KUNCORO', 'Survey', 'Completed', 'complete', 'SURABAYA ANCHORAGE, SURABAYA', '2026-01-14', '2026-01-02', '<p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Structural compliance with general marine industry standards</span></u></span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Classification Certificates were found expired</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><font color="#212529">-&nbsp;</font><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">UTM Report was found not available on board</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Plimsoll / Load line marks (P &amp; S) were found faded</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Forecastle deck plate at port side was found corroded</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Watertight doors were found without Open / Close marking</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Main Engine was found being overhauled</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Auxiliary Engine 1 &amp; 2 were found being overhauled</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Fuel air vent at starboard side was found not red painted</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Bunker manifold at port side and Fuel air vents were found not fitted with save-alls / drip tray</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Bridge Management.<o:p></o:p></span></u></span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Implemented by shipâs crew but still can be improved.</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Navigational equipment</span></u></span><span style="font-weight: bolder;"><u><span lang="IN" style="font-size: 10pt; line-height: 20px;"><o:p></o:p></span></u></span></p><p class="MsoNormal" style="margin-left: 8.7pt; text-indent: -8.7pt; line-height: 21px;"><span lang="IN" style="font-size: 10pt; line-height: 20px;">&nbsp;&nbsp; The&nbsp;</span><span lang="EN-US" style="font-size: 10pt; line-height: 20px;">navigation and communication were&nbsp;</span><span lang="IN" style="font-size: 10pt; line-height: 20px;">found&nbsp;</span><span lang="EN-US" style="font-size: 10pt; line-height: 20px;">fitted</span><span lang="IN" style="font-size: 10pt; line-height: 20px;">&nbsp;on board</span><span lang="EN-US" style="font-size: 10pt; line-height: 20px;">&nbsp;and apparently in satisfactory condition. But Echo sounder was found not available, NTM/ BPI was found not supplied on board, and Charts were found not updated as per latest NTM/ BPI</span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">&nbsp;&nbsp;&nbsp;<u>Competent of Officers<o:p></o:p></u></span></span></p><p class="MsoNormal" style="text-indent: 7.1pt; line-height: 21px;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">The Officer and crew appeared to be competent; all certificates complied as per STCW standard.</span></p><p class="MsoNormal" style="text-indent: 7.1pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Interassociation of Officers and Crew<o:p></o:p></span></u></span></p><p></p><p class="MsoNormal"><span lang="EN-GB" style="font-size: 10pt;">&nbsp;&nbsp; All crew have good cooperation during the survey.</span></p>', '<p class="MsoHeader" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 14px; line-height: 18px;">The Wreck Removal &amp; Oil Pollution&nbsp;</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="font-size: 14px; line-height: 18px;">survey</span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 14px; line-height: 18px;">&nbsp;of MT. âBerlian Selatanâ was conducted on 14 January 2026, whilst she anchored at Surabaya anchorage, Surabaya, Indonesia, waiting for completion of the Main Engine &amp; Auxiliary Engine overhaul. During the survey, we were accompanied/ assisted by the Chief Officer, Chief Engineer and, crew.</span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">HULL</span><o:p></o:p></span></span></p><p class="MsoListParagraph" style="margin-left: 0cm; text-align: justify; line-height: 21px;"><span tahoma",sans-serif"="" style="font-size: 14px; line-height: 18px;">MT. Berlian Selatan is 38 years old vessel, t</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 14px; line-height: 18px;">he&nbsp;</span><span tahoma",sans-serif"="" style="font-size: 14px; line-height: 18px;">vessel</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="font-size: 14px; line-height: 18px;">&nbsp;was</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:en-gb"="" style="font-size: 14px; line-height: 18px;">&nbsp;</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 14px; line-height: 18px;">a</span><span tahoma",sans-serif"="" style="font-size: 14px; line-height: 18px;">&nbsp;single hull&nbsp;</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 14px; line-height: 18px;">steel</span><span tahoma",sans-serif"="" style="font-size: 14px; line-height: 18px;">&nbsp;Oil Tanker with the dimension&nbsp;</span><span style="font-size: 14px; line-height: 18px;">LPP = 35 m, B</span><span style="font-size: 14px; line-height: 18px;">&nbsp;</span><span style="font-size: 14px; line-height: 18px;">= 7.30 m</span><span style="font-size: 14px; line-height: 18px;">&nbsp;</span><span style="font-size: 14px; line-height: 18px;">H = 3.1 m</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">, DWT 350, GT 228 and NT 90.</span><span style="color: red; font-size: 14px;">&nbsp;</span><span style="font-size: 14px;">The Vessel was registered at <span style="background-color: rgb(255, 255, 255);">Surabaya</span> and under the Classification of Biro Klasifikasi Indonesia (BKI). The vessel&nbsp;</span></span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 14px; line-height: 18px;">was&nbsp;</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">built by Yamakawa Shipbuilding Co,.Ltd, Japan</span><span style="color: red; font-size: 14px;">&nbsp;</span><span style="font-size: 14px;">in 1988. Reported, <span style="background-color: rgb(255, 255, 255);">the vessel Statutory and Class Certificate was provided, however the Class Certificates were found expired on 06 May 2025. Ship Safety Construction Certificate, Ship Safety Radio Certificate and Ship Safety Equipment Certificate expired on 07 October 2024</span></span></span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px; background-color: rgb(255, 255, 255);"><span style="font-size: 14px;">.</span><span style="color: red; font-size: 14px;">&nbsp;</span></span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 0.875rem; line-height: 18px;">Anti Fouling System Certificate expired on 29 October 2024. Inflatable Life Raft Certificate and Fire Protect &amp; Service expired on 22 April 2025. The visible shell plating was found in satisfactory condition, but Plimsoll / Load line marks (P &amp; S) were found faded.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 14px; line-height: 18px;">During the survey, we found that the Main deck was found in satisfactory condition, Anchor &amp; Mooring Windlass were found in satisfactory condition. The Superstructure and accommodation space were found satisfactory. Watertight doors were found without Open/ Close marking. The&nbsp;</span><span style="font-size: 0.875rem; text-align: left;">Forecastle deck plate at port side was found corroded.</span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">CARGO HOLDS / COMPARTMENTS</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">The Vessel was fitted with <span style="background-color: rgb(255, 255, 255);">8 (Eight) Cargo Tanks with (1 - 4 P &amp; S)</span>. The internal structure and tank top apparently in satisfactory condition.</span> The Oil Tight Hatch and rubber sealing of COT were found in satisfactory condition.<span lang="EN-US" tahoma",sans-serif"="" style="font-size: 14px; line-height: 18px;">&nbsp;</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">NON-CARGO TANKS:</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 14px; line-height: 18px;">The&nbsp;</span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 14px; line-height: 18px;">V</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 14px; line-height: 18px;">essel was&nbsp;</span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 14px; line-height: 18px;">fitted with Fore peak and After peak Tanks. The internal structure of Fore Peak and After peak tanks was found in satisfactory condition.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">MACHINERY</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 14px; line-height: 18px;">The Vessel was equipped with 1 (one) unit of Yanmar Type MF 24 NTD with <span style="background-color: rgb(255, 255, 255);">400 HP </span>x 370 Rpm and equipped with <span style="background-color: rgb(255, 255, 255);">1&nbsp;(one) unit Auxiliary Engine Yanmar Type 4 JHL-TN 26 HP, 1 (one) unit Auxiliary Engine with no data (at main deck) and&nbsp;</span></span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px; background-color: rgb(255, 255, 255);"><span style="font-size: 14px;">1 (one) unit Emergency Generator with no data (at Boat deck).</span><span style="color: red; font-size: 14px;">&nbsp;</span><span style="font-size: 14px;">The Engine Room was located in the aft area. Main Engine, All Auxiliary Engines were found in overhauled condition.</span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">POLLUTION</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 14px; line-height: 18px;">SOPEP, Scupper plugs and, Oil absorbents were found not available.&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Fuel air vent at starboard side was found not red painted.&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Bunker manifold at port side and Fuel air vents were found not fitted with save-alls/ drip tray.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">NAVIGATION</span><o:p></o:p></span></span></p><p></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 14px; line-height: 18px;">Navigation and communication were fitted on the Bridge, such as Gyro Compass, Radar, AIS, GPS, VHF Radios etc. Navigational Charts were sufficient for trading area but not updated as per last BPI. NTM / BPI was found not supplied on board regularly. Echo sounder was found not available.</span></p>', '<p>The vessel was found in satisfactory structural condition but several items to be repaired/rectified.&nbsp; Bridge equipment i.e. Echo sounder to be fitted, NTM/ BPI to be supplied and Charts to be updated. The Crew and Ship Management are still can be improved. Pollution prevention and equipment was found satisfactory but SOPEP, Scupper plugs, Oil absorbent to be provided.&nbsp;</p>', '2025-12-03', '2026-12-03', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (604, 354, NULL, 9, 'FAJAR TRIHASTYANTO', 'Survey', 'Completed', 'complete', 'TUBAN ANCHORAGE, EAST JAVA, INDONESIA', '2025-11-17', '2026-01-07', NULL, NULL, NULL, '2025-12-08', '2026-12-08', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (605, 455, 3, 9, NULL, 'Survey', 'Completed', 'complete', NULL, NULL, '2026-01-08', NULL, NULL, NULL, '2025-12-09', '2026-12-09', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (606, 20, 3, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-01-22', NULL, NULL, NULL, '2025-12-23', '2026-12-23', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (607, 458, 8, 9, 'FAJAR TRIHASTYANTO KUNCORO', 'Survey', 'Completed', 'complete', 'SURABAYA ANCHORAGE, SURABAYA', '2025-12-26', '2026-01-18', '<p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Structural compliance with general marine industry standards</span></u></span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Tween Deck was found partly dent / deformed</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Internal structure of WBT was found heavy corroded</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Bilge well cargo hold was found remaining water</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- Oil absorbent was found not available on board</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Bridge Management.<o:p></o:p></span></u></span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Implemented by shipâs crew but still can be improved.</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Navigational equipment</span></u></span><span style="font-weight: bolder;"><u><span lang="IN" style="font-size: 10pt; line-height: 20px;"><o:p></o:p></span></u></span></p><p class="MsoNormal" style="margin-left: 8.7pt; text-indent: -8.7pt; line-height: 21px;"><span lang="IN" style="font-size: 10pt; line-height: 20px;">&nbsp;&nbsp; The&nbsp;</span><span lang="EN-US" style="font-size: 10pt; line-height: 20px;">navigation and communication were&nbsp;</span><span lang="IN" style="font-size: 10pt; line-height: 20px;">found&nbsp;</span><span lang="EN-US" style="font-size: 10pt; line-height: 20px;">fitted</span><span lang="IN" style="font-size: 10pt; line-height: 20px;">&nbsp;on board</span><span lang="EN-US" style="font-size: 10pt; line-height: 20px;">&nbsp;and apparently in satisfactory condition.</span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">&nbsp;&nbsp;&nbsp;<u>Competent of Officers<o:p></o:p></u></span></span></p><p class="MsoNormal" style="text-indent: 7.1pt; line-height: 21px;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">The Officer and crew appeared to be competent; all certificates complied as per STCW standard.</span></p><p class="MsoNormal" style="text-indent: 7.1pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Interassociation of Officers and Crew<o:p></o:p></span></u></span></p><p></p><p class="MsoNormal"><span lang="EN-GB" style="font-size: 10pt;">&nbsp;&nbsp; All crew have good cooperation during the survey.</span></p>', '<p class="MsoHeader" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">The Wreck Removal &amp; Oil Pollution&nbsp;</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">survey</span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">&nbsp;of MV. âFortunerâ was conducted on 26 December 2025, whilst she anchored at Surabaya anchorage, Surabaya, Indonesia waiting for cargo loading operation. During the survey, we accompanied/ assisted by the Chief Officer, Chief Engineer and crew.</span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">HULL<o:p></o:p></span></span></p><p class="MsoListParagraph" style="margin-left: 0cm; text-align: justify; line-height: 21px;"><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">MV. Fortuner is a 35 years old vessel, t</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">he&nbsp;</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">vessel</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">&nbsp;was</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:en-gb"="" style="font-size: 9pt; line-height: 18px;">&nbsp;</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">a</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">&nbsp;single hull&nbsp;</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">steel</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">&nbsp;General Cargo with dimension&nbsp;</span><span style="font-size: 9pt; line-height: 18px;">LPP = 60.35 m, B</span><span style="font-size: 9pt; line-height: 18px;">&nbsp;</span><span style="font-size: 9pt; line-height: 18px;">= 12.50 m</span><span style="font-size: 9pt; line-height: 18px;">&nbsp;</span><span style="font-size: 9pt; line-height: 18px;">H = 6.50 m</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">, GT 1163 and NT 617.<span style="color: red;">&nbsp;</span>The Vessel was registered at Surabaya and under Classification of Biro Klasifikasi Indonesia (BKI). The vessel&nbsp;</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">was&nbsp;</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">built by Honda Shipbuilding Co,.Ltd, Japan<span style="color: red;">&nbsp;</span>in 1990. Reported, the vessel has a valid Class Certificate i.e: Hull</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">&nbsp;Class</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">&nbsp;Certificate, Tonnage Certificate and Load Line Certificate as well as a Statutory Certificate.<span style="color: red;">&nbsp;</span></span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">The visible shell plating was found in satisfactory condition</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">During the survey, we found that Main deck was found in satisfactory condition, Anchor &amp; Mooring Winches were found in satisfactory condition. &nbsp;Bollards, rollers, fairleads were found without SWL marking. The Superstructure and accommodation space were found satisfactory. Weathertight doors were found without Open/ Close marking.</span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">CARGO HOLDS / COMPARTMENTS<o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">The Vessel was fitted with 1 (one) Cargo Hold and 1 (one) unit Crawler Crane at Forward of cargo hold. The internal structure and tank top were found in satisfactory condition, but tween deck floor was found partly dent / deformed. The Hatch covers were found in satisfactory condition. The cargo hold bilge was found remaining water. Suction test of Bilge wells and tightness test of Hatch covers have been tested and found satisfactory.&nbsp;</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">NON-CARGO TANKS:<o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">The&nbsp;</span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">V</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="font-size: 9pt; line-height: 18px;">essel&nbsp;</span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">fitted with 6 WBT (1 â 3 (P &amp; S)), Fore peak and After peak Tanks. The internal structure of WBT was heavy corroded. Overflow test was carried out by the crew on next day and found in satisfactory condition.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">MACHINERY<o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">The Vessel was equipped with 1 (one) unit of Niigata Type 6 M 30 GT with 1,000 HP x 310 Rpm and equipped with 2 (two) units Auxiliary Engine i.e. Yanmar Type 6 CHL - HTN @120 HP and Yanmar Type 6 HAL - TN @120 HP (in Engine room) and 1 (one) unit&nbsp;</span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">Harbour Generator with no data.&nbsp;Also, 1 (one) unit Emergency Generator (no data) in Boat deck.<span style="color: red;">&nbsp;</span>The Engine Room was located in the aft area. Main Engine, Auxiliary Engines reported in working order. &nbsp;&nbsp;</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">POLLUTION<o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">SOPEP was found not complete but SOPEP equipment had been provided (Rectified), Scupper plugs were found available, but Oil Absorbent were found not available on board. FO Air vents, and winches were found fitted with save-alls.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">NAVIGATION<o:p></o:p></span></span></p><p></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;">Navigation and communication fitted on the Bridge such Magnetic Compass, Radar, AIS, Echo Sounder, GPS, VHF Radios etc. Navigational Charts were sufficient for trading area and updated as per last BPI.</span></p>', '<p>The vessel was found in satisfactory structural condition but several items to be repaired/rectified.&nbsp; Bridge equipment, Crew and Ship Management are still can be improved. Pollution prevention and equipment was found satisfactory but oil absorbent to be provided.&nbsp;</p>', '2025-12-19', '2026-12-19', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
