INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (609, 456, 3, NULL, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-19', '2026-12-18', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
