INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (611, 460, 3, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-02-05', NULL, NULL, NULL, '2026-01-06', '2027-01-06', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (612, 461, 8, 9, 'FAJAR TRIHASTYANTO KUNCORO', 'Survey', 'Completed', 'complete', 'GRESIK ANCHORAGE, GRESIK - INDONESIA', '2026-01-20', '2026-01-23', '<p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Structural compliance with general marine industry standards</span></u></span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;">- <font color="#212529">SOPEP Locker was found obstructed with foreign materials and SOPEP equipment not complete</font></span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-size: 13.3333px;"><font color="#212529">- Hydraulic operating handleÂ </font></span><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">Anchor & Mooring Windlass</span><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">Â and Aft Mooring WinchesÂ </span><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -17.85pt;">were found not fitted with save-alls</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">- FO & LO air vents and sounding pipes were found not fitted with save-alls</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">- Scupper plugs were found not available</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">- Oil absorbentsÂ </span><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">were found not available</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">- Hull coating was found faded and slight rusty</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">- Main deck was found mostly rusty</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">- Hatch coaming longitudinal stiffener were found corroded</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">- Bulwark at forward and aft area were found corroded</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">- Railing at flag deck was found partly missing</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">- Cargo hold access at fore deck was found heavy rusty</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">- Anchor &</span><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">Â Mooring Windlass, Hydraulic operating handle and Anchor chains were found rusty</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">- Watertight doors access to accommodation at P & S were found corroded</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">- Tank top cargo hold was found rusty, many doublers and dented at several places</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">- Cargo hold bilge wells were found cargo residue and not dry</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 13.3333px; text-indent: -23.8px;">- Suction test has not been tested due to end of suction pipe corroded</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Bridge Management.<o:p></o:p></span></u></span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Implemented by shipâs crew but still can be improved.</span></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Navigational equipment</span></u></span><span style="font-weight: bolder;"><u><span lang="IN" style="font-size: 10pt; line-height: 20px;"><o:p></o:p></span></u></span></p><p class="MsoNormal" style="margin-left: 8.7pt; text-indent: -8.7pt; line-height: 21px;"><span lang="IN" style="font-size: 10pt; line-height: 20px;">Â Â  TheÂ </span><span lang="EN-US" style="font-size: 10pt; line-height: 20px;">navigation and communication wereÂ </span><span lang="IN" style="font-size: 10pt; line-height: 20px;">foundÂ </span><span lang="EN-US" style="font-size: 10pt; line-height: 20px;">fitted</span><span lang="IN" style="font-size: 10pt; line-height: 20px;">Â on board</span><span lang="EN-US" style="font-size: 10pt; line-height: 20px;">Â and apparently in satisfactory condition, but NTM/ BPI was found not supplied on board and Charts were found not updated as per latestÂ </span><span style="font-size: 13.3333px; text-indent: -11.6px;">NTM/ BPI.</span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Â Â Â <u>Competent of Officers<o:p></o:p></u></span></span></p><p class="MsoNormal" style="text-indent: 7.1pt; line-height: 21px;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">The Officer and crew appeared to be competent; all certificates complied as per STCW standard.</span></p><p class="MsoNormal" style="text-indent: 7.1pt; line-height: 21px;"><span style="font-weight: bolder;"><u><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Interassociation of Officers and Crew<o:p></o:p></span></u></span></p><p></p><p class="MsoNormal"><span lang="EN-GB" style="font-size: 10pt;">Â Â  All crew have good cooperation during the survey.</span></p>', '<p class="MsoHeader" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">The Wreck Removal & Oil PollutionÂ </span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="line-height: 18px;">survey</span><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">Â of MV. âSurya Persadaâ was conducted on 20 January 2026, whilst she anchored at Gresik anchorage, Gresik, Indonesia waiting for cargo loading operation. During the survey, we were accompanied/ assisted by the Chief Officer, Chief Engineer and crew.</span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">HULL</span><o:p></o:p></span></span></p><p class="MsoListParagraph" style="margin-left: 0cm; text-align: justify; line-height: 21px;"><span tahoma",sans-serif"="" style="line-height: 18px;">MV. Surya Persada is 37 years old vessel, t</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">heÂ </span><span tahoma",sans-serif"="" style="line-height: 18px;">vessel</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="line-height: 18px;">Â was</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:en-gb"="" style="line-height: 18px;">Â </span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">a</span><span tahoma",sans-serif"="" style="line-height: 18px;">Â single hullÂ </span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">steel</span><span tahoma",sans-serif"="" style="line-height: 18px;">Â General Cargo with dimension LOA = 69.35 m,Â </span><span style="line-height: 18px;">LPP = 59.38 m, B</span><span style="line-height: 18px;">Â </span><span style="line-height: 18px;">= 12.50 m</span><span style="line-height: 18px;">Â </span><span style="line-height: 18px;">H =Â 6.25 m</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">, GT 1245 and NT 727.</span><span style="color: red; font-size: 14px;">Â </span><span style="font-size: 14px;">The Vessel was registered at Surabaya and under Classification of Biro Klasifikasi Indonesia (BKI). The vesselÂ </span></span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">wasÂ </span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">built by Masui Shipyard Co,.Ltd., Japan</span><span style="color: red; font-size: 14px;">Â </span><span style="font-size: 14px;">in 1989.Â Reported, the vessel has a valid Class Certificate i.e: Hull</span></span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="line-height: 18px;">Â Class</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">Â Certificate, Tonnage Certificate and Load Line Certificate as well as a Statutory Certificate.</span><span style="color: red; font-size: 14px;">Â </span></span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">The visible shell plating was found in satisfactory condition. But hull coating</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Â was found faded and slight rusty.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">During the survey, we found that the Superstructure and accommodation space were found satisfactory. ButÂ </span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Main deck was found mostly rusty. Hatch coaming longitudinal stiffener were found corroded. Bulwark at forward and aft area were found corroded. Railing at flag deck was found partly missing. Cargo hold access at fore deck was found heavy rusty. Anchor & Mooring Windlass, Hydraulic operating handle and Chains were found rusty.</span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">CARGO HOLDS / COMPARTMENTS</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">The Vessel was fitted with 1 (one) Cargo Hold and 2<span style="background-color: rgb(255, 255, 255);">Â (two) units Derrick</span> at Middle of cargo hold.Â </span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Internal structure of cargo hold was found in satisfactory condition, but t</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">ank top cargo hold was found rusty, many doublers, and dented at several places.Â </span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Bilge wells were found cargo residue and not dry, Suction test of bilge well has not been tested due to end of suction pipe corroded.Â </span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Hatch covers panel were found corroded andÂ </span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Hose test to Hatch covers has been carried out and were found no leakages to the cargo hold.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">NON-CARGO TANKS:</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">TheÂ </span><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">V</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">esselÂ </span><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">fitted with 6 WBT (1 â 3 (P & S)), Fore peak and After peak Tanks.Â <span style="color: rgb(33, 37, 41); text-align: left;">Internal structure of WBTÂ </span></span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">was found in satisfactory condition andÂ </span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Ballast tanks pressure test has been carried out and was found no leakages to the cargo hold.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">MACHINERY</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">The Vessel was equipped with 1 (one) unit of Yanmar Type MF33-STD1 with 1,000 HP x 240 Rpm and equipped with 2 (two) units Auxiliary Engine i.e. Yanmar Type 6 HAL-HTN with @160 HP 2 x 160 Rpm (in Engine room) andÂ </span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">2 (two) units Emerg<span style="background-color: rgb(255, 255, 255);">ency Generator (no data) in Steering gear room and Boat deck.</span></span><span style="color: red; font-size: 14px; background-color: rgb(255, 255, 255);">Â </span><span style="font-size: 14px;"><span style="background-color: rgb(255, 255, 255);">The Engine Room was located in the aft area. TheÂ Main Engine was found in progress to complete overhaul</span>, Auxiliary Engines reported in working order and<span style="background-color: rgb(255, 255, 255);"> Emergency generator on Boat deck was found in repair on shore.</span></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">POLLUTION</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="color: rgb(33, 37, 41); text-align: left;">Bunker Manifolds and Fuel air vents was found in satisfactory condition, but SOPEP Locker was found obstructed with foreign materials and SOPEP equipment not complete. </span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Hydraulic operating handle of Anchor & Mooring Windlass and Aft Mooring Winches</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Â </span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">were found not fitted with save-alls.Â </span><span style="font-size: 0.875rem; text-align: left; color: rgb(33, 37, 41);">FO & LO air vents and sounding pipesÂ </span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">were found not fitted with save-alls. Scupper plugs and Oil absorbent were found not available</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">NAVIGATION</span><o:p></o:p></span></span></p><p></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">Navigation and communication fitted on the Bridge such Gyro Compass, Magnetic Compass, Radar, AIS, Echo Sounder, GPS, VHF Radios etc. Navigational Charts were sufficient for trading area but not updated as per last BPI and NTM / BPI was found not supplied on board regularly.</span></p>', '<p>The vessel was found in satisfactory structural condition but several items to be repaired/rectified.Â  Bridge equipment was found satisfactory but NTM/ BPI to be supplied and Charts to be u<span style="background-color: rgb(255, 255, 255);">pdated</span><span style="font-size: 0.875rem;"><span style="background-color: rgb(255, 255, 255);">. The Crew and Ship Management are still can be improved. Pollution prevention and equipment was found satisfactory but SOPEP, Scupper plugs, Oil absorbents to be provided. Save-alls o</span>nÂ </span><span style="font-size: 0.875rem;">Hydraulic operating handle ofÂ </span><span style="font-size: 0.875rem;">Anchor & Mooring Windlass and Aft Mooring Winches</span><span style="font-size: 0.875rem;">, alsoÂ </span><span style="font-size: 0.875rem; color: rgb(33, 37, 41);">FO & LO air vents to be fitted.</span></p>', '2025-12-24', '2026-12-24', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
