INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (639, 476, 3, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-02-21', NULL, NULL, NULL, '2026-01-22', '2027-01-22', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
