INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (642, 479, 3, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-02-21', NULL, NULL, NULL, '2026-01-22', '2027-01-22', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (643, 480, 8, 9, 'Capt.Risanda Ajirogo', 'Survey', 'Completed', 'complete', 'Palembang Anchorage, Palembang, Indonesia', '2026-02-13', '2026-03-07', '<div class="prose dark:prose-invert inline leading-relaxed break-words min-w-0 [word-break:break-word] prose-strong:font-medium visRefresh2026Fonts:prose-strong:font-bold [&amp;_&gt;*:first-child]:mt-0 [&amp;_&gt;*:last-child]:mb-0"><p class="my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2">Concern is primarily focused on several <strong>critical</strong> structural and watertight integrity issues on hull, deck, cargo holds and hatch covers which, if not rectified promptly, may significantly increase the risk of cargo damage, water ingress and progressive structural deterioration.<span class="inline-flex" aria-label="Surveys" data-state="closed">â</span></p>n<ul class="marker:text-quiet list-disc">n<li class="py-0 my-0 prose-p:pt-0 prose-p:mb-2 prose-p:my-0 [&amp;&gt;p]:pt-0 [&amp;&gt;p]:mb-2 [&amp;&gt;p]:my-0">n<p class="my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2">Extensive rusting observed on external hull plating with major rust at several shell areas and rust stain around shipâs name, indicating coating breakdown and increased vulnerability to further wastage.</p>n</li>n<li class="py-0 my-0 prose-p:pt-0 prose-p:mb-2 prose-p:my-0 [&amp;&gt;p]:pt-0 [&amp;&gt;p]:mb-2 [&amp;&gt;p]:my-0">n<p class="my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2">Local heavy damage on halfâround steel fender port side about 2 m length may adversely affect hull protection and berthing safety, especially during alongside operations in confined ports.<span class="inline-flex" aria-label="Surveys" data-state="closed">â</span></p>n</li>n<li class="py-0 my-0 prose-p:pt-0 prose-p:mb-2 prose-p:my-0 [&amp;&gt;p]:pt-0 [&amp;&gt;p]:mb-2 [&amp;&gt;p]:my-0">n<p class="my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2">Internal forward peak tank structure shows heavy corrosion, cracking and deformation, raising concern on longâterm strength and watertight integrity of forward hull spaces under ballast and seagoing loads.&nbsp;<span class="inline-flex" aria-label="Surveys" data-state="closed">â</span></p></li></ul>n<ul class="marker:text-quiet list-disc">n<li class="py-0 my-0 prose-p:pt-0 prose-p:mb-2 prose-p:my-0 [&amp;&gt;p]:pt-0 [&amp;&gt;p]:mb-2 [&amp;&gt;p]:my-0">n<p class="my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2">Heavy corrosion on forward deck, forecastle store floor, winch foundations, Tâbollards, forward bulwark and several railing sections indicates advanced steel deterioration at critical mooring and working areas, increasing risk of local failure, unsafe working conditions and potential loss of mooring fittings under load.<span class="inline-flex" aria-label="Surveys" data-state="closed">â</span></p>n</li>n<li class="py-0 my-0 prose-p:pt-0 prose-p:mb-2 prose-p:my-0 [&amp;&gt;p]:pt-0 [&amp;&gt;p]:mb-2 [&amp;&gt;p]:my-0">n<p class="my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2">Watertight doors at aft and starboard poop deck and forecastle store found with heavy corrosion and local damage, which may compromise weathertight/watertight boundaries of accommodation and deckhouses in heavy weather or greenâsea conditions.<span class="inline-flex" aria-label="Surveys" data-state="closed">â</span></p></li></ul>n<ul class="marker:text-quiet list-disc">n<li class="py-0 my-0 prose-p:pt-0 prose-p:mb-2 prose-p:my-0 [&amp;&gt;p]:pt-0 [&amp;&gt;p]:mb-2 [&amp;&gt;p]:my-0">n<p class="my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2">Cargo holds, though structurally intact, are generally rusted with uncoated tank tops and poor coating characterized by extensive scaling and corrosion, increasing likelihood of steel wastage, cargo contamination and difficulty in proving âcargoâworthyâ condition to charterers and cargo interests.<span class="inline-flex" aria-label="Surveys" data-state="closed">â</span></p>n</li>n<li class="py-0 my-0 prose-p:pt-0 prose-p:mb-2 prose-p:my-0 [&amp;&gt;p]:pt-0 [&amp;&gt;p]:mb-2 [&amp;&gt;p]:my-0">n<p class="my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2">Cargo hold bilge fixed suction system not operational, with vessel relying on portable pump for bilge removal; this arrangement is considered unreliable during heavy weather or cargo damage incidents and may delay dewatering, directly elevating risk of cargo wetting and flooding of lower structures.</p></li></ul>n<ul class="marker:text-quiet list-disc">n<li class="py-0 my-0 prose-p:pt-0 prose-p:mb-2 prose-p:my-0 [&amp;&gt;p]:pt-0 [&amp;&gt;p]:mb-2 [&amp;&gt;p]:my-0">n<p class="my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2">Heavy corrosion on hatch pontoon structures and top areas of hatch coamings indicates deterioration at primary weathertight boundaries, with increased risk of local deformation, improper seating and potential water ingress during heavy weather, green seas on deck or heavy spray.<span style="font-size: 0.875rem;">â</span></p></li></ul></div>', '<p>MV CHUO NO 1, a 1988âbuilt Indonesianâflagged general cargo vessel of about 1,393 GRT and 2,300 DWT, classed with Biro Klasifikasi Indonesia, was attended at Palembang Anchorage, Indonesia on 13 February 2026 for condition survey. The vessel is managed and operated by PT. Multiguna Shipping Lines and was observed alongside the Masterâs representative and shipâs staff during routine operational status. Class and statutory certificates, including the class certificate and STCWârelated competency documents for officers, were verified as available and valid, with no class recommendations or exemption certificates recorded.</p><p><span style="font-size: 0.875rem;"><b>Hull</b></span></p><p><span style="font-size: 0.875rem;">The vessel is of double bottom, single hull construction, with ultrasonic thickness measurement last carried out on 24 May 2023 during drydock at Dock Mariana Bahagia Palembang, and the classâapproved report indicating recorded steel diminution below 20 percent. As far as could be seen from afloat condition, the external hull plating and anodes showed general rusting, with major rust noted in several shell areas and rust staining around the vesselâs name marking, and a locally damaged halfâround steel fender on the port side of approximately 2 meters in length.&nbsp; There are two cargo holds; the overall structure of the holds was found intact, but the internal surfaces were generally rusted, with uncoated tank tops and poor coating condition characterized by extensive scaling and corrosion.</span></p><p><b>Deck and ballast</b></p><p>The superstructure was observed in overall fair condition, while the main deck plating, poop deck and ballast vents were generally in sound condition except at the forward deck and associated areas, where heavy corrosion was seen on the forecastle store floor plate, winch foundations, Tâbollards, forward bulwark and several railing sections around the main deck. Watertight openings, including doors at the aft and starboard side poop deck and forecastle store, exhibited heavy corrosion and local damage. Ballast tank arrangements comprise double bottom water ballast tanks DBWT 1, 2, 3 and 4 port and starboard, with all ballast tanks full during the survey and a representative internal inspection of the forepeak tank showing heavy corrosion with some cracking and deformation of structural members. A ballast tank pressure test was conducted and all double bottom ballast tanks held pressure satisfactorily, with no leakage observed into the cargo hold spaces.</p><p><b>Cargo worthiness</b></p><p>The vessel is fitted with two cargo holds serviced by lifting pontoon type hatch covers, and the internal cargo spaces, although structurally intact, were found with uncoated tank tops and general rusting consistent with poor coating condition. Cargo hold bilges were inspected and found with the fixed bilge suction system not operating; consequently, the vessel presently uses portable pumps for bilge water removal from the cargo holds. Access ladders and manholes to the holds were available and functional, with no major structural defects reported in these access arrangements. Hatch coaming structures were in generally good coating condition along the vertical and side portions, while heavy corrosion was concentrated on the top areas of the hatch coamings and hatch pontoons. The vessel employs a threeâlayer tarpaulin arrangement over the pontoon covers as the primary weathertight barrier, the tarpaulins and their securing arrangements were inspected and found in serviceable condition at the time of survey. The vessel is additionally equipped with a dieselâengineâpowered cargo crane of 15âton safe working load, which was observed in fair working condition for cargo handling.</p><p><b>Navigation</b></p><p>Bridge navigational equipment was available and functional, with radar tested and found operational with satisfactory target detection and tracking performance, and the echo sounder tested with accurate depth readings and correct display. A magnetic compass is fitted and was found in good condition, with a deviation card properly posted on the bridge. Paper charts were sufficient in coverage for the vesselâs Indonesian trading area; however, Notices to Mariners (NTM BPI weekly) were not available on board and the charts had not been updated due to this, so chart corrections were not current at the time of inspection. Emergency steering changeover instructions were not sighted on the bridge, although means of communication between the steering gear compartment and bridge via direct telephone were fitted and tested in working condition.</p><p><b>Machinery</b></p><p>The main engine is a Yanmar MF28NâSTD4 diesel engine with an output of about 1,000 PS, and the main generator set is a Yanmar 6CHLâN with an output of about 74 PS, forming the primary propulsion and electrical power arrangement. The engine room was observed in overall fair, clean and tidy condition, with the main engine general appearance considered satisfactory and without significant oil leakage noted during the inspection. The main switchboard was sighted in satisfactory condition, with no abnormality reported during the survey. Auxiliary power is provided by at least two generator sets; Generator No. 1 and 3 was tested and found operational with satisfactory performance, while Generator No. 2 was under repair at the time of inspection and therefore not tested. An emergency generator is installed on the starboard side boat deck, also serving as an additional generator; this unit was observed without saveâalls fitted beneath its position. Emergency steering arrangements from the steering gear compartment were tested and found operational, and changeover from main to emergency steering was carried out satisfactorily.</p><p><b>Pollution prevention</b></p><p>Pollution prevention arrangements on deck showed several missing or incomplete items: a dedicated SOPEP locker and associated spill response equipment were not available on deck at the time of survey, and oil absorbents and scupper plugs were not sighted on board. Bunkering connections were inspected and found in satisfactory condition, with flanges, valves and blank flanges present and properly maintained. Fuel oil tank air vents on deck were operational but not labeled according to their respective services. The bunker station was not fitted with saveâalls.</p>', '<p>Overall, MV. CHUO 01 is in fair condition, with class and statutory certificates valid, main propulsion and essential machinery generally reliable, and key navigational equipment operational for routine trading within Indonesian waters. However, several items listed in the defect list require priority attention, particularly those related to structural condition of the hull and decks, heavy corrosion and damage on forward deck structures and watertight doors, as well as degraded coating, nonâfunctional fixed bilge suction, and heavily corroded hatch coamings and pontoons in the cargo section, all of which pose increased risk to cargo safety and longâterm structural integrity if not timely rectified.</p>', '2026-01-27', '2027-01-27', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (644, 430, NULL, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-03-12', NULL, NULL, NULL, '2026-02-10', '2027-02-10', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
