INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (647, 482, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-03-20', NULL, NULL, NULL, '2026-02-18', '2027-02-18', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (648, 483, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-03-22', NULL, NULL, NULL, '2026-02-20', '2027-02-20', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (649, 484, 13, 9, 'SAMUEL MISDOM', 'Survey', 'Completed', 'complete', 'Cilegon', '2026-04-08', '2026-03-22', '<p>During the survey, several critical concerns were raised by the surveyor which may affect the vesselâs compliance, safety, and operational performance.</p><p>First, from a regulatory and documentation perspective, essential certificates such as the Classification Certificate and Certificate of Competency were not available onboard at the time of inspection, as they were held by the agent. Furthermore, the Notice to Mariners (NTM) had not been updated for the past six months, which may pose a risk to navigational safety. The Ultrasonic Thickness (UT) measurement records were also not available onboard for verification.</p><p>Second, from an operational standpoint, the absence of a radar log book indicates a lack of proper recording of navigational activities. In addition, no emergency steering instruction was found onboard, which could present a significant risk in the event of steering system failure.</p><p>From a safety and environmental perspective, the vessel was not equipped with scupper plugs on both port and starboard sides, and no oil absorbent materials were available onboard. This condition may lead to non-compliance with pollution prevention requirements and increase the risk of environmental contamination.</p><p>In terms of structural integrity, the accommodation door was found not to be watertight due to missing or damaged rubber seals. This condition may allow water ingress and compromise safety, particularly in adverse weather conditions.</p><p>Last, the inspection of hatch cover could not be carried out due to ongoing dockyard works, which may indicate the possibility of unidentified defects in these areas</p>', '<p>Based on the survey conducted on board KM. Permata Ibu on 08 April 2026 at the dockyard, the overall condition of the vessel is assessed as fair condition.</p><p>The inspection revealed several deficiencies related to documentation, operational procedures, safety equipment, and structural integrity. Additionally, certain areas of the vessel could not be inspected due to ongoing repair works at the dockyard, particularly at the hatch cover.</p><p>In general, the vessel remains in operable condition; however, the identified deficiencies require corrective actions to ensure compliance with applicable regulations, operational safety, and seaworthiness standards</p>', '<p>The findings from the defect survey can be summarized into several categories as follows:</p><p>From the documentation aspect, several mandatory documents were not available onboard, including the Classification Certificate and Certificate of Competency. In addition, the Notice to Mariners was not updated, and UT thickness measurement records were not available for onboard verification.</p><p>From the operational aspect, the vessel lacks a radar log book and does not have emergency steering instructions available onboard, indicating insufficient operational preparedness.</p><p>From the safety and environmental aspect, the absence of scupper plugs and oil absorbent materials represents a deficiency in pollution prevention measures and emergency response readiness.</p><p>From the structural aspect, the accommodation door is not watertight, which may affect the vesselâs integrity and safety under certain conditions.</p><p>Furthermore, certain critical areas hatch cover, were not inspected due to ongoing repair works, and therefore their condition remains unverified.</p>', '2026-02-20', '2027-02-20', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (650, 485, 8, 9, 'E.Prasetya Nugraha, S.T., M.T.', 'Survey', 'Completed', 'complete', 'Badas Port, Sumbawa, West Nusa Tenggara', '2026-02-25', '2026-03-27', '<p class="MsoNormal"><b><u>STRUCTURALnCOMPLIANCE WITH GENERAL MARINE INDUSTRY STANDARDS</u></b><o:p></o:p></p><ul style="margin-top:0cm" type="disc">n <li class="MsoNormal">Latest NTM was found unavailable onboard<o:p></o:p></li>n <li class="MsoNormal">Paper chart was found not updated withn     latest NTM/ BPI<o:p></o:p></li>n <li class="MsoNormal">Scupper plugs were found unavailable onn     board<o:p></o:p></li>n <li class="MsoNormal">Oil absorbent was found unavailable onn     board<o:p></o:p></li>n <li class="MsoNormal">Forward draught mark was found faded<o:p></o:p></li>n <li class="MsoNormal">Main deck was found rusty<o:p></o:p></li>n <li class="MsoNormal">Doubler platting was found at several mainn     deck area<o:p></o:p></li>n <li class="MsoNormal">Bulwarks was found rusty and partlyn     corroded<o:p></o:p></li>n <li class="MsoNormal">Bollard, roller &amp; fairleads were foundn     without SWL marking &amp; rusty<o:p></o:p></li>n <li class="MsoNormal">Rubber gasket of CH manhole access weren     found partly missing<o:p></o:p></li>n <li class="MsoNormal">Cargo holds no. 1 &amp; 2 were found rustyn     and partly corroded on tween deck and side shell frames<o:p></o:p></li>n <li class="MsoNormal">Hatch coaming of CH no.1 and 2 were foundn     rusty and partly corroded<o:p></o:p></li>n <li class="MsoNormal">Hatch cover panels were found rusty hatchn     cover pontoon panels CH no. 2 were found rusty and partly corroded<o:p></o:p></li>n</ul><p class="MsoNormal" style="margin-left:36.0pt"><o:p>&nbsp;</o:p></p><p class="MsoNormal"><b><u>ITEMS NOT TESTED</u></b><o:p></o:p></p><p>nnnnnnnn</p><ul style="margin-top:0cm" type="disc">n <li class="MsoNormal">Cargo hold bilge suction test has not beenn     conducted due to cargo discharging operation<o:p></o:p></li>n <li class="MsoNormal">Hose test to hatch cover has not beenn     conducted due to cargo discharging operation<o:p></o:p></li>n <li class="MsoNormal">Ballast overflow pressure test has notn     been conducted due to cargo discharging operation<o:p></o:p></li>n</ul>', '<p style="text-align: justify; ">The Wreck Removal &amp; Oil Pollution Survey of MV âTRIFOSAâ was conducted on 25 February 2026 while the vessel was anchored at Badas Port, West Nusa Tenggara, Indonesia, during cargo discharging operations.</p><p style="text-align: justify; ">During the survey, we were accompanied and assisted by the Master, Chief Officer, Chief Engineer, and crew.</p><p style="text-align: justify; "><b>HULL</b></p><p style="text-align: justify; ">MV âTRIFOSAâ is a 43-year-old steel single-hull general cargo vessel with principal dimensions as per shipâs particulars:</p><p style="text-align: justify; ">LOA: 100.17 m</p><p style="text-align: justify; ">LPP: 89.80 m</p><p style="text-align: justify; ">Breadth: 18.80 m</p><p style="text-align: justify; ">Depth: 12.90 m</p><p style="text-align: justify; ">GT: 5,380</p><p style="text-align: justify; ">NT: 2,242</p><p style="text-align: justify; ">DWT: 6,774</p><p style="text-align: justify; ">The vessel is registered in Jakarta and classed with Biro Klasifikasi Indonesia (BKI). She was built by Kochi Jyuko Co., Ltd., Japan, in June 1983.</p><p style="text-align: justify; ">The vessel was reported to hold valid class certificates, including Hull &amp; Machinery Class Certificate, Load Line Certificate, and relevant statutory certificates.</p><p style="text-align: justify; "><b>CARGO HOLDS/ COMPARTMENTS</b></p><p style="text-align: justify; ">The vessel is fitted with two (2) cargo holds and equipped with four (4) derrick cranes.</p><p style="text-align: justify; ">Inspection of the tank tops in Cargo Hold Nos. 1 and 2 was not carried out, as the areas were not accessible due to cargo onboard at the time of survey.</p><p style="text-align: justify; ">The cargo holds are fitted with pontoon-type hatch covers, covered with five (5) layers of tarpaulins. The hatch covers were found rusty and partly corroded.</p><p style="text-align: justify; ">Cargo hold bilge suction test was not conducted due to ongoing cargo discharging operations.</p><p style="text-align: justify; "></p><p style="text-align: justify; ">Hose test of the hatch covers was also not conducted due to cargo discharging operations.</p><p style="text-align: justify; ">The visible shell plating was found in fair condition. The forward draught marks were observed to be faded.</p><p style="text-align: justify; "><span style="font-size: 0.875rem;">During the survey, the superstructure and accommodation spaces were found satisfactory. The main deck was found rusty. The top plates and stanchions of the hatch coamings / coaming stays were found rusty and partly corroded. The bulwarks were found partly corroded.</span></p><p style="text-align: justify; "><span style="font-size: 0.875rem;"><b>NON-CARGO TANKS</b></span></p><p style="text-align: justify; ">The vessel is fitted with five (5) water ballast tanks (1C, 2P/S, 3P/S), one (1) fore peak tank (FPT), one (1) aft peak tank (APT), and a forward deep tank.</p><p style="text-align: justify; "></p><p style="text-align: justify; ">Ballast overflow pressure test and inspection of the internal structure of the water ballast tanks were not carried out due to cargo discharging operations.</p><p style="text-align: justify; "><b>MACHINERY</b></p><p style="text-align: justify; ">The vessel is equipped with:</p><ul><li style="text-align: justify;">One (1) unit Hanshin Main Engine, Type 6EL40, rated 3,300 HP at 248 RPM</li><li style="text-align: justify;">Three (3) units Yanmar Auxiliary Engines, Type 6MAL-HT, rated 3 Ã 470 HP</li><li style="text-align: justify;">Two (2) units Emergency Generators (details not available), located on the poop deck</li></ul><p style="text-align: justify; ">The engine room is located aft.</p><p style="text-align: justify; ">The main engine and auxiliary engines were reported to be in working order.</p><p style="text-align: justify; "><b>POLLUTION</b></p><p style="text-align: justify; ">Bunker manifolds and fuel air vents were found in fair condition. Save-alls / drip trays were fitted.&nbsp;<span style="font-size: 0.875rem;">Scupper plugs were found unavailable.&nbsp;</span><span style="font-size: 0.875rem;">Oil absorbent materials were not available at the time of survey.</span></p><p style="text-align: justify; "><span style="font-size: 0.875rem;"><b>NAVIGATION</b></span></p><p style="text-align: justify; ">Navigation and communication equipment fitted on the bridge includes: Gyro Compass, Magnetic Compass, Radar, Echo Sounder, AIS, GPS, and VHF radios.</p><p style="text-align: justify; ">Navigational charts were sufficient for the vesselâs trading area; however, they were not corrected up to the latest Notices to Mariners. BPI publications were reported to be regularly supplied onboard.</p><p style="text-align: justify; "></p><p style="text-align: justify; ">Changeover instructions for emergency steering were found properly posted and displayed.</p>', '<p class="MsoNormal"><span lang="EN-US">The vessel was found in fair structuralncondition. However, several items need to be repaired/rectified.<o:p></o:p></span></p>', '2026-02-25', '2027-02-25', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (651, 486, 13, 9, 'Wahono Eko P', 'Survey', 'Completed', 'complete', 'Area berlabuh Pelabuhan Sunda Kelapa', '2026-04-27', '2026-03-22', '<p>The following concern were noted:</p><p>1. Emergency lighting in crew accommodation not installed and/or not functioning</p><p>2. Emergency generator not in working condition</p><p>3. Engine room bilge alarm/sensors not functioning</p><p>4. No records of lubricating oil analysis and smoke detector test</p><p>5. Blackout procedures and emergency steering procedures not available</p><p>6. Escape route plans not posted in accommodation</p><p>7. No steering gear synchronization test records</p><p>8. Insulation mats not available</p><p>9. No workshop onboard (hand tools only available)</p><p>10. Stability calculations at departure/arrival not carried out or recorded</p><p>11. Hatch cover seals and compression bars not provided</p>', '<p>The vessel is generally found to be in satisfactory condition. Main propulsion and auxiliary engines are operational and maintained in accordance with makerâs requirements. Deck equipment, mooring arrangements, cargo hold condition, and hatch covers are generally in good order. Navigation, communication, fire-fighting systems, and essential machinery are mostly in serviceable condition based on inspection and testing carried out.<br></p>', '<p>The vessel is generally in satisfactory operational condition. However, several deficiencies were identified mainly related to emergency preparedness, safety documentation, and certain critical safety systems. These should be addressed promptly to improve compliance and operational safety.<br></p>', '2026-02-20', '2027-02-20', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (652, 486, 13, 9, 'Miftah Wibowo', 'Survey', 'Completed', 'complete', 'Sunda Kelapa Anchorage, Jakarta', '2026-04-27', '2026-03-22', '<p data-start="25" data-end="579" style="text-align: justify; ">Based on the findings during the survey, several deficiencies were identified that may affect the vesselâs seaworthiness and regulatory compliance. Particular concern is raised regarding the unsatisfactory hatch cover tightness, which poses a risk of water ingress to cargo holds, as well as the unsatisfactory ballast tank pressure test due to damaged air and sounding pipes. In addition, the absence of an emergency generator represent significant safety concern.</p><p>n</p><p data-start="581" data-end="961" data-is-last-node="" data-is-only-node="" style="text-align: justify; ">Furthermore, deficiencies in pollution prevention arrangements, including the absence of SOPEP locker, scupper plugs, and oil absorbents, indicate non-compliance with basic environmental protection requirements. These issues, if not rectified, may impact the vesselâs operational safety, environmental compliance, and insurability, and therefore require prompt corrective actions.</p>', '<p>The survey on board the general cargo vessel&nbsp; "SUMBER ABADI 178" was conducted on 27 April 2026 at the Sunda Kelapa Anchorage, Jakarta, Indonesia with the following attendances:</p><p>1. Wardiyanto&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; -&nbsp; &nbsp; &nbsp;Chief Officer&nbsp;of the vessel</p><p>2. Krisna Yoga N.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-&nbsp;&nbsp; &nbsp; Second Officer of the vessel</p><p>3. Pacha Seriosa Saragih&nbsp; &nbsp;-&nbsp;&nbsp; &nbsp; Chief Engineer of the vessel</p><p>4. Indra Kurnyawan&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-&nbsp;&nbsp; &nbsp; Owner Representative</p><p>General cargo "SUMBER ABADI 178" is 1,316 GT presently owned and operated by PT Alexindo Yakin Prima, Jakarta. At the time of survey, the vessel was anchored at Sunda Kelapa Anchorage, Jakarta for waiting cargo operations. Furthermore, the vessel''s trading area is within Indonesian waters.</p><p><br></p><p><b><u>VESSEL CERTIFICATION AND DOCUMENTATION</u></b></p><p data-start="220" data-end="542" style="text-align: justify;">The vesselâs statutory and classification documents were found to be generally in order. The Classification Certificate remains valid until 18 May 2027, with the last inspection carried out on 15 April 2026. Crew certification and safe manning documentation were verified and found compliant with applicable regulations.</p><p>n</p><p data-start="544" data-end="754" style="text-align: justify;">Ultrasonic thickness measurement conducted between 26 March 2025 and 8 April 2025 indicated that structural steel diminution remains within acceptable class limits, below the maximum allowable threshold of 20%.</p><p data-start="544" data-end="754"><br></p><p><b><u>GENERAL CONDITION OF HULL AND DECK</u></b></p><p data-start="807" data-end="1118" style="text-align: justify; ">The hull was observed to be in generally fair condition. While no major structural deformation was evident, localized corrosion, coating deterioration, and minor indentations were noted, particularly along the waterline and side shell. Maintenance and recoating are recommended to prevent further degradation.</p><p data-start="1120" data-end="1243" style="text-align: justify;">Decks and superstructure were generally in good condition; however, damage was observed on the port side forward bulwark.</p><p>nn</p><p data-start="1245" data-end="1483" style="text-align: justify;">Hatch covers (folding type) were found in fair plating condition; however, hose test results were not satisfactory due to improper closing in fully shut position.&nbsp;<span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">During sailing, the hatch cover was covered with tarpaulins.</span></p><p><br></p><p><b><u>BALLAST TANKS</u></b></p><p data-start="1515" data-end="1644" style="text-align: justify; ">Internal inspection of selected ballast tanks (No. 1P, 1S, 2P, and 2S) indicated that the overall structural condition is fair.</p><p>n</p><p data-start="1646" data-end="1830" style="text-align: justify;">However, ballast tank pressure test results were unsatisfactory. Damage was identified on the air pipe and sounding pipe during testing, which requires repair and further verification.</p><p data-start="1646" data-end="1830"><br></p><p><b><u>BRIDGE DECK AND NAVIGATION</u></b></p><p data-start="1876" data-end="2050" style="text-align: justify; ">Navigation equipment, including radar and echo sounder, were found operational, and navigational charts were updated. Magnetic compass was also in proper working condition.&nbsp;<span style="font-size: 0.875rem;">Emergency steering instructions were available on board.&nbsp;</span>The latest update to the Notice to Mariners (NTM) records was dated 03 April 2026<span style="font-size: 0.875rem;">.&nbsp;</span><span style="font-size: 0.875rem;">Overall, bridge equipment is considered functional.</span></p><p><br></p><p><b><u>MACHINERY SPACE AND STEERING GEAR</u></b></p><p data-start="2332" data-end="2451" style="text-align: justify; ">The main engine and auxiliary engines were found in good operational condition, with no significant leakage observed.&nbsp;<span style="font-size: 0.875rem;">Communication systems between bridge and engine room were available and functional.</span></p><p data-start="2540" data-end="2640" style="text-align: justify; ">However, no emergency generator was provided on board, which constitutes a significant deficiency.&nbsp;<span style="font-size: 0.875rem;">Emergency steering test was conducted; however, steering was controlled manually from the bridge, and no local emergency steering arrangement in the steering gear room was available.</span></p><p style="text-align: justify; "><br></p><p><b><u>SAFETY AND POLLUTION</u></b></p><p data-start="2875" data-end="3099" style="text-align: justify; ">Significant deficiencies were noted in pollution prevention arrangements. SOPEP locker, scupper plugs, and oil absorbents were not available on board, indicating non-compliance with basic pollution prevention requirements.</p><p>n</p><p data-start="3101" data-end="3208" style="text-align: justify; ">Other items such as bunker connections, fuel air vents, and save-alls were found in satisfactory condition.</p>', '<p style="text-align: justify; ">Based on the survey findings, the vessel is in generally fair condition; however, several critical deficiencies were identified that may affect safety and compliance. These include unsatisfactory hatch cover tightness, failed ballast tank pressure test due to damaged piping, absence of an emergency generator, and inadequate pollution prevention equipment. Immediate corrective actions are recommended to mitigate risks to seaworthiness, cargo safety, and environmental compliance.</p>', '2026-06-29', '2027-06-29', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (653, 487, 8, 9, 'Capt.Risanda Ajirogo', 'Survey', 'Completed', 'complete', 'Pangkal Pinang', '2026-04-28', '2026-03-15', '<p>Critical deficiencies were noted during the survey as follows:</p><p>1. Echo sounder found inoperative during inspection â immediate repair or replacement required prior to departure to ensure navigational safety.</p><p>2. Oil absorbents and SOPEP equipment not available on board â to be provided immediately as required by MARPOL Annex I.</p><p>3. Watertight door access to cargo hold at forward found broken â immediate repair required to maintain watertight integrity of the vessel.=</p><p>Owner/operator is strongly recommended to rectify the above deficiencies immediately to ensure safe operation, regulatory compliance, and the protection of the vessel, crew, cargo, and the marine environment.</p>', '<p>Based on the visual survey conducted on 28 April 2026 on board MV SATYA BERJAYA at Pangkal Pinang, Bangka Island, Indonesia, the following is the summary of the vessel''s overall condition:</p><p>The vessel MV SATYA BERJAYA is a non-classed general cargo vessel of 1,200 GRT, built in Japan and currently operated by PT. Pelayaran Tropic Jaya Perkasa in Indonesian waters. All officers on board were found to hold valid certificates of competency in accordance with STCW requirements. The last Ultrasonic Steel Thickness measurement report was noted dated 29 March 2026.</p><p>Bridge and navigation equipment were generally found in satisfactory condition. The radar and both gyro and magnetic compasses were found in good working condition. Notices to Mariners (NTM) were up to date as of 24 April 2026, and paper charts were found sufficient for the vessel''s current trading area. However, the echo sounder was found not working during inspection.</p><p>Regarding pollution prevention, several significant deficiencies were noted. The SOPEP Box/Locker and oil absorbent materials were not available on board, and the bunker station/manifold was not fitted with save-alls. On a positive note, fuel air vents were found in good condition with no blockage or damage, and scupper plugs were available on board and ready for use.</p><p>Hull and deck structural condition were found to be in fair overall condition. Hull and anodes were inspected as far as visible with no significant structural defects noted. All decks and superstructure were found in fair condition and well coated. The interior of cargo holds was in fair condition with no significant structural damage or excessive corrosion. Cargo holds bilge was reasonably clean and the bilge suction system tested satisfactorily. However, the watertight door access to the cargo hold at the forward end was found broken and requires immediate repair. It is also noted that the hatch covers are not designed to be weathertight; the vessel was relying on 4 layers of tarpaulins as cover, which poses a risk of water ingress to the cargo.</p><p>Ballast tanks were found in fair internal structural condition. Representative double bottom ballast tanks (DBWT 3 P/S) were inspected without significant corrosion noted. Pressure tests on ballast tanks surrounding the cargo hold were carried out satisfactorily with no leakage sighted.</p><p>The main engine is HANSHIN 6LUD-35,735 KW 1000 hp and 2 unit generator MITSUBISHI 6D 16-OA,2 X 135 HP .The main engine and generator were in good general appearance, operating satisfactorily and considered trustworthy. The emergency generator was confirmed operational and functioning satisfactorily in its designated location. All auxiliary engines were found operational and in satisfactory working condition. Means of communications between the engine room and bridge were in good working order. The emergency steering test was carried out satisfactorily with the steering gear responding correctly from the steering gear room.</p>', '<p>Overall, the vessel MV SATYA BERJAYA was found in FAIR condition, with hull, decks, ballast tanks, cargo holds, and machinery spaces generally maintained to a fair standard. Officers on board hold valid STCW certificates and the last ultrasonic thickness measurement was conducted in March 2026. Navigation equipment including radar and compasses were found operational. Except for several significant deficiencies were identified during the survey. All of these deficiencies require prompt rectification by the owner/operator prior to risk acceptance to ensure the vessel''s seaworthiness, crew safety, cargo protection, and compliance with applicable maritime regulations.</p>', '2026-05-18', '2027-05-18', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (654, 488, NULL, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, '2026-02-03', '2027-02-03', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (657, 489, 8, 9, 'Erriawan Dharma Santosa', 'Survey', 'Completed', 'complete', 'TANJUNG PERAK ANCHORAGE', '2026-03-04', '2026-03-18', '<p><u><b>STRUCTURAL COMPLIANCE WITH GENERAL MARINE INDUSTRY STANDARDS</b></u><br></p><ol><li>Deviation Card posted on bridge was found more than 2 years</li><li>NTM/ BPI was found not regularly supplied on board</li><li>Paper Chart was found not updated/ corrected</li><li>Main Deck was found Rusty at Several Area</li><li>Railings were found Partly Missing and Deformed</li><li>Bollards, Fairleads, and Rollers were found without SWL Marking/ Paint-Over</li><li>Plating of Chain Locker was found partly corroded</li><li>Weathertight doors were found without Open/Close direction marking/ Paint-Over</li><li>Ballast Tanks Pressure Test has not been carried out due to still being in full load cargo.</li></ol><div bis_skin_checked="1"><br></div>', '<p style="text-align: justify; ">Tameda Maru is an Oil & Chemical Tanker was provided with 4 P/S (Four) Cargo Oil Tanks and Cargo Trunk. The vessel dimension is LOA 65.80 (m), (LBP x B x D) 62.00 x 10.00 x 4.50 (m), was built in SASAKI SHIPBUILDING CO., LTD., JAPAN, in 2009, Flag Indonesia, Port of Registry of Tanjung Priok, and under Classification of Biro Klasifikasi Indonesia (BKI). The vessel was powered by NIIGATA 6M30GT 1 x 1,000 HP x 310 RPM; 2 (two) units of Auxiliary Engines YANMAR 6HALHTN 160 HP and MITSUI DEUTZ F5L912 68 HP; 1 (one) unit of Emergency Generator with no information; 2 (two) units of Cargo Pump 2 x Centrifugal, with no information or detailed specification. All of the Engines and Machinery were found in satisfactory condition and good working order.Â </p><p style="text-align: justify; ">The Hull was found in fair condition; Hull Markings were found legible. Main deck was found Rusty at several area; the Railings were found partly missing and partly deformed; bollards, fairleads, and rollers were found without SWL Marking/ Paint-Over; Plating of Chain Locker at forward compartment was found partly corroded; Weathertight doors were found without Open/Close Direction Marking/ Marking was found paint-over.Â </p><p class="MsoNormal" style="text-align:justify">The Internal Structure of COT No.rn1 P/S and Hatch/ Manhole Covers were found in fair condition. The CargornManifolds were found in fair condition. The rubber gasket of the hatch cover of the manhole was found in fair condition. The Internal Structure of COT No. 2-4rn(P/S) was not inspected due to the full load of the cargo.</p><p class="MsoNormal" style="text-align:justify">The Superstructure was found in satisfactory condition.</p><p class="MsoNormal" style="text-align:justify">The Navigation and communication are in satisfactory condition.Â </p><div style="text-align: justify;" bis_skin_checked="1">The main engine, auxiliary engines, and steering equipment were found in satisfactory condition. 2 (two) units of Centrifugal Pump were found in fair condition.Â </div><div style="text-align: justify;" bis_skin_checked="1"><br></div><div style="text-align: justify;" bis_skin_checked="1">The Internal structure of Ballast Tanks was found still in fair condition.Â </div><div style="text-align: justify;" bis_skin_checked="1"><br></div><div style="text-align: justify;" bis_skin_checked="1"><div bis_skin_checked="1">The crew was found well-knowledge about the vessel and how to maintain the vessel and her cargo. The shipboard management was found in good order and well recorded.</div><div bis_skin_checked="1"><br></div><div bis_skin_checked="1">During the survey, the Master was provided documents of the vessel i.e. Statutory & Class Certificates and found in order.</div></div><p class="MsoNormal" style="text-align:justify"><o:p></o:p></p>', '<p class="MsoNormal"><span lang="EN-US" style="font-family:"Calibri",sans-serif;rnmso-fareast-font-family:"Arial Unicode MS";mso-bidi-font-family:"Times New Roman"">Thernvessel was found in fair structural condition. However, several items need tornbe repaired/rectified.<o:p></o:p></span></p>', '2026-02-16', '2027-02-16', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (658, 490, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-03-18', NULL, NULL, NULL, '2026-02-16', '2027-02-16', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
