INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (660, 492, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-03-16', NULL, NULL, NULL, '2026-02-14', '2027-02-14', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (661, 493, 13, 9, 'Samuel Misdom', 'Survey', 'Outstanding', 'complete', 'Jakarta', '2026-03-03', '2026-04-12', '<p data-start="158" data-end="243">Based on the survey findings, the undersigned Surveyor raises the following concerns:</p>rn<ol data-start="245" data-end="1079"><li data-start="245" data-end="504">rn<p data-start="248" data-end="504">The absence of mandatory statutory and class documentation onboard, including the Class Certificate, Officersâ Certificates of Competency, and Ultrasonic Steel Measurement Certificate, may affect the vesselâs regulatory compliance and operational readiness.</p>rn</li><li data-start="506" data-end="683">rn<p data-start="509" data-end="683">The unavailability of a test logbook and the failure to receive Notices to Mariners (NTM) within the last six months indicate inadequate navigational and operational control.</p>rn</li><li data-start="685" data-end="896">rn<p data-start="688" data-end="896">The presence of corrosion and rusting, particularly in the forecastle area, reflects insufficient maintenance and poses a potential risk to the vesselâs structural integrity if not promptly rectified.</p>rn</li><li data-start="898" data-end="1079">rn<p data-start="901" data-end="1079">The absence of pollution prevention equipment (scupper plugs) onboard represents a significant environmental and regulatory risk, especially during cargo or bunkering operations.</p></li></ol><p><br></p>', '<p>Based on the survey conducted, a significant number of technical and operational deficiencies were found, placing the vessel in an unsatisfactory condition and placing the vessel in an unsatisfactory with details as follows:<br><b>1. Non-Compliance with Documentation and Procedures</b><br>Mandatory certifications (including Class Certificate, Officer Competency Certificates, and the Ultrasonic Steel Certificate) were not available onboard the vessel. Routine testing procedures were hindered by the absence of a Test Logbook and the vessel''s failure to receive Notices to Mariners (NTM) within the last six months.</p><p><b>2.Â  Structural Degradation and Hull Integrity</b><br>Observations indicate minor corrosion and rusting on the vessel''s structure, particularly in the forecastle areas. This condition points to inadequate maintenance and requires immediate structural attention.</p><p><b>3. Pollution Prevention</b><br>The pollution prevention materials (scupper plugs) were not available on board, necessitating rnimmediate availability.</p>', '<p data-start="1116" data-end="1488">Based on the survey conducted, the vessel was found to be in an <span data-start="1180" data-end="1208">unsatisfactory condition</span> due to multiple technical and operational deficiencies.<br data-start="1264" data-end="1267">rn</p><p data-start="1116" data-end="1488">The main issues identified include non-compliance with mandatory documentation and procedures, signs of structural deterioration in several areas of the hull, and the absence of essential pollution prevention equipment. Immediate corrective actions and proper maintenance, as well as the completion and verification of all statutory and operational requirements, are necessary to restore the vessel to an acceptable and safe operating condition.</p><p><br></p>', '2026-03-13', '2027-03-13', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (662, 494, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-04-14', NULL, NULL, NULL, '2026-03-15', '2027-03-15', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
