INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (665, 501, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-03-23', NULL, NULL, NULL, '2026-02-21', '2027-02-21', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (666, 325, 14, 9, NULL, 'Survey', 'Completed', 'complete', NULL, NULL, '2026-04-09', NULL, NULL, NULL, '2026-03-10', '2027-03-10', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (667, 21, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-04-14', NULL, NULL, NULL, '2026-03-15', '2027-03-15', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (668, 21, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-04-14', NULL, NULL, NULL, '2026-03-15', '2027-03-15', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (669, 502, 13, 9, 'Miftah Wibowo', 'Survey', 'Completed', 'complete', 'Port of Sunda Kelapa, Jakarta', '2026-04-05', '2026-03-25', '<p>Particular concern is drawn to the condition of the vesselâs watertight integrity arrangements. It was noted that the rubber seal for the watertight door to the forepeak store was not available. In addition, the locking mechanisms for the port and starboard bridge watertight doors, as well as those for the accommodation watertight doors, were not available. These deficiencies may compromise the vesselâs watertight integrity and increase the risk of water ingress under adverse conditions.</p><p>Further concern is noted regarding the condition of the hatch cover sealing arrangements. The rubber seals on two (2) out of a total of twelve (12) hatch cover panels were not available. In addition, the hatch covers were observed to be of folding type and secured using tarpaulins as a secondary means of protection. This condition may affect the weathertightness of the cargo holds and poses a risk of cargo damage due to potential water ingress.</p><p>It is also noted that the internal inspection of ballast tanks was limited. Inspection was only carried out for the forepeak tank, while other ballast tanks, including the double bottom tanks, were not inspected due to ongoing cargo operations. As such, the overall internal condition of the vesselâs ballast tanks could not be fully ascertained, and the presence of any underlying corrosion or structural deficiencies cannot be identified.</p><p data-start="1797" data-end="2116">Furthermore, certain operational limitations were encountered during the survey. The hose test for the hatch covers and inspection of the double bottom ballast tanks could not be carried out due to ongoing cargo loading and unloading operations. Therefore, the assessment of these areas remains limited and conditional.</p><p>n</p><p data-start="2118" data-end="2468">Overall, the above findings may indicate that maintenance of certain critical components, particularly those related to watertight integrity and cargo protection systems, requires further attention. It is recommended that necessary rectifications and comprehensive inspections be carried out to ensure the vesselâs safety and operational reliability.</p>', '<p><span style="font-size: 0.875rem;">The survey on board the general cargo vessel "INDAH VIRGO" was conducted on 05 April 2026 at the Port of Sunda Kelapa, Jakarta, Indonesia with the following attendances:</span></p><p>1. Yana Supriatna&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Master of the vessel</p><p>2. Oktaviany Grace&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-&nbsp; &nbsp; Chief Officer of the vessel</p><p>3. Rakha Permana&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; -&nbsp; &nbsp; Chief Engineer of the vessel</p><p>4. Edy Suprapto&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;-&nbsp; &nbsp; Owner Representative</p><p><span style="font-size: 0.875rem;">General cargo "INDAH VIRGO" is a 1,016 GT presently owned and operated by PT. Bintan Megah Abadi, Jakarta. At the time of survey, the vessel was berthed at Port of Sunda Kelapa, Jakarta for unloading and loading cargo operations. Furthermore, the vessel''s trading area is within Indonesian waters.</span></p><p><span style="font-size: 0.875rem;"><br></span></p><p><span style="font-weight: bolder;"><u>VESSEL CERTIFICATION AND DOCUMENTATION</u></span></p><p>Class survey records for hull, machinery, and load line were made available at the time of the survey and the class status was maintained. The statutory certificates were found to be valid and not overdue for the next inspection schedule or renewal.</p><p>The thickness measurement (UTM) report was available on board. Based on the provided report, the diminution level of the vessel''s steel structures was found to be below the class maximum allowable limit of 20%.</p><p><br></p><p><span style="font-weight: bolder;"><u>GENERAL CONDITION OF HULL AND DECK</u></span></p><p>As far as could be ascertained, the starboard and port side shell plating from aft to fore, and from the sheer strake down to the waterline, were visually found to be in fair condition, with no doublers observed, and the paint coating in good condition. The draft marks and load lines were clearly marked and visible.</p><p>At the time of our attendance, the visible condition of the deck plating on the forecastle, main deck, forepeak, and poop deck, was found to be in fair condition. The starboard and port bulwarks, and railings on the forecastle, main deck and poop deck were found in order.</p><p>The fuel air ventilation, sounding pipe, and air ventilation was found in good order.&nbsp;<span style="font-size: 0.875rem;">The rubber seal for the watertight door to the forepeak store was not available.&nbsp;</span><span style="font-size: 0.875rem;">The locking mechanisms for the port and starboard bridge watertight doors were not available.&nbsp;</span><span style="font-size: 0.875rem;">The locking mechanisms for the port and starboard accommodation watertight doors were not available.</span></p><p>The hatch cover was the folding type and covered by tarpaulins as a securing device.&nbsp;<span style="color: rgb(33, 37, 41);">The rubber seals on two (2) out of a total of twelve (12) hatch cover panels were not available.</span>&nbsp;The winch and windlass are generally in fair condition and good operation. The vessel was fitted with 1 (one) cargo hold.</p><p><br></p><p><span style="font-weight: bolder;"><u>BALLAST TANKS</u></span></p><p data-start="141" data-end="393">Internal tank inspection was carried out only for the forepeak tank, which was found to be in fair condition. Further inspection of other ballast tanks, including the double bottom tanks, is recommended to ascertain the overall internal condition.</p><p></p><p data-start="395" data-end="545">Inspection of the double bottom ballast tanks could not be carried out at the time of survey due to ongoing cargo loading and unloading operations.</p><p data-start="395" data-end="545"><br></p><p data-start="395" data-end="545"><span style="font-weight: bolder;"><u>BRIDGE DECK AND NAVIGATION</u></span></p><p data-start="395" data-end="545">The navigation and communication equipment were tested and found to be in good condition, and were considered adequate for the vesselâs domestic trading area within Indonesian waters.</p><p data-start="395" data-end="545">The updated Indonesia Notice to Marine (NTM) was available onboard and updated. The vessel was provided with updated charts and bridge management records. The deck logbook was generally well maintained and up to date.</p><p data-start="395" data-end="545"><br></p><p data-start="395" data-end="545"><span style="font-weight: bolder;"><u>MACHINERY SPACE AND STEERING GEAR</u></span></p><p data-start="152" data-end="402">The vessel is fitted with 1 (one) main engine, 1 (one) auxiliary engine, and 2 (two) generator sets, which were tested and found to be in good running condition at the time of our attendance. The engine logbook was found to be regularly updated.</p><p data-start="395" data-end="545"></p><p data-start="404" data-end="541">The emergency steering gear and emergency generator were tested in accordance with emergency procedures and found to be in good order.</p><p data-start="395" data-end="545"><br></p><p data-start="395" data-end="545"><span style="font-weight: bolder;"><u>SAFETY AND POLLUTION</u></span></p><p data-start="395" data-end="545">The vessel was provided with a SOPEP and oil absorbent materials. The bunkering connection pipelines were found to be in good order. The fuel tank air vents and sounding pipes were observed to be in good order. Scupper plugs were available on board.</p>', '<p data-start="1845" data-end="2033">The survey on board the general cargo vessel âINDAH VIRGOâ was conducted on 05 April 2026 at the Port of Sunda Kelapa, Jakarta. The vessel was generally found to be in fair condition.</p><p data-start="2035" data-end="2274">However, deficiencies were noted in the watertight door arrangements and hatch cover sealing, which may affect the vesselâs watertight integrity and cargo protection.&nbsp;</p><p>nn</p><p data-start="2276" data-end="2492">Inspection of ballast tanks was limited due to ongoing cargo operations, and therefore the overall internal condition could not be fully ascertained. Further inspection and necessary rectification are recommended.</p>', '2026-02-23', '2027-02-23', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (670, 503, 13, 9, 'Miftah Wibowo', 'Survey', 'Completed', 'complete', 'Port of Sunda Kelapa, Jakarta', '2026-04-12', '2026-03-25', '<li data-section-id="dnncf1" data-start="136" data-end="330">The cargo hold bilge is not fitted with a fixed bilge suction system and is currently handled manually using a portable pump, which may affect efficiency in emergency dewatering situations.n</li><li data-section-id="rf2ysh" data-start="332" data-end="513">nBallast tank pressure testing could not be conducted at the time of survey due to shallow water conditions; therefore, the tightness of the ballast tanks could not be verified.n</li><li data-section-id="1l87d8g" data-start="515" data-end="664">nChangeover instructions for the emergency steering gear were not available on board, which may affect crew response during emergency situations.n</li><li data-section-id="415xu9" data-start="666" data-end="819">nThe vessel was not provided with a SOPEP locker and oil absorbent materials, indicating non-compliance with basic pollution prevention requirements.n</li><li data-section-id="19onbyo" data-start="821" data-end="943">nScupper plugs were not available on board, which may increase the risk of overboard pollution during deck operations.n</li><p>nnnnn</p><li data-section-id="8tywbo" data-start="945" data-end="1113">nSave-alls/drip trays for the forward winch, stern winch, and bunkering connection were not available, posing a risk of oil leakage and environmental contamination.</li>', '<p>The survey on board the general cargo vessel&nbsp; "INDAH ABADI" was conducted on 12 April 2026 at the Port of Sunda Kelapa, Jakarta, Indonesia with the following attendances:</p><p>1. Nasrun Samin&nbsp;&nbsp;&nbsp;-&nbsp;&nbsp; &nbsp; Master of the vessel</p><p>2. Irfan Wahyudi&nbsp;&nbsp;&nbsp;&nbsp;-&nbsp;&nbsp; &nbsp; Chief Officer of the vessel</p><p>3. Syahrazat&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-&nbsp;&nbsp; &nbsp; Chief Engineer of the vessel</p><p>4. Edy Suprapto&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-&nbsp;&nbsp; &nbsp; Owner Representative</p><p>General cargo "INDAH ABADI" is 1,200 GT presently owned and operated by PT Bintan Megah Abadi, Jakarta. At the time of survey, the vessel was berthed at Port of Sunda Kelapa, Jakarta for unloading and loading cargo operations. Furthermore, the vessel''s trading area is within Indonesian waters.</p><p><br></p><p><span style="font-weight: bolder;"><u>VESSEL CERTIFICATION AND DOCUMENTATION</u></span></p><p>Class survey records for hull, machinery, and load line were made available at the time of the survey and the class status was maintained. The statutory certificates were found to be valid and not overdue for the next inspection schedule and renewal.</p><p>The thickness measurement (UTM) report was available on board. Based on provided report, the diminution level of the vessel''s steel structures was found to be below the class maximum allowable limit of 20%.</p><p><br></p><p><span style="font-weight: bolder;"><u>GENERAL CONDITION OF HULL AND DECK</u></span></p><p>As far as could be ascertained, the starboard and port side shell plating from aft to fore, and from the sheer strake down to the waterline, were visually found to be in fair condition, with no doublers observed, and the paint coating in good condition. The draft marks and load lines were clearly marked and visible.</p><p>At the time of our attendance, the visible condition of the deck plating on the forecastle, main deck, forepeak, and poop deck, was found to be in fair condition. The starboard and port bulwarks, and railings on the forecastle, main deck and poop deck were found in order.</p><p>The fuel air ventilation, sounding pipe, and air ventilation was found in good order.<span style="font-size: 0.875rem;">&nbsp;The winch and windlass are generally in fair condition and good operation. The vessel was fitted with 1 (one) cargo hold.&nbsp;</span><span style="font-size: 0.875rem;">The internal condition of the cargo hold was found to be in fair condition. The cargo hold bilge was not equipped with a bilge suction system and was cleaned manually using a portable pump.</span></p><p><span style="font-size: 0.875rem;"><br></span></p><p><b><u>BALLAST TANKS</u></b></p><p>Internal tank inspection was carried out&nbsp;<span style="color: rgb(33, 37, 41); font-size: 0.875rem;">on 2 (two) ballast tanks, which consist of wing tank No. 2P and 3S.&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">The ballast tanks, complete with the internal structure, were found in fair condition.&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Ballast tank pressure test could not be carried out at the time of the survey due to shallow water conditions.</span></p><p><span style="color: rgb(33, 37, 41); font-size: 0.875rem;"><br></span></p><p><b><u>BRIDGE DECK AND NAVIGATION</u></b></p><p>The navigation and communication equipment were tested and found to be in good condition, and were considered adequate for the vessel''s domestic trading area within Indonesian waters.</p><p>The updated Indonesia Notice to Marine (NTM) was available onboard and updated. The vessel was provided with updated charts and bridge management records. The deck logbook was generally well maintained and up to date.</p><p><br></p><p><b><u>MACHINERY SPACE AND STEERING GEAR</u></b></p><p>The vessel id fitted with 1 (one) main engine, 1 (one) auxiliary engine, and 2 (two) generator sets, which were tested and found to be in good running condition at the time of our attendance. The engine logbook was found to be regularly updated.</p><p>The emergency steering gear and emergency generator were tested in accordance with emergency procedures and found to be in good order. Changeover instruction from emergency steering not available on board.</p><p><br></p><p><b><u>SAFETY AND POLLUTION</u></b></p><p>The vessel was not provided with SOPEP locker and oil absorbent. The bunkering connection pipelines were found to be in good order. The fuel tank air vents and sounding pipes were observed to be in good order. Scupper plugs were not available on board. Save-alls/drip trays for the forward winch, stern winch, and bunkering connection were not available.</p>', '<p data-start="24" data-end="509">Based on the survey conducted on board the general cargo vessel "INDAH ABADI"<i>&nbsp;</i>the overall condition of the vessel was found to be generally in fair to good condition, with hull, deck, machinery, and navigation systems maintained in satisfactory order for its domestic trading operations within Indonesian waters. Class and statutory certificates were valid, and no major structural deficiencies were identified based on visual inspection and available thickness measurement records.</p><p data-start="511" data-end="1020">However, several deficiencies were noted during the survey, particularly related to safety and pollution prevention arrangements. These include the absence of a fixed cargo hold bilge suction system, unavailability of SOPEP equipment and oil absorbents, lack of scupper plugs, missing save-alls/drip trays at key locations, and absence of emergency steering changeover instructions. In addition, ballast tank pressure testing could not be carried out, and therefore tank integrity could not be fully verified.</p><p>nn</p><p data-start="1022" data-end="1232" data-is-last-node="" data-is-only-node="">Overall, while the vessel remains operational, the above-mentioned deficiencies should be rectified to enhance safety, operational reliability, and compliance with marine regulations and good industry practice.</p>', '2026-02-23', '2027-02-23', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (671, 504, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-04-17', NULL, NULL, NULL, '2026-03-18', '2027-03-18', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
