INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (674, 505, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-03-27', NULL, NULL, NULL, '2026-02-25', '2027-02-25', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (675, 506, NULL, 9, NULL, 'Survey', 'Cancelled', 'draft', NULL, NULL, '2026-03-31', NULL, NULL, NULL, '2026-03-01', '2027-03-01', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (676, 507, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-04-02', NULL, NULL, NULL, '2026-03-03', '2027-03-03', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (677, 508, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-19', '2027-09-19', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (678, 509, 8, 9, 'EPRASETYA NUGRAHA, S.T., M.T.', 'Survey', 'Completed', 'complete', 'GRESIK ANCHORAGE, EAST JAVA, INDONESIA', '2026-05-15', '2026-04-08', '<p><span style="font-weight: bolder;"><u>Structural Compliance with general marine industry standards</u></span></p><p><span style="font-weight: bolder;"><u>SHIP''S CERTIFICATE</u></span></p><ul><li>UTM Report was found unavailable on board.</li></ul><p><span style="font-weight: bolder;"><u>BRIDGE AND NAVIGATION</u></span></p><ul><li>Paper Charts were found not corrected with the latest NTM.</li><li>Changeover Instructiron for Emergency Steering was found not posted.</li></ul><p><span style="font-size: 0.875rem;"><span style="font-weight: bolder;"><u>POLLUTION PREVENTIONS</u></span></span></p><ul><li>SOPEP was found insufficient.</li><li>Steel Save-Alls/ Drip Trays were found not fitted on the Anchor Windlass, Aft Winch, and Hydraulic Control System of the Hatch Cover.</li><li>Scupper Plugs were found unavailable on board.</li><li>Oil Absorbent was found unavailable on board.</li></ul><p><span style="font-weight: bolder;"><u>HULL AND DECK STRUCTURAL CONDITIONS</u></span></p><ul><li>The main deck was found rusty.</li><li>Forward Deck between Forecastle Deck &amp; Cargo Hold, and Coaming Stay were found rusty and paint peel-off.</li><li>The forward hydrant valve was found missing.</li><li>Hydrant Pipelines on the Main Deck (Fwd) were found to be leaking.</li><li>Bulwarks were found rusty.</li><li>Bilge Suction test has not been carried out due to safety reasons.</li><li>Cargo Hold Bilge Well was found with sludge and cargo residue.</li><li>Rubber Sealing of Hatch Cover Panels was found hardened.</li></ul><p style=""><span style="font-weight: bolder;"><u>BALLAST TANKS</u></span></p><ul><li>Internal Structure of the Ballast Tanks has not been inspected due to the manholes were found in steel welded conditions.</li></ul><div bis_skin_checked="1"><span style="font-size: 0.875rem;"><b><u>BRIDGE MANAGEMENT</u></b></span></div><div bis_skin_checked="1"><span style="font-size: 0.875rem;">Implemented by the shipâs crew, but it can still be improved.</span></div><div bis_skin_checked="1"><br></div><div bis_skin_checked="1"><u style="font-weight: 700; text-indent: -23.8px;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">NAVIGATIONAL EQUIPMENT</span></u></div><div bis_skin_checked="1"><span lang="EN-US" style="text-indent: -11.6px; line-height: 20px;">Navigation and Communication were </span><span lang="IN" style="text-indent: -11.6px; line-height: 20px;">found </span><span lang="EN-US" style="text-indent: -11.6px; line-height: 20px;">fitted</span><span lang="IN" style="text-indent: -11.6px; line-height: 20px;"> on board</span><span lang="EN-US" style="text-indent: -11.6px; line-height: 20px;"> and apparently in satisfactory condition.&nbsp;</span></div><div bis_skin_checked="1"><br></div><div bis_skin_checked="1"><span style="text-indent: -23.8px;"><span lang="EN-GB" style="line-height: 20px;"><span style="font-weight: bolder;"><u>COMPETENT OFFICER</u></span></span></span></div><div bis_skin_checked="1"><span style="text-indent: -23.8px;"><span lang="EN-GB" style="line-height: 20px;">The Officer and crew appeared to be competent; all certificates complied with the STCW standard.</span></span></div><div bis_skin_checked="1"><span style="text-indent: -23.8px;"><span lang="EN-GB" style="line-height: 20px;"><br></span></span></div><div bis_skin_checked="1"><u style="font-weight: 700; text-indent: 9.46667px;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">INTERASSOCIATION OF OFFICERS AND CREW</span></u><span style="text-indent: -23.8px;"><span lang="EN-GB" style="line-height: 20px;"><br></span></span><span style="font-size: 13.3333px;">The entire crew has good cooperation during the survey.</span></div>', '<p class="MsoNormal" style="text-align: justify;">The Wreck Removal &amp; Oil Pollution Survey of MV âBEN 10â was conducted on 15 May 2026 whilst the vessel was anchored at Gresik, East Java, Indonesia, waiting for berthing scheduled.<o:p></o:p></p><p class="MsoNormal" style="text-align: justify;">During the survey, we were accompanied and assisted by the Chief Officer, Chief Engineer, and crew.<o:p></o:p></p><p class="MsoNormal" style="text-align: justify;"><span style="font-weight: bolder;">HULL</span><o:p></o:p></p><p class="MsoNormal" style="text-align: justify;">MV. BEN 10 is a 37-year-old vessel and was built by MITSUBISHI HEAVY INDUSTRIES CO., LTD. - JAPAN in 1989. The vessel was a single-hull steel General Cargo with dimensions: LOA: 76.70 m, LPP = 72.60 m, B = 12.00 m, H = 6.50 m, GT 1,403, and NT 769. The Vessel was registered at Tanjung Priok and under the classification of Biro Klasifikasi Indonesia (BKI).<o:p></o:p></p><p class="MsoNormal" style="text-align: justify;">The vessel is reported to have a valid Class Certificate, i.e., Hull &amp; Machinery Class Certificate, Tonnage Certificate, and Load Line Certificate, as well as a Statutory Certificate. The visible shell plating was found slightly rusty but still in satisfactory condition. However the UTM Report was found unavailable on board.<o:p></o:p></p><p class="MsoNormal" style="text-align: justify;">During the survey, we found that the Main Deck was found to be rusty in several areas; however, still in fair condition. The Superstructure and accommodation space were found in fair condition.<span style="font-size: 10pt; line-height: 14.2667px; font-family: " arial="" narrow",="" sans-serif;"=""> </span><span lang="EN-US">Forward Deck between Forecastle Deck &amp; Cargo Hold, and Coaming Stay were found rusty and peel-off paint.</span><span lang="EN-US"> </span>Forward Hydrant Valve was found missing. Hydrant Pipelines on the Main Deck (Forward) were found leakage. Bulwarks were found rusty. Hatch Cover Panels were found rusty at several areas. Rubber Sealing of Hatch Cover Panels were found hardened.<o:p></o:p></p><p class="MsoNormal" style="text-align: justify;"><o:p>&nbsp;</o:p></p><p class="MsoNormal" style="text-align: justify;"><span style="font-weight: bolder;">CARGO HOLDS/ COMPARTMENTS</span><o:p></o:p></p><p class="MsoNormal" style="text-align: justify;">The vessel is fitted with one (1) cargo hold and equipped with 1 (one) crawler crane.<o:p></o:p></p><p class="MsoNormal" style="text-align: justify;">The internal structure and Tank Top of the Cargo Hold were found still in fair condition. The cargo holds are fitted with folding-type hatch covers, covered with 2 (two) layers of tarpaulins. The cargo hold bilge suction test was not conducted due to safety reasons.<o:p></o:p></p><p class="MsoNormal" style="text-align: justify;">Hose test of the hatch covers has been carried out and found No Leakage.<o:p></o:p></p><p class="MsoNormal" style="text-align: justify;">During the survey, the superstructure and accommodation spaces were found satisfactory. The main deck was found rusty. The top plates and stanchions of the hatch coamings/coaming stays were found rusty and paint peel-off. The bulwarks were found rusty.<o:p></o:p></p><p class="MsoNormal" style="text-align: justify;"><o:p>&nbsp;</o:p></p><p class="MsoNormal" style="text-align: justify;"><span style="font-weight: bolder;">NON-CARGO TANKS</span><o:p></o:p></p><p class="MsoNormal" style="text-align: justify;">The vessel is fitted with six (6) water ballast tanks (1C, 2P/S, 3P/S, 4C), one (1) fore peak tank (FPT), one (1) aft peak tank (APT), Fresh Water Tanks (FWT P/S) and Separated Bilge Oil Tanks.<o:p></o:p></p><p class="MsoNormal" style="text-align: justify;">Ballast overflow pressure test has been carried out and found NO Leakage/ Contamination. For the inspection of the internal structure of the water ballast tanks were not carried out due to the Manholes were found steel welded.<o:p></o:p></p><p class="MsoNormal" style="text-align: justify;"><span style="font-weight: bolder;">MACHINERY</span><o:p></o:p></p><p class="MsoNormal" style="text-align: justify;">The vessel is equipped with:<o:p></o:p></p><ul type="disc" style="margin-top: 0cm;"><li class="MsoNormal" style="text-align: justify;">One (1) unit AKASAKA Main Engine, Type K28FD, rated 1,400 HP at 400 RPM<o:p></o:p></li><li class="MsoNormal" style="text-align: justify;">Two (2) units MITSUBISHI Auxiliary Engines, Type 6D14-MPT, rated 120 HP<o:p></o:p></li><li class="MsoNormal" style="text-align: justify;">Two (2) units NISHISHIBA ELECTRIC Generator, Type NTAKL-VEK rated 100 kVA<o:p></o:p></li><li class="MsoNormal" style="text-align: justify;">Two (2) units MITSUBISHI Generator 3A, with No Details<o:p></o:p></li><li class="MsoNormal" style="text-align: justify;">One (1) unit Emergency Generators (No details information), located on the poop deck<o:p></o:p></li></ul><p class="MsoNormal" style="text-align: justify;">The engine room is located aft.<o:p></o:p></p><p class="MsoNormal" style="text-align: justify;">The Machinery reported has been good working order.<o:p></o:p></p><p class="MsoNormal" style="text-align: justify;"><span style="font-weight: bolder;">POLLUTION</span><o:p></o:p></p><p class="MsoNormal" style="text-align: justify;">Bunker manifolds and fuel air vents were found in fair condition. Save-alls / drip trays were fitted; However, the Anchor Windlass, Aft Winch and Hydraulic Control of Hatch Cover were found without Steel Save-Alls. SOPEP was found insufficient. Scupper plugs were found unavailable. Oil absorbent materials were not available at the time of survey.<o:p></o:p></p><p class="MsoNormal" style="text-align: justify;"><span style="font-weight: bolder;">NAVIGATION</span><o:p></o:p></p><p class="MsoNormal" style="text-align: justify;">Navigation and communication equipment fitted on the bridge includes Gyro Compass, Magnetic Compass, Radar, Echo Sounder, AIS, GPS, and VHF radios.<o:p></o:p></p><p class="MsoNormal" style="text-align: justify;">Navigational charts were sufficient for the vesselâs trading area; however, they were not corrected up to the latest Notices to Mariners. BPI publications were reported regularly supplied onboard.<o:p></o:p></p><p style="text-align: justify;"></p><p class="MsoNormal" style="text-align: justify;">Changeover instructions for emergency steering were not posted and displayed.</p>', '<p>The vessel was found in fair structural condition. However, several items need to be repaired/rectified.</p>', '2026-01-27', '2027-01-27', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (679, 510, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, '2026-01-27', '2027-01-27', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (680, 50, 8, 9, 'FAJAR TRIHASTYANTO KUNCORO', 'Survey', 'Completed', 'complete', 'SURABAYA ANCHORAGE, SURABAYA', '2026-03-16', '2026-05-02', '<p class="MsoNormal"><span style="font-weight: bolder;"><u>Structural compliance with general marine industry standards</u></span></p><ul><li><span style="color: rgb(33, 37, 41);">Port side FOT air vent was found corroded/ broken</span></li><li><span style="color: rgb(33, 37, 41);">Save-alls were found not fitted on Bunker manifolds, Fuel air vents, Hatch covers hydraulic operating handle, and Anchor windlass & aft mooring winches hydraulic operating handle</span></li><li><span style="color: rgb(33, 37, 41);">Scupper plugs were found not available</span></li><li><span style="color: rgb(33, 37, 41);">Oil absorbent was found not available</span></li><li>Main deck was found rusty at port and starboard side of cargo hold</li><li>Hatch coaming was found heavy corroded</li><li>Derrick deck foundations were found heavy corroded</li><li>Bulwark was found heavy corroded</li><li>Most of the railing were found heavy corroded, dented, and partly missing</li><li>Boat deck was found messy</li><li>Anchor windlass and Aft Mooring winch foundations were found corroded</li><li>Mooring lines of port side Anchor & mooring windlass, and Starboard side Aft mooring winches were found abrasive</li><li>Hydrant pipe at starboard side main deck was found corroded and tightened with rubber ban</li><li>Hydraulic systems (Pipelines and Hydraulic engine) of derricks (Aft and Fore) were found leakages</li><li><span style="color: rgb(33, 37, 41);">Hatch of emergency exit manhole, Hatch of manhole access to fore peak tank, and most of Watertight doors were found heavy corroded</span></li><li><span style="color: rgb(33, 37, 41);">Ventilation cover of steering gear room found missing</span></li><li><span style="color: rgb(33, 37, 41);">Cargo hold bilge wells were found heavy rusty and not clean with cargo residue</span></li><li><span style="color: rgb(33, 37, 41);">Suction test has not been carried out due to malfunction of suction system</span></li><li><span style="color: rgb(33, 37, 41);">Rubber sealing of Hatch covers were found hardened and not properly fitted</span></li><li><span style="color: rgb(33, 37, 41);">Hydraulic pipe of Hatch covers was found leakages</span></li><li><span style="color: rgb(33, 37, 41);">WBT overflow/ pressure test has not been carried out due to operational reasons</span></li><li><span style="color: rgb(33, 37, 41);">Steering gear room was found flooded with oily water</span></li></ul><p class="MsoNormal"><span style="font-weight: bolder;"><u>Bridge Management<o:p></o:p></u></span></p><p style="margin-bottom: 0cm; text-align: justify; text-indent: -18pt; line-height: 21px;"></p><p class="MsoNormal">Implemented by shipâs crew but still can be improved.</p><p class="MsoNormal"><span style="font-weight: bolder;"><u>Navigational equipment<o:p></o:p></u></span></p><p class="MsoNormal"></p><p class="MsoNormal" style="text-align: justify;">The navigation and communication were found fitted on board and apparently in satisfactory condition. NTM/ BPI was supplied on board regularly. Charts were found not updated as per latest NTM/ BPI. The Changeover instructions from emergency steering was found not posted / displayed.</p><p class="MsoNormal"><span style="font-weight: bolder;"><u>Competent of Officers</u></span></p><p class="MsoNormal" style="text-align: justify;"></p><p class="MsoNormal">The Officer and crew appeared to be competent; all certificates complied as per STCW standard.</p><p class="MsoNormal"><span style="font-weight: bolder;"><u>Interassociation of Officers and Crew<o:p></o:p></u></span></p><p class="MsoNormal"><o:p></o:p></p><p class="MsoNormal">Â All crew have good cooperation during the survey.</p>', '<p class="MsoHeader" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">The Wreck Removal & Oil PollutionÂ </span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="line-height: 18px;">survey</span><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">Â of MV. âBunga Teratai XXIâ was conducted on 16 March 2026, whilst she anchored at Tanjung perak anchorage, Surabaya, Indonesia waiting for cargo loading operation. During the survey, we were accompanied/ assisted by the Chief Officer, Chief Engineer and crew.</span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;"><u>HULL</u></span><o:p></o:p></span></span></p><p style="text-align: justify; line-height: 21px;"><span tahoma",sans-serif"="" style="line-height: 18px;">MV. Bunga Teratai XXI is 39 years old vessel, t</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">heÂ </span><span tahoma",sans-serif"="" style="line-height: 18px;">vessel</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="line-height: 18px;">Â was</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:en-gb"="" style="line-height: 18px;">Â </span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">a</span><span tahoma",sans-serif"="" style="line-height: 18px;">Â single hullÂ </span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">steel</span><span tahoma",sans-serif"="" style="line-height: 18px;">Â General Cargo with dimensionÂ </span><span style="line-height: 18px;">LPP = 72.00 m, B</span><span style="line-height: 18px;">Â </span><span style="line-height: 18px;">= 12.00 m, H = 6.50 m</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">, GT 1368 and NT 477.</span><span style="color: red; font-size: 14px;">Â </span><span style="font-size: 14px;">The Vessel was registered at Surabaya and under Classification of Biro Klasifikasi Indonesia (BKI). The vesselÂ </span></span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">wasÂ </span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">built by Shimonoseki Shipyard & Machinery Works, Japan</span><span style="color: red; font-size: 14px;">Â </span><span style="font-size: 14px;">in 1987.Â <span style="background-color: rgb(255, 255, 255);">Reported, the vessel has a valid Class Certificate i.e: Hull & Machinery</span></span></span><span style="background-color: rgb(255, 255, 255);"><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="line-height: 18px;">Â Class</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">Â Certificate, Tonnage Certificate and Load Line Certificate as well as a Statutory Certificate.</span></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">During the survey, we found that the Shell plating was found in fair condition.Â </span><span style="font-size: 0.875rem;">Superstructure and accommodation space were found satisfactory. ButÂ </span><span style="font-size: 0.875rem;">Main deck was found rusty on port and starboard side of cargo hold.Â </span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">CARGO HOLDS / COMPARTMENTS</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">The Vessel was fitted with 1 (one) Cargo Hold and fitted with 3 (three) derricks. TheÂ </span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Internal structure of cargo hold was found in fair condition but found cargo residue of cement on tank top</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">. TheÂ </span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Cargo hold bilges was found heavy rusty and not clean with cargo residue. Suction test has not been carried out due to malfunction of suction system. The Hatch covers was found in satisfactory condition, but Rubber sealing was found hardened and not properly fitted. Hydraulic pipe of Hatch covers was found leakages.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">NON-CARGO TANKS:</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">TheÂ </span><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">V</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">esselÂ </span><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">fitted with 5 WBT (2 â 3 (P & S) and 1 C), Fore peak and After peak Tanks. TheÂ <span style="color: rgb(33, 37, 41); text-align: left;">Internal structures of WBT were found in fair condition, butÂ </span></span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">WBT overflow/ pressure test has not been carried out due to operational reasons.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">MACHINERY</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">The Vessel was equipped with 1 (one) unit of Akasaka Type 6K 28 FD with 1,400 HP x 400 Rpm and equipped with 2 (two) unit Auxiliary Engine Mitsubishi Type 6D 14-MPT 2 x 120 HP (in Engine room), 1 (one) unit Auxiliary engine with (no data in engine room) and 2Â </span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">(two) unit Emergency Generator (no data) on boat deck.</span><span style="color: red; font-size: 14px;">Â </span><span style="font-size: 14px;">The Engine Room was located in the aft area. Main Engine, Auxiliary Engine and Emergency generator reported in working order. Â Â </span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">POLLUTION</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">SOPEP box and equipment was found available. Bunker connections were found in fair conditions. Port side FOT</span></span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Â air vent was found corroded/ broken. Scupper plugs were found not available. Oil absorbent was found not available. S</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">ave-alls were found not fitted on Bunker manifolds, Fuel air vents, Hatch covers hydraulic operating handle, and Anchor windlass & aft mooring winches hydraulic operating handle.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">NAVIGATION</span><o:p></o:p></span></span></p><p></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">Navigation and communication fitted on the Bridge such Magnetic Compass, Radar, AIS, Echo Sounder, GPS, VHF Radios etc.Â </span><span style="font-size: 0.875rem;">NTM / BPI was found supplied on board regularly.Â </span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 0.875rem; line-height: 18px;">Navigational Charts were sufficient for trading area but not updated as per latest BPI. C</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">hangeover instructions for Emergency Steering were found posted/ displayed.</span></p>', '<p>The vessel was found in satisfactory structural condition but several items to be repaired/rectified.Â </p>', '2026-04-02', '2027-04-02', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (681, 511, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-04-04', NULL, NULL, NULL, '2026-03-05', '2027-03-05', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (682, 512, 8, 9, 'Twin Suganda Syahputra Aruan', 'Survey', 'Completed', 'complete', 'PT. Inti Lingga Sejahtera Terminal', '2026-04-02', '2026-04-08', '<p class="MsoNormal"><b><u><span lang="EN-GB">Structuralrncompliance with general marine industry standards</span></u></b><o:p></o:p></p><p class="MsoNormal">-Â The save-all of mooring windlass at forepeak area was found corrosion and wastage<o:p></o:p></p><p class="MsoNormal">- 1 of roller at stern starboard was found loss<o:p></o:p></p><p class="MsoNormal">- Vessel not equipped with Emergency Generator</p><p class="MsoNormal"><b><u><span lang="EN-GB">BridgernManagement.</span></u></b><o:p></o:p></p><p class="MsoNormal"><span lang="EN-GB">Implementedrnby shipâs crew but still can be improved.</span><o:p></o:p></p><p class="MsoNormal"><b><u><span lang="EN-GB">Navigationalrnequipment</span></u></b><o:p></o:p></p><p class="MsoNormal"><span lang="IN">TheÂ </span><span lang="EN-US">navigation andrncommunication wereÂ </span><span lang="IN">foundÂ </span><span lang="EN-US">fitted</span><span lang="IN">Â on board</span><span lang="EN-US">Â and apparently in satisfactory condition.</span><o:p></o:p></p><p class="MsoNormal"><b><span lang="EN-GB"><u>Competentrnof Officers</u></span></b><o:p></o:p></p><p class="MsoNormal"><span lang="EN-GB">The Officerrnand crew appeared to be competent; all certificates complied as per STCWrnstandard.</span><o:p></o:p></p><p class="MsoNormal"><b><u><span lang="EN-GB">Interassociationrnof Officers and Crew</span></u></b><o:p></o:p></p><p>rnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrn</p><p class="MsoNormal"><span lang="EN-GB">Â All crew have good cooperation during the survey.</span><o:p></o:p></p>', '<p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph"><span lang="EN-US">The Wreck Removal & OilrnPollutionÂ </span><span lang="IN">survey</span><span lang="EN-US">Â of MT. âNAGATOâ was conductedrnon 02 April 2026, whilst she berthed at PT. Inti Lingga Sejahtera Terminal, Merakrnâ Indonesia purpose for loading operation. During the survey, we havernaccompanied/ assisted by ownerâs representative, Master, Chief Officer, ChiefrnEngineer and crew.</span><o:p></o:p></p><p class="MsoNormal"><b><span lang="EN-US">HULL</span></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph">MT. "NAGATO" is 35 years old vessel, t<span lang="IN">heÂ </span>vessel<span lang="IN">Â designedrnwithÂ a</span>Â single hullÂ <span lang="IN">steel welded construction oil tanker </span>with dimensionÂ LPP = 61.00rnm, BÂ = 10.20 m, H = 4.50 m, GT 736 and NT 369.Â The Vessel wasrnregistered at Tanjung Priok and under Classification of Biro KlasifikasirnIndonesia (BKI). The vesselÂ <span lang="IN">wasÂ </span>builtrnby Kanmon Shipbuilding Co,.Ltd, JapanÂ in 1991.Â The interim Classificationrncertificate for Hull & Machinery<span lang="IN">Â Class</span>Â were available on board. The Nationality, MinimumrnSafe Manning, Load line certificate and Tonnage Certificate were sighted onrnboard. The Cargo Ship safety construction, equipment and radio were sighted onrnboard.Â <span lang="IN">The visible shellrnplating was found in good condition and well coating. The shipâs name, plimsolrnand draft marks were clearly legible. </span><o:p></o:p></p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph"><span lang="EN-US">During the survey, we found theÂ </span>Superstructurernand accommodation space were in satisfactory. The deck fitting such asrnwindlass, anchor chain, cargo pipe line, valve, air vents, sounding point,rncargo lids, manhole cover and handrails were found in well condition except thernroller at aft starboard which was found loss and the save-all of windlass atrnforecastle which was found wastage condition. The watertight door throughout vesselrnfound with IMO symbol/ Sign posted. Â <o:p></o:p></p><p class="MsoNormal"><b><span lang="EN-US">CARGOrnHOLDS / COMPARTMENTS</span></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph"><span lang="EN-US">The Vessel was fitted with 8 COT (1 ârn4 P/S). TheÂ </span>Internal structure of cargo oil tank was found in goodrncondition. The lids, cleats and rubber sealing were found in good condition.rnThe cargo pipeline and valve were found in good condition. Cargo manifold was foundrnin good condition and provided with oil spill box.<o:p></o:p></p><p class="MsoNormal"><b><span lang="EN-US">NON-CARGOrnTANKS:</span></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph"><span lang="EN-US">TheÂ Internal structures of WBTrnwere found in fair condition.Â </span>Ballast tank pressure test has beenrncarried out and found satisfactory, no leakage found. <o:p></o:p></p><p class="MsoNormal"><b><span lang="EN-US">MACHINERY</span></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph">1rnunit Diesel engine Akasaka powered with 1000 HP at 376 RPM, built at AkasakarnDiesel Ltd, Japan, connected with gear box Nico 1300 PS at 440 RPM and gear boxrnshaft generator Nico 217 PS at 1200 RPM for main propulsion. Â Equipped with 2 (two) units auxiliary engine :rnMitsui Deutz 135 and 68 PS at 2 x 1800 RPM. The main engine and auxiliaryrnengine were tested and found in good working order. The vessel not equippedrnwith emergency generator.</p><p class="MsoNormal"><b><span lang="EN-US">POLLUTION</span></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph"><span lang="EN-US">The vessel fitted with SOPEP room. ThernSOPEP Equipment was adequately available as regulation for the vessel type. TheÂ </span>fuelrnair vents were found fitted with save-all. The Scupper plugs were foundrnavailable. Bunker Station was found in good condition and fitted with save-all.rnThe cargo manifolds area was found fitted with oil spill box. The save-all of hydraulicrnoperating handle of Anchor & Mooring Windlass was found wastage condition.rnOil absorbents were found available on board and well stored in SOPEP room. <o:p></o:p></p><p class="MsoNormal"><b><span lang="EN-US">NAVIGATION</span></b><o:p></o:p></p><p>rnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrn</p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph"><span lang="EN-US">The NTM / BPI was found supplied onrnboard regularly, Navigation and communication equipment fitted on the wheelhousernsuch Gyro Compass (Tokimec ES 11-A), Magnetic Compass (Tokimec GH MAS C8K9),rnRadar (Furuno FR-1815), Navtex (Samyung SNX-300),GPS navigator (Furuno GP-32),rnGPS Tracking (Vamos), AIS (Icom MA 500-TR), Echo Sounder (Furuno FCV 688), VHFrnRadios, Auto Pilot (Tokimec PR-2000), etc. Navigational Charts were sufficientrnfor trading area and updated as per latest NTM/ BPI. C</span>hangeoverrninstructions for Emergency Steering were found posted/ displayed.<o:p></o:p></p>', '<p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph"><span lang="EN-GB">Â </span><span style="font-size: 0.875rem;">Thernvessel was found in satisfactory structural condition but several items to bernrepaired/rectified. Save-alls to be fitted on operating handle of Anchor &rnMooring Windlass. The roller to be repair and emergency generator to be provide.</span></p>', '2026-03-09', '2027-03-09', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (683, 513, 8, 9, 'Twin Suganda Syahputra Aruan', 'Survey', 'Completed', 'complete', 'Samarinda, East Kalimantan', '2026-04-27', '2026-04-08', '<ol><li><span lang="EN-GB" style="font-size: 10pt;">Fuel Air Vents not fitted with driprntray and fuel air ventilation at portside not marked with identification marks<o:p></o:p></span></li><li><span lang="EN-GB" style="font-size: 10pt;">Fore and aft windlass not fitted with save-all<o:p></o:p></span></li><li><span lang="IN" style="font-size:10.0pt;mso-bidi-font-size:rn12.0pt;mso-ansi-language:IN">Bollards and rollers not marked with SWL<o:p></o:p></span></li><li><span lang="EN-GB" style="font-size:10.0pt;mso-bidi-font-size:rn12.0pt;mso-ansi-language:EN-GB">Air vents and manhole cover of ballast tankrnwere found not marked with identification marks<o:p></o:p></span></li><li><span lang="EN-GB" style="font-size:10.0pt;mso-ansi-language:rnEN-GB">Sounding point not marked with identification marks<o:p></o:p></span></li><li><span lang="IN" style="font-size:10.0pt;mso-bidi-font-size:rn12.0pt;mso-ansi-language:IN">All weather tight door throughout vessel notrnmarked with IMO symbol and open/close marks</span></li><li><span lang="IN" style="font-size:10.0pt;mso-bidi-font-size:rn12.0pt;mso-ansi-language:IN">Access gate to emergency steering was foundrnobstructed</span><span lang="EN-GB"><o:p></o:p></span></li></ol>', '<p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph">Thernsurvey on vessel MT âZuishoâ wasrnconducted on 27 April 2026 while the vessel was berth at Jetty of PT IntirnLingga Samudera, Samarind for loading cargo operation.Â During the survey,rnwe were accompanied and assisted by the Master, Chief Officer, Chief Engineerrnand crews.<o:p></o:p></p><p class="MsoNormal"><b>HULL</b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph">MT âZUISHOârnis a 36 years old oil tanker, steel welded construction, designed with double hullrnand double bottom. The dimensions of vessel as per certificate are (L x B x D)rn45.04 x 7.80 x 3.30 meters with GT 391 and DWT 590 M/tonnes, Owned and operatedrnby PT. Inti Lingga Sejahtera, registered in Tanjung Priok and underrnclassification of Biro Klasifikasi Indonesia. She was built by KOA SANGYO CO,.rnLTD, Japan in 1990. All valid statutory and class certificate were sighted onrnboard. The latest of ultrasonic thickness report was valid with lastrnmeasurement is on 19 August 2024 by PT. Samudra Mitra Service in PT. Eka MultirnBahari Shipyard. <o:p></o:p></p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph">Thernvisible shell plating was found in good condition, no any corrosion and doublerrnis visible. The draught, plimsol and shipâs name were observed clearly legible.</p><p class="MsoNormal"><b>CARGO HOLDS, MAIN DECK, AND COMPARTMENT</b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph">Thernvessel is fitted with one 6 (1 â 3 P/S) cargo oil tank. The internal conditionrntank was found to be in good condition. The manhole lids and rubber gasket werernfound in maintained condition and marked with identification marks.Â <o:p></o:p></p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph">Duringrnthe survey, the superstructure and accommodation spaces were foundrnsatisfactory. The main deck such as catwalk, handrails, structural of windlass andrnanchor winch, mooring ropes, anchor chain and anchor were found in goodrncondition. However, the bollards and rollers not marked with SWL, <span style="mso-bidi-font-size:10.0pt;line-height:115%">air vents, manhole cover ofrnballast tank and sounding point were found not marked with identification marks,rnall weather tight door throughout vessel not marked with IMO symbol andrnopen/close marks and access gate to emergency steering room was found obstructed.rn<o:p></o:p></span></p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph"><span style="mso-bidi-font-size:10.0pt;line-height:115%">The LSA and FFA were found adequaternonboard and placed in suitable location.</span></p><p class="MsoNormal"><b>NON-CARGO TANKS</b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph">Thernvessel is fitted with 5 WBT (1 â 5 P/S), based on observation the internalrnstructure of ballast water tank was found in fair condition. No sign ofrncorrosion, wastage, crack and leaks is visible. <o:p></o:p></p><p class="MsoNormal"><b>MACHINERY</b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph">In generally,rnengine space was found clean and tidy condition, no oily and slippery. The enginernroom bilge well was found clean condition and bilge high level alarm found in order. <o:p></o:p></p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph">Thernvessel equipped with diesel engine Yanmar, type MF 24-UT, powered with 800 HPrnat 420 RPM as main engine propulsion and 2 units diesel engine Yanmar with typern6 CHL-TNA, powered with 122 HP at 1800 RPM of each as auxiliary engine. Thernmain and auxiliary engine were tested and found in working order. <o:p></o:p></p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph">1rnunit cargo pump Toshiba with type IKK at 1740 RPM, O.WS pump Yaskawa, type FEG atrn1730 RPM, bilge pump CMG Australia SGAT 112M-4 at 1450 RPM, 2-unit strippingrnpump Yaskaswa at 2 x 1100 RPM, 1 unit ballast pump Yaskawa at 1740 RPM, 1 unitrnLO pump Yaskawa at 1170 RPM and FO pump Yaskawa at 1150 RPM were noted to be inrnworking order. <o:p></o:p></p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph">Thernvessel fitted with emergency generator Wichai with type OOF5 JWJ at 1500 RPM, locatedrnat aft upper deck. During tested, found that the emergency generator not readyrnto use.</p><p class="MsoNormal"><b>POLLUTION</b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph">Bunkerrnstation was fitted with save-all and marked with identification marked. Cargornpipe manifold was equipped with oil spill box. Scupper plugs were found availablernand equipped nearest to drainage hole. There are 2 boxes of SOPEP which were locatedrnat P/S main deck. The SOPEP materials were found in adequate as per shipâs typernand regulation. However, <span lang="EN-GB" style="line-height: 115%;">Fuel Air Vents not fittedrnwith drip tray and fuel air ventilation at portside not marked withrnidentification marks</span><span lang="EN-GB" style="font-size:16.0pt;mso-bidi-font-size:rn18.0pt;line-height:115%"> </span>and <span lang="EN-GB" style="line-height: 115%;">Fore and aftrnwindlass not fitted with save-all.</span><span style="font-size:16.0pt;rnmso-bidi-font-size:18.0pt;line-height:115%"><o:p></o:p></span></p><p class="MsoNormal"><b>NAVIGATION</b><o:p></o:p></p><p>rnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrn</p><p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph">Navigationrnand communication equipment fitted on the bridge such as Magnetic Compass,rnRadar, AIS, GPS, Navtex, Echosounder, VHF radios and SSB radio.Â BPI/ NTMrnwas found regularly supplied onboard and the charts for vesselâs trade were foundrncorrected with BPI/NTM.Â Changeover instruction for emergency steering wasrnposted and displayed. The navigation light and panels were found in order.Â <o:p></o:p></p>', '<p class="MsoNormal">The vessel was found in fair structural condition. However,rnseveral items need to be repaired/rectified.<o:p></o:p></p>', '2026-03-09', '2027-03-09', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (684, 17, 8, 9, 'E.Prasetya Nugraha, S.T., M.T.', 'Survey', 'Completed', 'complete', 'PORT OF CELUKAN BAWANG, BALI, INDONESIA', '2026-04-14', '2026-05-02', '<p><b><u>Structural Compliance with general marine industry standards</u></b></p><p><span style="font-size: 0.875rem;"><b>POLLUTION PREVENTIONS</b></span></p><ul><li>BUNKER STATIONS WERE FOUND OBSTRUCTED WITH FOREIGN MATERIALS</li><li>STEEL SAVE-ALLS NOT FITTED AT THE BUNKER STATION, FO &amp; LO VENTS, HYDRAULIC SYSTEM OF FWD &amp; AFT WINCH, AND HYDRAULIC CONTROL OF HATCH COVERS.</li><li>SCUPPER PLUG WAS FOUND UNAVAILABLE ON BOARD</li><li>OIL ABSORBENT WAS FOUND UNAVAILABLE ON BOARD</li></ul><p><b>HULL AND DECK STRUCTURAL CONDITIONS</b></p><ul><li>MAIN DECK WAS FOUND RUSTY IN SEVERAL AREAS.</li><li>ANCHOR WINDLASS AND AFT WINCHES WERE FOUND RUSTY.</li><li>BOLLARDS, ROLLERS, AND FAIRLEADS AT THE FORWARD DECK WERE FOUND RUSTY AND WITHOUT SWL MARKING.</li><li>HYDRAULIC SYSTEM OF DERRICK WAS FOUND TO HAVE LEAKAGES.</li><li>FORWARD DERRICK WAS FOUND IN REPAIR CONDITION.</li><li>COAMING STAY OF HATCH COVER WAS FOUND RUSTY AND PARTLY CORRODED.</li><li>MOORING LINES AT FORWARD AND AFT WERE FOUND ABRASIVE.</li><li>DERRICK STEEL FOUNDATION WAS FOUND PARTLY CORRODED.</li><li>TANKTOP WAS FOUND COVERED WITH CARGO CEMENT RESIDUE.</li><li>WEATHERTIGHT DOORS WERE MOSTLY PARTIALLY CORRODED.</li><li>WEATHERTIGHT DOORS WERE FOUND WITHOUT OPEN/CLOSED DIRECTIONS AND KEPT CLOSED AT SEA MARKING.</li><li>THE STEERING GEAR ROOM VENT HATCH WAS FOUND MISSING.</li><li>MANHOLE ACCESS TO THE FORWARD STORE AND CHAIN LOCKER ROOM WAS FOUND PARTLY CORRODED.</li><li><span style="font-size: 0.875rem;">HATCH COVER WAS FOUND RUSTY AND PARTLY CORRODED.</span></li><li>HOSE TEST HAS NOT BEEN CARRIED OUT DUE TO OPERATIONAL REASONS.</li></ul><p><b>BALLAST TANKS</b></p><ul><li>BALLAST OVERFLOW TEST HAS NOT BEEN CARRIED OUT DUE TO OPERATIONAL REASONS.</li></ul><p><b>MACHINERY SPACES</b></p><ul><li>MAIN ENGINE WAS FOUND IN REPAIRING CONDITIONS.</li></ul><div bis_skin_checked="1"><b><u>Bridge Management</u></b></div><div bis_skin_checked="1">Implemented by the shipâs crew, but it can still be improved.</div><div bis_skin_checked="1"><br></div><div bis_skin_checked="1"><u style="font-weight: 700; text-indent: -23.8px;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Navigational Equipment</span></u></div><div bis_skin_checked="1"><span lang="EN-US" style="text-indent: -11.6px; font-size: 14px; line-height: 20px;">Navigation and Communication were&nbsp;</span><span lang="IN" style="text-indent: -11.6px; font-size: 14px; line-height: 20px;">found&nbsp;</span><span lang="EN-US" style="text-indent: -11.6px; font-size: 14px; line-height: 20px;">fitted</span><span lang="IN" style="text-indent: -11.6px; font-size: 14px; line-height: 20px;">&nbsp;on board</span><span lang="EN-US" style="text-indent: -11.6px; font-size: 14px; line-height: 20px;">&nbsp;and apparently in satisfactory condition.&nbsp;</span></div><div bis_skin_checked="1"><br></div><div bis_skin_checked="1"><span style="text-indent: -23.8px;"><span lang="EN-GB" style="line-height: 20px;"><b><u>Competent Officers</u></b></span></span></div><div bis_skin_checked="1"><span style="text-indent: -23.8px;"><span lang="EN-GB" style="line-height: 20px;">The Officer and crew appeared to be competent; all certificates complied with the STCW standard.</span></span></div><div bis_skin_checked="1"><span style="text-indent: -23.8px;"><span lang="EN-GB" style="line-height: 20px;"><br></span></span></div><div bis_skin_checked="1"><u style="font-weight: 700; text-indent: 9.46667px;"><span lang="EN-GB" style="font-size: 10pt; line-height: 20px;">Interassociation of Officers and Crew</span></u><span style="text-indent: -23.8px;"><span lang="EN-GB" style="line-height: 20px;"><br></span></span><span style="font-size: 13.3333px;">The entire crew has good cooperation during the survey.</span><span style="text-indent: -23.8px;"><span lang="EN-GB" style="line-height: 20px;"><br></span></span><br></div>', '<p style="text-align: justify; ">The Wreck Removal &amp; Oil Pollution Survey of MV. âSHORYU XIXâ was conducted on 14 April 2026, whilst she berthed port-side alongside at Celukan Bawang Port, Bali, Indonesia, for cargo discharge operations. During the survey, we were accompanied/ assisted by the Master, Chief Officer, Chief Engineer, and Crew.</p><p style="text-align: justify; "><b><u>HULL</u></b></p><p style="text-align: justify; ">MV. SHORYU XIX is a 35-year-old vessel. The vessel was a single-hull steel General Cargo with dimensions: LOA: 81.20 m, LPP = 75.24 m, B = 12.50 m, H = 7.50 m, GT 1,727, and NT 594. The Vessel was registered at Surabaya and under the classification of Biro Klasifikasi Indonesia (BKI). The vessel was built by Yamanaka Zhosen Shipbuilding Co., Ltd., Japan in 1991. Reported, the vessel has a valid Class Certificate, i.e., Hull &amp; Machinery Class Certificate, Tonnage Certificate, and Load Line Certificate, as well as a Statutory Certificate. The visible shell plating was found slightly rusty but in satisfactory condition.</p><p style="text-align: justify; ">During the survey, we found that the Main Deck was found Rusty at Several Areas, however, still in fair condition. The Superstructure and accommodation space were found in fair condition. Anchor Windlass and Aft Winches were found to be rusty. Bollards, Rollers, and Fairleads at the Forward Deck were found to be rusty and without SWL marking. The hydraulic system of Derrick was found to have leaks. Forward Derrick was found in Repair Condition. Coaming Stay of Hatch Cover was found Rusty and Partly Corroded. Mooring Lines at Forward and Aft were found Abrasive. The Derrick Steel Foundation was found to be partly corroded. Weathertight Doors were mostly Partially Corroded. Weathertight Doors were found without Open/Closed Directions and Kept Closed at the Sea Marking. The Steering Gear Room Vent Hatch was found missing. Manhole Access to the Forward Store and Chain Locker Room was found to be partly corroded. Several Areas on Cargo Hold was found Partly Corroded. Cargo Holds Bilge Well was found to be rusty and with Cargo Residue. Hatch Cover was found Rusty and Partly Corroded. Hose Test has not been carried out due to Operational Reasons.</p><p style="text-align: justify; "><b><u>CARGO HOLDS / COMPARTMENTS</u></b></p><p style="text-align: justify; ">The Vessel was fitted with 1 (one) Cargo Hold, 2 (two) units of Derrick at the mid-section of Cargo Hold, and 1 (one) unit of Derrick at the forward of Cargo Hold. The internal structure of Cargo Hold was found in fair condition.</p><p style="text-align: justify; "><span style="font-size: 0.875rem;">Hatch Covers were found to be rusty and Partly Corroded. This test has not been tested due to operational reasons.</span></p><p style="text-align: justify; "><b><u>NON-CARGO TANKS:</u></b></p><p style="text-align: justify; ">The Vessel fitted with 6 WBT Double Bottom (1 â 3 (P &amp; S)) and 4 WBT Wing Tank (1 - 2 (P &amp; S)), Fore Peak and After Peak Tanks. The Internal structure of WBT was found in fair condition. Ballast Tanks Overflow Pressure Test has not been carried out due to operational reasons.</p><p style="text-align: justify; "><b><u>MACHINERY</u></b></p><p style="text-align: justify; ">The Vessel was equipped with 1 (one) unit of Hanshin Type 6LU38G with 2,000 HP x 300 Rpm and equipped with 2 (two) units Auxiliary Engine i.e. Yanmar Type 6 KFL 185 HP &amp; Type 6LAAL-DTN 330 HP (in Engine Room) and 1 (one) unit Emergency Generator of Yanmar Type 4CHL-TN 62 HP in Engine Room. The Engine Room was located in the aft area. Machinery was reported in working order. However, during the survey, the main engine was found in repair conditions.</p><p style="text-align: justify; "><b><u>POLLUTION</u></b></p><p style="text-align: justify; ">SOPEP Locker and Equipment were found available. Fuel air vents were found in fair condition. However, Bunker Stations were found to be obstructed with Foreign Materials. Steel save-alls Not Fitted at the Bunker Station, FO &amp; LO Vents, Hydraulic System of Forward &amp; Aft Winch, and Hydraulic Control of Hatch Covers. Scupper Plug was found unavailable on board. Oil Absorbent was found unavailable on board.</p><p style="text-align: justify; "><b><u>NAVIGATION</u></b></p><p style="text-align: justify; ">Navigation and communication fitted on the Bridge, i.e., Gyro Compass, Magnetic Compass, Radar, GPS, VHF Radios, etc. Navigational Charts were sufficient for the trading area, and NTM / BPI was found to be supplied on board regularly.&nbsp;</p><div bis_skin_checked="1"><br></div>', '<p>The vessel was found in fair structural condition. However, several items need to be repaired/rectified.<br></p>', '2026-04-02', '2027-04-02', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (685, 19, 8, 9, 'FAJAR TRIHASTYANTO KUNCORO', 'Survey', 'Completed', 'complete', 'SURABAYA ANCHORAGE, SURABAYA', '2026-04-13', '2026-05-02', '<p class="MsoNormal" style="text-align:justify"><b><u><span lang="EN-GB">Structural compliance with general marinenindustry standards</span></u></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify">-&nbsp;Bunker manifolds were found obstructed with foreign materials.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">-&nbsp;Save-alls were found not fitted on all Hydraulic operating handlenof Hatch covers.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">-&nbsp;Scupper plugs were found not available.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- Oil absorbents&nbsp;were found not available.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">-&nbsp;Forward deck was found rusty.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">-&nbsp;Forward and Aft Bulwark was found corroded.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">-&nbsp;Hydraulic of Anchor &amp; Mooring Windlass were found leakages.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">-&nbsp;Port side Chain stopper was found heavy corroded and starboardnside Chain stopper missing.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">- Hydraulic system of Derrick deck was found leakages.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">-&nbsp;Hatch coaming was found partly corroded.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">-&nbsp;Forward hydraulic operating handle pipe of Hatch covers was foundnleakages.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">-&nbsp;Mooring lines of Anchor &amp; Mooring Windlass and Aft MooringnWinches was found abrasive.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">-&nbsp;Watertight doors were found without Open/ Close and Kept close atnsea marking.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">-&nbsp;Watertight door access to Cargo hold was found partly corroded onnbelow area.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify">-&nbsp;Hose test has not been tested due to operational reasons.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><b><u><span lang="EN-GB">Bridge Management.</span></u></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><span lang="EN-GB">Implemented by shipâs crew but still can benimproved.</span><o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><b><u><span lang="EN-GB">Navigational equipment</span></u></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><span lang="IN">The&nbsp;</span><span lang="EN-US">navigation and communication were&nbsp;</span><span lang="IN">found&nbsp;</span><span lang="EN-US">fitted</span><span lang="IN">&nbsp;on board</span><span lang="EN-US">&nbsp;andnapparently in satisfactory condition. However,&nbsp;</span>AIS was found malfunction. Echo Sounder wasnfound not available.&nbsp;<span lang="EN-US">NTM/ BPI was found notnsupplied on board and Charts were found not updated as per latest&nbsp;</span>NTM/ BPI.<o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><b><u><span lang="EN-GB">Competent of Officers</span></u></b><o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><span lang="EN-GB">The Officer and crew appeared to be competent;nall certificates complied as per STCW standard.</span><o:p></o:p></p><p class="MsoNormal" style="text-align:justify"><b><u><span lang="EN-GB">Interassociation of Officers and Crew</span></u></b><o:p></o:p></p><p class="MsoNormal" style="margin-left: 26.9pt; text-indent: -17.85pt; line-height: 21px;">nnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnn</p><p class="MsoNormal" style="text-align:justify"><span lang="EN-GB">All crew have good cooperation during thensurvey.</span><o:p></o:p></p>', '<p class="MsoHeader" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">The Wreck Removal &amp; Oil Pollution&nbsp;</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="line-height: 18px;">survey</span><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">&nbsp;of MV. âShoryu XXVIIâ was conducted on 13 April 2026, whilst she anchored at Surabaya anchorage, Surabaya, Indonesia waiting for cargo loading operation. During the survey, we were accompanied/ assisted by the Chief Officer, Chief Engineer and crew.</span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">HULL</span><o:p></o:p></span></span></p><p class="MsoListParagraph" style="margin-left: 0cm; text-align: justify; line-height: 21px;"><span tahoma",sans-serif"="" style="line-height: 18px;">MV. Shoryu XXVII <span style="background-color: rgb(247, 247, 247);">is 35</span>&nbsp;years old vessel, t</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">he&nbsp;</span><span tahoma",sans-serif"="" style="line-height: 18px;">vessel</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="line-height: 18px;">&nbsp;was</span><span lang="IN" tahoma",sans-serif;mso-ansi-language:en-gb"="" style="line-height: 18px;">&nbsp;</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">a</span><span tahoma",sans-serif"="" style="line-height: 18px;">&nbsp;single hull&nbsp;</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">steel</span><span tahoma",sans-serif"="" style="line-height: 18px;">&nbsp;General Cargo with dimension&nbsp;</span><span style="line-height: 18px;">LPP = <span style="background-color: rgb(247, 247, 247);">68.00 m, B</span></span><span style="background-color: rgb(247, 247, 247);"><span style="line-height: 18px;">&nbsp;</span><span style="line-height: 18px;">= 11.50 m</span><span style="line-height: 18px;">&nbsp;</span><span style="line-height: 18px;">H =&nbsp;6.80&nbsp;m</span></span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;"><span style="background-color: rgb(247, 247, 247);">, GT 1360 and NT 514</span>.</span><span style="color: red; font-size: 14px;">&nbsp;</span><span style="font-size: 14px;">The Vessel was registered at<span style="background-color: rgb(247, 247, 247);"> Surabaya and u</span>nder Classification of Biro Klasifikasi Indonesia (BKI).<span style="background-color: rgb(247, 247, 247);"> The vessel&nbsp;</span></span></span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px; background-color: rgb(247, 247, 247);">was&nbsp;</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="background-color: rgb(247, 247, 247);"><span style="font-size: 14px;">built by Yamanaka Shipbuilding Co,.Ltd., Japan</span><span style="color: red; font-size: 14px;">&nbsp;</span></span><span style="font-size: 14px;"><span style="background-color: rgb(247, 247, 247);">in 1991.</span>&nbsp;Reported, the vessel has a valid Class Certificate i.e: Hull &amp; Machinery</span></span><span lang="IN" tahoma",sans-serif;mso-ansi-language:in"="" style="line-height: 18px;">&nbsp;Class</span><span tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">&nbsp;Certificate, Tonnage Certificate and Load Line Certificate as well as a Statutory Certificate.</span><span style="color: red; font-size: 14px;">&nbsp;</span></span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">The visible shell plating was found slight rusty but in satisfactory condition.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">During the survey, we found that the Main deck was found to be in satisfactory condition. The Superstructure and accommodation space were found satisfactory. However. F</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">orward deck was found rusty.&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Forward and Aft Bulwark was found corroded.&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Hydraulic of Anchor &amp; Mooring Windlass were found leakages.&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Port side Chain stopper was found heavy corroded and starboard side Chain stopper missing.&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Hydraulic system of Derrick deck was found leakages.&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Hatch coaming was found partly corroded.&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Forward hydraulic operating handle pipe of Hatch covers was found leakages.&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Mooring lines of Anchor &amp; Mooring Windlass and Aft Mooring Winches was found in poor condition.</span></p><p class="MsoNormal" style="line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">CARGO HOLDS / COMPARTMENTS</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">The Vessel was fitted with 1 (one) Cargo Hold, 1 (one) unit Crawler Crane at middle of cargo hold and 1 (one) unit Derrick at forward of cargo hold.&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Internal structure of cargo hold was found in satisfactory condition. However, the Tank top was found covered with cement cargo residue. </span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">The&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Cargo&nbsp;</span><span style="color: rgb(33, 37, 41); text-align: left;">holds bilge well (P &amp; S) were found heavy rusty</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">. Suction test&nbsp;</span><span style="color: rgb(33, 37, 41); text-align: left;">has not been carried out due to malfunction system</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">.&nbsp;</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Hatch covers and rubber sealing have not been inspected due to safety and operational reasons.&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Hose test has not been tested due to operational reasons.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">NON-CARGO TANKS:</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">The&nbsp;</span><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">V</span><span lang="IN" tahoma",sans-serif;="" mso-ansi-language:in"="" style="line-height: 18px;">essel&nbsp;</span><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">fitted with 6 WBT Double bottom (1 â 3 (P &amp; S)) and 6 WBT Wing Tank (1 - 3 (P &amp; S)), Fore peak and After peak Tanks. The&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Internal structure of WBT was found in satisfactory condition. B</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">allast tanks pressure test has been carried out and found no leakages to the Cargo holds</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">MACHINERY</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">The Vessel was equipped with 1 (one) unit of Hanshin Type LH 31 RG with 1,000 HP x 315 Rpm and equipped with 2 (two) units Auxiliary Engine i.e. Mitsui Deutz Type F4L 912 with 50 HP and Yanmar Type 6 KFLT 185 HP (in Engine Room) and 1</span><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">&nbsp;(one) unit Emergency Generator (no data) in Engine Room.</span><span style="color: red; font-size: 14px;">&nbsp;</span><span style="font-size: 14px;">The Engine Room was located in the aft area. Main Engine, Auxiliary Engines reported in working order. &nbsp;&nbsp;</span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">POLLUTION</span><o:p></o:p></span></span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;"><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">SOPEP Locker and Equipment was found available.</span>&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem; text-align: left;">Fuel air vents were found in fair condition. However,&nbsp;</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">Bunker connection was found obstructed with foreign materials</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">. S</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">ave-alls were found not fitted on all Hydraulic operating handle of Hatch covers.&nbsp;</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">Scupper plugs were found not available. Oil absorbents</span><span style="font-size: 0.875rem; color: rgb(33, 37, 41); text-align: left;">&nbsp;were found not available.</span></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span style="font-weight: bolder;"><span lang="EN-US" tahoma",sans-serif"="" style="font-size: 9pt; line-height: 18px;"><span style="font-size: 14px;">NAVIGATION</span><o:p></o:p></span></span></p><p></p><p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span lang="EN-US" tahoma",sans-serif"="" style="line-height: 18px;">Navigation and communication fitted on the Bridge such Gyro Compass, Magnetic Compass, Radar, GPS, VHF Radios etc.&nbsp;</span><span style="font-size: 0.875rem;">AIS was found malfunction. Echo Sounder was found not available.&nbsp;</span><span style="font-size: 0.875rem;">Navigational Charts were sufficient for trading area but not updated as per last BPI and NTM / BPI was found not supplied on board regularly.&nbsp;</span></p>', '<p>The vessel was found in satisfactory structural condition but several items to be repaired/rectified.&nbsp;</p>', '2026-04-02', '2027-04-02', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (686, 194, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-05-02', NULL, NULL, NULL, '2026-04-02', '2027-04-02', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (687, 18, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-05-02', NULL, NULL, NULL, '2026-04-02', '2027-04-02', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (688, 195, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-05-02', NULL, NULL, NULL, '2026-04-02', '2027-04-02', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (689, 48, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-05-02', NULL, NULL, NULL, '2026-04-02', '2027-04-02', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (690, 103, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-05-02', NULL, NULL, NULL, '2026-04-02', '2027-04-02', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (691, 6, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-05-02', NULL, NULL, NULL, '2026-04-02', '2027-04-02', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (692, 514, 8, 9, 'kristian zen', 'Survey', 'Completed', 'complete', 'Berlian Timur, Surabaya - Indonesia', '2026-04-27', '2026-04-20', '<p>Concern is primarily focused on several critical structural and watertight integrity issues affecting the hull, deck, cargo holds, and hatch covers, which, if not promptly rectified, may significantly increase the risk of cargo damage, water ingress, and progressive structural deterioration.</p><ul><li>Radar log book were not sighted on board</li><li>NTM/BPI were not provided on board</li><li>Paper chart were not up to dateÂ </li><li>Changeover for emergency steering instruction were not posted on board</li><li>some save alls were found holes</li><li>some location of hand railing were found fracture/damage</li><li>COT were not inspected due to all tanks were full cargo condition during survey.</li></ul>', '<p><strong data-start="119" data-end="165">VESSEL PARTICULARS AND GENERAL DESCRIPTION</strong><br data-start="165" data-end="168">rnMT <span data-start="171" data-end="182" style="">Cosmic 15</span> is an Indonesian-flagged oil tanker employed as a bunker vessel within the Surabaya area. The vessel, built approximately 35 years ago, is of double hull and double bottom construction and is classed with <span data-start="388" data-end="422">Biro Klasifikasi Indonesia (BKI)</span> under notation A100(l)P, Oil Tanker (ESP, FP > 60Â°C). Ownership and management are under PT Landasindo Sahu Baruna Jaya.<span style="font-size: 0.875rem;">The vessel is manned by an all-Indonesian crew who were observed to be generally familiar with the vesselâs type, size, and operational requirements.</span></p><hr data-start="698" data-end="701"><p data-start="703" data-end="915"><strong data-start="703" data-end="737">CERTIFICATION AND CLASS STATUS</strong><br data-start="737" data-end="740">rnThe vessel is arranged with four (4) cargo oil tanks. Class certificates, officersâ certificates, and an Ultrasonic Thickness Measurement (UTM) report were sighted on board.<span style="font-size: 0.875rem;">The UTM report (No. 700/SPK/TEK/UT/X/2024), with the last measurement conducted on 2 November 2024 during dry docking at PT Dewa Ruci Agung, was noted to be class-approved, with maximum diminution recorded below 20% (rectified where required).</span><span style="font-size: 0.875rem;">The Classification Certificate was found valid until 09 October 2026. The last bottom survey was carried out on 17 November 2021. No outstanding class recommendations or exemption certificates were noted at the time of inspection.</span></p><hr data-start="1396" data-end="1399"><p data-start="1401" data-end="1614"><strong data-start="1401" data-end="1436">NAVIGATION AND BRIDGE EQUIPMENT</strong><br data-start="1436" data-end="1439">rnNavigation equipment was found to be generally in satisfactory operational condition. The radar was tested and operational; however, no radar logbook was available on board.<span style="font-size: 0.875rem;">The magnetic compass was observed to be in good condition, free from air bubbles, with a valid deviation card properly posted.</span><span style="font-size: 0.875rem;">Bridge publications and nautical charts were found not up to date, as no Notices to Mariners (NTM) or Berita Pelaut Indonesia (BPI) were available on board.</span><span style="font-size: 0.875rem;">The echo sounder was tested and confirmed operational. Emergency steering changeover procedures were not posted in either the wheelhouse or the steering gear room.</span></p><hr data-start="2071" data-end="2074"><p data-start="2076" data-end="2348"><strong data-start="2076" data-end="2113">POLLUTION PREVENTION ARRANGEMENTS</strong><br data-start="2113" data-end="2116">rnPollution prevention arrangements were found to be generally adequate. The SOPEP locker was located on the main deck, and scupper plugs were available. Oil absorbent materials were also provided on board at the time of inspection.Â <span style="font-size: 0.875rem;">Bunkering connections and fuel tank air vents were observed to be in generally good condition, with save-alls properly fitted. However, some save-alls on the fuel tank air vents were noted to be holed and require attention.</span></p><hr data-start="2575" data-end="2578"><p data-start="2580" data-end="2732"><strong data-start="2580" data-end="2607">HULL AND DECK CONDITION</strong><br data-start="2607" data-end="2610">rnThe hull was observed to be in fair condition, with minor scratches and dents consistent with operational wear and tear.<span style="font-size: 0.875rem;">Deck fittings and watertight doors were also noted to be in fair condition. Air vents and sounding pipes on the main deck were generally in fair condition; however, associated save-alls were found holed.</span><span style="font-size: 0.875rem;">Internal inspection of cargo oil tanks was not carried out, as all tanks were fully loaded at the time of attendance.</span></p><hr data-start="3060" data-end="3063"><p data-start="3065" data-end="3229"><strong data-start="3065" data-end="3107">TANK ARRANGEMENT AND BALLAST CONDITION</strong><br data-start="3107" data-end="3110">rnThe vessel is arranged with fore peak tank, aft peak tank, six (6) ballast tanks, and four (4) cargo oil tanks (COT).<span style="font-size: 0.875rem;">Internal inspection of selected ballast tanks was conducted and found to be in fair condition. COT were not inspected due to all tanks were full cargo condition during survey.</span></p><hr data-start="3327" data-end="3330"><p data-start="3332" data-end="3510"><strong data-start="3332" data-end="3371">MACHINERY AND ENGINE ROOM CONDITION</strong><br data-start="3371" data-end="3374">rnThe engine room was found to be clean and generally well-maintained. All machinery observed was operational at the time of inspection.<span style="font-size: 0.875rem;">The main engine consists of one (1) HANSHIN LH28G, a 4-stroke diesel engine rated at approximately 1,000 HP at 355 RPM.</span><span style="font-size: 0.875rem;">Auxiliary power is provided by two (2) Yanmar 6HAL-HTN diesel generator engines, each rated at approximately 180 HP.</span><span style="font-size: 0.875rem;">The emergency generator was tested and found operational. The steering gear system was also tested and observed to be in good working condition.</span></p>', '<p>Based on the attendance and findings, MT <em data-start="58" data-end="69">Cosmic 15</em> was observed to be in generally fair operational condition; however, several deficiencies were noted, particularly concerning structural integrity and watertight arrangements, including holed save-alls and damaged hand railings, which require prompt rectification to prevent further deterioration. In addition, deficiencies in navigational documentation and procedures were identified, including the absence of a radar logbook, outdated paper charts, lack of NTM/BPI updates, and unposted emergency steering changeover instructions. Cargo Oil Tanks (COT) were not inspected due to all tanks being in a fully loaded condition at the time of survey. These findings, if not addressed in a timely manner, may increase the risk of operational non-compliance, water ingress, and potential cargo-related incidents</p>', '2026-03-21', '2027-03-21', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (693, 515, 8, 9, 'kristian zen', 'Survey', 'Completed', 'complete', 'Surabaya anchorage, Surabaya - Indonesia', '2026-05-22', '2026-05-20', '<p data-start="111" data-end="370">Concern is primarily focused on several observations and deficiencies related to vessel documentation, navigational records, pollution prevention arrangements, and limitations during tank inspections, which may require further attention and corrective action.</p><p class="MsoNormal">rn</p><ul data-start="372" data-end="1205">rn<li data-section-id="b131wn" data-start="372" data-end="589">rnThe UTM report was not sighted on board. Based on the Master''s verbal statement, the report had not yet been received from the vendor from the date of measurement during dry docking until the date of our attendance.rn</li>rn<li data-section-id="fi7z9v" data-start="591" data-end="733">rnRadar logbook and NTM publications were not available on board; however, the radar was tested and found in working order and fair condition.rn</li>rn<li data-section-id="jm44wb" data-start="735" data-end="815">rnPaper charts were not updated due to the absence of NTM publications on board.rn</li>rn<li data-section-id="c9j7n2" data-start="817" data-end="889">rnSave-alls were not fitted at bunker manifolds and fuel tank air vents.rn</li>rn<li data-section-id="41uxu4" data-start="891" data-end="1031">rnInternal inspection of Cargo Oil Tanks (COT) could not be carried out as all tanks were fully loaded with cargo at the time of attendance.rn</li>rn<li data-section-id="zxxxmf" data-start="1033" data-end="1205">rnCorrosion was observed at the bottom plating of side ballast tanks. Double bottom ballast tanks could not be inspected as they were found full of water during the survey.</li></ul>', '<p data-start="160" data-end="550">MT Bagus Selatan is a 38-year-old steel-welded vessel constructed with double bottom and double hull arrangements. The vessel has nine cargo tanks, including slop tanks. The vessel is owned and managed by PT Landasindo Sahu Baruna Jaya. She was built in Japan in 1988 and sails under the Indonesian flag with IMO No. 8823939. The survey was carried out at Surabaya Anchorage on 22 May 2026.</p><p data-start="552" data-end="1171">The vessel is classed with BKI under class notation BKI A100(l)P, Oil Tanker (ESP, FP > 60Â°C). The Class Certificate was found to be provisional and valid until 5 November 2026. Other statutory certificates were found valid. The vessel''s last dry docking was conducted on 20 April 2026. Based on the Master''s verbal statement, the UTM certificate had not yet been received from the vendor from the date of measurement at dry dock until the date of our attendance. Officers on board were found capable and familiar with the vessel systems and vessel type. Some officers were also able to communicate in Maritime English.</p><p data-start="1173" data-end="1682">During the survey, navigational equipment including radar, echo sounder, magnetic compass, paper charts, and NTM was checked and/or tested. One deficiency was noted whereby the radar logbook was not available on board; however, the radar itself was tested and found in working order and fair condition. NTM/BPI publications were not available on board, indicating that paper charts and other navigational publications had not been updated. Changeover procedures for manual steering were found posted on board.</p><p data-start="1684" data-end="2232">Pollution prevention measures on board were generally implemented; however, save-alls were not fitted at the bunker manifolds and fuel tank air vents. The SOPEP locker was located on the forward part of the main deck and its contents, including sawdust, mops, oil absorbents, and other equipment, were found in satisfactory condition. Scupper plugs were also found available on board. Both port and starboard bunker manifolds were found in fair condition. Fuel tank air vents were also found in fair condition, although save-alls were not provided.</p><p>rnrnrnrnrn<p data-start="3073" data-end="3362"></p></p><p data-start="2234" data-end="3071">The vessel''s hull was reported to be in good condition with newly applied coatings following dry docking. Draft marks, Plimsoll marks, and ship identification markings were found clear and legible. During onboard inspection around the vessel, the main deck was found in fair condition with newly applied paint coatings. Hand railings, ballast air vents, and deck edges were also found in fair condition. Deck fittings such as roller fairleads, bollards, windlass, and anchor compartments were found in fair condition. Watertight doors were found in fair condition with rubber gaskets in place. During the survey, internal inspection of the Cargo Oil Tanks (COT) could not be carried out as all tanks were found fully loaded with cargo (MFO). However, accessible cargo tank manhole covers were found in fair condition with rubber gaskets.</p><p data-start="3073" data-end="3362">Ballast tank pressure testing was conducted and found satisfactory. Internal inspection of side ballast tanks was carried out, during which corrosion was observed at the tank bottom plating. Double bottom ballast tanks were not inspected as they were found full of water during the survey.</p><p data-start="2234" data-end="3071">rn</p><p data-start="3364" data-end="3884">The vessel is fitted with one main engine, a HANSIN 6LU28G four-stroke single-acting diesel engine with an output of 1,300 HP at 395 RPM, and two auxiliary engines, YANMAR 6CHL-TN, each rated at 100 HP. The Oily Water Separator (OWS) was tested and found satisfactory. The vessel uses emergency batteries as an emergency power supply, located at the boat deck. Main engine and auxiliary generators were tested and found in working order and fair condition. Emergency steering gear was also tested and found satisfactory.</p>', '<p>Based on the survey findings, MT Bagus Selatan was generally found in fair operational condition with major shipboard systems and equipment tested and found in working order. Several deficiencies and observations were noted, including missing navigational records/publications, absence of save-alls at certain locations, and corrosion observed in side ballast tanks. Overall, the vessel appeared adequately maintained for her intended operation, subject to the observations noted above.</p>', '2026-04-20', '2027-04-20', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (694, 516, 15, 9, 'Dedi', 'Survey', 'Cancelled', 'complete', 'Tarahan Anchorage, Bandar Lampung', '2026-04-22', '2026-05-09', '<p>We noted several deficiencies in various parts of the vessel as stated above, and our recommendationsÂ <span style="font-size: 0.875rem;">for the relevant items are as follows:</span></p><div><div>Items Nos: 202, 206, 301, 302, 306, 402, 403 and 502. These items should be rectified at theÂ <span style="font-size: 0.875rem;">earliest opportunity, or at the latest within two (2) months.</span></div><div><br></div><div>Item No: 304, 305, 405, 406, 604 and 605. These items should be rectified at the earliest opportunity, orÂ <span style="font-size: 0.875rem;">at the latest within three (3) months.</span></div></div><div><br></div>', '<p>Briefly remark on the following subjects:</p><p>â¢ Structural compliance with general marine industry standards.</p><p>The vessel is a general cargo carrier fitted with two (2) cargo holds. An internal inspection of the cargoÂ <span style="font-size: 0.875rem;">holds was carried out, and the internal structures, including bulkheads, side walls, coamings, side shellÂ </span><span style="font-size: 0.875rem;">frames, and web frames, were found to be in fair condition.</span></p><p><span style="font-size: 0.875rem;">As far as could be inspected, the port and starboard external shell plating above the waterline wereÂ </span><span style="font-size: 0.875rem;">found to be well coated. The main deck, forecastle, and poop deck were observed to be in fair conditionÂ </span><span style="font-size: 0.875rem;">with coating in good order. No significant damage was noted on the deck pipelines and associatedÂ </span><span style="font-size: 0.875rem;">fittings.</span></p><div><div>The holdâs bilge was found to contain residual water and remained previous cargo and the bilge waterÂ <span style="font-size: 0.875rem;">suction operation was completed successfully; however, disposal was carried out directly to sea, whichÂ </span>is not recommended. It is advised to provide a designated bilge tank or convert unused ballast tanksÂ <span style="font-size: 0.875rem;">(No. 11 and/or No. 12) into bilge holding tanks. Drums may be used as a temporary arrangement.Â </span></div><div><span style="font-size: 0.875rem;"><br></span></div><div><div style="">A hose test was conducted on the hatch covers, which were protected by three (3) layers of tarpaulin.Â <span style="font-size: 0.875rem;">No leakage was observed, and no water ingress into the cargo holds was noted.</span></div><div style=""><br></div><div style="">Vessel fitted with 12 (twelve) Water Ballast Tank which transverse from starboard to portside,Â <span style="font-size: 0.875rem;">internal inspection to WBT Nos. 1, 4, 8 and 12 was carried out, structural members of ballast tankÂ </span><span style="font-size: 0.875rem;">found to be in good condition with zinc anodes fitted.</span></div><div style=""><br></div><div style="">A pressure test randomly carried out of WBT No. 2, 6 and 10, the result of pressure test was foundÂ <span style="font-size: 0.875rem;">leakage on the man hole of ballast tank no. 2 and no. 10, we recommend the rubber manhole must beÂ </span><span style="font-size: 0.875rem;">changed and the cement must be renewed regularly.</span></div><div style=""><br></div><div style="">All ballast valves were reportedly blind-flanged during the vesselâs conversion from a tanker to aÂ <span style="font-size: 0.875rem;">general cargo ship. As a result, their locations could not be identified by the Chief Engineer, and it isÂ </span><span style="font-size: 0.875rem;">likely that the pipelines were blanked off at the bulkhead during the ship conversion.Â </span></div><div style=""><span style="font-size: 0.875rem;"><br></span></div><div style=""><div style="">Refers to latest ultrasonic thickness report, the latest thickness measurements conducted on 29 JanuaryÂ <span style="font-size: 0.875rem;">2026 indicated that entire plating were generally acceptable, with no widespread evidence of wastageÂ </span><span style="font-size: 0.875rem;">exceeding 25% of the original plate thickness.</span></div><div style=""><br></div><div style="">In the opinion of the Surveyor, the vessel is considered seaworthy and suitable for operation withinÂ <span style="font-size: 0.875rem;">her current trading area.</span></div><div style=""><span style="font-size: 0.875rem;"><br></span></div><div style=""><div style="">â¢ Bridge management</div><div style=""><br></div><div style="">Master and Company Standing Order are posted on bridges; Passage plan berth to berth is undertakenÂ <span style="font-size: 0.875rem;">and recorded. Deck log book, etc, are well recorded. All deck officers are familiar with navigationalÂ </span><span style="font-size: 0.875rem;">and radio equipment.</span></div><div style="">Â </div><div style="">â¢ Navigational equipment</div><div style=""><br></div><div style="">All the bridge navigational devices, RADARâs, GPS, Echo Sounder, AIS, NAVTEX and MagneticÂ <span style="font-size: 0.875rem;">Compass, VHF Radio, etc are in good working conditions.</span></div><div style=""><br></div><div style="">â¢ Competence officers</div><div style=""><br></div><div style="">Based on our review on certificates of Competence / Endorsement and Safe Manning Certificate, weÂ <span style="font-size: 0.875rem;">note that the all officers and crews are found with valid Indonesian endorsements.</span></div><div style=""><br></div><div style="">â¢ Interassociasion officers and crew</div><div style=""><br></div><div style="">The Master, Officers and crews found to be in harmonize team work, diligent, good attitude andÂ <span style="font-size: 0.875rem;">competent in the operation of the vessel.</span></div><div style="font-size: 0.875rem;"><br></div></div></div></div></div>', '<div>MV. âSUMBER REJEKI VIIIâ is a general cargo steel construction, which was built in accordance with the rules and regulations of the Classification Society of PT Biro Klasifikasi Indonesia.</div><div><br></div><div>The vessel was adequately equipped and fully operational, with navigation and communication equipment, firefighting equipment, mooring equipment, and life-saving appliances on board. The vessel is also fitted with 1 (one) unit of Main Engine of HANSHIN DIESEL 2000 HP x 280 RPM. The shipâs is fitted with 2 (two) sets of Auxiliary Engine of Yanmar 6HALTN with generating 2 x 190 HP, 1 (one) unit of Mitsui with generating 68 HP and 1 (one) unit of Hino with generating 68 HP, and also 1 (one) unit crane with engine Hino LS-78RH-5 with SWL 20 tons, and Pumps-all were reported to be well-maintained and in good condition. All machinery and equipment were in proper working condition.</div><div><br></div><div>The vessel is fitted with two (2) cargo holds. An internal inspection of the cargo holds was carried out, and the internal structures, including bulkheads, side walls, coamings, side shell frames, and web frames, were found to be in good condition.</div><div><br></div><div>The vessel has a limited trading area and operates predominantly within coastal waters. The risk of encountering heavy seas is considered moderate to low.</div><div><br></div><div>All crew members have been serving with the same company for more than 16 years. Based on the information gathered, the vessel MV âSUMBER REJEKI VIIIâ has not experienced any major casualties since commencement of operations, such as stranding, grounding, or collision.</div><div><br></div><div>The vessel and its management hold valid ISM Code certificates. Document of Compliance issued by Directorate General of Marine Transport on October 11, 2022 and valid until October 6, 2027 and safety management certificate issued by the Directorate General of Sea Transportation on March 13, 2023 and valid until April 16, 2028.</div><div><br></div><div>The vesselâs Class was valid until January 04, 2028. The annual Class survey was completed on February 19, 2026, with Class maintained as per the issued endorsement.</div>', '2026-04-09', '2027-04-09', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (695, 517, 15, 9, 'Darussalam', 'Survey', 'Completed', 'complete', 'Surabaya Anchorage, East Java', '2026-04-04', '2026-05-09', '<p><span style="font-size: 11pt; line-height: 115%; font-family: " times="" new="" roman",="" serif;"="">We noted that the water ballast tanks were not utilized andnequipped with blind valves. however, we understand that the trading area this vessel andnfound within Indonesian water only, mostly coastal area and as the vessel wasnengaged solely in domestic trading within Indonesian waters, inter alianKalimantan, Sumatra, and Lampung, which are considered coastal waters and innaverage the wave height was less than 2 meters. Hence the master only utilizesnfor stability purposes, WBT No. 1C was utilized, and to correct rolling conditions,nthe FWT at the aft wing tanks (P/S) was also used. Nevertheless, when the wavenheight more than 4 meter high, the ship might be in critical situation hancenballasting capability of the vessel is essential. Nevertheless, in seanconditions where wave heights exceed 4 meters, the vessel may encounterncritical conditions; therefore, adequate ballasting capability is essential.</span></p>', '<p class="MsoListParagraphCxSpFirst" style="margin-left:0cm;mso-add-space:auto;ntab-stops:5.0cm 155.95pt"><span style="font-size:11.0pt;line-height:115%;nfont-family:" times="" new="" roman",serif"="">Briefly remark on teh following subjects:<o:p></o:p></span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:0cm;mso-add-space:auto;ntab-stops:58.0pt"><span style="font-size:11.0pt;line-height:115%;font-family:n" times="" new="" roman",serif"="">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <o:p></o:p></span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:58.0pt;mso-add-space:nauto;text-indent:-2.0cm;mso-list:l0 level1 lfo1;tab-stops:58.0pt"><!--[if !supportLists]--><span style="font-size:11.0pt;line-height:115%;font-family:Wingdings;mso-fareast-font-family:nWingdings;mso-bidi-font-family:Wingdings;mso-bidi-font-style:italic">Ã<span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: " times="" new="" roman";"="">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;n</span></span><!--[endif]--><i><span style="font-size:11.0pt;line-height:n115%;font-family:" times="" new="" roman",serif"="">Structural compliance with generalnmarine industry standards.<o:p></o:p></span></i></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:0cm;mso-add-space:auto;ntab-stops:58.0pt"><span style="font-size:11.0pt;line-height:115%;font-family:n" times="" new="" roman",serif"="">&nbsp;</span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:14.2pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><span style="font-size:11.0pt;nline-height:115%;font-family:" times="" new="" roman",serif"="">The vessel is generalncargo carrier fitted with 1 cargo hold fitted with hatch covers<i> o</i>fnhydraulic single pull type.<o:p></o:p></span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:14.2pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><span style="font-size:11.0pt;nline-height:115%;font-family:" times="" new="" roman",serif"="">&nbsp;</span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:14.2pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><span style="font-size:11.0pt;nline-height:115%;font-family:" times="" new="" roman",serif"="">As far as could beninspected port and starboard external side/shell plating above the water linenwas found in well coated. Main deck, forecastle and poop deck found innsatisfactory condition and well coated. No significant damage was observed onnthe pipe lines and other fittings on deck.<o:p></o:p></span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:14.2pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><span style="font-size:11.0pt;nline-height:115%;font-family:" times="" new="" roman",serif"="">&nbsp;</span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:14.2pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><span style="font-size:11.0pt;nline-height:115%;font-family:" times="" new="" roman",serif"="">We did internalninspection to cargo hold and as could be inspected, an internal structure ofncargo hold i.e. bulkhead, side wall, coamings, side shell frame, web frame, etcnwere found in worn down paint coating, and slightly rust at several places butnin good structural condition.<o:p></o:p></span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:14.2pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><span style="font-size:11.0pt;nline-height:115%;font-family:" times="" new="" roman",serif"="">&nbsp;</span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:15.45pt;mso-add-space:nauto;text-align:justify"><span style="font-size:11.0pt;line-height:115%;nfont-family:" times="" new="" roman",serif"="">Holdâs bilges found remained of waterandnpreviously cargo, we were not carried out the suction test due to both of thenbilge valve in Engine Room were jammed.<o:p></o:p></span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:15.45pt;mso-add-space:nauto;text-align:justify"><span style="font-size:11.0pt;line-height:115%;nfont-family:" times="" new="" roman",serif"="">&nbsp;</span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:15.45pt;mso-add-space:nauto;text-align:justify"><span style="font-size:11.0pt;line-height:115%;nfont-family:" times="" new="" roman",serif"="">Hose test to the hatch cover was carriednout and found no leakage was observed.<o:p></o:p></span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:15.45pt;mso-add-space:nauto;text-align:justify"><span style="font-size:11.0pt;line-height:115%;nfont-family:" times="" new="" roman",serif"="">&nbsp;</span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:15.45pt;mso-add-space:nauto;text-align:justify"><span style="font-size:11.0pt;line-height:115%;nfont-family:" times="" new="" roman",serif"="">Internal inspection to WBT No. 2P/S, 3P/S,n4P/S was carried out structural members of ballast tank found to be in wornndown paint coating and scaled, sligthly corrosiaon at several palces but inngood structural condition with zinc anodes fitted.<o:p></o:p></span></p><p class="MsoListParagraphCxSpLast" style="margin-left:15.45pt;mso-add-space:nauto;text-align:justify"><span style="font-size:11.0pt;line-height:115%;nfont-family:" times="" new="" roman",serif"="">&nbsp;</span></p><p class="MsoNormal" style="margin-left:15.45pt;text-align:justify"><span style="font-size:11.0pt;line-height:115%;font-family:" times="" new="" roman",serif"="">Anpressure test and overflowing test only carried out of WBT No. 1 centre andnfound the air, and manhole covers in good condition and intact.<o:p></o:p></span></p><p class="MsoNormal" style="margin-left:15.45pt;text-align:justify"><span style="font-size:11.0pt;line-height:115%;font-family:" times="" new="" roman",serif"="">&nbsp;</span></p><p class="MsoListParagraphCxSpFirst" style="margin-left:15.95pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><b><i><span style="font-size:n11.0pt;line-height:115%;font-family:" times="" new="" roman",serif"="">Except:</span></i></b><b><span style="font-size:11.0pt;line-height:115%;font-family:" times="" new="" roman",serif"=""> </span></b><span style="font-size:11.0pt;line-height:115%;font-family:" times="" new="" roman",serif"="">Soundingnpipe and tank top plate of WBT No. 1 centre found leakage.<o:p></o:p></span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:15.95pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><span style="font-size:11.0pt;nline-height:115%;font-family:" times="" new="" roman",serif"="">&nbsp;</span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:15.95pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><span style="font-size:11.0pt;nline-height:115%;font-family:" times="" new="" roman",serif"="">Refers to latestnultrasonic thickness report, there are some shell expansion at frame Nos.26-28,n67-68 and 88-89 were diminution from 22.50% to 27.50% from original thichness,nand some spot found subtantial corrosion however overall mostly the result wasnsatisfactory without evidence of wastage in excess of 25% of original thicknessnto shipâs plate. And refer to the last docking report noted that the shipâsnplate at frame Nos. 26-28, 67-68 and 88-89 had been replated.<o:p></o:p></span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:15.95pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><span style="font-size:11.0pt;nline-height:115%;font-family:" times="" new="" roman",serif"="">&nbsp;</span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:15.95pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><u><span style="font-size:n11.0pt;line-height:115%;font-family:" times="" new="" roman",serif"="">Surveyor in thenopinion that the vessel is seawortiness and fit to sail with her currentntrading area.<o:p></o:p></span></u></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:15.95pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><u><span style="font-size:n11.0pt;line-height:115%;font-family:" times="" new="" roman",serif"="">&nbsp;</span></u></p><p class="MsoListParagraphCxSpLast" style="margin-left:58.0pt;mso-add-space:auto;ntext-indent:-2.0cm;mso-list:l0 level1 lfo1;tab-stops:58.0pt"><!--[if !supportLists]--><span style="font-size:11.0pt;line-height:115%;font-family:Wingdings;mso-fareast-font-family:nWingdings;mso-bidi-font-family:Wingdings;mso-bidi-font-style:italic">Ã<span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: " times="" new="" roman";"="">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;n</span></span><!--[endif]--><i><span style="font-size:11.0pt;line-height:n115%;font-family:" times="" new="" roman",serif"="">Bridge management<o:p></o:p></span></i></p><p class="MsoNormal" style="margin-left:15.45pt;tab-stops:58.0pt"><span style="font-size:11.0pt;line-height:115%;font-family:" times="" new="" roman",serif"="">&nbsp;</span></p><p class="MsoNormal" style="margin-left:15.45pt;tab-stops:58.0pt"><span style="font-size:11.0pt;line-height:115%;font-family:" times="" new="" roman",serif"="">Masternand Company Standing Order are posted on bridges; Passage plan berth to berthnis undertaken and recorded. Deck log book, etc, are well recorded. Alldecknofficers are familiar with navigational and radio equipment.<o:p></o:p></span></p><p class="MsoNormal" style="margin-left:15.45pt;tab-stops:58.0pt"><span style="font-size:11.0pt;line-height:115%;font-family:" times="" new="" roman",serif"="">&nbsp;</span></p><p class="MsoListParagraph" style="margin-left:58.0pt;mso-add-space:auto;ntext-indent:-2.0cm;mso-list:l0 level1 lfo1;tab-stops:58.0pt"><!--[if !supportLists]--><span style="font-size:11.0pt;line-height:115%;font-family:Wingdings;mso-fareast-font-family:nWingdings;mso-bidi-font-family:Wingdings;mso-bidi-font-style:italic">Ã<span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: " times="" new="" roman";"="">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;n</span></span><!--[endif]--><i><span style="font-size:11.0pt;line-height:n115%;font-family:" times="" new="" roman",serif"="">Navigational equipment<o:p></o:p></span></i></p><p class="MsoNormal"><i><span style="font-size:11.0pt;nline-height:115%;font-family:" times="" new="" roman",serif"="">&nbsp;</span></i></p><p class="MsoNormal" style="margin-left:15.45pt;tab-stops:58.0pt"><span style="font-size:11.0pt;line-height:115%;font-family:" times="" new="" roman",serif"="">Allnthe bridge navigational devices, RADARâs, GPS, Echo Sounder, AIS, NAVTEX andnGyro Compass, VHF Radio, etc are in good working conditions.<o:p></o:p></span></p><p class="MsoNormal" style="margin-left:15.45pt;tab-stops:58.0pt"><span style="font-size:11.0pt;line-height:115%;font-family:" times="" new="" roman",serif"="">&nbsp;</span></p><p class="MsoListParagraphCxSpFirst" style="margin-left:58.0pt;mso-add-space:nauto;text-indent:-2.0cm;mso-list:l0 level1 lfo1;tab-stops:58.0pt"><!--[if !supportLists]--><span style="font-size:11.0pt;line-height:115%;font-family:Wingdings;mso-fareast-font-family:nWingdings;mso-bidi-font-family:Wingdings;mso-bidi-font-style:italic">Ã<span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: " times="" new="" roman";"="">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;n</span></span><!--[endif]--><i><span style="font-size:11.0pt;line-height:n115%;font-family:" times="" new="" roman",serif"="">Competence officers<o:p></o:p></span></i></p><p class="MsoListParagraphCxSpLast" style="margin-left:58.0pt;mso-add-space:auto;ntab-stops:58.0pt"><i><span style="font-size:11.0pt;line-height:115%;font-family:n" times="" new="" roman",serif"="">&nbsp;</span></i></p><p class="MsoNormal" style="margin-left:15.45pt;tab-stops:58.0pt"><span style="font-size:11.0pt;line-height:115%;font-family:" times="" new="" roman",serif"="">Basednon our review on certificates of Competence / Endorsement and Safe ManningnCertificate, we note that the all officers and crews are found with validnIndonesian endorsements.<o:p></o:p></span></p><p class="MsoListParagraphCxSpFirst" style="margin-left:58.0pt;mso-add-space:nauto;tab-stops:58.0pt"><i><span style="font-size:11.0pt;line-height:115%;nfont-family:" times="" new="" roman",serif"="">&nbsp;</span></i></p><p class="MsoListParagraphCxSpLast" style="margin-left:58.0pt;mso-add-space:auto;ntext-indent:-2.0cm;mso-list:l0 level1 lfo1;tab-stops:58.0pt"><!--[if !supportLists]--><span style="font-size:11.0pt;line-height:115%;font-family:Wingdings;mso-fareast-font-family:nWingdings;mso-bidi-font-family:Wingdings;mso-bidi-font-style:italic">Ã<span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: " times="" new="" roman";"="">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;n</span></span><!--[endif]--><i><span style="font-size:11.0pt;line-height:n115%;font-family:" times="" new="" roman",serif"="">Interassociasion officers and crew<o:p></o:p></span></i></p><p class="MsoNormal" style="text-align:justify;tab-stops:5.0cm 155.95pt"><u><span style="font-size:11.0pt;line-height:115%;font-family:" times="" new="" roman",serif"="">&nbsp;</span></u></p><p>nnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnn</p><p class="MsoNormal" style="margin-left:15.45pt;tab-stops:58.0pt"><span style="font-size:11.0pt;line-height:115%;font-family:" times="" new="" roman",serif"="">ThenMaster, Officers and crew found to be in harmonize team work, diligent, of goodnattitude and competent in the operation of the vessel.<o:p></o:p></span></p>', '<p class="MsoListParagraphCxSpFirst" style="margin-left:1.7pt;mso-add-space:auto;ntext-align:justify;tab-stops:5.0cm 155.95pt"><span lang="EN-US" style="font-size:n11.0pt;line-height:115%;font-family:" times="" new="" roman",serif;mso-ansi-language:="" en-us"="">The MV. âSUMBER REJEKI 88â is a general cargo steel construction, whichnwas built in accordance with the rules and regulations of the ClassificationnSociety of PT Biro Klasifikasi Indonesia.<o:p></o:p></span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:1.7pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><span lang="EN-US" style="font-size: 11pt; line-height: 115%; font-family: " times="" new="" roman",="" serif;"="">The vessel was adequately equipped and fullynoperational, with navigation and communication equipment, firefightingnequipment, mooring equipment, and life-saving appliances on board. The vesselnis also fitted with 1 (one) unit of Main Engine </span><span style="font-size: 11pt; line-height: 115%; font-family: " times="" new="" roman",="" serif;"="">of AKASAKA A31R,nwith effective power of 1,000 HP at 240 Rpm</span><span lang="EN-US" style="font-size: 11pt; line-height: 115%; font-family: " times="" new="" roman",="" serif;"="">, </span><span style="font-size: 11pt; line-height: 115%; font-family: " times="" new="" roman",="" serif;"="">2 (two) sets of Auxialary Engine ofnYanmar 6HAL-N with generating 2 x 160 HP, 1 (one) unit of Mitsui withngenerating 68 HP and 1 (one) unit of Hino with generating 65 KVA, and also 1n(one) unit crane with engine Mitsubishi 6D810 with SWL 5 tons,</span><span style="font-size: 11pt; line-height: 115%; font-family: " times="" new="" roman",="" serif;"=""> <span lang="EN-US">and Pumps-all were reported to benwell-maintained and in satisfactory condition. All machinery and equipment werenin proper working condition.</span></span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:1.7pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><span lang="EN-US" style="font-size: 11pt; line-height: 115%; font-family: " times="" new="" roman",="" serif;"="">The vessel has 1 (one)</span><span style="font-size: 11pt; line-height: 115%; font-family: " times="" new="" roman",="" serif;"=""> cargo holdncovered with hydraulic single pull type, designed with 7 (seven) Water BallastnTank (WBT Nos. 1C, 2-4P/S), Fore peak tank, After peak tank Af Wing Tank P/Sn(filled with fresh water) </span><span lang="EN-US" style="font-size: 11pt; line-height: 115%; font-family: " times="" new="" roman",="" serif;"="">werenobserved to be in good order condition.</span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:1.7pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><span style="font-family: " times="" new="" roman",="" serif;="" font-size:="" 11pt;"="">The vessel has a limitedntrading area and operates predominantly within coastal waters. The risk ofnencountering heavy seas is considered moderate to low.</span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:1.7pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><span style="font-family: " times="" new="" roman",="" serif;="" font-size:="" 11pt;"="">All crew members havenbeen serving with the same company for more than 16 years. Based on theninformation gathered, the vessel MV </span><i style="font-family: " times="" new="" roman",="" serif;="" font-size:="" 11pt;"="">âSUMBER REJEKI 88â</i><span style="font-family: " times="" new="" roman",="" serif;="" font-size:="" 11pt;"=""> has notnexperienced any major casualties since commencement of operations, such asnstranding, grounding, or collision.</span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:1.7pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><span style="font-family: " times="" new="" roman",="" serif;="" font-size:="" 11pt;"="">The vessel and itsnmanagement hold valid ISM Code certificates. Document of Compliance valid from Octobern11, 2022 to October 6, 2027 and Safety Management Code valid from May 26, 2025nto May 27, 2030.</span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:1.7pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><span style="font-family: " times="" new="" roman",="" serif;="" font-size:="" 11pt;"="">The vesselâs Class wasnvalid until March 6 2030. The annual Class survey was completed on</span><span style="font-family: " times="" new="" roman",="" serif;="" font-size:="" 11pt;"="">&nbsp; December 29, 2025, with Class maintained asnper the issued visa endorsement.</span></p><p class="MsoListParagraphCxSpMiddle" style="margin-left:1.7pt;mso-add-space:nauto;text-align:justify;tab-stops:5.0cm 155.95pt"><u><span times="" new="" roman",serif"="" style="font-size: 11pt; line-height: 16.8667px;">Surveyor in the opinion that the vessel is seawortiness and fit to sail with her current trading area, subject.</span></u></p>', '2026-04-09', '2027-04-09', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (696, 518, 13, 9, 'Frendi Tri Bimantoro', 'Survey', 'Outstanding', 'complete', 'Jakarta', '2026-04-16', '2026-04-11', '<p><span style="text-align: justify;">The following section outlines the key concerns identified by the surveyor during the condition survey. These concerns highlight areas requiring corrective action, enhanced monitoring, or further verification in order to ensure continued compliance with applicable safety, operational, and regulatory standards:</span></p><p><span style="font-weight: bolder; text-align: justify;">1. Bridge and Navigation</span></p><p>The surveyor''s primary concerns center on the compromise of navigational redundancy and emergency preparedness, specifically highlighted by the non-functional secondary radar unit and the total absence of required operational radar logbooks. This technical failure, coupled with the lack of posted emergency steering instructions, represents a significant breach of safety protocols and regulatory standards, indicating that while basic tools are present, the vessel''s ability to safely manage equipment malfunctions or critical steering emergencies is currently inadequate.</p><p><b>2. Pollution Prevention</b></p><p>The surveyor''s primary concerns regarding pollution prevention focus on the vessel''s inability to contain or mitigate an oil spill, characterized by the critical absence of essential response equipment such as oil absorbents, scupper plugs, and a designated SOPEP locker. This lack of readiness is further exacerbated by the structural failure of the save-alls, where existing leaks and holes render the primary containment system ineffective. Consequently, these deficiencies represent a severe breach of MARPOL and SOPEP regulatory requirements, posing an unacceptable risk of environmental contamination and potential legal liabilities during bunkering or oil transfer operation.</p><p><b>3. Hull and Deck Structural</b></p><p>The surveyor''s primary concern focuses on the compromised watertight integrity of the vessel''s internal spaces. Despite the generally good condition of the hull and decks, the absence of rubber sealings on critical watertight doors leading to the accommodation and cargo holds creates a high-risk vulnerability. This deficiency directly threatens the vessel''s ability to maintain reserve buoyancy and prevent progressive flooding during heavy weather or accidental ingress.</p><p><span style="text-align: justify;"></span></p>', '<p class="MsoNormal" style="text-align: justify; line-height: 21px;"><span arial",sans-serif"="">This resume presents a summary of the condition survey conducted on board MV INTAN 31 at Sunda Kelapa waters, North Jakarta, Jakarta. The survey was carried out to assess the general condition, operational status, and structural integrity of the vessel in accordance with applicable marine and safety standards.<o:p></o:p></span></p><p><span style="font-weight: bolder; font-size: 0.875rem;">1. Ships Certificates</span></p><p style="text-align: justify; line-height: 21px;"><span arial",sans-serif"="">Based on the review of the shipâs certificates and inspection results, the vessel is generally in good condition and compliant with applicable requirements. The Classification Certificate is valid until the last inspection, and the officersâ competence is confirmed to be valid and in accordance with the Crew List (note: the chief officer become a port captain due to the captain was sign off). The Ultrasonic Steel Thickness Test indicates that the vesselâs structural condition is satisfactory, with recorded thickness diminutions below 20%,Â  which remain within acceptable limits. Overall, no critical deficiencies were identified, although continued monitoring of steel thickness is recommended.</span></p><p style="text-align: justify; line-height: 21px;"><b>2. Bridge and NavigationÂ </b></p><p>The vessel exhibited varying levels of compliance, although it had updated navigation charts and a functioning compass, it still faced critical safety deficiencies due to a partial failure of the second radar system (the 3 GHz/9 GHz unit was not functioning) and the absence of required radar operational records. Additionally, there were no emergency steering instructions.</p><p><b>3. Pollution Prevention</b></p><p>The vessel''s pollution prevention measures are currently inadequate due to several major deficiencies in spill response readiness, specifically the critical absence of oil absorbents and  the SOPEP locker and scupper plugs not available on board. While bunkering connections and fuel air vents remain in good condition, the physical integrity of the save-alls is compromised by holes and leaks, which, combined with the no equipments of SOPEP locker, significantly increases the risk of environmental contamination and regulatory non-compliance during oil transfer operations.</p><p><b>4. Hull and Deck Structural</b></p><p>The vesselâs hull and deck structural condition are generally well-maintained, with the hull, decks, and anodes reported in good status following the 2025 docking and successful hose testing of the cargo holds. However, a critical deficiency exists regarding the vessel''s watertight integrity, as multiple watertight doorsâincluding those providing access to the accommodation and cargo holdsârequire the installation of rubber sealings to meet safety standards. While the hatch covers are functional and reinforced with tarpaulins, the lack of proper seals on primary structural openings poses a significant risk to the vessel''s internal buoyancy and weather-tightness during heavy seas.</p><p><b>5. Ballast Tanks</b></p><p><span style="text-align: justify;">Based on the inspection of the ballast tanks, the overall internal structural condition was assessed as fair, with no visible cracks observed on the internal structures, indicating that the primary structural integrity remains acceptable at the time of survey and the ballast tank pressure was already tested with good conditions.</span></p><p style="text-align: justify; "><b>6. Machinery Space</b></p><p>The machinery spaces are in good operational condition, with all primary and emergency systems functioning reliably. The main engine is noted for its effortless start-up and smooth operation, while all auxiliary engines and the emergency generator on the open deck are fully operational and in good condition. Furthermore, critical safety and coordination linksâincluding the telephone communication line between the engine room and the bridge and the emergency steering systemâhave been tested and confirmed to be in normal working order, indicating a high level of technical readiness in the vessel''s machinery spaces.</p>', '<p>This summary provides a summary of conditional survey of MV. INTAN 31 at Sunda Kelapa waters, North Jakarta:</p><p>The MV INTAN 31 is structurally and mechanically sound, with the main engine, auxiliary engines, and emergency systems in good operational condition. Recent inspections and thickness tests confirm the hull and ballast tanks remain within acceptable safety limits, showing no critical structural wear following the 2025 docking.</p><p>However, critical deficiencies exist in navigational safety and environmental compliance. The secondary radar is non-functional, and there is a total lack of required radar logs and emergency steering instructions. Additionally, the vessel is ill-equipped for pollution prevention, lacking a SOPEP locker, absorbents, and scupper plugs, while the save-alls suffer from leaks and holes.</p><p>Furthermore, the vessel''s watertight integrity is compromised by missing rubber seals on critical doors leading to the accommodation and cargo holds. Immediate corrective actions are required to repair the radar, procure essential spill-response equipment, and restore watertight seals to ensure the vessel meets all safety and MARPOL regulatory standards.</p>', '2026-03-12', '2027-03-12', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (697, 519, 8, 9, 'kristian zen', 'Survey', 'Completed', 'complete', 'Sunda kelapa Anchorage, Jakarta Utara - Indonesia', '2026-04-14', '2026-04-10', '<p class="MsoNormal"><span style="font-size: 10.5pt; line-height: 107%;">Concern is primarily focused on severalncritical structural and watertight integrity issues affecting the hull, deck,ncargo holds, and hatch covers, which, if not promptly rectified, maynsignificantly increase the risk of cargo damage, water ingress, and progressivenstructural deterioration.<o:p></o:p></span></p><ul><li><span style="font-size: 10.5pt; line-height: 107%;">Marine growth was observed on the externalnhull, particularly affecting the draft marks and Plimsoll mark.</span></li><li>Heavy damage was noted on thenforecastle deck, especially on the portside bulkhead, which may pose a risknduring mooring operations.</li><li>Internal inspection of the doublenbottom/ballast tanks revealed corrosion, indicating a lack of maintenance.nHowever, the latest class-approved Ultrasonic Thickness Measurement (UTM)nreport indicates that the recorded steel diminution remains below 20%.</li></ul>', '<p style="margin-top:0cm"><span style="font-size: 10.5pt;">MV A1, a 1986âbuilt Indonesianâflagged general dry cargo vessel ofnabout 1,679 GRT and 2,622 DWT, classed with Biro Klasifikasi Indonesia, wasnattended at Sunda kelapa Anchorage, Indonesia on 14 April 2026 for conditionnsurvey. The vessel is managed and operated by PT. Indo Shipping and wasnobserved alongside the Masterâs representative and shipâs staff during routinenoperational status. Class and statutory certificates, including the classncertificate and STCWârelated competency documents for officers, were verifiednas available and valid, with no class recommendations or exemption certificatesnrecorded.<o:p></o:p></span></p><p style="margin-top: 0cm;"><span style="font-size: 0.875rem;"><b>Hull</b></span><span style="font-size: 10.5pt;"><o:p></o:p></span></p><p style="margin-top: 0cm;"><span style="font-size: 0.875rem;">The vessel is of doublenbottom, single hull construction, with ultrasonic thickness measurement lastncarried out on 15 November 2025 during drydock at Cilegon, Banten - Indonesia,nand the classâapproved report indicating recorded steel diminution below 20npercent. As far as could be seen from afloat condition, the external hullnplating and anodes showed general covered with marine growth, also dart marknand plimsol mark was to be found covered with marine growth and not clearnsigthed. There are two cargo holds; the overall structure of the holds wasnfound intact with old coating.<o:p></o:p></span></p><p style="margin-top: 0cm;"><b>Deck and ballast</b><span style="font-size: 10.5pt;"><o:p></o:p></span></p><p><span style="font-size: 10.5pt;">Thensuperstructure, including all decks, was observed to be in overall fairncondition. Air vents and watertight doors were also found in fair condition.nHowever, at the forecastle deck, the bulkhead was noted to have sustainedndamage and fracture. Ballast tank arrangements comprise double bottom waternballast tanks DBWT 1, 2, 3, and 4 on both port and starboard sides. All ballastntanks were full at the time of survey. A representative internal inspection wasncarried out in ballast tank No. 4 (port and starboard), where internalnstructures were found to be heavily corroded.A ballast tank pressure test wasnconducted on double bottom tanks No. 1 and 2 (port and starboard), and allntested tanks were found to hold pressure satisfactorily, with no leakagenobserved into the cargo hold spaces.<o:p></o:p></span></p><p><b>Cargonworthiness</b><span style="font-size: 10.5pt;"><o:p></o:p></span></p><p style="margin-top: 0cm;"><span style="font-size: 10.5pt;">Thenvessel is fitted with two cargo holds serviced by lifting pontoon type hatchncovers, and the internal cargo spaces, although structurally intact, were foundnwith uncoated tank tops and general rusting consistent with poor coatingncondition. Cargo hold bilges were inspected and found with the fixed bilgensuction system not operating; consequently, the vessel presently uses portablenpumps for bilge water removal from the cargo holds. Access ladders and manholesnto the holds were available and functional, with no major structural defectsnreported in these access arrangements. Hatch coaming structures were inngenerally good coating condition along the vertical and side portions, whilenheavy corrosion was concentrated on the top areas of the hatch coamings andnhatch pontoons. The vessel employs a threeâlayer tarpaulin arrangement over thenpontoon covers as the primary weathertight barrier, the tarpaulins and theirnsecuring arrangements were inspected and found in serviceable condition at thentime of survey. The vessel is additionally equipped with a dieselâengineâpoweredncargo crane of 15âton safe working load, which was observed in fair workingncondition for cargo handling.<o:p></o:p></span></p><p style="margin-top: 0cm;"><b>Navigation</b><span style="font-size: 10.5pt;"><o:p></o:p></span></p><p style="margin-top: 0cm;"><span style="font-size: 10.5pt;">Navigationnequipment was found to be in good working condition at the time of inspection.nKey instruments, including AIS, VHF radio, echo sounder, GPS, radar, andnmagnetic compass, were observed to be operational, with the magnetic compass inngood condition and free from bubble defects. Notices to Mariners (NTM) andnBerita Pelaut Indonesia (BPI) were available and up to date, and all paperncharts were found to be properly corrected and maintained. Instructions fornemergency steering were available and properly posted on the bridge. However,nno records were available for the radar log book.<o:p></o:p></span></p><p style="margin-top:0cm"><b>Machinery</b><span style="font-size: 10.5pt;"><o:p></o:p></span></p><p><span style="font-size: 10.5pt;">Thenmain engine is a Hansin 6LU32 diesel engine, 4-stroke, with an effective powernoutput of 1,013 HP at 305 RPM, forming the vesselâs primary propulsion system.nThe main generator set is a Yanmar 6KFL, with an output of approximately 147nPS, supporting the vesselâs electrical power supply.he engine room was observednto be in overall fair, clean, and tidy condition. The general appearance of thenmain engine was satisfactory, with no significant oil leakage noted during theninspection. The main switchboard was sighted and found to be in satisfactoryncondition, with no abnormalities reported.Auxiliary power is provided by atnleast three generator sets. Generators No. 2, 3, and 4 were tested and found tonbe operational with satisfactory performance. The emergency generator, locatednon the boat deck, was also available.Emergency steering arrangements from thensteering gear compartment were tested and found to be operational. Changeovernfrom main steering to emergency steering was carried out satisfactorily.<o:p></o:p></span></p><p><b>Pollutionnprevention</b><span style="font-size: 10.5pt;"><o:p></o:p></span></p><p>nnnnnnnnnnnnnnnnnnnnnnnn</p><p class="MsoNormal"><span style="font-size: 10.5pt; line-height: 107%;">Pollution prevention arrangements on decknwere found to be generally in place and satisfactory. The SOPEP locker andnassociated spill response equipment were available on the main deck at the timenof survey. However, scupper plugs were not sighted. Bunkering connections wereninspected and found to be in satisfactory condition, with flanges, valves, andnblank flanges properly maintained. Fuel oil tank air vents on deck werenoperational and properly labeled according to their respective services. Thenbunker station was fitted with save-alls.</span><o:p></o:p></p>', '<p>MV A1, a 1986-built Indonesian-flagged general cargo vessel, was inspected on 14 April 2026 at Sunda Kelapa Anchorage, with class and statutory certificates verified as valid. Overall, the vessel was found in fair operational condition, with navigation and machinery systems functioning satisfactorily, and pollution prevention arrangements generally in place. However, several concerns were identified, including marine growth obscuring draft and Plimsoll marks, heavy structural damage on the forecastle deck bulkhead posing potential mooring risks, and corrosion within ballast tanks indicating inadequate maintenance. Cargo holds were structurally intact but showed poor coating condition and non-operational fixed bilge systems. While UTM results remain within acceptable limits (below 20% diminution), the noted structural deficiencies and maintenance gaps may increase the risk of cargo damage, water ingress, and progressive deterioration if not addressed promptly.</p>', '2026-03-11', '2027-03-11', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
