INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (787, 597, 13, 9, 'Samuel Misdom', 'Survey', 'Completed', 'complete', 'Surabaya', '2026-05-21', '2026-06-05', '<h4 data-path-to-node="2" style="font-family: "Google Sans", sans-serif !important; line-height: 1.15 !important;"><b data-path-to-node="2" data-index-in-node="0" style="font-family: "Google Sans Text", sans-serif !important; line-height: 1.15 !important; margin-top: 0px !important;"><span style="font-size: 14px;">1. Critical Safety & Compliance Concerns (Defects)</span></b></h4><ul data-path-to-node="3" style="padding-inline-start: 32px; font-family: "Google Sans Text", sans-serif !important; line-height: 1.15 !important;"><li style="line-height: 1.15 !important; margin-top: 0px !important;"><p data-path-to-node="3,0,0" id="p-rc_99d16c6fd489349c-68" style="line-height: 1.15 !important;"><span data-path-to-node="3,0,0,0" style="line-height: 1.15 !important; margin-top: 0px !important;"><b data-path-to-node="3,0,0,0" data-index-in-node="0" style="line-height: 1.15 !important; margin-top: 0px !important;">Navigational & Voyage Risk:</b> The absence of an updated <i data-path-to-node="3,0,0,0" data-index-in-node="54" style="line-height: 1.15 !important; margin-top: 0px !important;">Chart List</i> onboard is a direct non-compliance with safe navigation procedures</span><span data-path-to-node="3,0,0,1" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c2700604988="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="3,0,0,2" style="line-height: 1.15 !important; margin-top: 0px !important;">. It poses a severe risk of the vessel operating without proper voyage planning or utilizing outdated navigational data</span><span data-path-to-node="3,0,0,3" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c2700604988="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="3,0,0,4" style="line-height: 1.15 !important; margin-top: 0px !important;">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c1005750260="" style="line-height: 1.15 !important; margin-top: 0px !important;">  <source-inline-chip _ngcontent-ng-c1005750260="" _nghost-ng-c4074466300="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----></source-inline-chip><!----><!----><!----></sources-carousel-inline></p></li><li style="line-height: 1.15 !important; margin-top: 0px !important;"><p data-path-to-node="3,1,0" id="p-rc_99d16c6fd489349c-69" style="line-height: 1.15 !important;"><span data-path-to-node="3,1,0,0" style="line-height: 1.15 !important; margin-top: 0px !important;"><b data-path-to-node="3,1,0,0" data-index-in-node="0" style="line-height: 1.15 !important; margin-top: 0px !important;">Emergency Preparedness Deficit:</b> The lack of <i data-path-to-node="3,1,0,0" data-index-in-node="44" style="line-height: 1.15 !important; margin-top: 0px !important;">changeover instructions</i> at the emergency steering station is highly critical</span><span data-path-to-node="3,1,0,1" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c2700604988="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="3,1,0,2" style="line-height: 1.15 !important; margin-top: 0px !important;">. In the event of a main steering gear failure, the crew may face confusion or delays in manually taking over control, significantly increasing the risk of collision or grounding</span><span data-path-to-node="3,1,0,3" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c2700604988="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="3,1,0,4" style="line-height: 1.15 !important; margin-top: 0px !important;">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c1005750260="" style="line-height: 1.15 !important; margin-top: 0px !important;">  <source-inline-chip _ngcontent-ng-c1005750260="" _nghost-ng-c4074466300="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----></source-inline-chip><!----><!----><!----></sources-carousel-inline></p></li><li style="line-height: 1.15 !important; margin-top: 0px !important;"><p data-path-to-node="3,2,0" id="p-rc_99d16c6fd489349c-70" style="line-height: 1.15 !important;"><span data-path-to-node="3,2,0,0" style="line-height: 1.15 !important; margin-top: 0px !important;"><b data-path-to-node="3,2,0,0" data-index-in-node="0" style="line-height: 1.15 !important; margin-top: 0px !important;">Environmental & Pollution Risk:</b> Operating with an uncovered <i data-path-to-node="3,2,0,0" data-index-in-node="60" style="line-height: 1.15 !important; margin-top: 0px !important;">drain hole</i> in the save-all area creates an immediate pollution hazard</span><span data-path-to-node="3,2,0,1" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c2700604988="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="3,2,0,2" style="line-height: 1.15 !important; margin-top: 0px !important;">. Any fuel or oil leakage in this area will discharge straight into the sea rather than being safely contained</span><span data-path-to-node="3,2,0,3" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c2700604988="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="3,2,0,4" style="line-height: 1.15 !important; margin-top: 0px !important;">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c1005750260="" style="line-height: 1.15 !important; margin-top: 0px !important;">  <source-inline-chip _ngcontent-ng-c1005750260="" _nghost-ng-c4074466300="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----></source-inline-chip><!----><!----><!----></sources-carousel-inline></p></li><li style="line-height: 1.15 !important; margin-top: 0px !important;"><p data-path-to-node="3,3,0" id="p-rc_99d16c6fd489349c-71" style="line-height: 1.15 !important;"><span data-path-to-node="3,3,0,0" style="line-height: 1.15 !important; margin-top: 0px !important;"><b data-path-to-node="3,3,0,0" data-index-in-node="0" style="line-height: 1.15 !important; margin-top: 0px !important;">Structural Documentation Gap:</b> The unavailability of the <i data-path-to-node="3,3,0,0" data-index-in-node="56" style="line-height: 1.15 !important; margin-top: 0px !important;">UT (Ultrasonic Testing) Certificate</i> onboard means there is no immediate, verifiable proof of the hull''s actual plate thickness and structural integrity for administrative clearance</span><span data-path-to-node="3,3,0,1" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c2700604988="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="3,3,0,2" style="line-height: 1.15 !important; margin-top: 0px !important;">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c1005750260="" style="line-height: 1.15 !important; margin-top: 0px !important;">  <source-inline-chip _ngcontent-ng-c1005750260="" _nghost-ng-c4074466300="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----></source-inline-chip><!----><!----><!----></sources-carousel-inline></p></li></ul><h4 data-path-to-node="4" style="font-family: "Google Sans", sans-serif !important; line-height: 1.15 !important;"><b data-path-to-node="4" data-index-in-node="0" style="font-family: "Google Sans Text", sans-serif !important; line-height: 1.15 !important; margin-top: 0px !important;"><span style="font-size: 14px;">2. Operational Blindspots & Unverified Risks (Not Inspected)</span></b></h4><ul data-path-to-node="5" style="padding-inline-start: 32px; font-family: "Google Sans Text", sans-serif !important; line-height: 1.15 !important;"><li style="line-height: 1.15 !important; margin-top: 0px !important;"><p data-path-to-node="5,0,0" id="p-rc_99d16c6fd489349c-72" style="line-height: 1.15 !important;"><span data-path-to-node="5,0,0,0" style="line-height: 1.15 !important; margin-top: 0px !important;"><b data-path-to-node="5,0,0,0" data-index-in-node="0" style="line-height: 1.15 !important; margin-top: 0px !important;">Undetected Hull Corrosion:</b> Because the <i data-path-to-node="5,0,0,0" data-index-in-node="39" style="line-height: 1.15 !important; margin-top: 0px !important;">Zinc Anodes</i> were fully submerged, their depletion rate and the current level of cathodic protection on the hull could not be verified</span><span data-path-to-node="5,0,0,1" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c2700604988="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="5,0,0,2" style="line-height: 1.15 !important; margin-top: 0px !important;">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c1005750260="" style="line-height: 1.15 !important; margin-top: 0px !important;">  <source-inline-chip _ngcontent-ng-c1005750260="" _nghost-ng-c4074466300="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----></source-inline-chip><!----><!----><!----></sources-carousel-inline></p></li><li style="line-height: 1.15 !important; margin-top: 0px !important;"><p data-path-to-node="5,1,0" id="p-rc_99d16c6fd489349c-73" style="line-height: 1.15 !important;"><span data-path-to-node="5,1,0,0" style="line-height: 1.15 !important; margin-top: 0px !important;"><b data-path-to-node="5,1,0,0" data-index-in-node="0" style="line-height: 1.15 !important; margin-top: 0px !important;">Potential Hidden Cargo Hold Damage:</b> Due to the vessel being laden, the surveyor could <b data-path-to-node="5,1,0,0" data-index-in-node="86" style="line-height: 1.15 !important; margin-top: 0px !important;">not</b> verify the internal structure of the holds, bilge cleanliness, or bilge suction functionality</span><span data-path-to-node="5,1,0,1" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c2700604988="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="5,1,0,2" style="line-height: 1.15 !important; margin-top: 0px !important;">. There is a hidden risk of blocked bilge lines or cargo contamination from moisture that remains undetected</span><span data-path-to-node="5,1,0,3" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c2700604988="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="5,1,0,4" style="line-height: 1.15 !important; margin-top: 0px !important;">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c1005750260="" style="line-height: 1.15 !important; margin-top: 0px !important;">  <source-inline-chip _ngcontent-ng-c1005750260="" _nghost-ng-c4074466300="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----></source-inline-chip><!----><!----><!----></sources-carousel-inline></p></li><li style="line-height: 1.15 !important; margin-top: 0px !important;"><p data-path-to-node="5,2,0" id="p-rc_99d16c6fd489349c-74" style="line-height: 1.15 !important;"><span data-path-to-node="5,2,0,0" style="line-height: 1.15 !important; margin-top: 0px !important;"><b data-path-to-node="5,2,0,0" data-index-in-node="0" style="line-height: 1.15 !important; margin-top: 0px !important;">Unverified Weather-tightness:</b> The inability to perform a <i data-path-to-node="5,2,0,0" data-index-in-node="57" style="line-height: 1.15 !important; margin-top: 0px !important;">Hose Test</i> or <i data-path-to-node="5,2,0,0" data-index-in-node="70" style="line-height: 1.15 !important; margin-top: 0px !important;">Ultrasonic Test</i> means the seal integrity of the hatch covers and rubber packings remains unproven, posing a risk of water ingress during bad weather</span><span data-path-to-node="5,2,0,1" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c2700604988="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="5,2,0,2" style="line-height: 1.15 !important; margin-top: 0px !important;">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c1005750260="" style="line-height: 1.15 !important; margin-top: 0px !important;">  <source-inline-chip _ngcontent-ng-c1005750260="" _nghost-ng-c4074466300="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----></source-inline-chip><!----><!----><!----></sources-carousel-inline></p></li><li style="line-height: 1.15 !important; margin-top: 0px !important;"><p data-path-to-node="5,3,0" id="p-rc_99d16c6fd489349c-75" style="line-height: 1.15 !important;"><span data-path-to-node="5,3,0,0" style="line-height: 1.15 !important; margin-top: 0px !important;"><b data-path-to-node="5,3,0,0" data-index-in-node="0" style="line-height: 1.15 !important; margin-top: 0px !important;">Unknown Ballast Tank Integrity:</b> The internal condition of the <i data-path-to-node="5,3,0,0" data-index-in-node="62" style="line-height: 1.15 !important; margin-top: 0px !important;">Ballast Tanks</i> remains completely unverified</span><span data-path-to-node="5,3,0,1" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c2700604988="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="5,3,0,2" style="line-height: 1.15 !important; margin-top: 0px !important;">. Any localized heavy corrosion, structural fatigue, or internal cracking could not be assessed during this attendance</span><span data-path-to-node="5,3,0,3" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c2700604988="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="5,3,0,4" style="line-height: 1.15 !important; margin-top: 0px !important;">.</span></p></li></ul>', '<h3 data-path-to-node="7"><b data-path-to-node="7" data-index-in-node="0"><span style="font-size: 10px;"><span style="font-size: 14px;">1. List of Defect Condition</span><span style="font-size: 14px;">s</span></span></b><span style="font-size: 12px;">ï»¿</span></h3><p data-path-to-node="8">The survey identified 4 major administrative and operational deficiencies onboard that require immediate rectification:<br><b data-path-to-node="9,0,0" data-index-in-node="0" style="font-size: 0.875rem;">Â (103) - UT Certificate Not Available onboard:</b><span style="font-size: 0.875rem;"> The Ultrasonic Testing (thickness gauging) certificate was missing from the vessel''s documentation.<br></span><b data-path-to-node="9,1,0" data-index-in-node="0" style="font-size: 0.875rem;">(204) - Chart list not available onboard:</b><span style="font-size: 0.875rem;"> The updated navigational chart list was not found onboard.<br></span><b data-path-to-node="9,2,0" data-index-in-node="0" style="font-size: 0.875rem;">(206) - Changeover instruction from emergency steering not available onboard:</b><span style="font-size: 0.875rem;"> The mandatory step-by-step procedures/manual for switching to emergency steering were not posted or available at the steering gear station.<br></span><b data-path-to-node="9,3,0" data-index-in-node="0" style="font-size: 0.875rem;">(304) - The drain hole in the save-all has no cover:</b><span style="font-size: 0.875rem;"> The discharge/drain hole within the oil save-all tray lacked a proper plug or cover, posing a risk of accidental discharge.</span></p><h3 data-path-to-node="11"><b data-path-to-node="11" data-index-in-node="0"><span style="font-size: 14px;">2. List of Items Not Inspected</span></b></h3><p data-path-to-node="12">Several critical structural areas and functional tests could not be verified by the surveyor due to operational constraints at the time of attendance:</p><p data-path-to-node="12"><b data-path-to-node="13,0,0" data-index-in-node="0" style="font-size: 0.875rem;"><i>Due to Submergence:</i><br></b><b data-path-to-node="13,0,1,0,0" data-index-in-node="0" style="font-size: 0.875rem;">(401) - Zinc Anodes:</b><span style="font-size: 0.875rem;"> External sacrificial anodes could not be inspected as they were submerged underwater.</span></p><p data-path-to-node="12"><b data-path-to-node="13,1,0" data-index-in-node="0" style="font-size: 0.875rem;"><i>Due to the Vessel Being Laden (Vessel Have Cargo):</i><br></b><b data-path-to-node="13,1,1,0,0" data-index-in-node="0" style="font-size: 0.875rem;">(404) - Interior of holds:</b><span style="font-size: 0.875rem;"> The internal structure of the cargo holds was inaccessible for inspection.<br></span><b data-path-to-node="13,1,1,1,0" data-index-in-node="0" style="font-size: 0.875rem;">(405) - Cargo hold bilge cleanliness and suction test:</b><span style="font-size: 0.875rem;"> Cleanliness of the hold bilges and the functional bilge suction test could not be carried out.<br></span><b data-path-to-node="13,1,1,2,0" data-index-in-node="0" style="font-size: 0.875rem;">(406) - General condition of hatch cover and rubber sealing:</b><span style="font-size: 0.875rem;"> The overall condition of the hatch covers and the integrity of the rubber seals could not be thoroughly examined.<br></span><b data-path-to-node="13,1,1,3,0" data-index-in-node="0" style="font-size: 0.875rem;">(407) - Hose test / Ultrasonic test:</b><span style="font-size: 0.875rem;"> Weather-tightness testing of the hatch covers via hose or ultrasonic methods could not be executed.<br></span><b data-path-to-node="13,1,1,4,0" data-index-in-node="0" style="font-size: 0.875rem;">(501) - Ballast tanks:</b><span style="font-size: 0.875rem;"> Internal inspection of the ballast tanks was not possible while the vessel was loaded.</span></p>', '<p data-path-to-node="3" id="p-rc_e4df39a02a545064-108" style="font-family: "Google Sans Text", sans-serif !important; line-height: 1.15 !important;"><span data-path-to-node="3,2" style="line-height: 1.15 !important; margin-top: 0px !important;">The survey revealed several administrative and technical deficiencies, alongside significant inspection limitations due to the vessel''s loaded condition</span><span data-path-to-node="3,3" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c2700604988="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="3,4" style="line-height: 1.15 !important; margin-top: 0px !important;">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c1005750260="" style="line-height: 1.15 !important; margin-top: 0px !important;">  <source-inline-chip _ngcontent-ng-c1005750260="" _nghost-ng-c4074466300="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----></source-inline-chip><!----><!----><!----></sources-carousel-inline></p><ul data-path-to-node="4" style="padding-inline-start: 32px; font-family: "Google Sans Text", sans-serif !important; line-height: 1.15 !important;"><li style="line-height: 1.15 !important; margin-top: 0px !important;"><p data-path-to-node="4,0,0" id="p-rc_e4df39a02a545064-109" style="line-height: 1.15 !important;"><span data-path-to-node="4,0,0,0" style="line-height: 1.15 !important; margin-top: 0px !important;"><b data-path-to-node="4,0,0,0" data-index-in-node="0" style="line-height: 1.15 !important; margin-top: 0px !important;">Key Deficiencies Found:</b> The vessel lacks essential onboard documentation, specifically the UT (Ultrasonic Testing) Certificate and the navigational Chart List</span><span data-path-to-node="4,0,0,1" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c2700604988="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="4,0,0,2" style="line-height: 1.15 !important; margin-top: 0px !important;">. Operationally, the emergency steering changeover instructions are missing, and the save-all drain hole lacks a proper cover, posing a potential pollution risk</span><span data-path-to-node="4,0,0,3" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c2700604988="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="4,0,0,4" style="line-height: 1.15 !important; margin-top: 0px !important;">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c1005750260="" style="line-height: 1.15 !important; margin-top: 0px !important;">  <source-inline-chip _ngcontent-ng-c1005750260="" _nghost-ng-c4074466300="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----></source-inline-chip><!----><!----><!----></sources-carousel-inline></p></li><li style="line-height: 1.15 !important; margin-top: 0px !important;"><p data-path-to-node="4,1,0" id="p-rc_e4df39a02a545064-110" style="line-height: 1.15 !important;"><span data-path-to-node="4,1,0,0" style="line-height: 1.15 !important; margin-top: 0px !important;"><b data-path-to-node="4,1,0,0" data-index-in-node="0" style="line-height: 1.15 !important; margin-top: 0px !important;">Inspection Limitations:</b> Due to the vessel being laden with cargo and active operational status, critical structural and tight-integrity areas could not be inspected</span><span data-path-to-node="4,1,0,1" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c2700604988="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="4,1,0,2" style="line-height: 1.15 !important; margin-top: 0px !important;">. This includes the internal cargo holds, hold bilges, hatch covers (no hose/ultrasonic testing performed), ballast tanks, and submerged zinc anodes</span></p></li></ul>', '2026-05-05', '2027-05-05', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (788, 598, 13, 9, 'Samuel Misdom', 'Survey', 'Outstanding', 'draft', 'Surabaya', '2026-05-20', '2026-06-10', '<p>(203) Navigating with uncorrected charts poses a severe threat to navigational safety, increasing the risk of grounding or collision due to unknown new maritime hazards.Â </p><p>(301) In the event of an accidental oil spill during cargo or bunkering operations, the absence of clear marking will cause confusion and delay the crew from locating emergency response equipment. standard stenciling must be applied immediately to maintain MARPOL compliance.Â </p><p>(501) the presence of cracks on several structural plates inside the ballast tanks compromises the vessel''s structural integrity. immediate corrective actions (re-welding) and further steel thickness measurements are strongly recommended.Â </p>', '<p>(203) Navigation Updates: the vessel has never received any NTM (Notices to Mariners) Bulletins. Consequently, navigation charts and publications on board are not updated.Â </p><p>(301) Safety/Pollution Prevention: Standard identification marking "SOPEP" is missing on the SOPEP lockerÂ </p><p>(402) Hull & Deck plating: Heavy corrosion observed on the main deck plating, both on the port side and starboard sideÂ </p><p>(501) Ballast Tanks structure: Internal structural inspections of all ballast tanks revealed minor corrosion and slight cracking (minor cracks) on several plates</p><p>(502) Ballast tanks testing: Indicator the pressure test for the ballast tanks could not be carried out / was not working operational during the inspection.Â </p><p>(401) Zinc Anodes: External hull zinc anodes could not be inspected as they were submerged underwaterÂ </p><p>(404) Cargo tanks interior: The interior structure of the cargo tanks / holds was inaccessible for inspection due to the presence of cargoÂ </p>', 'MT. DAN 03 was surveyed at Surabaya Anchorage and is in operational condition, with certain findings requiring attention to maintain technical and safety standards. the primary points noted include outdated navigation charts due to lack of NTM updates, and internal corrosion alongside minor cracks on several structural frames within the ballast tanks, where the pressure test was not performed. additionally, corrosion was observed on the main deck plating, and standard identification marking was missing on the SOPEP locker. Cargo tank internals and external anodes were not inspected due to the vessel being laden. timely rectifications for the navigation updates and structural frame repairs are recommended to ensure continuous class compliance and smooth operations.Â', '2026-05-11', '2027-05-11', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (789, 599, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-06-12', NULL, NULL, NULL, '2026-05-13', '2027-05-13', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
