INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (799, 604, 13, 9, 'SAMUEL MISDOM', 'Survey', 'Outstanding', 'draft', 'Gresik', '2026-06-20', '2026-06-14', '<li style="font-family: " google="" sans="" text",="" sans-serif="" !important;="" line-height:="" 1.15="" margin-top:="" 0px="" !important;"=""><p data-path-to-node="5,0,0" id="p-rc_7e7046225175ac23-37" style="line-height: 1.15 !important;"><span data-path-to-node="5,0,0,0" style="line-height: 1.15 !important; margin-top: 0px !important;"><b data-path-to-node="5,0,0,0" data-index-in-node="0" style="line-height: 1.15 !important; margin-top: 0px !important;">Statutory & Certification Deficiencies (High Risk):</b> The total absence of the <b data-path-to-node="5,0,0,0" data-index-in-node="77" style="line-height: 1.15 !important; margin-top: 0px !important;">Classification Certificate (101)</b>, <b data-path-to-node="5,0,0,0" data-index-in-node="111" style="line-height: 1.15 !important; margin-top: 0px !important;">Officers'' Certificates of Competency (102)</b>, and <b data-path-to-node="5,0,0,0" data-index-in-node="159" style="line-height: 1.15 !important; margin-top: 0px !important;">UT Test Certificate (103)</b>Â <span data-path-to-node="5,0,0,0">onboard poses an immediate risk of Port State Control (PSC) detention</span><span data-path-to-node="5,0,0,1"><response-element class="" ng-version="0.0.0-PLACEHOLDER"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></response-element></span><span data-path-to-node="5,0,0,2">. The vessel cannot legally operate or clear port customs without these valid documents</span><span data-path-to-node="5,0,0,3"><response-element class="" ng-version="0.0.0-PLACEHOLDER"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></response-element></span><span data-path-to-node="5,0,0,4"></span><br><br><span data-path-to-node="5,0,0,4"></span></span></p></li><li style="font-family: " google="" sans="" text",="" sans-serif="" !important;="" line-height:="" 1.15="" margin-top:="" 0px="" !important;"=""><p data-path-to-node="5,1,0" id="p-rc_7e7046225175ac23-38" style="line-height: 1.15 !important;"><span data-path-to-node="5,1,0,0" style="line-height: 1.15 !important; margin-top: 0px !important;"><b data-path-to-node="5,1,0,0" data-index-in-node="0" style="line-height: 1.15 !important; margin-top: 0px !important;">Navigational Safety Hazards:</b> The vessel has <b data-path-to-node="5,1,0,0" data-index-in-node="44" style="line-height: 1.15 !important; margin-top: 0px !important;">never received any Notice to Mariners (NTM) Bulletins (203)</b> and lacks a <b data-path-to-node="5,1,0,0" data-index-in-node="116" style="line-height: 1.15 !important; margin-top: 0px !important;">List of Charts (204)</b></span><span data-path-to-node="5,1,0,1" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c3458427909="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="5,1,0,2" style="line-height: 1.15 !important; margin-top: 0px !important;">. <br>Operating without updated nautical charts and safety notices significantly compromises safe passage planning and increases navigation risks</span><span data-path-to-node="5,1,0,3" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c3458427909="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="5,1,0,4" style="line-height: 1.15 !important; margin-top: 0px !important;">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c667180327="" style="line-height: 1.15 !important; margin-top: 0px !important;">  <source-inline-chip _ngcontent-ng-c667180327="" _nghost-ng-c3963944138="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----></source-inline-chip><!----><!----><!----></sources-carousel-inline></p></li><li style="font-family: " google="" sans="" text",="" sans-serif="" !important;="" line-height:="" 1.15="" margin-top:="" 0px="" !important;"=""><p data-path-to-node="5,2,0" id="p-rc_7e7046225175ac23-39" style="line-height: 1.15 !important;"><span data-path-to-node="5,2,0,0" style="line-height: 1.15 !important; margin-top: 0px !important;"><b data-path-to-node="5,2,0,0" data-index-in-node="0" style="line-height: 1.15 !important; margin-top: 0px !important;">Emergency Preparedness:</b> The lack of <b data-path-to-node="5,2,0,0" data-index-in-node="36" style="line-height: 1.15 !important; margin-top: 0px !important;">Emergency Steering Changeover Instructions (206)<br></b>Â posted at the bridge and engine room is a serious safety non-compliance</span><span data-path-to-node="5,2,0,1" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c3458427909="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="5,2,0,2" style="line-height: 1.15 !important; margin-top: 0px !important;">. In the event of a main steering failure, the crew may face delays in taking manual control</span><span data-path-to-node="5,2,0,3" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c3458427909="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="5,2,0,4" style="line-height: 1.15 !important; margin-top: 0px !important;">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c667180327="" style="line-height: 1.15 !important; margin-top: 0px !important;">  <source-inline-chip _ngcontent-ng-c667180327="" _nghost-ng-c3963944138="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----></source-inline-chip><!----><!----><!----></sources-carousel-inline></p></li><li style="font-family: " google="" sans="" text",="" sans-serif="" !important;="" line-height:="" 1.15="" margin-top:="" 0px="" !important;"=""><p data-path-to-node="5,3,0" id="p-rc_7e7046225175ac23-40" style="line-height: 1.15 !important;"><span data-path-to-node="5,3,0,0" style="line-height: 1.15 !important; margin-top: 0px !important;"><b data-path-to-node="5,3,0,0" data-index-in-node="0" style="line-height: 1.15 !important; margin-top: 0px !important;">Structural Integrity:</b> The <b data-path-to-node="5,3,0,0" data-index-in-node="26" style="line-height: 1.15 !important; margin-top: 0px !important;">torn and damaged hull plating at the starboard bow (401)</b> and the <b data-path-to-node="5,3,0,0" data-index-in-node="91" style="line-height: 1.15 !important; margin-top: 0px !important;">bent internal members of the cargo holds (404)</b> <br>require close monitoring</span><span data-path-to-node="5,3,0,1" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c3458427909="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="5,3,0,2" style="line-height: 1.15 !important; margin-top: 0px !important;">. While the bow is currently under repair, all structural welding must be fully approved by the attending Class Surveyor before the vessel returns to sea</span><span data-path-to-node="5,3,0,3" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c3458427909="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="5,3,0,4" style="line-height: 1.15 !important; margin-top: 0px !important;">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c667180327="" style="line-height: 1.15 !important; margin-top: 0px !important;">  <source-inline-chip _ngcontent-ng-c667180327="" _nghost-ng-c3963944138="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"></source-inline-chip></sources-carousel-inline></p></li>', '<h3 data-path-to-node="7"><b data-path-to-node="7" data-index-in-node="0"><span style="font-size: 14px;">1. Certification & Documentation</span></b></h3><ul data-path-to-node="8"><li><p data-path-to-node="8,0,0"><b data-path-to-node="8,0,0" data-index-in-node="0">Classification Certificate (101):</b> Not available onboard. This is a critical statutory document; lack of availability poses a high risk of port state detention.</p></li><li><p data-path-to-node="8,1,0"><b data-path-to-node="8,1,0" data-index-in-node="0">Competence of Officers (102):</b> Officers'' certificates of competency are not available onboard.</p></li><li><p data-path-to-node="8,2,0"><b data-path-to-node="8,2,0" data-index-in-node="0">UT Test Certificate (103):</b> Ultrasonic Thickness (UT) gauging certificate is not available onboard.</p></li></ul><h3 data-path-to-node="9"><b data-path-to-node="9" data-index-in-node="0"><span style="font-size: 14px;">2. Navigation & Publications</span></b></h3><ul data-path-to-node="10"><li><p data-path-to-node="10,0,0"><b data-path-to-node="10,0,0" data-index-in-node="0">Notice to Mariners / NTM (203):</b> Not available onboard. The vessel has reportedly never received any NTM Bulletins, which poses a risk to passage planning and chart updating.</p></li><li><p data-path-to-node="10,1,0"><b data-path-to-node="10,1,0" data-index-in-node="0">List of Charts (204):</b> The standard list/catalog of marine charts is not available onboard.</p></li></ul><h3 data-path-to-node="11"><b data-path-to-node="11" data-index-in-node="0"><span style="font-size: 14px;">3. Safety & Operational Equipment</span></b></h3><ul data-path-to-node="12"><li><p data-path-to-node="12,0,0"><b data-path-to-node="12,0,0" data-index-in-node="0">Emergency Steering Instructions (206):</b> Changeover instructions for the emergency steering system are missing and not posted at the navigation bridge and engine room.</p></li><li><p data-path-to-node="12,1,0"><b data-path-to-node="12,1,0" data-index-in-node="0">Scupper Plugs (305):</b> Not available onboard, posing a non-compliance risk for pollution prevention during port operations.</p></li></ul><h3 data-path-to-node="13"><b data-path-to-node="13" data-index-in-node="0"><span style="font-size: 14px;">4. Hull Structure & Cargo Hold Condition</span></b></h3><ul data-path-to-node="14"><li><p data-path-to-node="14,0,0"><b data-path-to-node="14,0,0" data-index-in-node="0">Hull Bow at Starboard Side (401):</b> The hull plating was found torn and damaged. At the time of the survey, this area was still undergoing repairs.</p></li><li><p data-path-to-node="14,1,0"><b data-path-to-node="14,1,0" data-index-in-node="0">Accommodation Door to Engine Room (403):</b> The structural door is damaged, with localized corrosion noted on the lower section (compromising structural fire/gas integrity).</p></li><li><p data-path-to-node="14,2,0"><b data-path-to-node="14,2,0" data-index-in-node="0">Cargo Hold Interior (404):</b> Several internal structural members within the cargo holds are bent and physically damaged.</p></li><li><p data-path-to-node="14,3,0"><b data-path-to-node="14,3,0" data-index-in-node="0">Hatch Covers (406):</b> Several areas of the hatch covers exhibit signs of minor corrosion.</p></li></ul><h3 data-path-to-node="15"><b data-path-to-node="15" data-index-in-node="0"><span style="font-size: 14px;">5. Excluded from Inspection (Not Inspected)</span></b></h3><ul data-path-to-node="16"><li><p data-path-to-node="16,0,0"><b data-path-to-node="16,0,0" data-index-in-node="0">Zinc Anodes :</b> The cathodic protection anodes could not be inspected as they were completely submerged under water.</p></li></ul>', '<li style="font-family: " google="" sans="" text",="" sans-serif="" !important;="" line-height:="" 1.15="" margin-top:="" 0px="" !important;"=""><p data-path-to-node="7,0,0" id="p-rc_e1b7030cc87eab21-97" style="line-height: 1.15 !important;"><span data-path-to-node="7,0,0,0" style="line-height: 1.15 !important; margin-top: 0px !important;"><b data-path-to-node="7,0,0,0" data-index-in-node="0" style="line-height: 1.15 !important; margin-top: 0px !important;">Administrative & Documentation Status:</b> The vessel''s statutory documentation is currently compliant but temporarily ashore</span><span data-path-to-node="7,0,0,1" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c3458427909="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="7,0,0,2" style="line-height: 1.15 !important; margin-top: 0px !important;">. The Classification Certificate (101), Officers'' Certificates of Competency (102), and UT Test Certificate (103) were not onboard during the inspection solely due to ongoing port clearance processes handled by the ship''s agent</span><span data-path-to-node="7,0,0,3" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c3458427909="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="7,0,0,4" style="line-height: 1.15 !important; margin-top: 0px !important;">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c667180327="" style="line-height: 1.15 !important; margin-top: 0px !important;">  <source-inline-chip _ngcontent-ng-c667180327="" _nghost-ng-c3963944138="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----></source-inline-chip><!----><!----><!----></sources-carousel-inline></p></li><li style="font-family: " google="" sans="" text",="" sans-serif="" !important;="" line-height:="" 1.15="" margin-top:="" 0px="" !important;"=""><p data-path-to-node="7,1,0" id="p-rc_e1b7030cc87eab21-98" style="line-height: 1.15 !important;"><span data-path-to-node="7,1,0,0" style="line-height: 1.15 !important; margin-top: 0px !important;"><b data-path-to-node="7,1,0,0" data-index-in-node="0" style="line-height: 1.15 !important; margin-top: 0px !important;">Physical & Structural Condition:</b> The vessel is under active maintenance</span><span data-path-to-node="7,1,0,1" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c3458427909="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="7,1,0,2" style="line-height: 1.15 !important; margin-top: 0px !important;">. The torn starboard bow plating (401) is actively undergoing repairs at the anchorage</span><span data-path-to-node="7,1,0,3" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c3458427909="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="7,1,0,4" style="line-height: 1.15 !important; margin-top: 0px !important;">. Concurrently, minor structural findings such as bent internal cargo hold members (404) and minor corrosion on the hatch covers (406) and the lower section of the accommodation door (403) have been noted for routine maintenance scheduling</span><span data-path-to-node="7,1,0,5" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c3458427909="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="7,1,0,6" style="line-height: 1.15 !important; margin-top: 0px !important;">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c667180327="" style="line-height: 1.15 !important; margin-top: 0px !important;">  <source-inline-chip _ngcontent-ng-c667180327="" _nghost-ng-c3963944138="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----></source-inline-chip><!----><!----><!----></sources-carousel-inline></p></li><li style="font-family: " google="" sans="" text",="" sans-serif="" !important;="" line-height:="" 1.15="" margin-top:="" 0px="" !important;"=""><p data-path-to-node="7,2,0" id="p-rc_e1b7030cc87eab21-99" style="line-height: 1.15 !important;"><span data-path-to-node="7,2,0,0" style="line-height: 1.15 !important; margin-top: 0px !important;"><b data-path-to-node="7,2,0,0" data-index-in-node="0" style="line-height: 1.15 !important; margin-top: 0px !important;">Operational Readiness Requirements (Priority):</b> Prior to vessel departure, immediate corrective actions should focus on replenishing the missing nautical charts and NTM bulletins (203, 204), providing scupper plugs (305), and posting the emergency steering changeover instructions (206) at the bridge and engine room to ensure full emergency preparedness</span><span data-path-to-node="7,2,0,1" style="line-height: 1.15 !important; margin-top: 0px !important;"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"><sup _ngcontent-ng-c3458427909="" class="superscript" style="line-height: 1.15 !important; margin-top: 0px !important; font-size: 16px !important; background-color: transparent !important;"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="7,2,0,2" style="line-height: 1.15 !important; margin-top: 0px !important;">.</span></p><p data-path-to-node="7,2,0" id="p-rc_e1b7030cc87eab21-99" style="line-height: 1.15 !important;"><span data-path-to-node="7,2,0,2" style="line-height: 1.15 !important; margin-top: 0px !important;"><br></span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c667180327="" style="line-height: 1.15 !important; margin-top: 0px !important;">  <source-inline-chip _ngcontent-ng-c667180327="" _nghost-ng-c3963944138="" class="ng-star-inserted" style="line-height: 1.15 !important; margin-top: 0px !important;"></source-inline-chip></sources-carousel-inline></p></li>', '2026-05-15', '2027-05-15', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (800, 605, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-06-14', NULL, NULL, NULL, '2026-05-15', '2027-05-15', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (801, 606, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-06-14', NULL, NULL, NULL, '2026-05-15', '2027-05-15', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (802, 607, 1, 9, 'Zhafran Fajar Bagaskoro', 'Survey', 'Completed', 'complete', 'Bojonegara, Banten', '2026-06-17', '2026-06-17', '<p><br></p>', '<p class="MsoNormal">The class and statutory certificates werernavailable onboard at the time of the survey.Â <o:p></o:p></p><p class="MsoNormal"><span style="font-size: 0.875rem;">The vessel''s structural condition was generally in fairrncondition, with fair paintwork. The draft marks on the port and starboardrnsides, as well as the load lines, were clearly marked.</span></p><p class="MsoNormal"><span style="font-size: 0.875rem;">The fuel-air vent and sounding pipe were found in fairrncondition. The hatch cover fitted on the vessel is a pontoon foldingrntype. The hatch cover was covered by tarpaulins (2-layers). Hence,rncompression bars, landing pads and securing devices are not applicable.</span></p><p class="MsoNormal"><span style="font-size: 0.875rem;">The navigation and communication equipment was consideredrnsufficient, although the charts list was not updated. The magnetic compass werernfound in good working order.</span></p><p class="MsoNormal"><span style="font-size: 0.875rem;">As far we could ascertain by visual appearance, thernemergency generator and emergency steering gear were found to be inrnsatisfactory condition. The ballast tank pressure test was satisfactory. Althoughrnthe manhole cover No. 2P was found leaked during test.</span></p><p class="MsoNormal"><span style="font-size: 0.875rem;">The SOPEP locker, complete with its contents, was availablernon board. The bunkering connection was fitted with proper save-alls, but thernwindlass on the poop deck was found to be without save-alls.</span></p><p class="MsoNormal"><span style="font-size: 0.875rem;">Nevertheless, the crew''s skill in working and operating therngeneral cargo was considered sufficient, and they were familiar with the typernand size of the vessel.</span></p><p style="margin-top: 0cm; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;">rnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrn</p><p class="MsoNormal"><o:p>Â </o:p></p>', '<p class="MsoNormal"><b><u>SUMMARY</u></b><o:p></o:p></p><p class="MsoNormal">The survey onboard General Cargo "BUANA MEKAR" wasrncarried out on 17 June 2026 at Bojonegara, Banten, with attendance,<o:p></o:p></p><p class="MsoNormal">1. HadirnSiswantoÂ Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â rnÂ Â Â  Â Â Â Â Â Â  Â  Â  Â rnÂ  Â  Â  Â  Â  Â  - Chief Officer of the General Cargorn"BUANA MEKAR"<o:p></o:p></p><p class="MsoNormal">2. Reza AlfizaÂ  Â  Â  Â  Â  Â rnÂ  Â  Â  Â  Â rnÂ Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â -rnChief Engineer of the General Cargo "BUANA MEKAR"<o:p></o:p></p><p class="MsoNormal">3. Yudi PurnawanÂ  Â  Â  Â  Â  Â rnÂ  Â  Â  Â  Â rnÂ Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â Â -rnRepresentative owner of PT Indomas Bahari Makmur<o:p></o:p></p><p class="MsoNormal">Â <o:p></o:p></p><p class="MsoNormal">General cargo "BUANA MEKAR" is a 649 GT vesselrnpresently owned and operated by PT Indomas Bahari Makmur. The vessel was moored at Bojonegara, Banten, while stand by for survey. Furthermore, thernvessel''s trading area is in Indonesian waters.<o:p></o:p></p><p class="MsoNormal">Â <o:p></o:p></p><p class="MsoNormal"><b><u>VESSEL CERTIFICATION AND DOCUMENTATION</u></b><o:p></o:p></p><p class="MsoNormal">Class survey certificates for hull and machinery werernavailable at the time of the survey.<o:p></o:p></p><p class="MsoNormal">The latest UT thickness measurement report was availablernonboard the vessel, and the diminution level of the vessel''s steel structuresrnwas found to be below the class maximum allowable limit of 20%.<o:p></o:p></p><p class="MsoNormal">Â <o:p></o:p></p><p class="MsoNormal"><b><u>GENERAL CONDITION OF HULL AND DECK</u></b><o:p></o:p></p><p class="MsoNormal">At the time of our survey, the vessel was moored alongsidernon her port side; therefore, only her starboard side could be ascertained. Thernstarboard side shell plating from the aft to the fore-ends was visually in fairrncondition. However, the painting work is also fair. The draft marks and loadrnlines were marked and visible.<o:p></o:p></p><p class="MsoNormal">During our inspection, the visible condition of the mainrndeck, boat deck and bridge deck plating was found to be in fair condition. The coamingrnaround the escape hatch opening was found damaged and broken. However, the walkwaysrnand ladders on the vessel were found to be in satisfactory condition. Thernmooring equipment, which includes theÂ <span style="font-size: 0.875rem;">bollard, fairlead, and capstan,rnwas found to be in fair condition. The fuel air vents and sounding pipes werernalso in good condition. The weathertight doors were also in fair condition.</span></p><p class="MsoNormal">The winch and windlass, as far as we could ascertain, wererngenerally in fair condition. The vessel had 1 (one) cargo hold.<o:p></o:p></p><p class="MsoNormal">The hatch cover fitted on the vessel is a pontoonrnfolding type. Hence, compression bars, landing pads and securing devices arernnot applicable. The hatch cover was covered by tarpaulins (2-layers) for weatherrntightness.<o:p></o:p></p><p class="MsoNormal">The vessel is a single-hull and double-bottom type.<o:p></o:p></p><p class="MsoNormal"><b><u>BALLAST TANKS</u></b><o:p></o:p></p><p class="MsoNormal">During our inspection, the vessel had no cargo onboard andrnwas already gas-free, but we can''t access the internal condition ofrnballast tanks no. 2 and 3 (port and starboard) due to the full water. So wernwere only assessing the internal condition of ballast tank No.1 (port andrnstarboard).<o:p></o:p></p><p class="MsoNormal">The steel structure and internal structure ballast tank Nos.rn1P, 1S are found corroded at several places, in fair condition, with the anodes installed in order.<o:p></o:p></p><p class="MsoNormal"><b><u>BRIDGE AND NAVIGATION</u></b><o:p></o:p></p><p class="MsoNormal">The navigation and communication equipment were in goodrncondition were sufficient for domestic or local trading within Indonesianrnwaters, although the charts list was not updated. The Notice to Mariners (NTM)rnwas updated on 15 May 2026. The crew''s emergency steering procedure wasrnprovided and posted.<br>rn<!--[if !supportLineBreakNewLine]--><br>rn<!--[endif]--><o:p></o:p></p><p class="MsoNormal"><b><u>MACHINERY SPACE AND STEERING GEAR</u></b><o:p></o:p></p><p class="MsoNormal">The vessel is equipped with 1 (one) main engine, 1 (one)rnauxiliary engine, 1 (one) emergency generator, as far we could ascertain, allrnof which found to be in satisfactory condition.<o:p></o:p></p><p class="MsoNormal">The auxiliary engine is registered on the classrncertificate.<o:p></o:p></p><p class="MsoNormal">As far as we could ascertain, by visual the emergencyrnsteering gear and generator were in satisfactory condition. The emergencyrnprocedure was posted.<o:p></o:p></p><p class="MsoNormal">The emergency steering was completely tested withrnsatisfactory results.<o:p></o:p></p><p class="MsoNormal"><b><u>SAFETY AND POLLUTION</u></b><o:p></o:p></p><p class="MsoNormal">The vessel was provided with SOPEP box, complete with itsrncontents. The pollution prevention equipment is adequate in accordance withrnsafety regulations.<o:p></o:p></p><p class="MsoNormal">The bunkering connection was found to be in good condition.rnHowever, the save-alls have not been installed on the poop deck mooringrnhydraulic windlass.<o:p></o:p></p><p class="MsoNormal">The fuel-air ventilation, sounding pipe, and air ventilationrnwere found in fair condition. The scupper plugs were available onboard.<o:p></o:p></p><p style="margin-top: 0cm; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;">rnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrnrn</p><p class="MsoNormal">==END==<o:p></o:p></p>', '2026-07-06', '2027-07-06', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (803, 608, 1, 9, 'Renaldio Pradipta Puspito', 'Survey', 'Completed', 'complete', 'Sunda Kelapa, Jakarta', '2026-05-29', '2026-05-29', '<p class="isSelectedEnd">The railing and bulwark in way of the superstructure were found slightly dented. During our interview, the crew verbally advised that the damage was sustained during berthing operations at Sunda Kelapa Port. It was understood that vessels operating at Sunda Kelapa Port commonly berth alongside other vessels rather than directly alongside a wharf, which may increase the risk of contact damage during berthing operations.</p><p>Whilst such berthing arrangements are considered common practice at the port, the owner is recommended to conduct an appropriate risk assessment and implement suitable risk mitigation measures to minimize the possibility of similar damage occurring during future port operations.</p><p>The internal structures within ballast tanks Nos. 1P and 1S, which were found to be in fair condition with zinc anodes installed, should be treated, and recoated to prevent further deterioration.</p>', '<p>The statutory certificate and class certificate were available onboard at the time of the survey.&nbsp;<br class="Apple-interchange-newline"></p><p><span style="font-size: 0.875rem;">The vessel''s structural condition was generally in fair condition, with fair paintwork and light indentations observed at places. The draft marks on the port and starboard sides, as well as the load lines, were clearly marked.</span></p><p style="color: rgb(33, 37, 41);"><span style="font-size: 0.875rem;">The fuel-air vent and sounding pipe were found in fair condition. </span>The hatch cover fitted on the vessel is a pontoon folding type.&nbsp;<span style="font-size: 0.875rem;">The hatch cover was covered by tarpaulins (2-layer).&nbsp;</span><span style="font-size: 0.875rem;">Hence, compression bars, landing pads and securing devices are not applicable.</span></p><p style="color: rgb(33, 37, 41);"><span style="font-size: 0.875rem;">The navigation and communication equipment was considered sufficient, although the charts list was not updated. The gyro compass and magnetic compass were found in good working order.</span></p><p style="color: rgb(33, 37, 41);">As far we could ascertain by visual appearance, the emergency generator and emergency steering gear were found to be in satisfactory condition. The ballast tank pressure test was satisfactory.</p><p><span style="color: rgb(33, 37, 41);">The SOPEP locker, complete with its contents, was available on board. The bunkering connection was fitted with <span style="background-color: rgb(255, 255, 255);">improper </span>save-alls.</span></p><p><span style="color: rgb(33, 37, 41);">Nevertheless, the crew''s skill in working and operating the general cargo was considered sufficient, and they were familiar with the type and size of the vessel.</span></p>', '<p style="color: rgb(33, 37, 41);"><span style="font-weight: bolder;"><u>SUMMARY</u></span></p><p style="color: rgb(33, 37, 41);">The survey onboard General Cargo "BUANA PERTIWI" was carried out on 29 May 2026 at Sunda Kelapa Anchorage, Jakarta, with attendance,</p><p style="color: rgb(33, 37, 41);">1. Montcomerri Robert Lewakabessy&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Master of the General Cargo "BUANA PERTIWI"</p><p style="color: rgb(33, 37, 41);">2. Solehudin&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Chief Engineer of the General Cargo "BUANA PERTIWI"</p><p style="color: rgb(33, 37, 41);">3. Yudi Purnawan&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- Representative owner of PT Indomas Bahari Makmur</p><p style="color: rgb(33, 37, 41);"><br></p><p style="color: rgb(33, 37, 41);">General cargo "BUANA PERTIWI" is a 632 GT vessel presently owned and operated by PT Indomas Bahari Makmur. The vessel whlist anchored at Sunda Kelapa Anchorage, Jakarta, while stand by for survey. Furthermore, the vessel''s trading area is mostly in Indonesian waters.</p><p style="color: rgb(33, 37, 41);"><br></p><p style="color: rgb(33, 37, 41);"><span style="font-weight: bolder;"><u>VESSEL CERTIFICATION AND DOCUMENTATION</u></span></p><p style="color: rgb(33, 37, 41);">Class survey records for hull and machinery were available at the time of the survey.</p><p style="color: rgb(33, 37, 41);">The latest UT thickness measurement report was available onboard the vessel, and the diminution level of the vessel''s steel structures was found to be below the class maximum allowable limit of 20%.</p><p style="color: rgb(33, 37, 41);"><br></p><p style="color: rgb(33, 37, 41);"><span style="font-weight: bolder;"><u>GENERAL CONDITION OF HULL AND DECK</u></span></p><p style="color: rgb(33, 37, 41);">As far as could be ascertained, the port and starboard side shell plating from the aft to the fore-ends was visually in fair condition. However, the painting work is also fair, with some light indentation at places. The draft marks and load lines on both the port and starboard sides were marked and visible.</p><p style="color: rgb(33, 37, 41);">During our inspection, the visible condition of the main deck, boat deck and bridge deck plating was found to be in fair condition. The walkways and ladders on the vessel were found to be in satisfactory condition, but some railing guards and bulwarks had light dented.&nbsp;</p><p style="color: rgb(33, 37, 41);">The mooring equipment, which includes the double bollard, fairlead, and capstan, was found to be in fair condition. The fuel air vents and sounding pipes were also in good condition. <span style="font-size: 0.875rem;">The watertight doors were also in fair condition.</span></p><p style="color: rgb(33, 37, 41);"><span style="font-size: 0.875rem;">The winch and windlass, as far as we could ascertain, were generally in fair condition.</span><span style="font-size: 0.875rem;">&nbsp;The vessel had 1 (one) cargo hold</span><span style="font-size: 0.875rem;">.</span></p><p style="color: rgb(33, 37, 41);">The hatch cover fitted on the vessel is a pontoon type that is stacked on the hatch coaming. Hence, compression bars, landing pads and securing devices are not applicable. <span style="font-size: 0.875rem;">The hatch cover was covered by tarpaulins (2-layer) for weather tightness.</span></p><p style="color: rgb(33, 37, 41);"><span style="color: rgb(0, 0, 0);">The vessel is a single-hull and double-bottom type.</span></p><p style="color: rgb(33, 37, 41);"><u style="font-size: 0.875rem; font-weight: 700;">BALLAST TANKS</u></p><p style=""><span style="color: rgb(0, 0, 0);">During our inspection, the vessel had no cargo onboard and was already gas-free, but we&nbsp;</span>can''t access the internal condition of ballast tanks no. 2 and 3 (port and starboard) due to the full <span style="font-size: 0.875rem;">water</span><span style="color: rgb(0, 0, 0); font-size: 0.875rem;">. So we were only assessing the internal condition of ballast tank No.1 (port and starboard).</span></p><p style=""><font color="#212529"><span style="font-size: 0.875rem;">The steel structure and internal structure ballast tank Nos. 1P,</span>&nbsp;1S are found corroded at several places, in fair condition,<span style="font-size: 0.875rem;">&nbsp;with the zinc anodes installed in order.</span></font></p><p style="color: rgb(33, 37, 41);"><u style="font-weight: bolder; font-size: 0.875rem;">BRIDGE AND NAVIGATION</u></p><p style="color: rgb(33, 37, 41);">The navigation and communication equipment were in good condition when flame tested and were sufficient for domestic or local trading within Indonesian waters. The Notice to Mariners (NTM) was updated on 15 May 2026. The crew''s emergency steering procedure was provided and posted.</p><p style="color: rgb(33, 37, 41);"><u style="font-weight: bolder; font-size: 0.875rem;">MACHINERY SPACE AND STEERING GEAR</u></p><p style="color: rgb(33, 37, 41);">The vessel is equipped with 1 (one) main engine, 2 (two) auxiliary engines, 1 (one) emergency generators, as far we could ascertain, all of which found to be in satisfactory condition. The engine logbook was reviewed and found to be regularly updated.&nbsp;</p><p style="color: rgb(33, 37, 41);">The auxiliary engines No.1 and No.2 are registered on the class certificate. The engine logbook was found to be regularly updated.</p><p style="color: rgb(33, 37, 41);">As far as we could ascertain, by visual the emergency steering gear and generator were in satisfactory condition. The emergency procedure was posted.</p><p style="color: rgb(33, 37, 41);"><span style="color: rgb(0, 0, 0);">The emergency steering was completely tested with satisfactory results.</span>n<br class="Apple-interchange-newline"></p><p style="color: rgb(33, 37, 41);"><u style="font-weight: bolder; font-size: 0.875rem;">SAFETY AND POLLUTION</u></p><p style="color: rgb(33, 37, 41);">The vessel was provided with SOPEP box, complete with its contents. The pollution prevention equipment is adequate in accordance with safety regulations.</p><p style="color: rgb(33, 37, 41);"><span style="font-size: 0.875rem;">The bunkering connection were found in good condition. However, the save-alls are not installed in order.</span></p><p style="color: rgb(33, 37, 41);"><span style="font-size: 0.875rem;">The fuel-air ventilation, sounding pipe, and air ventilation were found in fair condition. </span><span style="font-size: 0.875rem;">The scupper plugs were available onboard.</span></p><p style="color: rgb(33, 37, 41);">==END==</p>', '2026-06-10', '2027-06-10', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (804, 609, 13, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-06-18', NULL, NULL, NULL, '2026-05-19', '2027-05-19', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (805, 610, 13, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-06-19', NULL, NULL, NULL, '2026-05-20', '2027-05-20', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (806, 611, 1, 9, 'Tomy Wijaya', 'Survey', 'Completed', 'complete', 'Tabuan Anchorage, Banyuwangi, East Java', '2026-06-02', '2026-06-26', '<p>According to the oil barges'' general arrangement, the accommodation spaces are located at the aft of the barge and are fully configured to accommodate the onboard crew.</p><p>It was verified that the crew remaining on board the oil barge hold valid Able Seaman (AB) certificates, ensuring competent assistance during cargo loading/unloading operations and mooring/unmooring procedures.</p>', '<p>The Ultrasonic Thickness (UT) measurement report was not available for review at the time of the survey.</p><p>The fuel oil air vent pipes, and the ballast tank sounding pipes were found without appropriate identification markings to indicate their respective service tanks.</p><p>The accommodation toilet doors were found without rubber sealing gaskets installed.</p>', '<p><b><u>SUMMARY</u></b></p><p>The survey onboard Oil Barge "JOHAR 02" was carried out on 02 June 2026 at Tabuan Anchorage, Banyuwangi, East Java, with attendance:</p><ol><li>Hadi Joko Suyono, the able seaman of Oil Barge "JOHAR 02"</li><li>Sopian Efendi, the able seaman of Oil Barge "JOHAR 02"</li><li>Redi Junaedi, the able seaman of Oil Barge "JOHAR 02"</li></ol><p>Oil Barge "JOHAR 02" is a 666 GT, the oil barge presently owned and operated by PT Insamjaya Reksa, Surabaya. The last docking of the oil barge at PT Orela Shipyard, Gresik, East Java, on 27 March 2025. Furthermore, the vessel''s trading area is mostly in Indonesian waters.</p><p><b style="font-size: 0.875rem;"><br></b></p><p><b style="font-size: 0.875rem;">GENERAL CONDITION</b></p><p>As far as could be ascertained while the oil barge was inspected afloat, the side shell plating from sheer down to the light water line, from aft to fore ends, was visually found in fair condition with fair paint works.</p><p><span style="font-size: 0.875rem;">The last thickness measurement record taken on the last dry dock is not available onboard.&nbsp;</span></p><div><br></div><p><b>DECK&nbsp;</b></p><p><span style="font-size: 13.3333px;">The main deck plating and structural fittings were observed in fair overall condition with good paint preservation. The cargo oil tank air vents, and ballast sounding pipes were not available with identification marks for their designated compartments.</span></p><p><br></p><p><b>CARGO &amp; NON CARGO TANKS</b></p><p>The barge is configured with 10 (ten) Cargo Oil Tanks (COTs), comprising COT Nos. 1 to 5 (Port and Starboard). Additionally, the forepeak and afterpeak tanks on both the port and starboard sides are utilized as freshwater tanks.&nbsp;</p><p><span style="font-size: 0.875rem;">During our inspection, the internal structures of the cargo tanks were observed to be generally in fair condition. However, several newly installed steel plates within the cargo oil tanks were found uncoated.</span></p><p>The barge is constructed with a double bottom configuration, which comprises 10 (ten) dedicated void tanks. Meanwhile, Void Tank No. 1 (Port) was opened by the crew for internal examination, and the internal structure was found to be in fair overall condition.</p><div><br></div><p><b>SHIP CERTIFICATES</b></p><p><span style="font-size: 0.875rem;">Classification certificate for hull was made available at time of survey. The class status is maintained.</span></p><p><span style="font-size: 0.875rem;"><br></span></p><p><b>SAFETY AND POLLUTION</b></p><p>The oil barge was provided with a SOPEP box complete with its contents (sawdust and the SOPEP tools). The pollution prevention equipment is adequate in accordance with safety regulations.</p><p>The bunkering connection save-alls were found in fair condition, and the required scupper plugs were verified as available on board.</p><div><br></div><p style="text-align: center; ">=== END ===</p><div><br></div>', '2026-05-27', '2027-05-27', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (807, 612, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-06-20', NULL, NULL, NULL, '2026-05-21', '2027-05-21', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
