INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (809, 614, NULL, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-06-20', NULL, NULL, NULL, '2026-05-21', '2027-05-21', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (810, 615, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-06-20', NULL, NULL, NULL, '2026-05-21', '2027-05-21', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (811, 616, 13, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-06-18', NULL, NULL, NULL, '2026-05-19', '2027-05-19', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (812, 617, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-06-26', NULL, NULL, NULL, '2026-05-27', '2027-05-27', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (813, 618, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-06-20', NULL, NULL, NULL, '2026-05-21', '2027-05-21', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (814, 619, 13, 9, 'SAMUEL MISDOM', 'Survey', 'Outstanding', 'complete', 'KUMAI', '2026-06-09', '2026-06-25', '<h2 data-path-to-node="2"><b data-path-to-node="2" data-index-in-node="0"><span style="font-size: 14px;">SURVEYOR''S CONCERNS (MV. MANDIRI 18)</span></b></h2><p data-path-to-node="3">Based on the survey findings, the Surveyor has summarized the following critical notes regarding operational compliance, navigation safety, and technical maintenance risks:</p><h3 data-path-to-node="4">&nbsp; &nbsp; <span data-path-to-node="4" data-index-in-node="0"><span style="font-size: 14px;"><b>1. Documentation Compliance &amp; Regulatory Readiness<br></b></span></span><span style="font-size: 0.875rem;"><b>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-</b>&nbsp;</span><b data-path-to-node="5,0,0" data-index-in-node="0" style="font-size: 0.875rem;">Class &amp; UT Certificates Not Available Onboard:</b><span style="font-size: 0.875rem;"> While these statutory certificates may be valid and currently held by the shipping agent, their physical absence from the vessel can trigger administrative compliance issues during spot-checks by Port Authorities or Flag State inspectors. Original documents or certified true copies must be returned to the vessel prior to departure.<br></span><span data-path-to-node="6" data-index-in-node="0" style="color: inherit; font-family: inherit; font-size: 1.75rem;"><span style="font-size: 14px;">&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<b>2. Navigation Safety Risks&nbsp;</b></span><i data-path-to-node="6" data-index-in-node="29" style="font-weight: bold;"><span style="font-size: 14px;"><br></span></i></span><b data-path-to-node="7,0,0" data-index-in-node="0" style="font-size: 0.875rem;"><i>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-&nbsp;</i>Defective Radar &amp; Outdated Publications:</b><span style="font-size: 0.875rem;"> Sailing with a malfunctioning radar unit and lacking any Notice to Mariners (NTM) updates or updated nautical charts for over a year poses a severe navigation hazard. This significantly increases the risk of </span><b data-path-to-node="7,0,0" data-index-in-node="249" style="font-size: 0.875rem;">collision</b><span style="font-size: 0.875rem;"> or </span><b data-path-to-node="7,0,0" data-index-in-node="262" style="font-size: 0.875rem;">grounding</b><span style="font-size: 0.875rem;">, particularly during nighttime navigation or restricted visibility.<br></span><span data-path-to-node="8" data-index-in-node="0" style="color: inherit; font-family: inherit; font-size: 1.75rem;"><span style="font-size: 14px;">&nbsp; &nbsp; &nbsp; &nbsp;<b>3. Hidden Structural Risks&nbsp;</b></span><i data-path-to-node="8" data-index-in-node="29" style="font-weight: bold;"><span style="font-size: 14px;"><br></span></i></span><b data-path-to-node="9,0,0" data-index-in-node="0" style="font-size: 0.875rem;"><i>&nbsp; &nbsp; &nbsp; &nbsp; -&nbsp;</i>Permanently Sealed Ballast Tanks:</b><span style="font-size: 0.875rem;"> This is the primary technical concern for the Surveyor. Because the manhole access openings are permanently welded shut, the internal structural integrity and corrosion rates inside the ballast tanks cannot be verified. This creates an unmonitored risk of internal structural wastage or hidden fractures.<br></span><span data-path-to-node="9,1,0" data-index-in-node="0" style="font-size: 0.875rem;">&nbsp; &nbsp; &nbsp; &nbsp; -&nbsp;</span><b data-path-to-node="9,1,0" data-index-in-node="0" style="font-size: 0.875rem;">Forecastle &amp; Deck Plate Corrosion:</b><span style="font-size: 0.875rem;"> If not immediately addressed via scaling, chipping, and recoating, the active corrosion on the forecastle and main deck (port and starboard) will weaken the deck plating, which supports heavy-duty mooring and anchoring equipment.<br></span><span data-path-to-node="10" data-index-in-node="0" style="color: inherit; font-family: inherit; font-size: 1.75rem;"><span style="font-size: 14px;">&nbsp; &nbsp; &nbsp; &nbsp;<b>4. Marine Environmental &amp; Pollution Risks<br></b></span></span><b data-path-to-node="11,0,0" data-index-in-node="0" style="font-size: 0.875rem;">&nbsp; &nbsp; &nbsp; &nbsp; - Missing Scupper Plugs &amp; Save-All Covers:</b><span style="font-size: 0.875rem;"> In the event of an accidental oil spill on deck (during bunkering or maintenance), the lack of proper scupper plugs and save-all drain covers means oil could flow directly into the sea, potentially triggering severe environmental penalties.<br></span><span data-path-to-node="12" data-index-in-node="0" style="color: inherit; font-family: inherit; font-size: 1.75rem;"><span style="font-size: 14px;">&nbsp; &nbsp; &nbsp; &nbsp;<b>5. Emergency Preparedness<br></b></span></span><b data-path-to-node="13,0,0" data-index-in-node="0" style="font-size: 0.875rem;">&nbsp; &nbsp; &nbsp; &nbsp; - Missing Emergency Steering Instructions:</b><span style="font-size: 0.875rem;"> The absence of clear, localized operating guidelines for the emergency steering gear could delay the crew''s response time during a sudden failure of the primary steering system at sea.</span></h3>', '<h4 data-path-to-node="17"><b data-path-to-node="17" data-index-in-node="0"><span style="font-size: 14px;">1. Certification &amp; Documentation</span></b></h4><ul data-path-to-node="18"><li><p data-path-to-node="18,0,0"><b data-path-to-node="18,0,0" data-index-in-node="0">(101):</b> Class certificate is not available onboard.</p></li><li><p data-path-to-node="18,1,0"><b data-path-to-node="18,1,0" data-index-in-node="0">(103):</b> UT (Ultrasonic Thickness) Test Certificate is not available onboard.</p></li><li><p data-path-to-node="18,2,0"><b data-path-to-node="18,2,0" data-index-in-node="0">(203):</b> The vessel has not received any Notice to Mariners (NTM) Bulletins for the past one (1) year.</p></li><li><p data-path-to-node="18,3,0"><b data-path-to-node="18,3,0" data-index-in-node="0">(204):</b> Up-to-date navigation charts are not available onboard.</p></li></ul><h4 data-path-to-node="19"><b data-path-to-node="19" data-index-in-node="0"><span style="font-size: 14px;">2. Bridge Equipment &amp; Navigation</span></b></h4><ul data-path-to-node="20"><li><p data-path-to-node="20,0,0"><b data-path-to-node="20,0,0" data-index-in-node="0">(201):</b> Radar is inoperable (error/damaged) and the official vessel Log Book is not available onboard.</p></li><li><p data-path-to-node="20,1,0"><b data-path-to-node="20,1,0" data-index-in-node="0">(206):</b> Operating instructions for the emergency steering system are not posted/available onboard.</p></li></ul><h4 data-path-to-node="21"><b data-path-to-node="21" data-index-in-node="0"><span style="font-size: 14px;">3. Safety &amp; Marine Pollution Prevention</span></b></h4><ul data-path-to-node="22"><li><p data-path-to-node="22,0,0"><b data-path-to-node="22,0,0" data-index-in-node="0">(304):</b> Drain covers are missing from the oil save-alls.</p></li><li><p data-path-to-node="22,1,0"><b data-path-to-node="22,1,0" data-index-in-node="0">(305):</b> Scupper plugs are not available onboard.</p></li></ul><h4 data-path-to-node="23"><b data-path-to-node="23" data-index-in-node="0"><span style="font-size: 14px;">4. Hull &amp; Structural Condition</span></b></h4><ul data-path-to-node="24"><li><p data-path-to-node="24,0,0"><b data-path-to-node="24,0,0" data-index-in-node="0">(402):</b> Active corrosion observed at the forecastle area and along the main deck (both port side and starboard side).</p></li><li><p data-path-to-node="24,1,0"><b data-path-to-node="24,1,0" data-index-in-node="0">(501):</b> Ballast tanks could not be inspected because the manhole access openings have been permanently sealed/welded shut.</p></li></ul><h4 data-path-to-node="25"><b data-path-to-node="25" data-index-in-node="0"><span style="font-size: 14px;">5. Areas Not Inspected (Inaccessible)</span></b></h4><ul data-path-to-node="26"><li><p data-path-to-node="26,0,0"><b data-path-to-node="26,0,0" data-index-in-node="0">(401):</b> Hull sacrificial Zinc Anodes could not be inspected as they are completely submerged underwater.</p></li></ul>', '<li><p data-path-to-node="5,0,0"><b data-path-to-node="5,0,0" data-index-in-node="0">Documentation &amp; Compliance:</b> The vessel is currently lacking mandatory paperwork, including Class and UT Test certificates, updated nautical charts, and a year''s worth of Notice to Mariners (NTM) bulletins.</p></li><li><p data-path-to-node="5,1,0"><b data-path-to-node="5,1,0" data-index-in-node="0">Navigation &amp; Safety:</b> Primary navigation is compromised due to a broken radar, and crew safety readiness is hindered by the absence of emergency steering instructions.</p></li><li><p data-path-to-node="5,2,0"><b data-path-to-node="5,2,0" data-index-in-node="0">Deck Conditions:</b> Physical deficiencies include structural corrosion on the forecastle and both side decks (port/starboard), alongside missing scupper plugs and save-all drain covers.</p></li><li><p data-path-to-node="5,3,0"><b data-path-to-node="5,3,0" data-index-in-node="0">Inspection Constraints:</b> Full assessment was restricted as the zinc anodes were submerged, and the ballast tanks could not be inspected due to being permanently sealed.</p></li>', '2026-05-26', '2027-05-26', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
