INSERT INTO surveys (id, vessel_id, surveyor_id, broker_id, surveyor_name, condition_type, status, form_status, location, date_of_survey, due_date, concern_from_surveyor, resume_from_surveyor, summary, policy_period_start, policy_period_end, created_at, updated_at) VALUES (830, 624, 14, 9, NULL, 'Survey', 'Outstanding', 'draft', NULL, NULL, '2026-05-30', NULL, NULL, NULL, '2026-04-30', '2027-04-30', NOW(), NOW()) ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, summary = EXCLUDED.summary;
