INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (112, 84, '<p>The hatch cover found with holes at places and some stiffener partly wasted&nbsp;</p>', '<p>Please repair the hatch cover with holes and wasted stiffeners.&nbsp;<br></p>', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (113, 84, '<p>The vessel uses some kind of pontoon as the hatch covers. The hatch covers found with holes at places and some stiffener partly wasted</p>', '<p>Please repair the hatch cover with holes and wasted stiffeners.&nbsp;<br></p>', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
