INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (119, 84, '<p><span style="font-size:11.0pt;line-height:107%;rnfont-family:&quot;Calibri&quot;,sans-serif;mso-ascii-theme-font:minor-latin;mso-fareast-font-family:rnCalibri;mso-fareast-theme-font:minor-latin;mso-hansi-theme-font:minor-latin;rnmso-bidi-font-family:&quot;Times New Roman&quot;;mso-bidi-theme-font:minor-bidi;rnmso-ansi-language:EN-ID;mso-fareast-language:EN-US;mso-bidi-language:AR-SA">Therernwas no evidence that the smoke detector alarm was tested.&nbsp;</span><br></p>', '<p>Please provide the smoke detector was tested&nbsp;</p>', 'Please refer to the attachment', 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (120, 84, '<p>The hose used during fire pump test was leaking&nbsp;</p>', '<p>Please repair the hoses&nbsp;</p>', 'Please refer to the attachment', 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (121, 84, '<p><span style="font-size:11.0pt;line-height:107%;rnfont-family:&quot;Calibri&quot;,sans-serif;mso-ascii-theme-font:minor-latin;mso-fareast-font-family:rnCalibri;mso-fareast-theme-font:minor-latin;mso-hansi-theme-font:minor-latin;rnmso-bidi-font-family:&quot;Times New Roman&quot;;mso-bidi-theme-font:minor-bidi;rnmso-ansi-language:EN-ID;mso-fareast-language:EN-US;mso-bidi-language:AR-SA">Thernstarboard cargo hold bilge filled with waters</span><br></p>', '<p>Please provide the cargo hold in a dry bilge&nbsp;</p>', 'Please refer to the attachment', 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
