INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (123, 84, '<p>The engine room floor plates and ladders were oily and slippery&nbsp;</p>', '<p>Please provide the engine room free from oily and sippery&nbsp;</p>', 'Please refer to the attachment', 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (124, 84, '<p>Class and statutory certificates were not available onboard for our perusal&nbsp;</p>', 'Please provide the class and staturtory certificates', 'Please refer to the attachment', 0, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (125, 84, '<p>Running hours of the&nbsp;<span style="font-size: 0.875rem;">AE were not recorded in the logbook. Nonetheless, the crew estimated the running hours of AE No. 1 was around 1,000 hours since the last&nbsp;</span><span style="font-size: 0.875rem;">overhaul.</span></p><p>Running hours of&nbsp;<span style="font-size: 0.875rem;">the AE were not recorded in the logbook. Nonetheless, the crew estimated the running hours of AE No. 2 was around&nbsp;</span><span style="font-size: 0.875rem;">900 hours since the last overhaul.</span></p><p>Running hours of AE&nbsp;<span style="font-size: 0.875rem;">No. 3 was not advised.</span></p>', '<p>Please provide the running hours of the AE were recorded in the logbook&nbsp;</p>', 'Please refer to the attachment', 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (126, 84, '<p>The record of lubricants oil analysis of the engines was not available onboard for our perusal&nbsp;</p>', '<p>Please provide the record of lubricants oil analysis&nbsp;</p>', 'Please refer to the attachment', 0, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
