INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (135, 61, '<p><span style="color: rgb(33, 37, 41);">The guardrails was found dented and rusted</span><br></p>', '<p>The guardrails should be renewed as original.</p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (136, 61, '<p><span style="color: rgb(33, 37, 41);">The ballast tank no. 2 (port and starboard) was found wastage and rusted.</span><br></p>', '<p>The internal ballast tank should be renewed as the original.</p>', 'Please refer to the attachment', 60, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (137, 61, '<p><span style="color: rgb(33, 37, 41);">The bollard and capstan was found rusted and not marked with SWL</span><br></p>', '<p>The Bollard and capstan should be marked with SWL and repainted</p>', 'Please refer to the attachment.', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
