INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (139, 61, '<p><span style="color: rgb(33, 37, 41);">The calibration of the lubricants oil pressure sensor was not recorded</span><br></p>', '<p><span style="color: rgb(33, 37, 41);">The calibration of the lubricants oil pressure sensor should be recorded</span><br></p>', 'Please refer to the attachment', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
