INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (141, 61, '<p><span style="color: rgb(33, 37, 41);">Lubricants oil analysis was not provided at the time of our survey.</span><br></p>', '<p><span style="color: rgb(33, 37, 41);">Lubricants oil analysis should be provided onboard.</span><br></p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (142, 61, '<p><span style="color: rgb(33, 37, 41);">the occasion can not ascertain due to the main engine was not running.</span><br></p>', '<p><span style="color: rgb(33, 37, 41);">The item can be ascertain during voyage.</span><br></p>', 'Please refer to the attachment', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (143, 61, '<p><span style="color: rgb(33, 37, 41);">The insulation mats was not available onboard</span><br></p>', '<p><span style="color: rgb(33, 37, 41);">The insulation mats should be fitted and provided onboard</span><br></p>', 'Please refer to the attachment', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (144, 61, '<p><span style="color: rgb(33, 37, 41);">The propeller condition was not ascertained yet because the survey was carried out while the vessel was lying afloat at Tanjung Perak anchorage and the photograph of the propeller in the latest drydocking report was not available.</span><br></p>', '<p><span style="color: rgb(33, 37, 41);">The photograph of the condition of propeller should be provided.</span><br></p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (145, 61, '<p><span style="color: rgb(33, 37, 41);">At the time of our survey, the record testing steering gear was not available onboard for our review.</span><br></p>', '<p><span style="color: rgb(33, 37, 41);">The record testing steering gear should be provided onboard.</span><br></p>', 'Please refer to the attachment', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (146, 61, '<p><span style="color: rgb(33, 37, 41);">At the time of our survey, the smoke alarm test record was not available onboard for our review.</span><br></p>', '<p><span style="color: rgb(33, 37, 41);">The smoke alarm test record should be provided onboard.</span><br></p>', 'Please refer to the attachment', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (147, 61, '<p><span style="color: rgb(33, 37, 41);">The charts was not correctly updated. Last updated was 2019.</span><br></p>', '<p><span style="color: rgb(33, 37, 41);">The charts should be provided onboard with the latest update.</span><br></p>', 'Please refer to the attachment.', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (148, 61, '<span style="color: rgb(33, 37, 41);">The bilge was found filled with water.</span>', '<span style="color: rgb(33, 37, 41);">The bilge should be cleaned.</span>', 'Please refer to the attachment. For your information the bilge was covered with  tarpaulin to prevent the cargo clogging the bilge of cargo hold', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (149, 61, '<span style="color: rgb(33, 37, 41);">The coaming steel structure were found in good integrity condition. However, The seal in the booby hatch in the way of cargo hold was missing.</span>', '<span style="color: rgb(33, 37, 41);">The seal in the booby hatch in the way of cargo hold should be fitted and provided onboard.</span>', 'Please refer to the attachment.', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (150, 61, '<span style="color: rgb(33, 37, 41);">As far as we could ascertain, the cargo hold was generally found in fair condition and well-coated. However, there''s dented structure at some places.&nbsp;</span>', 'The structure plate should be renewed as the original.', 'The dented to the plate is a result of the cargo. The steel was installed to prevent the cargo from coming into contact with the cargo hold wall (kind of protection to prevent the cargo directly contact with main structure of cargo hold) and also the dented plate is not main structure of the vessel. It should be noted that the steel is still of a considerable thickness, despite the shipowner renewing the plate. It is likely that the steel will become dented again due to the cargo.', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (151, 73, '<p><span style="color: rgb(33, 37, 41);">The seal in the watertight opening in the way of cargo hold was missing.</span><br></p>', '<p><span style="color: rgb(33, 37, 41);">The seal in the watertight opening in the way of cargo hold should be fitted and provided onboard.</span><br></p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (152, 73, '<p><span style="color: rgb(33, 37, 41);">The charts was not correctly updated. Last updated : 2017.</span><br></p>', '<p><span style="color: rgb(33, 37, 41);">The charts should be provided onboard with the latest update.</span><br></p>', 'Please refer to the attachment', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
