INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (202, 83, '<p>The escpae routes are not posted in the crew accomodation&nbsp;</p>', '<p>The escape routes should be posted in the crew accomodation&nbsp;</p>', 'Please refer to the attachment', 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (203, 83, '<p>The propeller condition was not ascertained yet</p><p>because the survey was carried out while the vessel was berthed at the wharf while carrying out cargo</p><p>loading.</p>', '<p>Please provided the condition of propeller&nbsp;</p>', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (204, 83, '<p>The charts are not recorded correctly&nbsp;</p>', '<p>The chart should be recorded with the latest updated</p>', 'Please refer to the attachment', 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (205, 83, '<p>The smoke detector alarm test is not regularly recorded</p>', '<p>The smoke detector alarm should be recorded&nbsp;</p>', 'Please refer to the attachment', 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (206, 81, '<p>The starboard railing was found slightly parted. However, the guardrails, walkaways, and ladders located in the main deck, poop deck, and accomodation deck were found&nbsp; in fair condition.&nbsp;</p>', '<p>The starboard railing should be repairing&nbsp;</p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (207, 81, '<p>The auxiliary engine No. 3 was under overhaul on the liner, crankpin, and piston ring. Meanwhile, the auxiliary engine No. 1 and 2 were found in fair and satisfactory condition while running</p>', '<p>Please provide the auxiliary engine No. 3&nbsp;</p>', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (208, 81, '<p>Generally, the windlass and winches were found in rusty. In addition, the port winch lock structure was found out of the track. The steel structure of the rubber pad seating was found corroded.&nbsp;</p>', '<p>The windlass and winches should be repaired&nbsp;</p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (209, 81, '<p>At the time of our survey, the hydraulic pump pipeline on the forecastle deck was discovered to have oil leakage</p>', '<p>The hydraulic pump pipeline should be repaired&nbsp;</p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (210, 81, '<p>The fairlead at aft found detached and missing. Meanwhile, the other steel structure of the deck equipment was found in fair condition, complete with the safe working load information&nbsp;</p>', '<p>The fairlead should be renewad as original&nbsp;</p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (211, 81, '<p>The running hours record of the main engine since the last overhaul has not been handed over from the prevoius owner. Hence, he has not recorded the present running hours yet. The chief engineer verbally advised that the machinery equipment would conduct a general overhaul on the next docking.&nbsp;</p>', 'The running hours record should be provided with the latest update&nbsp;', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (212, 81, '<p>The main engine was replaced the crankpin and piston ring in August - September 2023. The maintenance record followed the engine maker manual.</p>', '<p>The maintenance record should be provided onboard with the latest update&nbsp;</p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (213, 81, '<p>The steering gear test record was not available onboard for our inspection&nbsp;</p>', '<p>The steering gear should be provided onboard</p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (214, 81, '<p>The blackout procedure was not available and posted onboard&nbsp;</p>', '<p>The blackout procedure should be provided onboard&nbsp;</p>', 'Please refer to the attachment', 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (215, 81, '<p>The updated NTM (BPI- Berita Pelaut Indonesia) is unavailable onboard. The latest available NTM was dated May 2023.</p>', '<p>NTM should be provided onboard with the latest update&nbsp;</p>', 'Please refer to the attachment', 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (216, 81, '<p>We could not inspect the full condition of the cargo hold due to still closed with the remaining cargo. As far as could be ascertained, the cargo hold plate was found doubling plate at several places, and cement and epoxy patching were sighted on the cargo hold plate.<br></p>', 'The cargo hold plate should be repaired&nbsp;', 'Please refer to the attachment', 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (217, 81, '<p>We could not inspect the full condition of the cargo hold due to still closed with remaining cargo. As far as could be ascertained, the cargo hold plate was found doubling plate at several places, and cement and epoxy patching were sighted on the cargo hold plate.</p><p>Meanwhile, the steel structure in good condition was also found well coated.</p>', '<p>The steel structure should be repaired</p>', 'Please refer to the attachment', 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (218, 83, '<p>The planned maintenance system did not include critical equipment&nbsp;</p>', '<p>The planned maintenace system should be provided onboard</p>', 'Please refer to the attachment', 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (219, 83, '<p>The planned maintenance system (PMS) was not available&nbsp;</p>', '<p>The planned maintenance system (PMS) should be provided onboard&nbsp;</p>', 'Please refer to the attachment', 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (220, 83, '<p>The planned maintenance system (PMS) was not available&nbsp;</p>', '<p>The planned maintenance system (PMS) should be provided onboard</p>', 'Please refer to the attachment', 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (221, 83, '<p>Not recorded in the logbook&nbsp;</p>', '<p>Total running hours of main engine (ME) should be provided&nbsp;</p>', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (222, 83, '<p>Not recorded in the logbook&nbsp;</p>', '<p>The running hours of auxiliary engine should be provided&nbsp;</p>', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (223, 88, '<p><span style="caret-color: rgb(33, 37, 41); color: rgb(33, 37, 41);">The side shell was found indented in several places.</span><br></p>', '<p>The undersigned recommends the indented side shell should be inspected by the class surveyor to ascertain whether the indented side shell exceeds the maximum allowable limit. If the indented side shell exceeds the maximum allowable limit by class standard, then the indented side shell has to be repaired and reinstated to the original condition.</p>', 'We have already invited class surveyor to check our vessel and do class endorsement on November 19, 2024 as attached. Based on class certificate attached, there is no visa for vessel KHATULISTIWA 8, therefore the class status is valid. Based on that, we can conclude the side shell still on allowable limit by class.', 60, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (224, 88, '<p><span style="caret-color: rgb(33, 37, 41); color: rgb(33, 37, 41);">Fuel air vents were not marked with the compartment they serve.</span><br></p>', '<p>Fuel air vents have to be marked with the compartment they serve.</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (225, 88, '<p><span style="caret-color: rgb(33, 37, 41); color: rgb(33, 37, 41);">There were no save-alls fitted surrounding the main deck.</span><br></p>', '<p>Save-alls have to be fitted around the main deck accordingly.</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (226, 88, '<p><span style="caret-color: rgb(33, 37, 41); color: rgb(33, 37, 41);">Scupper plugs were not available onboard.</span><br></p>', '<p>An adequate number of scupper plugs should be provided onboard.</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (227, 88, '<p><span style="caret-color: rgb(33, 37, 41); color: rgb(33, 37, 41);">All Decks/superstructures were found in good condition. Nevertheless, air vents and sounding pipes surrounding the main deck were not clearly marked with the compartment they serve.</span><br></p>', '<p>The air vents and sounding pipes surrounding the main deck should be marked with the compartment they serve.</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (228, 88, '<p><span style="caret-color: rgb(33, 37, 41); color: rgb(33, 37, 41);">Watertight doors were found corroded and wasted at several places.</span><br></p>', '<p>The corroded watertight doors are to be repaired and reinstated to their original condition. The booby hatch leading to the cargo hold No. 2 should be fitted with the rubber seal.</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (229, 88, '<p><span style="caret-color: rgb(33, 37, 41); color: rgb(33, 37, 41);">The bilge suction test could not be conducted at the time of the survey due to the manhole of the cargo holds bilge was still covered with residue of the remaining cargo.</span><br></p>', '<p>The cargo hold should be cleaned from the cargo residue, and later, the bilge suction should be tested accordingly. Please provide the videographs and photographs of the process of the bilge suction test.</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (230, 88, '<p><span style="caret-color: rgb(33, 37, 41); color: rgb(33, 37, 41);">The communication with the bridge using the telephone was not functioning at the time of the survey. The crew was using a handy talkie to communicate.</span><br></p>', '<p>The telephone system of the bridge and the engine room should be repaired, tested, and used as the main means of communication.</p>', 'noted that telephone was not functioning, however our crewmember still able to communicate from bridge to engine room using handy talkie as the surveyor already noted and stated on deficiency explanation. So, even though the telephone was not functioning our crewmember can still maintain the communication between bridge and engine room verry well.', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (231, 88, '<p><span style="caret-color: rgb(33, 37, 41); color: rgb(33, 37, 41);">The internal structure of ballast tank Nos. 1P and 1S were found generally corroded at places.&nbsp;</span><br></p>', '<p>The corroded internal structure of ballast tank Nos. 1P and 1S should be repaired and reinstated to their original condition.</p>', 'We noted that the ballast tank condition needs to be repaired, however ballast tank can only be repaired when the vessel undergo a dry docking. Further, please be advised that the last docking of KHATULISTIWA 8 was on September 20, 2023, we also carried out the UT test during last dry docking, therefore please find the UT test report on the attachment. Based on the latest UT test report reveal that the plate condition is still in fair condition. rnrnPlease be advised that the next dry docking of KHATULISTIWA 8 is estimated to be carry out on September 20, 2025. Based on the above explanation and considering the latest UT test, please advise whether the ballast tank could be repaired on the next dry dock? rn', 60, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (232, 128, '<p>Port side pilot combination ladder was found damage and out of order&nbsp;</p>', '<p>Please improve the pilot and stairs on the Port side<br></p>', 'Please refer to the attachment', 0, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (233, 128, '<p>Some access ladder (australian ladder) was found bent and damage&nbsp;</p>', '<p>Please provide protection for the pipes in the cargo hold.<br></p>', 'Please refer to the attachment', 0, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (234, 128, '<p>Hatch coaming and hatch cover (including landing pads and hatch cover clutch) was found corrosion and need to maintenance&nbsp;</p>', '<p>Please repair hatch coaming and hatch cover (including landing pads and hatch cover clutch).</p><div><br></div>', 'Please refer to the attachment', 0, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
