INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (253, 128, 'Only 2nd officer have spesific ECDIS certificate&nbsp;', '<p>All operating ECDIS should obtain an ECDIS certificate.<br></p>', 'Please refer to the attachment', 0, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (254, 72, '<p>NTM/BPI are not regularly updated, last updated on 10 May 2024</p>', '<p>The owner to provide and regularly update the NMT/BPI and send onboard weekly or monthly.</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
