INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (259, 121, '<p>The scupper plugs were not available onboard.</p>', '<p>The scupper plugs should be provided onboard.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (260, 72, '<p>The rubber seal of the fore bobby hatch was missing.</p>', 'The missing rubber seal of the booby hatch to be supplied and fitted as original.', 'Please refer to the attachment', 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (261, 121, '<p>The oil absorbent was not available onboard.</p>', '<p>The oil absorbent should be provided onboard.</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (262, 72, '<p>The interior of holds,&nbsp; ladder, side stringer, and web frames, were found deformed.</p>', '<p>The deformed ladder, side stringer, and web frames in way of cargo holds are to be repaired immediately.&nbsp;</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (263, 121, '<p>The plating in the cargo hold was found doublers in several places.</p>', 'The doublers should be cropped and renewed.', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (264, 121, '<p>The internal condition of ballast tank no. 1 was found wasted in several places.</p>', 'The internal structural of ballast tank no.1 should be renewed immediately.', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (265, 72, '<p>The cargo holds bilge suction No. 1 and 2 were out of order.&nbsp;&nbsp;&nbsp;&nbsp;</p>', '<p>The out of order bilge suction of the cargo hold No.1 and 2 are to be rectified immediately.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (266, 72, '<p>The hydraulic jack of the hatch covers No. 1 and 2 were found oil leaked.&nbsp;&nbsp;&nbsp;&nbsp;</p>', '<p>The leaked hydraulic jack of <span style="font-size: 0.875rem;">the hatch covers No. 1 and 2 are&nbsp;</span><span style="font-size: 0.875rem;">to be repaired as necessary.</span></p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (267, 72, '<p>The internal ballas tank No. 2 Portside is generally corroded and wasted.&nbsp;</p>', '<p>The corroded and wasted internals of ballast tank No. 2P are to be cropped and renewed immediately.</p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (268, 72, 'The ballast tanks pressure test was not carried out.', '<p>The ballast tank pressure test to be carried out as necessary.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (269, 72, '<p>The emergency generator in the steering gear room is under maintenance.</p>', '<p>The emergency generator to be tested satisfactorily after maintenance.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (270, 72, '<p>The crew was not familiar with the emergency steering test.</p>', '<p>The familiarization and sufficient training to be provided to the crew, especially for emergency steering test.&nbsp;</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (271, 74, '<p>The stability booklet was not availabe onboard</p>', '<p>The stability booklet should be available onboard&nbsp;</p>', 'Please refer to the attachment', 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (272, 74, '<p>The half part of the draft marks at fore, midship, and aft are not clearly marked. Meanwhile, the port and starboard load line marks are clear and visible.</p>', '<p>The draft marks&nbsp; at fore, midship, and aft should be clearly marked</p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (273, 74, '<p>The pilot ladder was found broken on the wooden foating. Meanwhile, the vessel uses the portable steel ladder for the temporal gangway.</p>', '<p>The pilot ladder should be repaired</p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (274, 74, '<p>Generally, most mooring equipment (bollard, fairlead, roller, capstan) is not clearly marked with safe working load (SWL) information.</p>', '<p>The mooring equipment should be marked with safe working load (SWL)</p>', 'Please refer to the attachment', 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (275, 74, '<p>Several air vents or sounding pipes were not clearly marked with the compartment they served. Meanwhile, the steel structure was in fair condition and well color-coded.</p><p>The air vents were not provided with floaters</p>', '<p>The air vents should be provided with floaters</p>', 'Please refer to the attachment', 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (276, 74, '<p>The insulation mats were absent on every engine switchboard panel, including the main switchboard panel and indicator</p>', '<p>The insulation mats should be provided on every switchboard panel and indicator</p>', 'Please refer to the attachment', 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (277, 74, '<p>The watertight door in way of forepeak store was found chipped on the lower end</p>', '<p>The watertight door should be repaired</p>', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (278, 74, '<p>The temperature measurement panel/indicator of auxiliary engine No.1 was broken. Hence, the crew could not carry out the temperature measurement.</p>', '<p>The temperature measurement panel/indicator should be repaired&nbsp;</p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (279, 74, '<p>Genset No. 2 was not ascertained yet due to the engine not running.&nbsp;</p><p>Meanwhile, Genset No. 3 was freed from significant oil or water leakages and/or temporary drains during the emergency generator test.</p><p>The auxiliary engine N0. 1 was found oil leakage on the engine valve pipe.</p>', 'Auxiliary engin No. 1 should be repaired from oil leakage on the engine valve pipe&nbsp;', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (280, 74, '<p>Emergency light in crew accomodation was installed onboard, but the system was out of order when tested.</p>', 'System emergency light in crew accomodation should be repaired', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (281, 74, '<p>The gyro compass system in way of the master compass was out of order. Meanwhile, the other navigation and communication equipment was found in order when the flame test was carried out.&nbsp;</p>', '<p>Gyro compass system should be repaired</p>', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (282, 74, 'The updated NTM ( BPI- Berita Pelaut Indonesia) was not available onboard', '<p>The NTM should be provided onboard with the latest update</p>', 'Please refer to the attachment', 17, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (283, 74, '<p>The crew expalained that the cargo hold bilge suction pipe was disconnected from the suction pump located in the engine room. Hence, the suction test was not carried out during our survey.</p>', 'The bilge suction pipe disconnected from the suction pump located in the engine room should be repaired', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
