INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (320, 130, '<p><span style="color: rgb(33, 37, 41);">The SOPEP locker complete with it''s contents wasn''t available on board.</span></p>', '<p><span style="color: rgb(33, 37, 41);">The SOPEP locker, complete with its contents (sawdust, oil dispersant, fabric) should be provided on board.</span></p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
