INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (325, 130, '<p><span style="color: rgb(33, 37, 41);">Most bollards were not marked with safe working load (SWL) information.</span></p><p><span style="color: rgb(33, 37, 41);"><br></span></p><p><br></p>', '<p><span style="color: rgb(33, 37, 41);">Bollards are to be marked with SWL information.</span></p><p><span style="background-color: rgb(255, 255, 255);"><br></span></p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (326, 130, '<p><span style="color: rgb(33, 37, 41);">The watertight door was found to be severely corroded, and the rubber seal was hardened.</span></p>', '<p>The watertight door should be cropped and renewed due to severe corrosion, and the rubber seal should be fitted and provided onboard.</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (327, 130, '<p><span style="color: rgb(33, 37, 41);">The hatch cover was found to be wasted in several spots. The rubber seal was found missing and hardened.</span></p>', '<p>The hatch cover should be cropped and renewed. The rubber seal is to be renewed.</p>', 'Please refer to the attachment', 90, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (328, 130, '<p><span style="color: rgb(33, 37, 41);">The associated zinc anode was found fully depleted in the internal of ballast tanks No. 2S and 2P.</span></p>', '<p><span style="color: rgb(33, 37, 41);">The associated zinc anode in the internal of ballast tanks No. 2S and 2P should be renewed.</span></p>', 'For zinc anode photographs, please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (329, 129, '<p><span style="color: rgb(33, 37, 41);">The gyro compass was found out of order.</span></p>', '<p><span style="color: rgb(33, 37, 41);">The gyro compass should be repaired.</span></p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
