INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (333, 129, '<p><span style="color: rgb(33, 37, 41);">The rubber seals on the hatch cover were found to be partially detached.</span></p>', '<p>The rubber seals&nbsp;<span style="font-size: 0.875rem; color: rgb(33, 37, 41);">on the hatch cover should be fitted.</span></p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (334, 129, '<p><span style="color: rgb(33, 37, 41);">The inspected internal condition of ballast tanks No. 3S and 3P are generally corroded, and the associated zinc anodes were found to be fully depleted.</span></p>', '<p><span style="color: rgb(33, 37, 41);">The internal of ballast tanks No 3S and 3P should be maintained properly.</span></p><p><span style="color: rgb(33, 37, 41);"><br>The associated zinc anode in the internal of ballast tanks No. 2S and 2P should be renewed.</span></p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (335, 76, '<p>The ballast tanks were not inspected at the time of our survey due to the bolt of nuts of manhole found out of order. Hence, the manhole of ballast tanks could not open prior our attendance.</p><p>We could not ascertain the wing tank of the vessel due to the tank being filled by water to maintain the stability.</p><p>At the time of our survey, we only inspected the forepeak. As far we ascertain, the condition of forepeak was found in good condition.</p>', 'The manhole cover and nuts should be repaired&nbsp;', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (336, 76, '<p>The vent and sounding pipes were not clearly marked with the compartment they serve.</p><p>The air vents was not provided with floaters.</p>', '<p>The vents and sounding pipe should be clearly marked with the compartement they serve</p>', 'Please refer to the attachment', 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (337, 76, '<p>The thermometer in the engine room was found unavailabe.</p><p>The thermometer in the engine room was found unavailable.</p>', '<p>The thermometer should be available in the engine room&nbsp;</p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (338, 76, '<p>Main engine and auxiliary engine manual book were not available onboard for our inspection.</p><p><br></p>', '<p>The main engine and auxiliary engine manual book should be provided onboard</p>', 'Please refer to the attachment', 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (339, 76, '<p>ECDIS, echosounder, single side band (SSB) and VHF DSC was found out of order</p>', '<p>ECDIS, echosounder, single side band (SSB) and VHF DSC should be maintained</p>', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (340, 76, '<p>Notice to mariner (NTM), Nautical almanac and tide table were found unavailable onboard</p>', '<p>NTM should be provided onboard</p>', 'Please refer to the attachment', 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (341, 76, '<p>The tween deck plate found wasted at several places and the vertical ladder in cargo hold found bent and corroded</p>', '<p>The tween deck plate wasted and the vertical ladder should be repaired</p>', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (342, 76, '<p>As far we could ascertain, the bulwark frames, and plate on forecastle deck were found wasted. The tween deck of cargo hold was found wasted at several places.&nbsp;</p>', '<p>The bulwark frames and plates on foracastle deck should be repaired</p>', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (343, 76, '<p>The draft marks not clearly marked at places. However, the draft mark and load line still slightly visible at the time of our survey</p>', '<p>The draft marks should be clearly marked&nbsp;</p>', 'Please refer to the attachment', 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (344, 76, '<p>The engine room ventilations were found inadequate</p>', '<p>The engine room ventilations should be repaired</p>', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (345, 76, 'Ship lifting appliance maintenance record was not available onboard', '<p>Ship lifting appliance maintenance record should be provided onboard</p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (346, 76, '<p>Bits and rollers were found wasted at several places.</p><p>All of deck equipment not marked with safe working loads (SWL)</p>', '<p>Bits and rollers should be repaired and all of deck equipment should be marked with safe working loads (SWL)</p>', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (347, 76, 'There is no record for steering gear test record for synchronization between the steering and navigation room is unavailable for our inspection&nbsp;', 'Steering gear test record for synchronization between the steering and navigation room should be provided onboard', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (348, 76, '<p>Nautical chart were not update. (last 2005)</p>', '<p>Nautical chart shoul be updated</p>', 'Please refer to the attachment', 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (349, 76, '<p>The suction test on the fore bilges wells was found out of order during test</p>', '<p>The suction test on the fore bilge wells should be maintained</p>', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (350, 76, '<p>Emergency steering procedure was not posted at the bridge deck</p>', '<p>The emergency steering procedure should be provided and posted at the bridge deck</p>', 'Please refer to the attachment', 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (351, 76, '<p>The main hydrant found water leakage during testing.</p><p>The main hydrant pipe on boar deck found wasted</p>', '<p>The main hydrant should be repaired and in good condition</p>', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (352, 65, '<p>Scupper plug was not available</p>', '<p>Scupper plug should be provided onboard</p>', 'Please refer to the attachment', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (353, 128, '<p>carried out ultraconic hatch cover test for hatch cover No. 1 to No. 7, was found DB reading over 10% and consider hatch was not weathertight</p>', '<p>ultrasonic hatch cover test for hatch covers No. 1 to No. 7 should have been carried out to test the watertightness of the hatches.</p>', 'Based on the results of the tightness test using the UT method by the surveyor, the results show that the UT reading is under 10 db, suggesting that the hatch is tight.', 0, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (354, 128, '<p><span style="color: rgb(33, 37, 41);">Near miss file was not sighted on board</span></p>', '<p>Please provide near miss documents</p>', 'Please refer to the attachment', 0, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (355, 375, '<p><font color="#212529">Not Inspected</font></p>', '<p><span style="color: rgb(33, 37, 41);">The propeller condition has not been ascertained yet because the survey was carried out while the vessel was anchored at the Biringkassi anchorage.</span><br style="color: rgb(33, 37, 41);"><br style="color: rgb(33, 37, 41);"><span style="color: rgb(33, 37, 41);">Based on the last docking report,&nbsp; the propeller blades were cleaned, polished, and press-tested during the previous docking in February 2024.</span></p>', 'For propeller condition please refer to the latest dry docking report (13 Februari 2024, Point IV). We refer to the last docking report due to there is a propeller repair details in that document, we believe that the propeller is currently still in proper condition', 90, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (356, 375, '<p>Not Inspected</p>', '<p><span style="color: rgb(33, 37, 41);">The occasion can not ascertain due to the main engine was not running.</span></p>', 'Please refer to the attachment for condition of the main engine', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (357, 375, '<p><font color="#212529">The Planned maintenance system, including critical equipment, was not available onboard.</font></p>', '<p>The planned maintenance system, including critical equipment, should be provided on board.</p>', 'Please refer to the attachment for Planned Maintenance System', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (358, 375, '<p><span style="color: rgb(33, 37, 41);">The insulation mats was not available onboard.</span></p>', '<p>The Insulation mats should be provided onboard and installed.</p>', 'Please refer to the attachment', 90, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
