INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (364, 375, '<p><span style="color: rgb(33, 37, 41);">The smoke detector was available on board but was found out of order.</span><br style="color: rgb(33, 37, 41);"><br style="color: rgb(33, 37, 41);"><span style="color: rgb(33, 37, 41);">The record of the smoke detector alarm test was not available on board.</span></p>', '<p>The smoke detector should be repaired and the record should be provided.</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (365, 375, '<p><span style="color: rgb(33, 37, 41);">At the time of our survey, the record-testing steering gear was not available onboard for our review.</span></p>', '<p><span style="color: rgb(33, 37, 41);">The record-testing steering gear should be provided onboard.</span></p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
