INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (367, 375, '<p><span style="color: rgb(33, 37, 41);">The watertight doors seal was generally found to be brittle.</span></p>', '<p>The water-tight door seal should be renewed.&nbsp;</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
