INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (369, 375, '<p><span style="color: rgb(33, 37, 41);">The company does not issue guidelines on the stowage plans and the cargo securing book approved by the class is not available.</span></p>', '<p>The guidelines on the storage plans and the cargo securing book approved by the class should be provided on board.&nbsp;</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (370, 375, '<p><span style="color: rgb(33, 37, 41);">The PMS list maintenance was not available onboard.</span></p>', '<p><span style="color: rgb(33, 37, 41);">The PMS list maintenance should be provided onboard.</span></p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (371, 375, '<p><span style="color: rgb(33, 37, 41);">The PMS list reminders for pending items were not available onboard.</span></p>', '<p><span style="color: rgb(33, 37, 41);">The PMS list reminders for pending items should be provided onboard.</span></p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (372, 375, '<p><span style="color: rgb(33, 37, 41);">The stability booklet was not available onboard.</span></p>', '<p>The stability booklet should be provided onboard.</p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (373, 375, '<p><span style="color: rgb(33, 37, 41);">The ballast tank No.3P and No.3S were found without any zinc anode installed.</span></p>', '<p><span style="font-size: 0.875rem;">The ballast tanks</span><span style="font-size: 0.875rem;">&nbsp;No.3 P and No. 3S were found without any zinc anodes and should be installed.</span></p>', 'Please refer to the attachment', 90, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (374, 375, '<p><span style="color: rgb(33, 37, 41);">The ship''s lifting appliance and loose gear maintenance records, complete with cargo gear certificate, were not available onboard.</span></p>', '<p>The ship''s lifting appliance and loose gear maintenance records, complete with a cargo certificate, should be provided on board.</p>', 'Please refer to the attachment', 60, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (375, 375, '<p><span style="color: rgb(33, 37, 41);">The guardrails on the port side of the vessel were removed due to modifications to the lifeboat pathway and have not been restored to the original conditions.</span></p>', '<p>The guard rails on the port side of the vessel were removed due to modifications to the lifeboat pathway and have not been restored to the original conditions.</p>', 'Please refer to the attachment', 60, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (376, 375, '<p><span style="color: rgb(33, 37, 41);">At the time of our survey, we could inspect 2 (two) ballast tanks, which consist of ballast tanks No. 3P and No. 3S.&nbsp;</span><br style="color: rgb(33, 37, 41);"><br style="color: rgb(33, 37, 41);"><span style="color: rgb(33, 37, 41);">The ballast tanks, complete with the internals structure, were corroded and pitting.</span></p>', '<p><span style="font-size: 0.875rem;">The ballast tanks</span><span style="font-size: 0.875rem;">&nbsp;No.3 P and No. 3S should be cropped and renewed.</span></p>', 'We refer to the latest UT report as attached, we are in the opinion that the plate thickness are still sufficient and within allowable limit. Also if we refer to the photographs uploaded by surveyor we think that the structure and thickness of the plate still in fair condition. A bit rusted is a normal condition on the plate of the vessel. Therefore, we are in the opinion that cropped and renew the plate is unnecessary for now. Just for your information ANUGERAH VIII was scheduled to be put on dry dock in 2026.', 90, NULL, 'Decline', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (377, 375, '<p><font color="#212529">The planned maintenance system includes spare parts inventory lists and overdue maintenance records.</font></p>', '<p><span style="color: rgb(33, 37, 41);">The planned maintenance system includes spare parts inventory lists and overdue maintenance records should be provided.</span></p>', 'Please refer to the attachment for ordering list', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (378, 375, '<p><span style="color: rgb(33, 37, 41);">The condition of deck equipment was not clearly marked with safe working load (SWL) information.&nbsp;</span><br></p>', '<p>The condition of the deck equipment should be clearly marked with the safe working load</p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (379, 375, '<p><span style="color: rgb(33, 37, 41);">The vents and air/sounding pipes on the deck were not clearly marked with the compartment they served.</span></p>', '<p>The vents and air/sounding pipes on the deck were not clearly marked with the compartment they served and should be marked.</p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (380, 375, '<p><span style="color: rgb(33, 37, 41);">Manufacturer''s manuals and service bulletins were not available onboard.</span></p>', '<p><span style="color: rgb(33, 37, 41);">Manufacturer''s manuals and service bulletins should be provided onboard.</span></p>', 'Please be advised that we bought this vessel as a secondhand vessel from previous owner. Therefore, we never receive any service bulletin from maker or anyone else, and we already seek the service bulletin from the maker website and also revealed that there is no service bulletin.rnrnTherefore, we use a manual book as a guidance to use and maintain the condition of the engine and the service bulletin would be considered as not applicable since there is no service bulletin from the maker.', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (381, 375, '<p><span style="color: rgb(33, 37, 41);">The calibration of the lubricants oil pressure sensor was not recorded.</span></p>', '<p><span style="color: rgb(33, 37, 41);">The calibration of the lubricant oil pressure sensor should be provided and record.</span></p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
