INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (420, 385, '<p><span style="color: rgb(33, 37, 41);">The echosounder was not available onboard.</span></p>', '<p>The echosounder should be provided onboard.</p>', 'As explained by the crew, they using a radar device that also can provide the information of the depth and object below the surface as video attached. The echo sounder was not available on the ship since the owner bought the ship and planned to install the echo sounder during the next dry docking. rnrnBased on above explanation we believe that the function of echo sounder has been fulfilled by the radar device. rn', 180, NULL, 'Decline', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
