INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (648, 542, '<p><span class="fontstyle0">Required on board for inspection by Flag and Class. It may affect the structural integrity and increases the risk of hull breach failure, affecting overall safety of crew and vessel.</span> rn<br style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: normal; text-align: -webkit-auto; text-size-adjust: auto;"></p>', 'Copy of UTM Report to be supplied onboard', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (649, 542, '<p><span class="fontstyle0">Outdated charts and/or lack of chart updates/corrections increases risk of navigational incidents and may indicate failing onboard management and/or poor shore side support. It puts the overall safety of crew, vessel and/or cargo at<br>stake</span> rn<br style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: normal; text-align: -webkit-auto; text-size-adjust: auto;"></p>', '<p>To be supplied onboard regularly</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (650, 542, '<p><span class="fontstyle0">Outdated charts and/or lack of chart updates/corrections increases risk of navigational incidents and may indicate failing onboard management and/or poor shore side support. It puts the overall safety of crew, vessel and/or cargo at<br>stake.</span><br style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: normal; text-align: -webkit-auto; text-size-adjust: auto;"></p>', '<p>Charts to be updated</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (651, 542, '<p>The vesselâs <span data-start="308" data-end="356">echo sounder is inoperative / malfunctioning</span> and unable to provide reliable under-keel depth readings.</p>', '<p>To be repair immediately</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (652, 542, '<p>Crew may not know correct sequence to transfer steering to emergency mode in an emergency.</p>', 'The instruction to be posted', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (653, 542, '<p>No containment for drips/leaks during bunkering.<br>Air vent overflow (fuel/ballast) has no tray to contain droplets.</p>', '<p>To be fitted</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (654, 542, '<p>Oil spill response failure due to crew cannot respond effectively to oil spills or leakages.</p>', '<p>SOPEP material and equipment to be supplied onboard</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (655, 542, 'Without proper absorbents and booms, spills can reach scuppers and the sea.', '<p>To be supplied onboard</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (656, 542, 'Without scupper plugs, oil drips or leaks during bunkering can flow directly to sea', '<p>To be supplied on board</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (657, 542, 'Ongoing corrosion may weaken deck plating, stiffeners, and welded fittings', '<p>To be maintained</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (658, 542, '<p>Hull was found slightly corroded, holed and wavy at some areas</p>', '<p>To be maintained</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (659, 542, '<p>Not clean and messy&nbsp;<span style="font-size: 0.875rem;">and not functional suction of&nbsp;</span><span style="font-size: 0.875rem;">Cargo hold bilge will increase risk damage of cargo on board&nbsp;</span></p>', '<p>To be cleaned up &amp; tidied&nbsp; immediately and suction test of bilge well to be carried out</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (660, 542, '<p>Not watertightness of watertight doors will incrase risk sea water seeped to the accommodation area and engine room. No open/ close marking will increase risk of safety during crew evacuation when fire/ emergency situation occured.</p>', '<p>Cooroded area of water watertight doors to be repaired immediately and Open/ close marking to be marked&nbsp;&nbsp;</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (661, 542, '<p>Non-watertightness of hatch cover will increase risk damage of cargo on board&nbsp;</p>', '<p>To be tested immediately</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (662, 542, '<p>Rusty on the hatch covers will increase risk to hatch cover''s structural strength&nbsp;&nbsp;</p>', '<p>To be chipped &amp; repainted immediately&nbsp;</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (663, 542, '<p>Rusty will increase risk of the internal structure and leaking of ballast tanks</p>', '<p>To be clean up, chipped and painted immediately</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (664, 585, '<p>Cargo tanks were not inspected due to in full condition during our attendance</p>', '<p>Cargo tanks should be available for the internal inspection or photos of cargo tanks to be forwarded</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (665, 546, '<p>Copy Certificate of Officers'' Competence is not available on board.</p>', '<p>Provide a copy of the crew certificate</p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (666, 546, 'not available onboard', '<p>It is mandatory to keep certified copies (or originals) of all important survey reports, including the hull ultrasonic tests, onboard the vessel in the certificate file (soft copy) provide a copy of certificate of ultrasonic thickness test&nbsp;</p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (667, 546, '<p>The gyro/magnetic compass is not operational</p>', '<p>Immediately carry out repair or replacement of the faulty compass by a certified technician. Conduct routine trials and calibration to ensure accuracy</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (668, 546, '<p>The Notice to Mariners (NTM) has not been received for six months</p>', '<p>Mandatory procedures must be enforced to ensure the Notice to Mariners (NTM) Bulletin is delivered to the vessel on a weekly/monthly basis, and all updates to charts and navigational publications are immediately recorded upon reception.</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (669, 546, '<p>echosounder not available onboard&nbsp;</p>', '<p>It is mandatory to install a fully functional echosounder, as it constitutes essential navigational equipment required by SOLAS</p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (670, 546, '<p>emergency generator not available onboard&nbsp;</p>', '<p>A functional emergency generator must be installed or provided immediately. Upon installation, mandatory load tests are required as per regulations to verify its readiness</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (671, 546, '<p>fuel air vents block by cargo&nbsp;</p>', '<p>Revise the vessel''s loading procedures. Ensure that areas around critical equipment (specifically fuel tank air vents) are maintained clear of cargo or other items according to the distance required by safety regulations. Once the cargo has been discharged, please send us photos or a video of the said item</p>', 'Please refer to the attachment', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (672, 546, '<p>bunkering connections block by cargo&nbsp;</p>', '<p>Revise the vessel''s loading procedures. Ensure that areas around critical equipment (specifically bunkering connections) are maintained clear of cargo or other items according to the distance required by safety regulations. Once the cargo has been discharged, please send us photos or a video of the said item</p>', 'Please refer to the attachment', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (673, 546, '<p>save alls block by cargo&nbsp;</p>', '<p>Revise the vessel''s loading procedures. Ensure that areas around critical equipment (specifically save alls) are maintained clear of cargo or other items according to the distance required by safety regulations. Once the cargo has been discharged, please send us photos or a video of the said item</p>', 'Please refer to the attachment', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (674, 546, '<p><span style="color: rgb(31, 31, 31); font-family: &quot;Google Sans Flex&quot;, &quot;Google Sans&quot;, &quot;Helvetica Neue&quot;, sans-serif; font-size: 14px; font-variant-ligatures: none; background-color: inherit;">In the absence of ultrasonic equipment, a Hose Test was conducted on hatch cover and&nbsp;</span><span style="font-size: 14px;">Water leakage, evidenced by visible droplets or streams entering the cargo hold, was noted during the spraying of the hatch cover''s exterior.</span></p>', '<p>1. Immediately carry out the total replacement of worn/hardened rubber seals on joints and panels with new and approved material</p><p>2.&nbsp;Perform adjustment on the cleating system (locking mechanism) and panel joints to achieve uniform compression pressure and close the gaps</p><p>Upon completion of seal replacement and mechanical adjustments, a mandatory ultrasonic test must be carried out along the entire length of the seals and panel connections to verify zero leakage</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (675, 546, '<p>test logbook maintained no available onboard&nbsp;</p>', '<p>It is mandatory to provide and regularly complete the trial logbook. Ensure this logbook is readily available on the bridge</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (676, 546, '<p>The emergency steering trial records are unavailable&nbsp;</p>', '<p>All emergency steering system trials must be documented in the ship''s logbook (or a separate record book) immediately upon their completion, as required by SOLAS</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (677, 546, '<p>The ship''s scupper plugs are constructed from wood</p>', '<p>Scupper plugs must be immediately provided and replaced with rubber types capable of ensuring a watertight seal to avoid inadvertent discharge overboard</p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (678, 546, '<p>Sawdust is used as the oil absorbent material; other types are recommended.</p>', '<p>An adequate supply of commercial oil absorbent materials (pads/granules) must be maintained onboard, strictly complying with the requirements of the SOPEP</p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (679, 546, '<p>anodes not inspected&nbsp;</p>', '<p>Schedule an underwater visual inspection or an inspection during the next docking to examine and replace consumed anodes to ensure cathodic protection</p>', 'Please refer to the attachment', 70, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (680, 546, '<p>Corrosion observed on the forecastle and main deck</p>', '<p>Carry out scaling (rust removal), followed by welding if the steel thickness is below the minimum renewal limit. Subsequently, apply an appropriate new coating (paint layer)</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (681, 546, '<p>The ballast tank pressure gauge/indicator is not functioning</p>', '<p>Immediately replace or repair the defective ballast tank pressure indicator to ensure proper operational and safety monitoring</p>', 'Please refer to the attachment', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (682, 546, '<p>The watertight door rubber seals are degraded</p>', '<p>All deteriorated or hardened watertight door gaskets must be immediately renewed. Regular leak testing must be carried out.</p>', 'Please refer to the attachment', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (683, 546, '<p>The hatch cover rubber seals are degraded, leakage is evident, and the cover is currently covered with a tarpaulin</p>', '<p>The damaged hatch cover seals must be replaced.&nbsp;Please repair the damage on hatch cover rubber seal&nbsp;</p><p>and ensure the hatch cover to watertight condition</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (684, 541, '<p><span style="color: rgb(33, 37, 41);">The Notice to Mariners (NTM) was not available on board</span></p>', '<p><span style="color: rgb(33, 37, 41);">Mandatory procedures must be enforced to ensure the Notice to Mariners (NTM) Bulletin is delivered to the vessel on a weekly/monthly basis, and all updates to charts and navigational publications are immediately recorded upon reception.</span></p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (685, 541, '<p>The ship''s scupper plugs are constructed from wood</p>', '<p>Scupper plugs must be immediately provided and replaced with rubber types capable of ensuring a watertight seal to avoid in advertent discharge overboard</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (686, 541, '<p>The Direct telephone from navigational bridge deck to engine room and steering gear room was not function</p>', '<p>It is recommend that immediate corrective action be taken to repair the non-functioning direct telephone communication system between the navigational bridge, engine room, and steering gear room. The system shall be restored to full operational condition without delay, as reliable communication is critical for safe navigation and emergency response. After completion of repairs, the communication system must be tested and confirmed operational, and the results should be properly recorded on board in accordance with applicable safety and regulatory requirements.</p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (687, 541, '<p><span style="color: rgb(33, 37, 41);">anodes not inspected.</span></p>', '<p><span style="color: rgb(33, 37, 41);">Schedule an underwater visual inspection or an inspection during the next docking to examine and replace consumed anodes to ensure cathodic protection.</span></p>', 'Please refer to the docking report page 81', 150, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (688, 541, '<p><span style="color: rgb(33, 37, 41);">The hatch cover rubber seals are degraded, and the cover is currently covered with a tarpaulin.</span></p>', '<p><span style="color: rgb(33, 37, 41);">The damaged hatch cover seals must be replaced.&nbsp;Please repair the damage on hatch cover rubber seal&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">and ensure the hatch cover to watertight condition.</span></p>', 'Please refer to the attachment', 45, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (689, 541, '<p>The ballast tank pressure gauge/indicator is not functioning&nbsp;</p>', '<p>Immediately replace or repair the defective ballast tank pressure indicator to ensure proper operational and safety monitoring.</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (690, 541, '<p><span style="color: rgb(33, 37, 41);">The emergency steering trial records are unavailable.</span></p>', '<p><span style="color: rgb(33, 37, 41);">All emergency steering system trials must be documented in the ship''s logbook (or a separate record book) immediately upon their completion, as required by SOLAS.</span></p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (691, 541, '<p>The Hose test conducted to hatch cover and found leakage</p>', '<p><span style="color: rgb(33, 37, 41);">It is recommend to the damaged hatch cover seals must be replaced.&nbsp;Please repair the damage on hatch cover rubber seal&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">and ensure the hatch cover to watertight condition.</span></p>', 'There is no sign of leakage during the hose test process', 45, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (692, 541, '<p>The charts no updated with the bulletin/Notice to Mariners due to the bulletin/Notice to Mariners was not available on board</p>', '<p>It is recommed to provide the updated bulletin/Notice to Mariners and immediately to update the charts based on information of bulletin/Notice to Mariners</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (693, 582, '<p>A non-functioning Gyro Compass is a critical deficiency that severely compromises the vessel''s ability to navigate safely and accurately, violating SOLAS Chapter V requirements.&nbsp;</p>', '<p>Repair or replace the Gyro Compass immediately and ensure it is properly calibrated. test functionality and record results in the log book.&nbsp;</p>', 'Please refer to the attachment', 37, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (694, 582, '<p>The lack of access&nbsp; to recent Notices to Mariners (NTM) Bulletins hinders the ability to update navigational charts and publications, increasing the risk of navigational hazards.&nbsp;</p>', '<p>Immediately obtain all relevant NTM Bulletins for the last 6 months and ensure all charts and navigational publications are corrected and updated prior to departure.&nbsp;</p>', 'Please refer to the attachment', 37, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (695, 582, '<p>The Echosounder is essential equipment for safe navigation in shallow waters. its absence constitutes a serious safety risk.&nbsp;</p>', '<p>Provide and Install a fully functional Echosunder, and ensure crew members are trained on its operation.&nbsp;</p>', 'As advised by the assured, they have concern that installing a new echo sounder may potentially affect the hull strength and plate tightness on the bottom of the vessel. It was also informed that the vessel has been operating without an echo sounder since they bought the vessel as a secondhand vessel. Therefore, the assured currently equips the vessel with updated depth charts and tide tables, which are regularly maintained. Please refer to the attachment.', 37, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (696, 582, '<p>The absence of Scupper Plugs violates pollution prevention regulations. in an emergency, this could lead to oil or other hazardous substances spilling overboard.&nbsp;</p>', '<p>Provide a complete set of appropriate scupper plugs for all scuppers on both sides of the vessel lad ensure they are readily accessible.&nbsp;</p>', 'Please refer to the attachment', 37, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (697, 582, '<p>The lack of oil absorbent materials is a MARPOL violation and indicates the vessel''s inability to handle minor oil spills, which is mandatory.&nbsp;</p>', '<p>Provide and position adequate quantities of oil absorbents in strategic locations (especially in the engine room)</p>', 'Please refer to the attachment', 37, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (698, 582, '<p>Anodes could not be inspected due to being submerged, leaving the current status of the vessel''s corrosion protection unverified.&nbsp;</p><p><span style="font-size: 14px;">Hull anodes are estimated to be effective, having been renewed on the last dry dock (October 26, 2024). Next inspection is scheduled for April 2027.</span></p>', '<span style="font-size: 14px;">Please kindly provide the latest zinc anode documentation</span>', 'Please refer to the blue-highlighted section in the attachment', 90, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (699, 582, '<p>Non-Watertight accommodation doors seriously compromise the vessel''s watertight integrity, potentially jeopardizing buoyancy in heavy weather or flooding scenarios.&nbsp;</p>', '<p>Immediately install proper rubber sealing for all accommodation watertight doors and test their watertight integrity.&nbsp;</p>', 'Please refer to the attachment', 37, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (700, 582, '<p>A damaged ballast tank pressure test indicator prevents verification of the tank''s structural integrity and operational efficiency, posing a hidden structural risk.&nbsp;</p>', '<p>repair or replace the ballast tank pressure test indicator and perform tank integrity verification.&nbsp;</p>', 'Please refer to the attachment', 37, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (701, 582, '<p>Damage to the backup auxiliary engine without spare parts is a high- category deficiency, eliminating critical power redundancy in emergency situations.&nbsp;</p>', '<p>carry out a complete repair of auxiliary engine number 3 and provide the necessary spare parts onboard before leaving the port.&nbsp;</p>', 'Please refer to the attachment', 37, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (702, 582, '<p>Broken communication between the engine room and the bridge hinders prompt decision-making and rapid response during critical maneuvers or emergencies.&nbsp;</p>', '<p>repair or replace the communication telephone and test its effectiveness to ensure the emergency communication link is always functional.&nbsp;</p>', 'Please refer to the attachment', 37, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (703, 582, '<p>the absence of an emergency steering test record indicates that essential testing procedures have not been carried out or properly documented&nbsp;</p>', '<p>Immediately conduct an emergency steering drill, record the results, and enter them into the new testing logbook&nbsp;</p>', 'Please refer to the attachment', 37, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (704, 582, '<p>The use of cut-up drums as improvised save-alls or drip trays is an unacceptable and temporary solution. this improper design carries a high risk of leakage, insufficient containment capacity, or insecure placement. this directly violates pollution prevention requirements (MARPOL) as it increases the likelihood of oil or fuel spilling into the bilge or, worst-case scenario, into the marine environment.&nbsp;</p>', '<p>Immediately replace all improvised save-alls (made from cut-up drums) with permanently designed and installed drip trays or save-alls made of suitable material and possessing sufficient containment capacity that meets machinery standards&nbsp;</p>', 'Please refer to the attachment', 37, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (705, 582, '<p>the failure to provide a recorded inspection and testing logbook indicates a lack of a proper safety management system and adequate verification procedures.&nbsp;</p>', '<p>Immediately establish an appropriate logbook and ensure all vital equipment is routinely tested, recorded, and verified&nbsp;</p>', 'Please refer to the attachment', 37, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (706, 582, '<p>Missing or damaged safety signage can impede crew emergency response, and corrosion indicates a structural maintenance failure</p>', '<p>replace and affix all missing or damaged safety signs/stickers. clean and repaint the corroded area found on&nbsp; the port side.&nbsp;</p>', 'Please refer to the attachment', 37, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (707, 514, '<p>Degraded rubber on watertight doors compromises the vessel''s rnwatertight integrity, potentially jeopardizing buoyancy in heavy weatherrn or flooding scenarios.&nbsp;</p>', '<p>Immediately install proper rubber sealing for all accommodation watertight doors and test their watertight integrity.&nbsp;</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (708, 514, 'A copy of the vessel classification certificate must be kept on board the vessel', '<p>Provide a copy of the classification certificate</p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (709, 514, '<br>', '<p>Provide a copy of all crew competencies certificate onboard the vessel</p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (710, 514, '<p>Corroded and porous areas on the deck parts indicate a structural maintenance failure</p>', '<p>Conduct repair, repaint, and clean&nbsp;the corroded and porous parts</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (711, 514, 'All of the hatch cover is corroded, and there is no rubber sealing in use', '<p>Conduct maintenance on the hatch cover to remove corrosion, prevent structural damage, and leakage</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (712, 514, '<p>The failure to provide a recorded inspection and testing logbook rnindicates a lack of a proper safety management system and adequate rnverification procedures</p>', '<p>Immediately establish an appropriate logbook and ensure all vital equipment is routinely tested, recorded, and verified&nbsp;</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (713, 514, 'Corrosion was found on all sides of the cargo holds', '<p>Conduct maintenance, cleaning, and repaint to cargo holds interior to prevent further damage</p>', 'Please refer to the attachment', 60, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (714, 514, 'The absence of an emergency steering test record indicates that rnessential testing procedures have not been carried out or properly rndocumented&nbsp;', '<p>Immediately conduct an emergency steering drill, record the results, and enter them into the new testing logbook&nbsp;</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (715, 514, '<p>The absence of Scupper Plugs violates pollution prevention regulations. In an emergency, this could lead to oil or other hazardous substances rnspilling overboard.&nbsp;</p>', '<p>Provide a complete set of appropriate scupper plugs for all scuppers on rnboth sides of the vessel lad ensure they are readily accessible.&nbsp;</p>', 'Based on the information from the assured, due to the existing design and condition of the scupper opening as shown in the attached photo, scupper plugs cannot be properly installed or applied. Despite of that, the scupper plug still provided on the vessel', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (716, 514, '<p>The lack of access to recent Notices to Mariners (NTM) Bulletins rnhinders the ability to update navigational charts and publications, rnincreasing the risk of navigational hazards.&nbsp;</p>', '<p>Immediately obtain all relevant NTM Bulletins for the last 3 months and rnensure all charts and navigational publications are corrected and rnupdated before departure</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (717, 514, '<p>Corrosion was found in some areas of the vessel''s hull. The anode was also not installed yet.</p>', '<p>Remove and repaint the corroded hull area, and install anodes at your convenience</p>', NULL, 50, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (718, 514, 'Bunkering Connection was found rusted and with incomplete bolts', '<p>Repaint and clean the bunkering connection, and complete the bolts used to maintain safety</p>', NULL, 40, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (719, 514, '<p>Cargo hold bilge was found corroded although the bilge pump was functioning</p>', '<p>Conduct cleaning and maintenance to the cargo holds bilge, and conduct suction test</p>', NULL, 35, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (720, 514, '<p>The hose test was not conducted due to repair works inside the cargo holds</p>', '<p>Conduct a hose test on the hatch cover of cargo holds no. 1 and 2 to check the possibility of leakage</p>', NULL, 50, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (721, 514, '<p>The internal structure of the ballast tank was found to be corroded, although no cracks were found</p>', '<p>Conduct maintenance and remove corrosion parts in the internal structure of the ballast tank</p>', 'Please refer to the attachment', 55, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (722, 514, '<p>The ultrasonic thickness test record was not available on board</p>', '<p>Provide a copy of the ultrasonic thickness test record</p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (723, 514, '<p>The ballast tank pressure test was not conducted due to the ship''s docking</p>', '<p>Conduct a ballast tank pressure test and provide a photo of the manometer/indicator of the pump</p>', 'PLEASE REFER TO THE ATTACHMENT', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (724, 473, '<p>The Safe Manning Certificate was not available onboard at the time of inspection, as it was held by the shipâs agent. Therefore, compliance with the vesselâs required manning levels could not be verified<br></p>', '<p>Ensure that a valid copy of the Safe Manning Certificate is kept onboard at all times. Provide a copy of the certificate or confirmation from the shipâs agent to verify compliance with manning requirements<br></p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (725, 473, '<p>The inspection and functional verification of the bilge wells and suction system could not be carried out as the vessel was undergoing docking at the time of the survey. Consequently, the operational condition and effectiveness of the bilge wells and suction system could not be confirmed<br></p>', '<p>Conduct a full inspection and functional test of the bilge wells and suction system after the vessel has completed docking to verify operational condition and compliance with safety requirements. Provide photographic evidence or signed test records to confirm the system is fully operational<br></p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (726, 473, '<p>The exhaust temperatures of the main engine could not be measured or verified as the vessel was undergoing docking at the time of the survey. Therefore, the operational condition of the exhaust system could not be confirmed<br></p>', '<p>Verify and record the exhaust temperatures of the main engine after completion of docking to ensure proper engine performance. Provide photographic evidence or signed test records to confirm measurements<br></p>', 'Please refer to the attachment', 90, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (727, 473, '<p>The smoke detector alarm test records were not available onboard at the time of inspection, and therefore the functionality and reliability of the smoke detection system could not be verified<br></p>', '<p>Conduct a full test of the smoke detector alarms onboard and maintain proper records of the test results. Provide signed test reports or photographic evidence to confirm that the smoke detection system is fully operational<br></p>', 'PLEASE REFER TO THE ATTACHMENT', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (728, 473, '<p>The engine room bilge water level alarms and sensors were not installed or available onboard at the time of inspection. As a result, the ability to detect high bilge water levels automatically could not be verified, which may affect early warning of potential flooding in the machinery space<br></p>', '<p>Install and commission bilge water level alarms and sensors in the engine room to ensure early detection of high bilge water levels. Provide commissioning records or photographic evidence to confirm proper installation and functionality<br></p>', 'PLEASE REFER TO THE ATTACHMENT', 90, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (729, 473, '<p>The officer certificates and endorsements were not available onboard during the inspection, as they were held by the shipâs agent. Consequently, the validity and compliance of the officersâ qualifications could not be verified at the time of the survey<br></p>', '<p>Ensure that all officer certificates and endorsements are kept onboard and readily accessible for verification. Provide copies of the certificates or a confirmation from the shipâs agent to demonstrate validity and compliance<br></p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (730, 473, '<p>The statutory certificates required for the vessel were not available onboard at the time of inspection, as they were held by the shipâs agent. Consequently, verification of compliance with statutory requirements could not be conducted during the survey<br></p>', '<p>Ensure that all statutory certificates are available and maintained onboard at all times. Provide copies of the certificates or confirmation from the shipâs agent to demonstrate compliance with statutory requirements<br></p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (731, 473, '<p>The zinc anodes in the ballast tanks were found damaged and corroded during inspection. This condition may reduce the effectiveness of corrosion protection for the ballast tank structure<br></p>', '<p>Replace or repair the damaged and corroded zinc anodes in the ballast tanks to restore effective corrosion protection. Provide photographic evidence or maintenance records to confirm replacement or rectification<br></p>', 'Please refer to the attachment', 90, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (732, 473, '<p>Records of testing for steering gear synchronization between the Steering Room and the Navigation Room were not available at the time of inspection. As a result, the proper functioning and coordination of the steering system could not be verified<br></p>', '<p>Conduct a full test of the steering gear synchronization between the Steering Room and the Navigation Room, and maintain proper records of the test results. Provide signed test reports or photographic evidence to confirm the system is fully operational<br></p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (733, 473, '<p>The test result of the emergency fire pump was not recorded at the time of inspection. Consequently, the operational readiness and performance of the emergency fire pump could not be verified<br></p>', '<p>Conduct a test of the emergency fire pump and maintain proper records of the test results. Provide signed test reports or photographic evidence to confirm that the emergency fire pump is fully operational<br></p>', 'Plase refer to the attachment', 30, NULL, 'Decline', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (734, 473, '<p>The calibration results of the lubricating oil pressure sensor were not recorded at the time of inspection. As a result, the accuracy and reliability of the sensor readings could not be verified<br></p>', '<p>Perform calibration of the lubricating oil pressure sensor and maintain proper records of the results. Provide signed calibration certificates or photographic evidence to confirm the sensor is accurately calibrated and operational<br></p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (735, 473, '<p>The maintenance records for the shipâs lifting appliances and gear were not properly maintained. As a result, the current condition, service history, and operational readiness of the lifting equipment could not be fully verified<br></p>', '<p>Ensure that maintenance records for all shipâs lifting appliances and gear are properly maintained and updated. Provide complete maintenance logs or photographic evidence to confirm that the lifting equipment is in safe and operational condition<br></p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (736, 473, '<p>The condition of the propeller could not be visually inspected or verified as the vessel was undergoing docking at the time of the survey. Therefore, the operational integrity and potential damages to the propeller could not be assessed<br></p>', '<p>Conduct a full inspection of the propeller to verify its condition and operational integrity. Provide photographic evidence or inspection reports to confirm that the propeller is free from damage and fully operational<br></p>', 'Please refer to the attachment', 90, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (737, 473, '<p>The stern tube sealages could not be inspected or verified as the vessel was undergoing docking at the time of the survey. Therefore, the presence of leaks and the operational integrity of the stern tube could not be confirmed<br></p>', '<p>Inspect the stern tube seals to verify the absence of leakages and ensure proper operational integrity. Provide photographic evidence or inspection reports to confirm the condition of the stern tube seals<br></p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (738, 473, '<p>Records of lubricating oil analysis were not available at the time of inspection. As a result, the condition and quality of the lubricating oil, as well as potential wear indicators for machinery, could not be verified<br></p>', '<p>Conduct regular lubricating oil analysis for all relevant machinery and maintain proper records of the results. Provide signed reports or photographic evidence to confirm that oil condition monitoring is being performed as required<br></p>', 'Please refer to the attachment', 90, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (739, 473, '<p>Leakages of the auxiliary engines could not be visually inspected or verified as the vessel was undergoing docking at the time of the survey. Therefore, the presence of any leaks of the auxiliary engines could not be confirmed<br></p>', '<p>Inspect the auxiliary engines to verify the absence of oil or water leakages and ensure proper operational condition. Provide photographic evidence or inspection reports to confirm the engines are free from leaks and fully operational<br></p>', 'PLEASE REFER TO THE ATTACHMENT', 90, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (740, 473, '<p>Leakages of the main engine could not be visually inspected or verified as the vessel was undergoing docking at the time of the survey. Therefore, the presence of any leaks of the main engine&nbsp;could not be confirmed<br></p>', '<p>Inspect the main engine to verify the absence of oil or water leakages and ensure proper operational condition. Provide photographic evidence or inspection reports to confirm the engines are free from leaks and fully operational<br></p>', 'PLEASE REFER TO THE ATTACHMENT', 90, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (741, 473, '<p>The exhaust temperatures of the auxiliary engines could not be measured or verified as the vessel was undergoing docking at the time of the survey. Therefore, the operational condition of the exhaust system could not be confirmed<br></p>', '<p>Verify and record the exhaust temperatures of the auxiliary engines&nbsp;after completion of docking to ensure proper engine performance. Provide photographic evidence or signed test records to confirm measurements<br></p>', 'PLEASE REFER TO THE ATTACHMENT', 90, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (742, 473, '<p>The Crew List was not available onboard at the time of survey as it was being held by the shipâs agent. Consequently, the crew composition and compliance with manning requirements could not be verified during the inspection<br></p>', '<p>It is recommended that an update and valid Crew List be made available onboard at all times. The Master/Owner should ensure that a copy of the Crew List is retained on board prior to sailing and presented during inspections. Evidence of compliance should include a copy of the approved Crew List kept in the shipâs official records and available for verification by the surveyor or relevant authorities<br></p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (743, 607, '<p>The remaining defect list are as follows:</p><p>- Tween deck plate was found partly dent/ deformed</p><p>- Bilge wells cargo hold was found remaining water</p><p>- Internal structure of ballast tanks was found heavy corroded</p><p>- Oil absorbent was found not available</p>', '<p>- Tween deck plate to be repaired on the dent and deformed area</p><p>- Bilge well cargo hold to be clean up/ dried</p><p>- The heavy corroded of internal ballast tank to be repaired/ replated</p><p>- Oil absorbent to be provided on board</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (744, 607, '<p class="MsoNormal">Internal structure of ballast tanks was found heavy corroded<o:p></o:p></p>', '<p class="MsoNormal">The heavy corroded of internal ballast tank to be repaired/rnreplated<o:p></o:p></p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (745, 607, '<p class="MsoNormal">Tween deck plate was found partly dent/ deformed<o:p></o:p></p>', '<p class="MsoNormal">Tween deck plate to be repaired on the dent and deformedrnarea<o:p></o:p></p>', 'Please refer to the attachment', 30, NULL, 'Decline', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (746, 607, '<p class="MsoNormal">Bilge wells cargo hold was found remaining water<o:p></o:p></p>', '<span style="font-size:11.0pt;line-height:107%;rnfont-family:&quot;Calibri&quot;,sans-serif;mso-ascii-theme-font:minor-latin;mso-fareast-font-family:rnCalibri;mso-fareast-theme-font:minor-latin;mso-hansi-theme-font:minor-latin;rnmso-bidi-font-family:&quot;Times New Roman&quot;;mso-bidi-theme-font:minor-bidi;rnmso-ansi-language:EN-ID;mso-fareast-language:EN-US;mso-bidi-language:AR-SA">Bilgernwell cargo hold to be clean up/ dried</span>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
