INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (892, 617, '<p><span style="font-size: 0.875rem;">S</span><span style="font-size: 0.875rem;">ome of fairlead construction at stern area were found wastage condition&nbsp;</span></p>', '<p>To be repaired</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
