INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (914, 621, '<p style="color: rgb(33, 37, 41);">- Hydraulic operating handle of Anchor &amp; Mooring Windlass was found not fitted with save-alls</p><p style="color: rgb(33, 37, 41);">- Hydraulic operating handle of Aft Mooring Winches was found not fitted with save-alls</p><p style="color: rgb(33, 37, 41);">- Emergency Generators were found not fitted with save-alls</p>', '<p>To be fitted</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (915, 621, '<p>Oil absorbents were found not available</p>', '<p>To be provided</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (916, 621, '<p><span style="color: rgb(33, 37, 41);">Draft marks, Plimsoll/ Load line marks, and stern ship''s name were found faded</span></p>', '<p>To be marked/ painted</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (917, 621, '<p><span style="color: rgb(33, 37, 41);">NTM/ BPI was found not supplied on board</span></p>', '<p>To be supplied regularly</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (918, 621, '<p style="color: rgb(33, 37, 41);">- Main deck was found rusty</p><p style="color: rgb(33, 37, 41);">- Bulwark was found heavy corroded</p><p style="color: rgb(33, 37, 41);">- Railings were found partly missing and broken/ corroded</p><p style="color: rgb(33, 37, 41);">- Stanchion, Top plate and Longitudinal Stiffener of Hatch coamings were found heavy corroded</p><p style="color: rgb(33, 37, 41);">- Hydraulic operating handles of Hatch cover were found leakages</p><p style="color: rgb(33, 37, 41);">- Vertical ladders on external Hatch coaming were found heavy corroded</p><p style="color: rgb(33, 37, 41);">- Hydrant pipe on Main deck was found leakages</p><p style="color: rgb(33, 37, 41);">- All inclined ladders on outside accommodation were found corroded</p><p style="color: rgb(33, 37, 41);">- Many doublers were found at forward deck</p><p style="color: rgb(33, 37, 41);">- Chain stopper of Anchor and Mooring Windlass (S) was found missing</p><p style="color: rgb(33, 37, 41);">- Hydraulic pipe of Anchor and Mooring Windlass was found tightened with rubber ban</p><p style="color: rgb(33, 37, 41);">- Drums of Aft Mooring Winches were found partly corroded</p>', '<p>- Main deck to be chipped and repainted</p><p>- Bulwark to be repaired</p><p>- Railing to be repaired</p><p>-&nbsp;<span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Stanchion, Top plate and Longitudinal Stiffener of Hatch coamings</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">&nbsp;to be repaired</span></p><p><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Hydraulic operating handles of Hatch cover to be repaired</span></p><p><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Vertical ladders on external Hatch coaming to be repaired</span></p><p><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Hydrant pipe on Main deck to be repaired</span></p><p><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">All inclined ladders on outside accommodation to be repaired</span></p><p><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Many doublers at forward deck to be repaired</span></p><p><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">- C</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">hain stopper of Anchor and Mooring Windlass (S) to be provided</span></p><p><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Hydraulic pipe of Anchor and Mooring Windlass to be repaired</span></p><p><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">-&nbsp;</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Drums of Aft Mooring Winches to be repaired</span></p>', 'Please refer to the attachment', 30, NULL, 'Decline', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (919, 621, '<p><span style="color: rgb(33, 37, 41);">Rubber sealing was found hardened and partly broken</span></p>', '<p>To be repaired/ renewed</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
