INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (921, 621, '<p>W<span style="color: rgb(33, 37, 41); font-size: 0.875rem;">atertight doors access to accommodation and cargo hold were found corroded &amp; without Open/ Close marking</span></p>', '<p>To be repaired and marked</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
