INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (946, 602, '<ol><li>HULL WAS GENERALLY FOUND IN A RUSTY CONDITION</li><li>DRAUGHT AND LOADLINES WERE FOUND FADED</li></ol>', '<ol><li>RUST TO BE CLEANED AND PAINTED</li><li>DRAUGHT &amp; LOADLINE TO BE PAINTED</li></ol>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (947, 602, '<ol><li>THE INTERNAL STRUCTURE OF WBT WAS FOUND RUSTY AND POSSIBLY SERIOUS CORROSION TO WBT 3 &amp; 4 STARBOARD SIDE</li><li>WBT NO. 3 &amp; 4 ( STARBOARD SIDE) WERE FOUND CONTAMINATED WITH OIL</li></ol>', '<p class="MsoNormal"><b>IMMEDIATE / SHORT-TERM ACTIONS (BEFORE DRY DOCK):</b><o:p></o:p></p><ol style="margin-top:0cm" start="1" type="1">rn <li class="MsoNormal">CLEANrn     AND REMOVE OIL CONTAMINATION FROM WBT NO. 3 &amp; 4 (STARBOARD).<o:p></o:p></li>rn <li class="MsoNormal">GASrn     FREE AND VENTILATE TANKS PRIOR TO INSPECTION.<o:p></o:p></li>rn <li class="MsoNormal">CARRYrn     OUT CLOSE-UP INSPECTION OF AFFECTED STRUCTURES.<o:p></o:p></li>rn <li class="MsoNormal">PERFORMrn     <b>UTM (ULTRASONIC THICKNESS MEASUREMENT)</b> ON SUSPECT AREAS TO ASSESSrn     STEEL WASTAGE.<o:p></o:p></li>rn <li class="MsoNormal">APPLYrn     TEMPORARY PROTECTIVE COATING IF NECESSARY.<o:p></o:p></li>rn <li class="MsoNormal">MONITORrn     CONDITION AND REPORT FINDINGS TO BKI FOR GUIDANCE.<o:p></o:p></li>rn</ol><p class="MsoNormal"><b>PERMANENT RECTIFICATION (AT DRY DOCK â MARCH 2026):</b><o:p></o:p></p><p>rnrnrnrnrnrn</p><ol style="margin-top:0cm" start="1" type="1">rn <li class="MsoNormal">CONDUCTrn     FULL INTERNAL INSPECTION IN ATTENDANCE OF <b>BKI SURVEYOR</b>.<o:p></o:p></li>rn <li class="MsoNormal">CROPrn     AND RENEW WASTED STEEL WHERE THICKNESS IS BELOW CLASS ALLOWABLE LIMITS.<o:p></o:p></li>rn <li class="MsoNormal">REPAIRrn     CRACKS (IF ANY) WITH APPROVED WELDING PROCEDURES.<o:p></o:p></li>rn <li class="MsoNormal">HIGH-PRESSURErn     WASH, SURFACE PREPARATION (SA 2.5), AND APPLY APPROVED COATING SYSTEM.<o:p></o:p></li>rn <li class="MsoNormal">TESTrn     TANKS (HOSE TEST / HYDRO TEST) AFTER REPAIRS.<o:p></o:p></li>rn <li class="MsoNormal">OBTAINrn     BKI CLASS ENDORSEMENT AFTER SATISFACTORY COMPLETION.<o:p></o:p></li>rn</ol>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
