INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (998, 588, '-&nbsp;<span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Main deck was found rusty</span><p style="color: rgb(33, 37, 41);">- Doubler was found below watertight door access to accommodation (S)</p><p style="color: rgb(33, 37, 41);">- Railings on main deck (P &amp; S) were found partly rusty</p><p style="color: rgb(33, 37, 41);">- Forward store (Below forward deck) was found heavy rusty</p><p style="color: rgb(33, 37, 41);">- CO2 room was found messy/ obstructed with foreign materials</p><p style="color: rgb(33, 37, 41);">- Windlass were found rusty and gear of windlass corroded</p><p style="color: rgb(33, 37, 41);">- Anchor chains were found rusty</p><p style="color: rgb(33, 37, 41);">- Mooring line of Aft Winches were found abrasive</p><p style="color: rgb(33, 37, 41);">- Bollards, Rollers, and Fairleads were found without SWL marking</p><p style="color: rgb(33, 37, 41);">- Endcaps of rollers and fairleads were found partly missing</p>', '<p style="color: rgb(33, 37, 41);">- Main deck to be chipped and painted</p><p style="color: rgb(33, 37, 41);">- Doubler to be repaired</p><p style="color: rgb(33, 37, 41);">- Railings on main deck (P &amp; S) to be repaired</p><p style="color: rgb(33, 37, 41);">- Forward store (Below forward deck) to be chipped and painted</p><p style="color: rgb(33, 37, 41);">- CO2 room to be tidied and clean up</p><p style="color: rgb(33, 37, 41);">- Windlass to be repaired</p><p style="color: rgb(33, 37, 41);">- Anchor chains to be painted</p><p style="color: rgb(33, 37, 41);">- Mooring line of Aft Winches to be renewed</p><p style="color: rgb(33, 37, 41);">- Bollards, Rollers, and Fairleads to be marked</p><p style="color: rgb(33, 37, 41);">- Endcaps of rollers and fairleads to be repaired</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
