INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1061, 650, '<ol style="color: rgb(33, 37, 41);"><li>Main Deck was found Rusty</li><li>Doubler Plating was found at Several Forward and Boat Deck Area</li><li>Bulwarks was found Rusty and Partly Corroded</li><li>Bollards, Rollers, and Fairleads were found without SWL Marking</li></ol>', '<ol style="color: rgb(33, 37, 41);"><li>The main deck to be mechanically cleaned, treated, and recoated as necessary.</li><li>Doubler plating areas to be evaluated for structural integrity and renewed where required.</li><li>Corroded sections of bulwarks to be repaired or renewed and properly coated.</li><li>SWL markings to be clearly marked and permanently displayed on all bollards, rollers, and fairleads.</li></ol>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1062, 657, '<p>NTM/ BPI was found not regularly supplied on board</p>', '<p>To be supplied on board regularly</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
