INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1064, 657, '<p><span xss=removed>Deviation card was found latest adjusted on 4 August 2023 (more than 2 years)s</span></p>', 'To be re-adjusted and posted', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1065, 661, '<p>During the survey, the vessel''s Classification Certificate was not available onboard for verification&nbsp; (file soft copy also no have )&nbsp;</p>', '<p>the vessel owner or operator should ensure that a valid Classification Certificate is kept onboard and available for inspection at all times&nbsp;</p>', 'Please refer to the attachment', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1066, 661, '<p>Certificate of Competency (COC) of the ship officers were not available onboard at the time of the survey&nbsp;</p>', '<p>All officer''s valid Certificates of Competency should be kept onboard and made available for inspection when required</p>', 'Please refer to the attachment', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1067, 661, '<p>The Ultrasonic Thickness Measurement (UTM) report was not available onboard for review&nbsp;</p>', '<p>The latest UTM report should be provided and kept onboard as reference to monitor the structural condition of the vessel.&nbsp;</p>', 'Please refer to the attachment', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1068, 661, '<p>Radar Log book was not available onboard during the inspection&nbsp;</p>', '<p>A radar log book should be provided and properly maintained to record radar operation checks and maintenance&nbsp;</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1069, 661, '<p>Notice to Mariners (NTM) was not available or updated onboard. the vessel reportedly has not received any NTM bulletin for the past six months&nbsp;</p>', '<p>The vessel should regularly obtain and update the latest Notice to Mariners to ensure all nautical charts and publications are properly corrected&nbsp;</p>', NULL, 20, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1070, 661, '<p>The changeover instruction for emergency steering operation was not available or posted onboard&nbsp;</p>', '<p>Clear changeover instructions for emergency steering operation should be posted in the steering gear room in accordance with safety requirements&nbsp;</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1071, 661, '<p>scupper plugs were not available onboard during the inspection.&nbsp;</p>', '<p>Adequate scupper plugs should be provided and kept ready for use to prevent accidental discharge of pollutants overboard&nbsp;</p>', NULL, 20, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1072, 661, '<p>Hull anodes were not inspected because they were submerged underwater during the survey.&nbsp;</p>', '<p>Inspection of hull anodes should be carried out during dry docking or when the vessel is out of the water&nbsp;</p>', NULL, 120, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1073, 661, '<p>Minor corrosion was observed at the forecastle area during the inspection.&nbsp;</p>', '<p>The affected area should be cleaned, treated with anti-corrosion protection, and repainted to prevent further deterioration.&nbsp;</p>', NULL, 45, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1074, 661, '<p>Emergency steering test logbook was not available onboard for verification&nbsp;</p>', '<p>a dedicated logbook should be provided and records of emergency steering tests should be properly maintained.&nbsp;</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
