INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1116, 680, '<p><span style="color: rgb(33, 37, 41);">Charts were found not updated as per latest NTM/ BPI</span></p>', '<p>To be updated</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1117, 680, '<p><span style="color: rgb(33, 37, 41);">Oil absorbents were found not available</span></p>', '<p>To be provided</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1118, 680, '<p><span style="color: rgb(33, 37, 41);">Scupper plugs were found not available</span></p>', '<p>To be provided</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1119, 680, '<p><span style="color: rgb(33, 37, 41);">Save-alls were found not fitted on Bunker manifolds, Fuel air vents, Hatch covers hydraulic operating handle, and Anchor windlass &amp; aft mooring winches hydraulic operating handle</span></p>', '<p>To be fitted</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1120, 680, '<p><span style="color: rgb(33, 37, 41);">Port side FOT air vent was found corroded/ broken</span></p>', '<p>To be repaired</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1121, 680, '<p style="color: rgb(33, 37, 41);">- Hatch of emergency exit manhole, Hatch of manhole access to fore peak tank, and most of Watertight doors were found heavy corroded</p><p style="color: rgb(33, 37, 41);">- Ventilation cover of steering gear room was found missing</p>', '<p>To be repaired and replaced</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1122, 680, '<p style="color: rgb(33, 37, 41);">- Shell plating was found slight rusty and the coating faded</p><p style="color: rgb(33, 37, 41);">- Draft and plimsoll marks were found faded</p>', '<p>To be repainted</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1123, 680, '<p><span style="color: rgb(33, 37, 41);">Steering gear room was found flooded with oily water</span></p>', '<p>To be cleaned up</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1124, 680, '<p style="color: rgb(33, 37, 41);">- Cargo hold bilge wells were found heavy rusty and not clean with cargo residue</p><p style="color: rgb(33, 37, 41);">- Suction test has not been carried out due to malfunction of suction system</p>', '<p>To be repaired and cleaned up</p>', 'Please refer to the attachment', 30, NULL, 'Decline', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1125, 680, '<p style="color: rgb(33, 37, 41);">- Main deck was found rusty at port and starboard side of cargo hold</p><p style="color: rgb(33, 37, 41);">- Hatch coaming was found heavy corroded</p><p style="color: rgb(33, 37, 41);">- Derrick deck foundations were found heavy corroded</p><p style="color: rgb(33, 37, 41);">- Bulwark was found heavy corroded</p><p style="color: rgb(33, 37, 41);">- Most of the railing were found heavy corroded, dented, and partly missing</p><p style="color: rgb(33, 37, 41);">- Anchor windlass and Aft Mooring winch foundations were found corroded</p><p style="color: rgb(33, 37, 41);">- Mooring lines of port side Anchor &amp; mooring windlass, and Starboard side Aft mooring winches were found abrasive</p><p style="color: rgb(33, 37, 41);">- Hydrant pipe at starboard side main deck was found corroded and tightened with rubber ban</p><p style="color: rgb(33, 37, 41);">- Hydraulic systems (Pipelines and Hydraulic engine) of derricks (Aft and Fore) were found leakages</p>', '<p style="color: rgb(33, 37, 41);">- Main deck to be chipped and painted</p><p style="color: rgb(33, 37, 41);"><span style="font-size: 0.875rem;">- Hatch coaming to be repaired</span></p><p style="color: rgb(33, 37, 41);">- Derrick deck foundations to be repaired</p><p style="color: rgb(33, 37, 41);">- Bulwark to be repaired</p><p style="color: rgb(33, 37, 41);">- Railings to be repaired/ replaced</p><p style="color: rgb(33, 37, 41);">- Anchor windlass and Aft Mooring winch foundations to be repaired</p><p style="color: rgb(33, 37, 41);">- Mooring lines of port side Anchor &amp; mooring windlass, and Starboard side Aft mooring winches to be renewed</p><p style="color: rgb(33, 37, 41);">- Hydrant pipe at starboard side main deck to be repaired</p><p style="color: rgb(33, 37, 41);">- Hydraulic systems (Pipelines and Hydraulic engine) of derricks (Aft and Fore) to be repaired</p>', 'Please refer to the attachment', 30, NULL, 'Decline', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1126, 680, '<p style="color: rgb(33, 37, 41);">- Rubber sealing of Hatch covers were found hardened and not properly fitted</p><p style="color: rgb(33, 37, 41);">- Hydraulic pipe of Hatch covers were found leakages</p>', '<p>- Rubber sealing of Hatch covers to be repaired/ renewed and properly fitted</p><p>-&nbsp;<span style="color: rgb(33, 37, 41); font-size: 0.875rem;">Hydraulic pipe of Hatch covers to be repaired</span></p>', 'Using tarpaulin to protect the cargoes, and protect the hatch cover with 3 layers of tarpaulin before sealing.', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1127, 680, '<p>H<span style="color: rgb(33, 37, 41); font-size: 0.875rem;">ose test has not been carried out due to operational reasons</span></p>', '<p>To be tested</p>', 'Please refer to the attachment', 30, NULL, 'Decline', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1128, 680, '<p><span style="color: rgb(33, 37, 41);">Cargo holds tank top were found cargo residue of cement</span></p>', '<p>To be cleaned up</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1129, 680, '<p><span style="color: rgb(33, 37, 41);">The internal structure of WBT was found rusty</span></p>', '<p>To be chipped and painted</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1130, 680, '<p><span style="color: rgb(33, 37, 41);">WBT overflow/ pressure test has not been carried out due to operational reasons</span></p>', '<p>To be tested</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1132, 682, '<p>The save-all of mooring windlass at forecastle was found corrosion and wastage</p>', '<p>To be repaired</p>', 'Please refeer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1133, 682, '<p>Emergency generator not equipped on board</p>', '<p>To be provided onboard</p>', 'Please refeer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1134, 669, '<p style="color: rgb(33, 37, 41);"><span style="font-size: 0.875rem;">Locking mechanisms for starboard and port bridge watertight doors were not available.</span></p><p style="color: rgb(33, 37, 41);">Locking mechanisms for starboard and port accommodation watertight doors were not available.</p>', '<li data-section-id="17x9uzb" data-start="46" data-end="120"><span style="font-size: 0.875rem;">Provide and install proper locking mechanisms for port and starboard bridge watertight doors.</span></li><li data-section-id="mlal4" data-start="121" data-end="222"><span data-start="225" data-end="329">Provide and install proper locking mechanisms for port and starboard accommodation watertight doors.</span></li>', 'Please refer to the attachment', 20, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1135, 669, '<p><span style="color: rgb(33, 37, 41);">The rubber seals on two (2) out of a total of twelve (12) hatch cover panels were not available.</span></p>', '<p></p><div aria-hidden="true" data-edge="true" class="pointer-events-none h-px w-px absolute bottom-0"></div><p></p><div class="flex flex-col text-sm pb-25"><section class="text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]" dir="auto" data-turn-id="request-WEB:561d1542-1dc6-4028-bc91-e0b687d0a5d1-17" data-testid="conversation-turn-18" data-scroll-anchor="true" data-turn="assistant"><div class="text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)"><div class="[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn"><div class="flex max-w-full flex-col gap-4 grow"><div data-message-author-role="assistant" data-message-id="21d3826f-60b3-4ec0-a2e3-efd9bb57d478" dir="auto" data-message-model-slug="gpt-5-3" class="min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1" data-turn-start-message="true" tabindex="0"><div class="flex w-full flex-col gap-1 empty:hidden"><div class="markdown prose dark:prose-invert w-full wrap-break-word dark markdown-new-styling"><p><span data-start="23" data-end="120" data-is-last-node="">Install rubber seals on the two (2) hatch cover panels to ensure proper watertight integrity.</span></p></div></div></div></div><div class="z-0 flex min-h-[46px] justify-start"></div><div class="mt-3 w-full empty:hidden"><div class="text-center"></div></div></div></div></section></div>', NULL, 20, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1136, 669, '<p><span style="color: rgb(33, 37, 41);">The hose test on the hatch covers could not be carried out due to ongoing cargo loading and unloading operations, as it was not yet possible to conduct the test.</span></p>', '<p><div aria-hidden="true" data-edge="true" class="pointer-events-none h-px w-px absolute bottom-0"></div></p><div class="flex flex-col text-sm pb-25"><section class="text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]" dir="auto" data-turn-id="request-WEB:561d1542-1dc6-4028-bc91-e0b687d0a5d1-18" data-testid="conversation-turn-20" data-scroll-anchor="true" data-turn="assistant"><div class="text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)"><div class="[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn"><div class="flex max-w-full flex-col gap-4 grow"><div data-message-author-role="assistant" data-message-id="e6268311-c71d-4b71-9d58-df2a58dca117" dir="auto" data-message-model-slug="gpt-5-3" class="min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1" data-turn-start-message="true" tabindex="0"><div class="flex w-full flex-col gap-1 empty:hidden"><div class="markdown prose dark:prose-invert w-full wrap-break-word dark markdown-new-styling"><p><span data-start="23" data-end="137" data-is-last-node="">Carry out hose testing of the hatch covers upon completion of cargo operations to verify watertight integrity.</span>rn</p><ul data-start="21" data-end="137" data-is-last-node="" data-is-only-node="">rn</ul></div></div></div></div><div class="z-0 flex min-h-[46px] justify-start"></div><div class="mt-3 w-full empty:hidden"><div class="text-center"></div></div></div></div></section></div>', NULL, 18, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1137, 669, '<p><span style="color: rgb(33, 37, 41);">Internal tank inspection was carried out only for the forepeak tank, which was found to be in fair condition. Further inspection of other ballast tanks, including the double bottom tanks, is recommended to ascertain the overall internal condition.</span></p>', '<p>Carry out internal inspection of selected double bottom tanks to ascertain the condition of the internal structure.</p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1138, 649, '<p>The vesselâs Classification Certificate was not available onboard during the time of inspection and was reported to be held by the agent. This condition prevents verification of the vesselâs class status and compliance with classification society requirements.</p>', '<p>it is recommended to ensure that a valid copy of the Classification Certificate is placed onboard at all times for verification. The document shall be up to date and readily available for inspection by relevant authorities.</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1139, 649, '<p>Certificates of Competency for officers were not available onboard during inspection. This may indicate non-compliance with manning regulations and could affect safe vessel operation.</p>', '<p>All valid Certificates of Competency shall be maintained onboard and readily available for inspection. The vessel owner/operator should ensure compliance with applicable manning requirements</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1140, 649, '<p>Ultrasonic Thickness (UT) measurement records were not available onboard for verification, as they were kept by the office. This condition limits the ability to assess the structural integrity of the vessel.</p>', 'UT measurement reports shall be made available onboard for verification. If required, additional thickness measurements should be conducted to confirm the current condition of the structure', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1141, 649, '<p>The Notice to Mariners has not been updated for the last six months. This may result in outdated navigational information being used, posing a risk to safe navigation</p>', '<p>It is recommended to update the Notice to Mariners regularly in accordance with the latest publications to ensure safe navigation</p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1142, 649, '<p>No radar log book was found onboard during the inspection. This indicates a lack of proper documentation of radar operation and navigation activities</p>', '<p>A radar log book shall be provided and properly maintained onboard to record all relevant navigation activities</p>', NULL, 10, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1143, 649, '<p>Emergency steering instructions were not available onboard. In case of main steering failure, the crew may not be able to respond effectively.</p>', '<p>Clear and approved emergency steering procedures shall be prepared and posted in the steering gear room and bridge for crew reference</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1144, 649, '<p>Scupper plugs were not available on both port and starboard sides. This condition may lead to uncontrolled discharge of pollutants overboard.</p>', '<p>Scupper plugs shall be provided and properly installed to prevent accidental discharge and ensure compliance with pollution prevention regulations.&nbsp;</p>', NULL, 10, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1145, 649, '<p>No oil absorbent materials were found onboard. This indicates that the vessel is not adequately prepared to handle oil spill incidents</p>', '<p>Adequate oil absorbent materials shall be provided onboard as part of the vesselâs pollution prevention and emergency response equipment.</p>', NULL, 10, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1146, 649, '<p>The accommodation door was found not watertight due to missing or damaged rubber seals. This condition may allow water ingress into accommodation spaces</p>', '<p>The rubber seals shall be repaired or replaced to ensure the door is fully watertight and capable of preventing water ingress</p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1147, 649, '<p>hatch cover were not inspected due to ongoing dockyard works. Therefore, their actual condition could not be verified.</p>', '<p>A follow-up inspection shall be carried out upon completion of dockyard works to verify the condition of these areas.</p>', NULL, 35, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1159, 695, '<p><span style="font-size:11.0pt;line-height:115%;rnfont-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Aptos;mso-fareast-theme-font:rnminor-latin;mso-ansi-language:IN;mso-fareast-language:EN-US;mso-bidi-language:rnAR-SA">Sounding pipe and tank top plate of WBT No. 1 centre found leakage.</span></p>', '<p>The Ship''s Owner/Operator/Crew must repair the damage to the sounding pipe and tank top plate of WBT No. 1 centre.</p>', NULL, 60, NULL, 'Outstanding', 'manual', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1163, 695, '<p><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 14.6667px; text-align: justify;">Deviation of magnetic compass found expire with last adjusted on April 26, 2023.</span></p>', '<p>The owner must be renewal/update the Deviation of magnetic compass.</p>', 'Please refer in the link one drive attached', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1164, 695, '<p>-&nbsp;<span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt;">The hatch covers found torn at various spot.</span></p><p><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt;">-&nbsp;</span><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt;">The hatch cover could not be closed tightly and there was a gap about 14rncm between end of fore and aft of hatch cover.</span></p><p><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt;">-&nbsp;</span><span style="font-size:11.0pt;line-height:115%;rnfont-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Aptos;mso-fareast-theme-font:rnminor-latin;mso-ansi-language:IN;mso-fareast-language:EN-US;mso-bidi-language:rnAR-SA">The some of rubber sealing/gasket found in normal condition and some notrnavailable.</span><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt;"><br></span><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt;"><br></span></p>', '<p>The Ship''s Owner/Operator/crew must repair the damage of hatch cover and complete the hatch cover rubber sealing/gasket.</p>', 'The hatch cover is now can closed tightly and there is no more gap between end of fore and aft of hatch cover.', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1165, 695, '<p><span style="font-size:11.0pt;line-height:115%;rnfont-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Aptos;mso-fareast-theme-font:rnminor-latin;mso-ansi-language:IN;mso-fareast-language:EN-US;mso-bidi-language:rnAR-SA">- Holdâs bilge found remained of water and previously cargo.</span></p><p><span style="font-size:11.0pt;line-height:115%;rnfont-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Aptos;mso-fareast-theme-font:rnminor-latin;mso-ansi-language:IN;mso-fareast-language:EN-US;mso-bidi-language:rnAR-SA">-&nbsp;</span><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt;">We were not carried out the suction test due to both of the bilge valvernin Engine Room were jammed.</span></p>', '<p>The Ship''s Crew should repair the bilge valve and cleaning the bilge well in cargo hold.</p>', 'Please refer in the link one drive attached', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1166, 695, '<p><span style="font-size:11.0pt;line-height:115%;rnfont-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Aptos;mso-fareast-theme-font:rnminor-latin;mso-ansi-language:IN;mso-fareast-language:EN-US;mso-bidi-language:rnAR-SA">Shipâs chartâs were not update.</span></p>', '<p>The Chief/Second officer must update / make correction to the chart''s as per update from BPI/INM.</p>', 'BPI / NTM has updated', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
