INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1173, 695, '<p>-&nbsp;<span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt;">Only one (1) piece from six (6) pieces of Watertight doorâs clip at portrnand starboard side were function well, meanwhile for remained of five (5)rnpieces were not function or incomplete or missing.</span></p><p><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt;">-&nbsp;</span><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt;">Only one (1) piece from six (6) pieces of Engine Room Watertight doorâsrnclip at aft side were function well, meanwhile for remained of five (5) piecesrnwere not function due to jammed.</span></p><p><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt;">-&nbsp;</span><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt;">Engine Room Watertight doorâs not marked with open / close direction.</span></p>', '<p>- Ship''s/Operator/Crew must be repair and complete the watertight doors clips.</p><p>- The Ship''s crew must make marking with open/close direction.</p>', 'Please refer in the link one drive attached', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
