INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1192, 685, '<p>- F<span style="color: rgb(33, 37, 41); font-size: 0.875rem;">orward deck was found rusty</span></p><p style="color: rgb(33, 37, 41);">- Forward and Aft Bulwark was found corroded</p><p style="color: rgb(33, 37, 41);">- Hydraulic of Anchor &amp; Mooring Windlass were found leakages</p><p style="color: rgb(33, 37, 41);">- Port side Chain stopper was found heavy corroded and starboard side Chain stopper missing</p><p style="color: rgb(33, 37, 41);">- Hydraulic system of Derrick deck was found leakages</p><p style="color: rgb(33, 37, 41);">- Hatch coaming was found partly corroded</p><p style="color: rgb(33, 37, 41);">- Forward hydraulic operating handle pipe of Hatch covers was found leakages</p><p style="color: rgb(33, 37, 41);">- Mooring lines of Anchor &amp; Mooring Windlass and Aft Mooring Winches was found in poor condition</p>', '<p style="color: rgb(33, 37, 41);">- Forward deck to be chipped and painted</p><p style="color: rgb(33, 37, 41);">- Forward and Aft Bulwark to be repaired</p><p style="color: rgb(33, 37, 41);">- Hydraulic of Anchor &amp; Mooring Windlass to be repaired</p><p style="color: rgb(33, 37, 41);">- Port side Chain stopper to be repaired and starboard side Chain stopper to be provided</p><p style="color: rgb(33, 37, 41);">- Hydraulic system of Derrick deck to be repaired</p><p style="color: rgb(33, 37, 41);">- Hatch coaming to be repaired</p><p style="color: rgb(33, 37, 41);">- Forward hydraulic operating handle pipe of Hatch covers to be repaired</p><p style="color: rgb(33, 37, 41);">- Mooring lines of Anchor &amp; Mooring Windlass and Aft Mooring Winches to be renewed</p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
