INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1196, 685, '<p>AIS was found under repair during our attendance</p>', '<p>Repair to be completed</p>', 'The AIS has been repaired', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1197, 684, '<p>BUNKER STATION WAS FOUND OBSTRUCTED WITH FOREIGN MATERIAL<br></p>', '<p>To be cleaned</p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1198, 684, '<p>STEEL SAVE-ALLS NOT FITTED AT THE BUNKER STATION, FO &amp; LO VENT, HYDRAULIC SYSTEM OF FWD &amp; AFT WINCH, AND HYDRAULIC CONTROL OF HATCH COVERS<br></p>', '<p>To be fitted</p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1199, 684, '<p>SCUPPER PLUG WAS FOUND UNAVAILABLE ON BOARD<br></p>', '<p>To be provided</p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1200, 684, '<ol><li>MAIN DECK WAS FOUND RUSTY IN SEVERAL AREAS.</li><li>ANCHOR WINDLASS AND AFT WINCHES WERE FOUND RUSTY.</li><li>BOLLARDS, ROLLERS, AND FAIRLEADS AT THE FORWARD DECK WERE FOUND RUSTY AND WITHOUT SWL MARKING.</li><li>HYDRAULIC SYSTEM OF DERRICK WAS FOUND TO HAVE LEAKAGES.</li><li>FORWARD DERRICK WAS FOUND IN REPAIR CONDITION.</li><li>COAMING STAY OF HATCH COVER WAS FOUND RUSTY AND PARTLY CORRODED.</li><li>MOORING LINES AT AFT WERE FOUND IN POOR CONDITION</li><li>DERRICK STEEL FOUNDATION WAS FOUND PARTLY CORRODED.</li></ol>', '<ol><li>Rusty area to be mechanically cleaned, treated, and recoated as necessary.</li><li>SWL markings to be clearly marked and permanently displayed on all bollards, rollers, and fairleads.</li><li>The leakages in the hydraulic system need to be repaired.</li><li>Corroded sections to be repaired or renewed and properly coated.</li><li>Mooring lines were found to be abrasive to be renewed.</li></ol>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1201, 684, '<ol><li>WEATHERTIGHT DOORS WERE MOSTLY PARTIALLY CORRODED.</li><li>WEATHERTIGHT DOORS WERE FOUND WITHOUT KEPT CLOSED AT SEA MARKING.</li><li>THE STEERING GEAR ROOM VENT HATCH WAS FOUND MISSING.</li><li>MANHOLE ACCESS TO THE FORWARD STORE AND CHAIN LOCKER ROOM WAS FOUND PARTLY CORRODED.</li></ol>', '<ol><li>Corroded sections of weathertight doors to be repaired or renewed and properly coated.</li><li>Weathertight doors to be marked with "kept closed at sea."</li><li>The vent of the steering gear room needs to be repaired and installed.</li><li>Corroded sections of the manhole access to the forward store to be repaired or renewed and properly coated.<br></li></ol>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1202, 684, '<p>CARGO HOLDS BILGE WELL WERE FOUND RUSTY AND WITH CARGO RESIDUE.<br></p>', '<p>To be mechanically cleaned up</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1203, 684, '<ol><li>TANKTOP WAS FOUND COVERED WITH CARGO CEMENT RESIDUE.</li><li>SEVERAL AREAS WERE FOUND PARTLY CORRODED.</li></ol>', '<ol><li>To be cleaned up from cargo residue.</li><li>To be repaired or renewed and properly coated.</li></ol>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1204, 684, '<p>HOSE TEST HAS NOT BEEN CARRIED OUT DUE TO OPERATIONAL REASONS.<br></p>', '<p>To be tested</p>', 'Plese refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1205, 684, '<p>HATCH COVER WAS FOUND RUSTY AND PARTLY CORRODED.<br></p>', '<p>Corroded sections of Hatch Covers to be repaired or renewed and properly coated.<br></p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1206, 684, '<p>MAIN ENGINE WAS FOUND UNDER REPAIR<br></p>', '<p class="MsoNormal"><span lang="EN-US">Repair works to be completed and the mainrnengine to be tested for satisfactory operation prior to use.<o:p></o:p></span></p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1207, 684, '<p>BALLAST OVERFLOW TEST HAS NOT BEEN CARRIED OUT DUE TO OPERATIONAL REASONS.</p>', '<p>To be tested</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1208, 726, '<p>Last Ultrasonic thickness measurement report was noted dated 24 Nov 2023.</p>', '<p>To conduct the Ultrasonic thickness measurement on the next drydock</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1209, 726, '<p>Radar operational and test logbook was not sighted on board during inspection.&nbsp;</p>', '<p>&nbsp;To provide and maintain a dedicated radar operational and test logbook on board.&nbsp;</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1210, 726, '<p>Magnetic compass was found to have a water bubble inside the compass bowl during inspection.&nbsp;</p>', '<p>to repair the magnetic compass by fulfill the compass bowl liquid</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1211, 726, '<p>Echo sounder was found not working during inspection.</p>', '<p>Echosounder to be repair or replaced on board and make sure working normally</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1212, 684, '<p>OIL ABORBENT WAS FOUND UNAVAILABLE ONBOARD</p>', '<p>To be supplied</p>', 'Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1213, 727, '<p><span style="color: rgb(33, 37, 41);">operational and test logbook was not sighted on board</span></p>', '<p>to be provided on board</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1214, 727, '<p>&nbsp;The cargo hold bilge suction pipe was found in poor condition with heavy corrosion.&nbsp;</p>', '<p>To be repair, or renewal of the corroded bilge suction pipe and make sure the suction working normally.</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1215, 696, '<p>The second radar (3 Ghz/6Ghz) not function, and no record of logbook of twice radars</p>', '<p>The second radar need to repair and a radar logbook record must be provided</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1216, 696, 'Change over instructions for emergency steering not available on bridge deck', '<p>Change over instructions for emergency steering must be provided on bridge deck</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1217, 696, '<p>SOPEP locker with equipments in locker not available on board</p>', '<p>SOPEP locker with equipments such as absorbents (pads and rolls) , oil boom, saw dust,&nbsp; shovels, brooms, mops, bucket, oil spill dispersant, rubber boots and gloves, scupper plugs.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1218, 696, 'Scupper plugs with rubber not available on board', '<p>Scupper plugs with rubber must be provided on board</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1219, 696, '<p>Save alls found hole/leak on corner</p>', '<p>The hole/leak need to be repair/replate to ensure save alls working properly</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1220, 696, '<p>Oil absorbents not available on board</p>', '<p>Oil absorbents must be provided on board</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1221, 696, '<p>Watertight doors on starboard side to accomodation room, bow and stern doors to cargo hold not available rubber sealingon door.</p>', '<p>The rubber sealing must be installed properly to starboard side<span style="font-size: 0.875rem;">&nbsp;to accomodation room, bow and stern doors to cargo</span></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1222, 670, '<p><span style="color: rgb(33, 37, 41);">The emergency steering instruction was not available.</span></p>', '<p>It is recommended that emergency steering changeover instructions be provided and clearly posted near the steering gear location for crew reference during emergency situations.</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1223, 670, '<p><span style="color: rgb(33, 37, 41);">Scupper plug was not available.</span></p>', '<p>It is recommended that scupper plugs be provided and readily available on board to prevent overboard discharge during deck operations.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1224, 670, '<p><span style="color: rgb(33, 37, 41);">Ballast tank pressure test could not be carried out at the time of the survey due to shallow water conditions.</span></p>', '<p>It is recommended that ballast tank pressure testing be carried out at the next suitable opportunity to verify the integrity and tightness of the tanks.</p>', NULL, 28, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1225, 670, '<p><span style="color: rgb(33, 37, 41);">Cargo hold bilge suction was not available.</span></p>', '<p>It is recommended that a fixed cargo hold bilge suction system be installed to ensure effective dewatering capability during operations and emergency conditions.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1226, 670, '<p><span style="color: rgb(33, 37, 41);">The SOPEP Locker was not available.</span></p>', '<p>It is recommended that a SOPEP locker be provided on board in accordance with applicable pollution prevention requirements.</p>', NULL, 28, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1227, 670, '<p style="color: rgb(33, 37, 41);">Save-alls / drip tray of forward winch was not available.</p><p style="color: rgb(33, 37, 41);">Save-alls / drip tray of stern winch was not available.</p><p style="color: rgb(33, 37, 41);">Save-alls/ drip tray of bunkering connection was not available.</p>', '<p>It is recommended that save-alls/drip trays be provided at the forward winch, stern winch, and bunkering connection to prevent oil leakage and environmental contamination.</p>', NULL, 28, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1228, 670, '<p>Oil absorbent was not available on board.</p>', '<p><div aria-hidden="true" class="pointer-events-none -mt-px h-px translate-y-[calc(var(--scroll-root-safe-area-inset-bottom)-14*var(--spacing))]"></div></p><section class="text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto [content-visibility:auto] supports-[content-visibility:auto]:[contain-intrinsic-size:auto_100lvh] R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]" dir="auto" data-turn-id="request-69e87a52-14f8-8324-8298-0c0f9242500d-16" data-testid="conversation-turn-30" data-scroll-anchor="false" data-turn="assistant"><div class="text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)"><div class="[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn"><div class="flex max-w-full flex-col gap-4 grow"><div data-message-author-role="assistant" data-message-id="9223f84b-a59e-4afb-bb96-bf2414c6c427" dir="auto" data-message-model-slug="gpt-5-3" class="min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1" data-turn-start-message="true" tabindex="0"><div class="flex w-full flex-col gap-1 empty:hidden"><div class="markdown prose dark:prose-invert w-full wrap-break-word dark markdown-new-styling"><p data-start="0" data-end="139" data-is-last-node="" data-is-only-node="">It is recommended that adequate oil absorbent materials be provided and maintained on board to effectively respond to potential oil spills.</p></div></div></div></div><div class="z-0 flex min-h-[46px] justify-start"></div><div class="mt-3 w-full empty:hidden"><div class="text-center"></div></div></div></div></section>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1229, 728, '<p>The original Ultrasonic Test (UT) Certificate, which provides essential data on the vessel''s plate thickness and structural health, was not available on board. The absence of this document prevents the verification of structural integrity during a survey or inspection.</p>', '<p>The vessel''s management must send the original or a certified true copy of the <span data-path-to-node="4,0,0" data-index-in-node="95">UT (Ultrasonic Test) Certificate</span> to the vessel immediately. This document must be kept on board at all times to prove structural integrity during official inspections</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1230, 728, '<p>The vessel is not in possession of the latest Notices to Mariners (NTM), meaning the nautical charts and publications have not been updated with the most recent safety information, such as new hazards or changes in buoyage</p>', '<p>The vessel must be provided with the latest <span data-path-to-node="8,0,0" data-index-in-node="60">Notices to Mariners (NTM</span><b data-path-to-node="8,0,0" data-index-in-node="60">)</b> data. All nautical charts and publications must be updated and corrected by the navigation officer to reflect the most current maritime safety information</p>', NULL, 20, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1231, 728, '<p>Mandatory procedures for changing over from main to emergency steering are not displayed. In an emergency situation, the lack of clear, posted instructions could lead to confusion and a delayed response by the crew</p>', '<p>&nbsp;Permanent and clear <span data-path-to-node="10,0,0" data-index-in-node="36">Emergency Steering Changeover Instructions</span> (Posters/Placards) must be posted in the steering gear room and on the bridge to guide the crew during a steering failure</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1232, 728, '<p>There is no formal documentation to prove that the emergency steering system is tested at regular intervals. The lack of testing records indicates a failure to comply with safety management procedures regarding emergency preparedness</p>', '<p>A dedicated <span data-path-to-node="14,0,0" data-index-in-node="28">Logbook for Emergency Steering Tests</span> must be maintained on board. All periodic tests and emergency drills must be formally recorded to provide evidence of system readiness and regulatory compliance.</p>', NULL, 10, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1233, 728, '<p>There is no dedicated record-keeping system for the radarâs operational status. Without a radar logbook, it is impossible to track performance trends, maintenance history, or total running hours, which are necessary for identifying potential equipment failures.</p>', '<p>&nbsp;A dedicated <span data-path-to-node="6,0,0" data-index-in-node="28">Radar Logbook</span> must be established on board. The bridge officers must record daily performance checks, maintenance activities, and total running hours to ensure the reliability of the primary navigation system.</p>', NULL, 10, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1234, 728, '<p>Certain internal or external structural sections were underwater at the time of survey, making them inaccessible for visual examination. This constitutes a limitation in the survey scope, as the physical condition of these areas remains unverified.</p>', '<p>Since these areas could not be visually inspected, it is recommended to conduct a <span data-path-to-node="12,0,0" data-index-in-node="98">follow-up underwater survey (Diver Survey</span><b data-path-to-node="12,0,0" data-index-in-node="98">)</b> or a detailed inspection during the next dry-docking to verify the condition of the submerged structures.</p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1235, 730, '<p>UTM certificate were found on board but last date of inspection at 19-29 september 2023</p>', '<p>update with new UTM certificate after dry dock</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1236, 730, '<p>oil absorbent were not provided/available on board</p>', '<p>to be provided on board</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1237, 730, '<p>marine growth were sighted around the hull</p>', '<p>clean all marine growth&nbsp;</p>', 'Please refer to the attachment', 30, NULL, 'Decline', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1238, 730, '<p>internal inspetion of COT were not conducted due to all tanks were filled with cargo</p>', '<p>conducted internal inspection in the cargo oil tanks</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1239, 730, '<p>deep tanks as void space were found significant corrosion</p>', 'Maintenance is to be carried out to remove all rust and to apply new coating', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1240, 730, '<p>coupling at emergency generator were not covered with safety cover</p>', '<p>covering the coupling with safety cover</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1241, 694, '<p>Deviation of magnetic compass found expire, last adjusted on&nbsp;<span style="font-size: 0.875rem;">January 31, 2023.&nbsp;</span></p>', '<p>These items should be updated at the&nbsp;<span style="font-size: 0.875rem;">earliest opportunity, or at the latest within two (2) months.</span></p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1242, 694, '<div>- Manual emergency steering test was conducted and found not&nbsp;<span style="font-size: 0.875rem;">functioning.</span></div>', '<p>These items should be rectified at the earliest opportunity, or&nbsp;<span style="font-size: 0.875rem;">at the latest within three (3) months.</span></p><div><br></div>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1243, 694, '<p>- Oil Absorbents are not available on board.</p>', '<p>These items should be provided onboard at the&nbsp;<span style="font-size: 0.875rem;">earliest opportunity, or at the latest within two (2) months.</span></p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1244, 694, '<p>- Communication telephones in Engine Room and Steering Room&nbsp;<span style="font-size: 0.875rem;">were not functioning.</span></p>', '<p>These items should be rectified at the earliest opportunity, or&nbsp;<span style="font-size: 0.875rem;">at the latest within three (3) months.</span></p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1245, 694, '<p>- Pressure test on ballast tank was conducted and found leakage on&nbsp;<span style="font-size: 0.875rem;">the man hole of ballast tank no. 2 and no. 10, the rubber manhole&nbsp;</span><span style="font-size: 0.875rem;">must be changed and the cement must be renewed regularly.</span></p>', '<p>These items should be rectified at the&nbsp;<span style="font-size: 0.875rem;">earliest opportunity, or at the latest within two (2) months.</span></p><div><br></div>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1246, 694, '<p>- All ballast valves were reportedly blind-flanged during the&nbsp;<span style="font-size: 0.875rem;">vesselâs conversion from a tanker to a general cargo ship. As a&nbsp;</span><span style="font-size: 0.875rem;">result, their locations could not be identified by the Chief&nbsp;</span><span style="font-size: 0.875rem;">Engineer, and it is likely that the pipelines were blanked off at the&nbsp;</span><span style="font-size: 0.875rem;">bulkhead during the conversion.&nbsp;</span></p><p>- No marking on WBT vent and sounding pipe.</p>', '<p>- According to the Shipowner, the ballast pipelines were intended for tanker use and were blanked off during conversion from tanker to general cargo ship under Class BKI supervision and no relevant remarks were noted from the Classification Society.&nbsp;According to information provided by the Shipowner, the vesselâs trading area is generally within a radius of approximately 400 nautical miles, with average wave heights typically below 2.5 meters.</p><p>- to paint the marking on WBT vent and sounding pipes.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1247, 694, '<p>- lock diagram instruction for change procedures from auto to&nbsp;<span style="font-size: 0.875rem;">manual steering and change of steering gear power units not&nbsp;</span><span style="font-size: 0.875rem;">displayed on bridge.</span></p>', '<p>These items should be provided and sticked it at the&nbsp;<span style="font-size: 0.875rem;">earliest opportunity, or at the latest within two (2) months.</span></p><div><br></div>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1248, 694, '<p><span style="font-size: 0.875rem;">- The hatch covers found holes at various spot.</span></p>', '<p>to rectify or to replate the holes on the hatch cover&nbsp;at the earliest opportunity, or&nbsp;<span style="font-size: 0.875rem;">at the latest within three (3) months.</span></p><div><br></div>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1249, 694, '<p>- SOPEP Locker was marked with âSOPEPâ but without SOPEP&nbsp;<span style="font-size: 0.875rem;">Equipment like Oil absorbent pads/sorbent, Oil boom,&nbsp;</span><span style="font-size: 0.875rem;">Dispersant, Shovel, Bucket, Broom, PPE (Personal Protective&nbsp;</span><span style="font-size: 0.875rem;">Equipment).</span></p>', '<p>to provide the proper SOPEP Equipment and stuff on the SOPEP box&nbsp;at the&nbsp;<span style="font-size: 0.875rem;">earliest opportunity, or at the latest within two (2) months.</span></p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1250, 694, '<p>- The holdâs bilge was found to contain residual water and&nbsp;<span style="font-size: 0.875rem;">remained previous cargo.</span></p><p>- The bilge water suction operation was completed successfully;&nbsp;<span style="font-size: 0.875rem;">however, disposal was carried out directly to sea, which is not&nbsp;</span><span style="font-size: 0.875rem;">recommended. It is advised to provide a designated bilge tank or&nbsp;</span><span style="font-size: 0.875rem;">convert unused ballast tanks (No. 11 and/or No. 12) into bilge&nbsp;</span><span style="font-size: 0.875rem;">holding tanks. Drums may be used as a temporary arrangement.</span></p>', '<p>to clean up the bilges'' well and to provide drums for temporary disposal of the bilge water.&nbsp;</p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1251, 694, '<p>- Water tight doorâs rubber gasket on AC room and ACCU room&nbsp;<span style="font-size: 0.875rem;">were not available and must be installed.&nbsp;&nbsp;</span></p><p>- Water tight entrance hatchâs rubber gasket on cargo hold&nbsp;<span style="font-size: 0.875rem;">hatchway were not available and must be installed.&nbsp;</span></p>', '<p>to install the rubber gasket at the latest within two (2) months.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1252, 694, '<p><span style="font-size: 0.875rem;">- Gutter bar plates on weather deck in starboard and portside were&nbsp;</span><span style="font-size: 0.875rem;">damaged and must be replated.</span></p><div><br></div>', '<p>to replate the gutter bar plates on the weather deck&nbsp;at the latest within two (2) months.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1253, 694, '<p><span style="font-size: 0.875rem;">- The marking on bunkering connection must be painted.</span></p><div><br></div>', '<p>to paint the marking on bunkering connection&nbsp;at the latest within two (2) months.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1254, 694, '<p>- Shipâs charts were not update, last update in December 2015.</p><div><br></div>', '<p>to provide the updated charts&nbsp;at the latest within two (2) months.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1255, 694, '<p>- Save-alls bar plate on mooring winch and windlass on forward&nbsp;<span style="font-size: 0.875rem;">and aft found not available.</span></p><div><br></div>', '<p>to install the bar plate on the mooring winch and windlass for save-alls purpose from oil leakage spreading&nbsp;at the latest within three (3) months.</p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1256, 694, '<p>- Scupper plugs were not available onboard.&nbsp;</p>', '<p>to provide the scupper plugs and install them on the designated holes&nbsp;at the latest within three (3) months.</p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1257, 694, '<p>- No marking on the Fuel Air Vent&nbsp;</p>', '<p>to paint the marking on the Fuel Air Vent&nbsp;at the latest within two (2) months.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1258, 762, '<p>Ultrasonic thickness measurement not available on board.</p>', '<p>To provide UTM report to verify the actual steel thickness and structural condition. The results should be documented and maintained on board for reference and future inspections.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1259, 762, '<p><span style="color: rgb(33, 37, 41);">Notice to Mariners / Berita Pelaut Indonesia was not available on board.</span></p>', '<p>The vessel should ensure that the latest Notice to Mariners / Berita Pelaut Indonesia is obtained, updated regularly, and maintained on board to support safe navigation and voyage planning.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1260, 762, '<p><span style="color: rgb(33, 37, 41);">Changeover instructions for emergency steering were not available on board.</span></p>', '<p>Clear and concise emergency steering changeover instructions should be provided, posted on the bridge and in the steering gear compartment, and crew should be familiarized through regular drills.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1261, 762, '<p><span style="color: rgb(33, 37, 41);">The rubber sealing was noted not to be watertight. It was reported that, during cargo operations, the hatch covers are additionally protected with three layers of tarpaulin when sailing with cargo.</span></p>', '<p>A hose test should be carried out with the tarpaulin protection in place to verify the effectiveness of the current arrangement in ensuring hatch cover watertight integrity.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1262, 762, '<p><span style="color: rgb(33, 37, 41);">SOPEP locker was not available on board.</span></p>', '<p>A designated SOPEP locker should be provided on board, properly equipped in accordance with the SOPEP requirements, to ensure readiness for oil spill response.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1263, 762, '<p><span style="color: rgb(33, 37, 41);">Bunkering line was observed to be installed on concrete foundation.</span></p>', '<p>The bunkering line arrangement should be reviewed and modified to comply with good marine practice, ensuring proper support, flexibility, and spill containment to minimize the risk of leakage or damage.&nbsp;</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1264, 762, '<p><span style="color: rgb(33, 37, 41);">No save-alls or drip tray arrangement was provided beneath the bunkering connection.</span></p>', '<p>A suitable save-all or drip tray should be installed beneath the bunkering connection to contain any potential oil leakage during operations.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1265, 762, '<p><span style="color: rgb(33, 37, 41);">Scupper plugs were not available on board.</span></p>', '<p>Scupper plugs should be provided and readily available on board to prevent oil or contaminated water from discharging overboard during operations.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1266, 762, '<p><span style="color: rgb(33, 37, 41);">Oil absorbents were not available on board.</span></p>', '<p>Oil absorbent materials should be provided and maintained on board in sufficient quantities to enable effective response to potential oil spills.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1267, 762, '<p>Ballast pressure test was not inspected.</p>', '<p>A ballast tank pressure test should be carried out at the earliest opportunity to verify the integrity and watertightness of the hull.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1268, 653, '<p>Echosounder was found not working during inspection</p>', '<p>The echosounder need to be repaired and make sure to be working normally</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1269, 653, '<p>Bunker station / manifold and fuel vent on deck were not fitted with save alls</p>', '<p>The save alls need to be fitted with sufficient size surrounding the bunker station and fuel vent</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1270, 653, '<p>SOPEP Locker/Box and the equipments were not available on board</p>', '<p>SOPEP locker to be provided on deck and provided with sufficient SOPEP equipments</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1271, 653, '<p>Oil absorbent was not available on board</p>', '<p>Oil absorbent to be provided on board and placed securely</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1272, 653, '<p>Watertight door for cargo hold access at forward was found broken / bad condition</p>', '<p>The watertight door need to be repair or new replaced and be able to closed and opened properly</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1273, 692, '<p>Radar log book were not sighted on board as per serve</p>', '<p>to be porovided</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1274, 692, '<p>NTM/BPI were not provided on board</p>', '<p>to be provided on board</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1275, 692, '<p>Paper chart were not up to date&nbsp;</p>', '<p>to be update</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1276, 692, 'Changeover for emergency steering instruction were not posted on board', 'to be posted on board', NULL, 0, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1277, 692, 'Changeover for emergency steering instruction were not posted on board', 'to be posted on board', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
