INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1281, 692, '<p>ballast pressure test were not conducted due to cargo operation during survey</p>', '<p>to be conducted</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1282, 683, '<p><span lang="EN-GB" style="font-size: 10pt; font-family: Arial, sans-serif;">Fuel AirrnVents not fitted with drip tray and fuel air ventilation at portside not markedrnwith identification marks</span></p>', '<p>To be fitted</p>', 'Please reefer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1283, 683, '<ol><li><span lang="IN" style="font-size:10.0pt;mso-bidi-font-size:rn12.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;rnmso-bidi-font-family:&quot;Times New Roman&quot;;mso-ansi-language:IN;mso-fareast-language:rnEN-US;mso-bidi-language:AR-SA;mso-no-proof:yes">Bollards and rollers were not markedrnwith SWL</span></li><li><span lang="IN" style="font-size:10.0pt;mso-bidi-font-size:rn12.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;rnmso-bidi-font-family:&quot;Times New Roman&quot;;mso-ansi-language:IN;mso-fareast-language:rnEN-US;mso-bidi-language:AR-SA;mso-no-proof:yes"><span style="font-size: 10pt;">Air vents and manhole cover ofrnballast tank were found not marked with identification marks</span></span></li><li><span lang="IN" style="font-size:10.0pt;mso-bidi-font-size:rn12.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;rnmso-bidi-font-family:&quot;Times New Roman&quot;;mso-ansi-language:IN;mso-fareast-language:rnEN-US;mso-bidi-language:AR-SA;mso-no-proof:yes"><span lang="EN-GB" style="font-size: 10pt;">Sounding pipes were not marked withrnidentification marks</span><span style="font-size: 10pt;"><br></span>&nbsp;</span></li></ol>', '<p>To be marked properly</p>', 'Please refeer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1284, 683, '<p><span lang="EN-GB" style="font-size: 10pt; font-family: Arial, sans-serif;">Fore and aft windlass notrnfitted with save-all</span></p>', '<p>To be fitted</p>', 'Please reefer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1285, 683, '<ol><li><span lang="IN" style="font-size:10.0pt;mso-bidi-font-size:rn12.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;rnmso-bidi-font-family:&quot;Times New Roman&quot;;mso-ansi-language:IN;mso-fareast-language:rnEN-US;mso-bidi-language:AR-SA;mso-no-proof:yes">All weather tight doorrnthroughout vessel were not marked with open/close marks and keep close at the sea</span></li><li><span lang="IN" style="font-size:10.0pt;mso-bidi-font-size:rn12.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;rnmso-bidi-font-family:&quot;Times New Roman&quot;;mso-ansi-language:IN;mso-fareast-language:rnEN-US;mso-bidi-language:AR-SA;mso-no-proof:yes"><span lang="IN" style="font-size: 10pt;">Access gate to emergencyrnsteering was found obstructed</span></span></li></ol>', '<p>To be marked and unobstructed</p>', 'Please reefer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1286, 683, '<p><span lang="EN-GB" style="font-size:10.0pt;font-family:rn&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;mso-bidi-font-family:rn&quot;Times New Roman&quot;;mso-ansi-language:EN-GB;mso-fareast-language:EN-US;rnmso-bidi-language:AR-SA;mso-no-proof:yes">Emergency generator found was not working properly during our attendance&nbsp;</span></p>', '<p>To be maintenanced</p>', 'Please reefer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1287, 651, '<p>The stability booklet was not available onboard at the time of inspection. This document is essential for verifying vessel stability conditions under various loading and operational scenarios.<br></p>', '<p>The ship owner is advised to ensure that the approved stability booklet is made available onboard.<br></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1288, 651, '<p>No record of calibration results for the lubricating oil pressure sensor was available at the time of inspection. This indicates that calibration documentation is either not maintained or not properly filed onboard, which is essential for ensuring reliability of critical engine monitoring instruments.<br></p>', '<p>It is recommended that the vessel implement proper calibration records for lubricating oil pressure sensor. Calibration should be carried out by authorized personnel and records maintained onboard.<br></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1289, 651, '<p>The emergency lighting in the engine room is available, however it was found not to be in working condition at the time of inspection. This condition reduces safe access and emergency response capability in the engine room during blackout or emergency situations.<br></p>', '<p>It is recommended that the vessel rectify the emergency lighting system in the engine room by carrying out necessary repairs, replacement of defective units, and functional testing to ensure full operational readiness.<br></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1290, 651, '<p>No engine room bilge water level alarm/sensors were observed to be installed onboard at the time of inspection. This results in the absence of an early warning system for bilge water ingress in the engine room.<br></p>', '<p>It is recommended that the vessel be fitted with an appropriate engine room bilge water level alarm/sensor system.<br></p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1291, 651, '<p>No insulation mats were observed on board at the time of inspection. The absence of insulation mats may pose a safety risk to personnel when operating or working near electrical equipment.<br></p>', '<p>It is recommended that suitable insulation mats be provided in areas with electrical equipment, particularly in front of main switchboards, in accordance with safety standards and best marine practice.<br></p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1292, 651, '<p>No emergency steering procedures were observed to be available in the engine room at the time of inspection. This may affect the crewâs ability to respond effectively in the event of steering system failure.<br></p>', '<p>It is recommended that clear and appropriate emergency steering procedures be prepared, posted in the engine room, and communicated to the crew to ensure proper understanding and readiness in accordance with safety requirements.<br></p>', 'Emergency steering procedure has been posted in the engine room', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1293, 651, '<p>No records of lubricating oil analysis were available at the time of inspection. Regular oil analysis is essential to monitor engine condition and detect early signs of wear or contamination.<br></p>', '<p>It is recommended that periodic lubricating oil analysis be carried out, and that proper records be maintained onboard for monitoring and reference purposes.<br></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1294, 651, '<p>No records of smoke detector alarm testing were available at the time of inspection, therefore the effectiveness and condition of the system could not be verified.<br></p>', '<p>It is recommended that the smoke detector alarm system be tested periodically in accordance with safety requirements, and that proper test records be maintained onboard for verification and reference.<br></p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1295, 651, '<p>No records of testing the steering gear synchronization between the steering room and the navigation room were available at the time of inspection. This may affect verification of proper coordination between control positions.<br></p>', '<p>It is recommended that steering gear synchronization tests be carried out periodically, and that proper records be maintained onboard to confirm effective operation between the steering room and bridge control.<br></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1296, 651, '<p>The emergency generator is available on board, however it was found not to be in proper working condition at the time of inspection. This condition may compromise the vesselâs ability to supply emergency power during blackout or emergency situations.<br></p>', '<p>It is recommended that the emergency generator be repaired and restored to full operational condition. A functional test should be carried out after repair to verify proper performance in accordance with applicable safety requirements.<br></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1297, 651, '<p>No emergency power sources and emergency lighting were observed to be available on board at the time of inspection. This condition may significantly affect the vesselâs ability to maintain essential functions and safe evacuation during emergency or blackout situations.<br></p>', '<p>It is recommended that the vessel be provided with appropriate emergency power sources and emergency lighting systems in accordance with applicable safety regulations. The systems should be installed, tested, and maintained to ensure full operational readiness.<br></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1298, 651, '<p>No escape route plans were observed to be posted in the crew accommodation at the time of inspection. This may hinder crew awareness and response during emergency situations.<br></p>', '<p>It is recommended that clear and updated escape route plans be posted in all relevant areas of the crew accommodation and that crew members be familiarized with the escape arrangements.<br></p>', 'Please refer to the updated attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1299, 651, '<p>No blackout procedure was observed to be posted on board at the time of inspection, and the crewâs understanding of such procedure could not be verified. This may affect the crewâs ability to respond effectively in the event of a power failure.<br></p>', '<p>It is recommended that a clear blackout procedure be prepared, posted in relevant areas, and communicated to the crew through familiarization or drills to ensure proper understanding and readiness.<br></p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1300, 651, '<p>No stability calculations at the time of departure and arrival were carried out or recorded by the Master or Chief Officer. This indicates a lack of verification of the vesselâs stability condition prior to and after voyages.<br></p>', '<p>It is recommended that stability calculations be performed for each voyage at departure and arrival in accordance with the approved stability booklet, and that proper records be maintained onboard by the Master or Chief Officer.<br></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1301, 651, '<p>Emergency lighting in the crew accommodation was not observed to be properly installed and/or no satisfactory test results were available at the time of inspection. This condition may affect safe evacuation during emergency or blackout situations.<br></p>', '<p>It is recommended that emergency lighting be properly installed in the crew accommodation and subjected to functional testing. Test results should be recorded and maintained onboard to ensure compliance with safety requirements.<br></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1302, 651, '<p>No seals and compression bars were observed to be fitted on the hatch covers at the time of inspection. This condition may compromise the watertight integrity of the cargo hold and increase the risk of water ingress.<br></p>', '<p>It is recommended that appropriate seals and compression bars be fitted on the hatch covers to ensure proper sealing and maintain watertight integrity in accordance with good marine practice.<br></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1303, 652, '<p><span style="color: rgb(33, 37, 41);">SOPEP locker was not available on board.</span></p>', '<p>It is recommended to provide and install a SOPEP locker on board in accordance with applicable MARPOL requirements.</p>', 'Please refer to the attachment', 21, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1304, 652, '<p><span style="color: rgb(33, 37, 41);">Scupper plugs were not available on board.</span></p>', '<p><span style="color: rgb(33, 37, 41);">Scupper plugs were not available on board.</span></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1305, 652, '<p><span style="color: rgb(33, 37, 41);">Oil absorbent was not available on board.</span></p>', '<p>To provide adequate oil absorbent materials on board in accordance with pollution prevention requirements.</p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1306, 652, '<p><span style="color: rgb(33, 37, 41);">It was noted that the port side forward bulwark was torn/damaged.</span></p>', '<p>To repair the torn/damaged port side forward bulwark to restore its original structure.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1307, 652, '<p><span style="color: rgb(33, 37, 41);">The hatch cover was not close properly closed in fully shut position.&nbsp;</span></p>', '<p>It is recommended to repair and ensure the hatch cover can be properly and fully closed and secured to maintain watertight integrity.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1308, 652, '<p><span style="color: rgb(33, 37, 41);">Hose test was carried out and found to be not satisfactory, considering that the hatch cover was not close properly closed in the fully shut position.</span></p>', '<p>It is recommended to repair and properly align the hatch cover to ensure full closure and achieve satisfactory hose test results.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1309, 652, '<p><span style="color: rgb(33, 37, 41);">Ballast tank pressure test was carried out and found to be not satisfactory. During the test, damage was observed on the air pipe and sounding pipe.</span></p>', '<p>It is recommended to repair the damaged air pipe and sounding pipe and to rectify any leakage points, followed by re-conducting the ballast tank pressure test to confirm satisfactory tightness.</p>', 'Please refer to the attachment', 21, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1310, 652, '<p><span style="color: rgb(33, 37, 41);">Emergency generator was not available on board.</span></p>', '<p>It is recommended to provide and install an emergency generator on board in accordance with applicable safety regulations.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1311, 731, '<p>PMS was not sighted on board</p>', '<p>To be supplied</p>', 'Please refer to the attachment', 30, NULL, 'Decline', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1312, 766, '<p><span style="color: rgb(33, 37, 41);">Ultrasonic steel thickness measurement was not available on board.</span></p>', '<p>It is recommended to provide the latest UTM report to assess the condition of the hull plating.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1313, 766, '<p>Emergency steering was not available on board.</p>', '<p>It is recommended to provide an emergency steering system on board.</p>', 'Please reefer to the attachment', 21, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1314, 766, '<p><span style="color: rgb(33, 37, 41);">No rubber sealing is provided on hatch covers. When carrying cargo, the hatch covers are secured with two layers of tarpaulin during voyage.</span></p>', '<p>It is recommended to install proper rubber sealing and ensure the hatch covers are made fully weathertight.</p>', 'The hatch covers are not fitted with rubber seals, as they are manually operated. The hatch covers are secured with 3 layers of terpaulin. Please refer to the attachment.', 14, NULL, 'Decline', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1315, 766, '<p><span style="color: rgb(33, 37, 41);">Notice to Mariner/ BPI was not available on board.</span></p>', '<p>It is recommended to provide updated Notice to Mariners (NTM) on board.</p>', 'Please refeer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1316, 766, '<p><span style="color: rgb(33, 37, 41);">Changeover instructions was not available on board.</span></p>', '<p>It is recommended to provide changeover instructions on board, available at both the bridge and steering gear room.</p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1317, 766, '<p><span style="color: rgb(33, 37, 41);">SOPEP locker was not available on board.</span></p>', '<p>It is recommended to provide a SOPEP locker on board, complete with essential equipment such as oil absorbents, containment booms, protective gear, and clean-up tools.</p>', 'Please refeer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1318, 766, '<p><span style="color: rgb(33, 37, 41);">Save-alls were not available on board.</span></p>', '<p>It is recommended to install save-alls at bunkering stations to prevent oil spillage.</p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1319, 766, '<p><span style="color: rgb(33, 37, 41);">Oil absorbents were not available on board.</span></p>', '<p>It is recommended to provide sufficient oil absorbents on board for spill response.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1320, 766, '<p><span style="color: rgb(33, 37, 41);">Host test was carried out not satisfactory as hatch cover not watertight.</span></p>', '<p>It is recommended to repair and seal the hatch covers to ensure they are fully watertight and pass the hose test.</p>', 'The hatch covers are not fitted with rubber seals, as they are manually operated. The hatch covers are secured with 3 layers of terpaulin. Please refer to the attachment.', 14, NULL, 'Decline', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1321, 731, '<p>last UTM were found on board but survey conducted on 19-29 September 2023</p>', '<p>to be provided new UTM certificate after dry dock</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1322, 731, '<p>marine growth were observed bellow 2-3 meter of draft mark around the vessel</p>', '<p>to be cleaned and removed the marine growth</p>', 'Please refer to the attachment', 30, NULL, 'Decline', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1323, 731, '<p>Draft and Plimsol mark were found covered with marine growth</p>', '<p>to be cleaned and repaint of draft and plimsol mark</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1324, 731, '<p>deep tank were found corroded condition</p>', '<p>to be cleaning, removed rust and repaint of deep tank</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1325, 731, '<p>COT were not inspected due to COT on cargo condition.</p>', '<p>to be inspected</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1326, 731, '<p>record of lubricant oil analysis were not sighted on board</p>', '<p>to be provided on board</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1327, 731, '<p>COT were not inspected due to COT on cargo condition.</p>', '<p>to be inspected on board</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1328, 731, '<p>COT were not inspected due to COT on cargo condition.</p>', '<p>to be inspected on board</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1329, 765, '<p><span style="color: rgb(33, 37, 41);">Ballast tanks (forepeak and afterpeak) were not inspected as they were full and in use for operational purposes.</span></p>', '<p>It is recommended to inspect the ballast tanks when they are empty and safe for access.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1330, 765, '<p>Bunkering connection was not available on board.</p>', '<p>It is recommended to provide a proper bunkering connection arrangement to ensure safe and controlled fuel transfer operations.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1331, 765, '<p style="color: rgb(33, 37, 41);">Watertight doors to the bridge were found in corroded condition and not fitted with rubber seals on both port and starboard sides.</p><p style="color: rgb(33, 37, 41);">Watertight doors to the engine room were found in corroded condition and not fitted with rubber seal on both port and starboard sides.</p>', '<p>It is recommended to repair or renew the corroded watertight doors and install proper rubber seals to ensure watertight integrity.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1332, 765, '<p><span style="color: rgb(33, 37, 41);">Radar was not available on board.</span></p>', '<p>It is recommended to install a radar system to improve navigation safety, especially in restricted visibility conditions.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1333, 765, '<p><span style="color: rgb(33, 37, 41);">Ultrasonic thickness measurement was not available on board.</span></p>', '<p>It is recommended to carry out ultrasonic thickness measurements or provide the latest UTM report to verify the structural condition of the vessel.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1334, 765, '<p><span style="color: rgb(33, 37, 41);">Notice to Mariners / BPI was not available on board.</span></p>', '<p>It is recommended to maintain updated Notice to Mariners (NTM) / BPI publications on board to ensure accurate and up-to-date navigational information.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1335, 765, '<p>SOPEP locker was not available on board.</p>', '<p><div aria-hidden="true" class="pointer-events-none -mt-px h-px translate-y-[calc(var(--scroll-root-safe-area-inset-bottom)-14*var(--spacing))]"></div></p><section class="text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto [content-visibility:auto] supports-[content-visibility:auto]:[contain-intrinsic-size:auto_100lvh] R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]" dir="auto" data-turn-id="request-WEB:f4e9a5e1-ef81-47dd-ba0e-02c66c57d592-30" data-testid="conversation-turn-62" data-scroll-anchor="false" data-turn="assistant"><div class="text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)"><div class="[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn"><div class="flex max-w-full flex-col gap-4 grow"><div data-message-author-role="assistant" data-message-id="229af368-69ca-4c14-abdd-2cc791b4cb74" dir="auto" data-message-model-slug="gpt-5-3" class="min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1" data-turn-start-message="true" tabindex="0"><div class="flex w-full flex-col gap-1 empty:hidden"><div class="markdown prose dark:prose-invert w-full wrap-break-word dark markdown-new-styling"><blockquote data-start="0" data-end="136" data-is-last-node="" data-is-only-node=""><p data-start="2" data-end="136" data-is-last-node=""><span data-start="2" data-end="136" data-is-last-node="" data-is-only-node="">It is recommended to provide a SOPEP locker with the required equipment on board to ensure proper oil spill response preparedness.</span></p>rn</blockquote></div></div></div></div><div class="z-0 flex min-h-[46px] justify-start"></div><div class="mt-3 w-full empty:hidden"><div class="text-center"></div></div></div></div></section>', 'Please refer to the attachment', 21, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1336, 765, '<p><span style="color: rgb(33, 37, 41);">Save-alls were not available on board.</span></p>', '<p>It is recommended to install save-alls at appropriate locations to prevent oil spillage and ensure compliance with pollution prevention requirements.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1337, 765, '<p><span style="color: rgb(33, 37, 41);">Oil absorbents were not available on board.</span></p>', '<p>It is recommended to provide adequate oil absorbent materials on board to handle potential oil spills.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1338, 732, '<p>The protective hull anodes could not be verified by the surveyor because they are positioned below the waterline; this is noted as their current depletion rate remains unknown</p>', '<p>&nbsp;Schedule a diver inspection or an underwater survey (UWI) to verify the condition and depletion rate of the submerged sacrificial anodes or check for anodes can do when the tugboat on dry dock.&nbsp;</p>', NULL, 120, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1339, 732, '<p>The radar is a primary navigational tool for detecting objects and other vessels, especially during restricted visibility; its failure violates maritime safety standards. The absence of a radar logbook means there is no official documentation regarding the equipment''s maintenance or operational hours</p>', '<p>Perform immediate technical troubleshooting or repair to ensure the radar can be switched on and is fully operational. Provide a dedicated Radar Logbook onboard to record all maintenance and operational checks</p>', NULL, 45, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1340, 732, '<p>Notice to Mariners (NTM) are essential for updating nautical charts regarding new navigational hazards or changes in aids to navigation; without these, the vessel risks using outdated and dangerous navigational data.</p>', '<p>Request and download the latest Notice to Mariners (NTM) bulletins from the company or official maritime authorities to ensure navigational data is current.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1341, 732, '<p>The vessel is required to maintain a clear inventory list of all charts to ensure that every map necessary for the intended voyage is available and valid onboard.</p>', '<p>Procure and maintain an updated official "List of Charts" relevant to the vessel''s trading area to comply with carriage requirements.</p>', NULL, 20, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1342, 732, '<p>In an emergency steering failure, the crew must be able to switch to emergency manual control rapidly; the lack of written instructions can lead to confusion or procedural delays during a crisis</p>', '<p>Prepare and post clear, durable changeover instructions for emergency steering operations at the steering gear station and on the bridge.</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1343, 732, '<p>The vessel lacks a centralized storage location for Shipboard Oil Pollution Emergency Plan (SOPEP) equipment, which is a violation of international marine pollution prevention regulations</p>', '<p>Install a designated and properly labeled SOPEP locker in an accessible location on deck</p>', NULL, 20, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1344, 732, '<p>Save-alls or drip trays are required to prevent oil drips or spills at pipe connections during bunkering operations from falling into the sea.</p>', '<p>Supply and place save-alls or drip trays under all bunkering connections to contain potential oil leaks</p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1345, 732, '<p>The absence of oil absorbents means the vessel lacks the basic means to quickly clean up and contain minor oil spills on deck</p>', '<p>Replenish the vessel''s stock with a sufficient quantity of oil absorbents (pads, socks, or pillows) as per the SOPEP manual.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1346, 732, '<p>Corrosion on a watertight door can damage the rubber seals or weaken the door''s structure, potentially leading to a failure in maintaining the vessel''s integrity during flooding</p>', '<p>Clean the corrosion on the port side watertight door, apply a rust-inhibitor primer, and repaint to maintain watertight integrity.</p>', NULL, 20, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1347, 732, '<p>&nbsp;Testing the emergency steering is a mandatory regulatory requirement; without a dedicated logbook, there is no legal evidence that the system has been tested and is fully functional.</p>', '<p>&nbsp;Provide a dedicated logbook for emergency steering tests and ensure all mandatory drills are recorded consistently</p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1348, 721, '<p>The structural failure of the access ladder is likely due to advanced localized corrosion or mechanical stress</p>', '<p>Immediately remove the broken ladder from Manhole No. 6 (Port Side).</p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1349, 721, '<p>Due to the vessel''s draft and tidal conditions at the time of survey, the sacrificial anodes were positioned below the waterline</p>', '<p>Arrange for a follow-up inspection or when the barge on dry dock&nbsp;</p>', NULL, 120, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1350, 721, '<p>The protective coating system on the main deck has failed, leading to active oxidation and scaling of the steel plates</p>', '<p>Carry out mechanical descaling (chipping/grinding) on the affected areas of the Main Deck.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1351, 721, '<p>The absence of a gasket means there is no compression seal between the manhole cover and its seating bar</p>', '<p>Procure new marine-grade rubber gaskets/sealing.</p>', 'Rubber Seal', 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1352, 766, '<p>Ballast tanks located in the double bottom are no longer in use, as the double bottom manholes have also been blank off, making internal inspection inaccessible.</p>', '<p>To restore the ballast tanks to operational condition, it is recommended that access manholes be reinstated for each ballast tank to allow proper internal inspection. Thereafter, thorough inspection, maintenance, and any necessary repairs to the tank structures should be carried out prior to returning the tanks to service.</p>', 'Please refer to the attachment', 21, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1353, 766, '<p><span style="color: rgb(33, 37, 41);">The double bottom ballast tanks cannot be filled; therefore, pressure testing of these tanks is no longer possible.</span></p>', '<p><div aria-hidden="true" class="pointer-events-none -mt-px h-px translate-y-[calc(var(--scroll-root-safe-area-inset-bottom)-14*var(--spacing))]"></div></p><div class="" data-turn-id-container="request-WEB:f98db378-04d4-4b78-a756-c4eb47432fb0-5" data-is-intersecting="true"><section class="text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]" dir="auto" data-turn-id="request-WEB:f98db378-04d4-4b78-a756-c4eb47432fb0-5" data-testid="conversation-turn-12" data-scroll-anchor="false" data-turn="assistant"><div class="text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)"><div class="[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn"><div class="flex max-w-full flex-col gap-4 grow"><div data-message-author-role="assistant" data-message-id="e5209cfe-a0a8-4c45-b1fb-e369d38