INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1354, 766, '<p><span style="color: rgb(33, 37, 41);">The double bottom ballast tanks cannot be filled; therefore, pressure testing of these tanks is no longer possible.</span></p>', '<p></p><div aria-hidden="true" class="pointer-events-none -mt-px h-px translate-y-[calc(var(--scroll-root-safe-area-inset-bottom)-14*var(--spacing))]"></div><p></p><div class="" data-turn-id-container="request-WEB:f98db378-04d4-4b78-a756-c4eb47432fb0-5" data-is-intersecting="true"><section class="text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]" dir="auto" data-turn-id="request-WEB:f98db378-04d4-4b78-a756-c4eb47432fb0-5" data-testid="conversation-turn-12" data-scroll-anchor="false" data-turn="assistant"><div class="text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)"><div class="[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn"><div class="flex max-w-full flex-col gap-4 grow"><div data-message-author-role="assistant" data-message-id="e5209cfe-a0a8-4c45-b1fb-e369d383aa4b" dir="auto" data-message-model-slug="gpt-5-5" class="min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1" data-turn-start-message="true" tabindex="0"><div class="flex w-full flex-col gap-1 empty:hidden"><div class="markdown prose dark:prose-invert wrap-break-word w-full dark markdown-new-styling"><p data-start="0" data-end="368" data-is-last-node="" data-is-only-node="">It is recommended that the ballast filling system be restored to operational condition. Furthermore, the structural condition of the double bottom ballast tanks should be reinstated through proper inspection, maintenance, and any necessary repairs prior to being returned to service.</p></div></div></div></div><div class="z-0 flex min-h-[46px] justify-start"></div><div class="mt-3 w-full empty:hidden"><div class="text-center"></div></div></div></div></section></div>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1355, 769, '<p>During the survey, the surveyor could not find the vessel''s list of charts onboard and therefore the document could not be verified. this condition is categorized as a navigational administrative deficiency.&nbsp;</p>', '<p>It is recommended that the vessel''s list of charts be completed and maintained onboard in order to comply with navigational administrative requirements&nbsp;</p>', 'Daftar Peta', 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1356, 769, '<p>Underwater part / Zinc Anodes could not be inspected inspection of the underwater part including zinc anodes could not be carried out because the vessel remained afloat (anchor) during the survey. therefore, the actual condition of the underwater part and zinc anodes could not be confirmed at the time of inspection.&nbsp;</p>', '<p>it is recommended that inspection of the underwater part of the vessel including zinc anodes be carried out during the next dry docking or underwater inspection to ensure the hull protection condition remains satisfactory&nbsp;</p>', 'Kondisi Zinc Anode', 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1357, 732, '<li><p data-path-to-node="5,1,0,0"><b data-path-to-node="5,1,0,0" data-index-in-node="0">Structural Defect:</b> Minor cracks were observed on the internal structural members/stiffeners inside the ballast tanks, indicating localized metal fatigue from operational stress or vibrations.</p></li><li><p data-path-to-node="5,1,1,0"><b data-path-to-node="5,1,1,0" data-index-in-node="0">Material Degradation:</b> Light surface corrosion was noted on the internal tank plating, resulting from localized coating breakdown.</p></li><li><p data-path-to-node="5,1,2,0"><b data-path-to-node="5,1,2,0" data-index-in-node="0">Compromised Watertight Integrity:</b> The ballast tank manhole covers are missing their rubber seals. The absence of these seals fails to meet the required standard for watertight compartment insulation.</p></li>', '<li><p data-path-to-node="5,1,0,0"><b data-path-to-node="5,1,0,0" data-index-in-node="0">Structural Repair:</b> Carry out proper gouging and re-welding on the cracked internal members using class-approved welding electrodes.</p></li><li><p data-path-to-node="5,1,1,0"><b data-path-to-node="5,1,1,0" data-index-in-node="0">Surface Treatment:</b> Clean the lightly corroded areas via wire-brushing or disc-sanding, and re-apply an approved protective ballast tank coating.</p></li><li><p data-path-to-node="5,1,2,0"><b data-path-to-node="5,1,2,0" data-index-in-node="0">Seal Replacement:</b> Renew all missing rubber seals on the manhole covers to restore 100% watertight integrity.</p></li>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1358, 678, '<p>The Paper Charts were found sufficient. However, has not been updated/ corrected.</p>', '<p>To be updated/ corrected.</p>', 'Chart has been updated. Please refer to the attachment', 30, NULL, 'Decline', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1359, 678, '<p>The Changeover Instruction for Emergency Steering was found not posted on the Bridge and Steering Gear Room.</p>', '<p>To be posted/ displayed.</p>', 'Emergency steering procedure has been provided. Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1360, 678, '<p>SOPEP was found insufficient.</p>', '<p>To be provide a complete and updated SOPEP in accordance with MARPOL requirements.</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1361, 678, '<p>Steel Save-Alls/ Drip Tray were found not fitted on Anchor Windlass, Aft Winches and Hydraulic Control System of Hatch Covers.</p>', '<p>To be fitted/ provided</p>', 'Save all has been provided. Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1362, 678, '<p>Scupper Plugs was found unavailable on board.</p>', '<p>To be provided</p>', 'Scupper plug has been provided. Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1363, 678, '<ol><li>Main Deck was found rusty.</li><li>Forward Deck between Forecastle Deck &amp; Cargo Hold, and Coaming Stay were found rusty and paint peel-off.</li><li>Forward Hydrant Valve was found missing.</li><li>Hydrant Pipelines on the Main Deck were found to be leaking.</li><li>Bulwarks were found rusty.</li></ol>', '<ol><li>Main Deck to be cleaned, chipped, and repainted accordingly.</li><li>Rusty and paint peel-off areas on Forward Deck between Forecastle Deck &amp; Cargo Hold, including Coaming Stay, to be properly treated and repainted.</li><li>Missing Forward Hydrant Valve to be provided and fitted accordingly.</li><li>Leaking hydrant pipelines on Main Deck to be repaired to ensure proper operational condition.</li><li>Rusty bulwarks to be cleaned, treated, and repainted accordingly.</li></ol>', 'Please refer to the attachment', 30, NULL, 'Decline', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1364, 678, '<p>Oil Absorbent was found unavailable on board.</p>', '<p>To be provided</p>', 'Oil absorbent has been provided. Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1365, 678, 'Rubber Sealing of Hatch Cover Panels was found hardened', 'Hardened rubber sealing of Hatch Cover Panels to be renewed to maintain proper weathertight condition', 'Please refer to the attachment', 30, NULL, 'Decline', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1366, 678, '<ol><li>Bilges Suction Test has not been carried out due to safety reasons.</li><li>Cargo Hold Bilge Well was found with sludge and cargo residue.</li></ol>', '<ol><li>Bilges suction test to be carried out at the earliest opportunity under safe operating conditions.</li><li>Cargo Hold Bilge Well to be cleaned from sludge and cargo residue accordingly.</li></ol>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1367, 678, '<p>UTM Report was found unavailable on board.</p>', '<p>To be provided</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1368, 678, '<p>Internal Structure of the Ballast Tanks has not been inspected due to the Manholes were found in steel welded.</p>', '<p>Manholes of Ballast Tanks to be opened for internal inspection of tank structures accordingly.</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1369, 693, '<p>UTM report were not sighted at the time of survey</p>', '<p>send and/or follow up the UTM report after issued by vendor</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1370, 693, '<p>Radar log book were not provided on board</p>', '<p>Supply on board and maintain</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1371, 693, '<p>NTM/BPI were not provided on board</p>', 'to be supply on board', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1372, 693, '<p>Paper chart were not update</p>', '<p>Paper charts to be updated upon receipt of the NTM/BPI publications.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1373, 693, '<p>Save all''s were not provide on board</p>', '<p>to be provided on board, on bunker manifolds and fuel air vents</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1374, 693, '<p>DB_Ballast tanks were not inspected due to full of water and side ballst tanks were found corrosion at tanks bottom plating.</p>', '<p>To be survey on DB-Ballast tank and maintenance on side ballast tank</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1375, 693, '<p>internal inspected on COT were not carried out due to fully loaded of cargo (MFO)</p>', '<p>Internal inspection of COT to be carried out.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1376, 773, '<p>The Radar with ARPA operational were not available on board</p>', '<p>Ship owners must equip navigation equipment in the form of radar with ARPA operational on board the ship.</p>', 'Radar 2 unit tersedia di Kapal', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1377, 773, '<p>Shipâs charts Nos. 348, 347, 13, 12, 11, 10 and 19 were not update.</p>', '<p>The ship''s crew must update the charts as per NTM/BPI&nbsp; update&nbsp;</p>', 'Chart Suficient and Updated', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1378, 773, '<ul><li>Gyro Compass was not function.</li><li>Deviation of magnetic compass found expire with last adjusted on January 23, 2025</li></ul>', '<ul><li>The ship''s owner must repair the Gyro Compass.</li><li>The ship''e owner must be update or renewal the Deviation of Magnetic Compass.</li></ul>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1379, 773, '<p>The SOPEP locker or box were not available.</p>', '<p>The ship''s owner must complete the SOPEP locker or box.</p>', 'Sopep Available on Board', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1380, 773, '<p><span style="font-size: 0.875rem;">Oil spill save-alls around the bunker connection found dirty and holes at various spot.</span></p>', '<p>The ship''s crew must be clean the save-all and repair the holes.</p>', 'Bunker Connection update', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1381, 773, '<ul><li>Found no save-alls around the anchor/mooring windlass at forecastle deck.</li><li>Found no save-alls around the mooring windlass at poop deck.</li></ul>', '<p>The ship'' s owner must be complete the anchor/mooring windlass with save-alls.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1382, 773, '<p>Scupper plugs were not available onboard.</p>', '<p>The ship''s owner must be complete the scupper plugs.</p>', 'Scupper Plugs available on Board', 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1383, 773, '<p>Oil Absorbents are not available on board.</p>', '<p>The ship''s owner must be complete the oil absorbents.</p>', 'Oil Absorbent Available on Boardrn', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1384, 773, '<p>Main deck port and starboard side found rust and paint peel off at various spot.</p>', '<p>The ship''s owner must be repair and repaint the main deck.</p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1385, 773, '<ul><li>Holdâs bilge found remained of water.</li><li>During bilge suction test at port and starboard side using portable pump, noted that the water thrown directly into the sea.</li></ul>', '<ul><li>The ship''s crew must be clean the bilge well from the water or any foreign object.</li><li>The ship''s crew do not directly trown the water or foreign object from bilge well onto sea, but must be placed or stored in a drum or slop tank.</li></ul>', 'The Cargo Hold Bilge has been Cleaned & the Suction Test has been conducted', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1386, 773, '<p>Found no rubber seal at Bosunâs store watertight door.</p>', '<p>The ship''s crew must be complete the rubber seal at Bosun''s store watertight door.</p>', NULL, 29, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1387, 773, 'During hose test, the water inside into the cargo hold.', '<p>The ship''s owner must be temporary repair the hatch cover soon while waiting for docking on next docking schedule on April 2027.</p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1388, 773, '<ul><li>The hatch coaming stays found corrossion and torn at various places.</li><li>The hatch covers found corrossion and torn at various places.</li><li>There is a gap between each hatch cover.</li></ul>', '<p>The ship''s owner must be temporary repair the hatch cover and hatch coaming stays soon while waiting for docking on next docking schedule on April 2027.</p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1389, 773, '<ul><li>The hatch coaming stays found corrossion and torn at various places.</li><li>The hatch covers found corrossion and torn at various places.</li><li>There is a gap between each hatch cover.</li></ul>', '<p>The ship''s owner must be temporary repair the hatch cover and hatch coaming stays soon while waiting for docking on next docking schedule on April 2027.</p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1390, 773, '<ul><li>The hatch coaming stays found corrossion and torn at various places.</li><li>The hatch covers found corrossion and torn at various places.</li><li>There is a gap between each hatch cover.</li></ul>', '<p>The ship''s owner must be temporary repair the hatch cover and hatch coaming stays soon while waiting for docking on next docking schedule on April 2027.</p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1391, 773, '<ul><li>The hatch coaming stays found corrossion and torn at various places.</li><li>The hatch covers found corrossion and torn at various places.</li><li>There is a gap between each hatch cover.</li></ul>', '<p>The ship''s owner must be temporary repair the hatch cover and hatch coaming stays soon while waiting for docking on next docking schedule on April 2027.</p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1392, 773, '<ul><li>During Ballast pressure test, found leakage on top plate of wing tank ballast No. 3 port side.</li><li>During Ballast pressure test, found leakage on top plate of wing tank ballast No. 4 port side.</li></ul>', 'The ship''s owner must be temporary repair the leakage on top plate of wing tank ballast No. 3P and 4P soon while waiting for docking on next docking schedule on April 2027.', 'Leakage of wing tank ballas has been repaired', 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1393, 788, '<p>During the navigation audit, it was noted that the vessel has zero records of receiving Notice to Mariners (NTM) Bulletins. consequently, onboard navigational charts and critical publications have not been updated with recent maritime safety changes or new hazards.&nbsp;</p>', '<p>The ship management / master must immediately arrange to supply the latest NTM Bulletins to the vessel. all affected navigational charts and publications for the intended voyage must be corrected and updated to the latest edition&nbsp;&nbsp;</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1394, 788, '<p>The dedicated SOPEP storage locker lacks the mandatory standard identification marking on its exterior. this absence of clear labeling creates an operational issue in identifying emergency pollution response gear</p>', 'Apply standard, highly visible identification stenciling or signage "SOPEP LOCKER" on the locker door to ensure quick location during emergency response.&nbsp;', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1395, 788, '<p>The external hull zinc anodes could not be visually evaluated or measured during the survey as they were completely submerged underwater at the anchorage layout&nbsp;</p>', '<p>The condition of the external hull zinc anodes must be verified by the crew during the next diving inspection or underwater survey. full replacement of the anodes should be scheduled during the next drydocking to ensure continuous cathodic protection against hull corrosion.&nbsp;</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1396, 788, '<p>Interior entry and structural verification of the cargo tanks were not possible during the inspection because the vessel was in a laden condition, with all tanks fully occupied by liquid cargo.&nbsp;</p>', '<p>Internal structural inspection of the cargo tanks must be carried out at the next convenient discharge port or when the tanks are empty and safely gas-free&nbsp;</p>', NULL, 10, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1397, 788, '<p>Visual inspection of the main deck plating revealed localized areas of heavy surface corrosion on both the port and starboard sides. the protective coating has degraded, exposing the steel plating to continuous marine weathering.&nbsp;</p>', '<p>Carry out chipping, wire-brushing, and apply proper marine-grade anti-corrosive primer and topcoat painting on the affected port and starboard main deck areas. additionally, Ultrasonic Thickness Measurement (UTM) should be arranged to monitor steel wastage&nbsp;</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1398, 788, '<p>Internal structural assessment of the ballast tanks revealed surface corrosion on the internal framing. additionally, minor physical cracks were observed on several structural frames (gading-gading), which affects the local reinforcement structure.&nbsp;</p>', '<p>Arrange for structural repair on the affected internal frames within the ballast tanks. the minor cracks must be properly gouged, cropped if necessary, and re-welded by certified welders according to class standards to restore local structural strength.&nbsp;</p>', NULL, 40, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1399, 788, '<p>The pressure testing system for the ballast tanks was found non-operational during the survey. due to this equipment status, the tight-integrity verification of the tank boundaries could not be performed.&nbsp;</p>', '<p>Inspect and overhaul the ballast tank testing valves, lines or relevant testing equipment to restore full operational capability. once repaired, a pressure/tightness test must be carried out to verify structural integrity.&nbsp;</p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1400, 495, '<p>The Planned Maintenance System was not available onboard.</p>', '<p>The planned maintenance system includes critical equipment, spare parts inventory, overdue maintenance records, and reminders for pending items that should be provided onboard.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1401, 495, '<p>The bilges in the cargo hold Nos. 1 and 2 were found filled with water</p>', '<p>The engine room bilges should be dry and cleaned.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1402, 495, '<p>The floor plates and ladder in the engine room were found slippery (oily).</p>', '<p>The floor plates and ladder were found to be slippery and should be cleaned and kept dry all time.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1403, 495, '<p>The bilges in the cargo hold Nos. 1 and 2 were found filled with water.</p>', '<p>The engine room bilges should be dry and cleaned.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1404, 495, '<p>The last 3 (three) voyage stability calculations at the time of departure and on arrival was not available onboard.</p>', '<p>The voyage stability calculations at the time of departure and on arrival should be calculated by the crew and provided onboard.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1405, 495, '<p>The emergency light in the crew accomodation was available onboard. However, it cannot be tested due to the vessel placed at dry dock for routine maintenance (Not inspected).</p>', '<p>The emergency light should be tested and confirmed to be in good working order upon completion of the dry-docking maintenance.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1406, 495, '<p>The internal cargo hold of No.1 was found residue from the recent cargo (cement) at several places)</p>', '<p>The remaining cement residues in Cargo Hold No. 1 should be completely removed and cleaned.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1407, 495, '<p>The engine room was found dirty and slippery due to the vessel placed at dry dock for routine maintenance.</p>', '<p>The engine room was found dirty and slippery should be cleaned and kept dry at all times.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1408, 495, '<p>The emergency fire pump cannot be tested due to the vessel placed at dry dock (Not inspected)</p>', '<p>The emergency fire pump should be tested upon completion of the dry-docking period to verify its operational readiness.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1409, 495, '<p>The escape routes was not clearly marked.</p>', '<p>The escape routes should be properly identified with clear and visible signage to facilitate safe evacuation in an emergency.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
