INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1414, 495, '<p>The record for testing the steering gear was not available onboard.</p>', '<p>The steering gear should be tested at the required intervals, and the test records should be provided onboard.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
