INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1418, 495, '<p>The exhaust temperature of auxiliary engines cannot be tested due to the vessel placed at dry dock for routine maintenance (Not inspected).</p>', '<p>The exhaust temperatures of the auxiliary engines should be checked and recorded upon completion of the dry-docking maintenance to verify normal operating conditions.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1419, 495, '<p style="color: rgb(33, 37, 41);">The fire extinguishers were found satisfactory.</p><p style="color: rgb(33, 37, 41);">However, the fire hose locker was not sufficient in numbers (only have 1 hose locker at 3rd deck).</p>', '<p>The number of fire hose lockers should be increased to comply with the approved Fire Control Plan arrangement.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
