INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1448, 516, '<p><span style="color: rgb(33, 37, 41);">The watertight doors were found not fitted with the rubber seal and were wastage at several places on the deck</span></p>', '<p><span style="font-size: 0.875rem;">The watertight doors should be fitted with the rubber seal and copped and renewed for the wastege area.&nbsp;</span></p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1449, 516, '<p style="color: rgb(33, 37, 41);"><span style="font-size: 0.875rem;">The forward starboard side shell was found cropped due to vessel maintenance at dry dock.</span></p>', '<p>The cropped forward starboard side shell should be fitted and renewed</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1450, 516, '<p style="color: rgb(33, 37, 41);">The steel structure and internal structure ballast tank Nos. 1P,1S,2P,2S,3P,3S are found wastage at several places.</p><p style="color: rgb(33, 37, 41);">The ballast tank Nos. 1P,1S,2P,2S,3P,3S were found without fitted with any zinc anodes&nbsp;</p>', '<p>The steel structure and internal structure ballast tank Nos. 1P,1S,2P,2S,3P,3S are found wastage at several places should be cropped and renewed. The ballast tank Nos. 1P,1S,2P,2S,3P,3S were found without any zinc anodes and should be installed.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1451, 516, '<p><span style="color: rgb(33, 37, 41);">The bilges at the cargo hold Nos 1 and 2 were found filled with water.</span></p>', '<p><span style="color: rgb(33, 37, 41);">The bilges at the cargo hold Nos 1 and 2 should be cleaned and kept dry all times</span></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1452, 516, '<p><span style="color: rgb(33, 37, 41);">Based on the visual inspection and the engine logbook on the last voyage, the auxiliary engine was found in satisfactory condition with no abnormality sighted.</span></p><p><span style="color: rgb(33, 37, 41);">However, we cannot test the Auxiliary engines while the vessel is placed at dry dock.</span><span style="color: rgb(33, 37, 41);"></span></p>', '<p><span style="color: rgb(33, 37, 41);">The auxiliary engines should be tested upon completion of the dry-docking maintenance to confirm their satisfactory working condition.</span></p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1453, 516, '<p><span style="color: rgb(33, 37, 41);">The ballast tank pressure cannot be conducted while the vessel is placed in dry dock.a</span></p>', '<p><span style="color: rgb(33, 37, 41);">The ballast tank pressure s</span><span style="color: rgb(33, 37, 41); font-size: 0.875rem;">hould be tested upon completion of the dry-docking maintenance to confirm the ballast tank''s satisfactory condition.</span></p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1454, 516, '<p><span style="color: rgb(33, 37, 41);">The emergency steering test was not conducted while the vessel placed at dry dock.&nbsp;</span></p>', '<p><span style="color: rgb(33, 37, 41);">The emergency steering gear should be tested upon completion of the dry-docking period to confirmed to be in satisfactory working condition.</span></p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1455, 495, '<p style="color: rgb(33, 37, 41);">As far as we could ascertain, the main switchboard indicator was in good condition.</p><p style="color: rgb(33, 37, 41);">However, the main switchboard indicator cannot be tested whilst the vessel is placed at dry dock.</p>', '<p><span style="color: rgb(33, 37, 41);">The main switchboard indicator should be tested upon completion of the dry-docking maintenance to confirm their satisfactory working condition.</span></p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1456, 803, '<p><span style="color: rgb(33, 37, 41);">The bunker station was installed with improper save-alls</span></p>', '<span style="color: rgb(33, 37, 41);">The save all of bunker station is to be installed properly.</span>', 'Please refer to the attached document and video', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1457, 803, '<p><span style="color: rgb(33, 37, 41);">the chart number 61, 68, 104, 54, 86 is outdated</span></p>', '<p>The charts are to be updated</p>', 'Please refer to the attached document', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1458, 803, '<p><span style="color: rgb(33, 37, 41);">Ballast vent pipe was found leaked on ballast tank no 2p</span></p>', '<p>The leaked vent pipe of ballast tank No.2P is to be repaired.</p>', 'Please refer to the attached document', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1459, 631, '<p>U<span style="color: rgb(33, 37, 41); font-size: 0.875rem;">TM Report was found not available on board</span></p>', '<p>To be provided</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1460, 631, '<ul style="color: rgb(33, 37, 41);"><li>Auxiliary engine no. 1 was found in repair condition</li><li>OWS was found malfunction</li><li>OWS overboard valve was found not secured with chain &amp; padlock and pollution warning notice not posted</li><li>Engine room bilge was found oily water and sludge</li></ul>', '<ul style="color: rgb(33, 37, 41);"><li>Repair of Auxiliary engine no. 1 to be completed</li><li>OWS to be repair</li><li>OWS overboard valve to be secured with chain &amp; padlock and pollution warning notice to be posted</li><li>Engine room bilge to be cleaned up</li></ul>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1461, 631, '<p><span style="color: rgb(33, 37, 41);">Plimsoll and Draft marks were found faded</span></p>', '<p>To be marked</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1462, 631, '<p><span style="color: rgb(33, 37, 41);">Emergency generator was found in repair condition</span></p>', '<p>Repair to be completed</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1463, 631, '<p><span style="color: rgb(33, 37, 41);">Ballast tank pressure test has not been conducted due to operational reasons</span></p>', '<p>To be tested</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1464, 631, '<p><span style="color: rgb(33, 37, 41);">NTM/ BPI was found not supplied regularly</span></p>', '<p>To be supplied regularly</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1465, 631, '<p><span style="color: rgb(33, 37, 41);">All inspected of Ballast tanks were found heavy rusty</span></p>', '<p>To be chipped/ repaired and painted</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1466, 631, '<p><span style="color: rgb(33, 37, 41);">Charts were found not corrected as per latest NTM/ BPI</span></p>', 'To be corrected', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1467, 631, '<ul style="color: rgb(33, 37, 41);"><li>Cargo holds bilge well were found rusty/ corroded</li><li>Suction test has not been conducted due to operational reasons</li></ul>', '<ul style="color: rgb(33, 37, 41);"><li>Cargo holds bilge well to be chipped/ repaired</li><li>Suction test to be tested</li></ul>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1468, 631, '<p>Echo sounder was found not available</p>', '<p>To be provided</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1469, 631, '<p><span style="color: rgb(33, 37, 41);">Many doublers were found fitted at Tank top</span></p>', '<p>To be replated</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1470, 631, '<p><span style="color: rgb(33, 37, 41);">Save-alls were found not fitted at FOT air vents (P &amp; S), and Hatch covers &amp; Anchor windlass hydraulic operating handle</span></p>', '<p>To be fitted</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1471, 631, '<p><span style="color: rgb(33, 37, 41);">Watertight doors were found without Open/ Close marking and Watertight door of store corroded at lower area</span></p>', '<p>To be marked and repair/ replaced</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1472, 631, '<p><span style="color: rgb(33, 37, 41);">Fuel air vents (P &amp; S) were found corroded</span></p>', '<p>To be repaired</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1473, 631, '<ul style="color: rgb(33, 37, 41);"><li>Doublers were found fitted at Starboard side main deck, Forward deck, and Aft deck</li><li>Derrick deck was found oily/ slippery due to hydraulic system leakage</li><li>Bollards, Rollers and Fairleads were found without SWL marking and rusty</li></ul>', '<ul style="color: rgb(33, 37, 41);"><li>Doublers to be replated</li><li>Derrick deck to be cleaned up and hydraulic system to be repaired</li><li>Bollards, Rollers and Fairleads to be chipped, painted and marked</li></ul>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1474, 631, '<p><span style="color: rgb(33, 37, 41);">Deviation card was found expired (more than 2 years)</span></p>', '<p>To be readjusted</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1475, 631, '<p><span style="color: rgb(33, 37, 41);">Oil absorbents were found not available</span></p>', '<p>To be provided</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1476, 516, '<p style="color: rgb(33, 37, 41);">The doubling plates were fitted at several locations on the boat deck plating.</p><p style="color: rgb(33, 37, 41);">The coating was found not well-painted in several places due to the vessel maintenance at the dry dock.</p>', '<p>The doubling plates were fitted at several locations on the boat deck should be cropped and renewed.</p><p>The coating should be cleaned and well painted.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1477, 516, '<p><span style="color: rgb(33, 37, 41);">The main engine was in good appearance. However, the operation was not inspected while the vessel was placed in the dry dock</span></p>', '<span style="color: rgb(33, 37, 41);">The main engine should be tested upon completion of the dry-docking maintenance to confirm their satisfactory working condition.</span>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1478, 516, '<p style="color: rgb(33, 37, 41);">The emergency generator was available onboard.</p><p style="color: rgb(33, 37, 41);">The vessel was fitted with 2 (two) emergency generators located on the 2nd deck and 3rd deck.</p><p style="color: rgb(33, 37, 41);">However, the emergency generator cannot be tested while the vessel is placed at dry dock.</p>', '<span style="color: rgb(33, 37, 41);">The emergency generator should be tested upon completion of the dry-docking maintenance to confirm its satisfactory working condition.</span>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1479, 806, '<p>The Ultrasonic Steel Thickness report is not available onboard.</p>', '<p>The Ultrasonic Steel Thickness reports should be provided onboard.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1480, 806, '<p>The fuel air ventilations, and ballast sounding pipes lacked proper markings or labels designating the specific compartments they serve.</p>', '<p>All fuel oil air ventilation pipes, and ballast tank sounding pipes must be clearly marked or labeled to designate the specific compartments they serve.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1481, 806, '<p>The accommodation toilet doors lacked rubber sealing gaskets, which are necessary to ensure proper water tightness.</p>', '<p>The rubber sealing gaskets on the door should be fitted.&nbsp;</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1482, 787, '<p>&nbsp;A save-all is a containment tray designed to catch oil or fuel leaks around machinery or bunker stations. The drain hole in this tray must remain plugged/covered during normal operations to contain any spilled fluids.</p>', '<p><span data-path-to-node="9,0,0,0">The ship''s crew/engine department must fabricate or source a proper, tight-fitting threaded plug or blind cover for the open drain hole of the save-all tray</span><span data-path-to-node="9,0,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted"><sup _ngcontent-ng-c2700604988="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="9,0,0,2">. The drain must remain strictly sealed during bunker operations and normal machinery running to prevent any accidental environmental discharge</span><span data-path-to-node="9,0,0,3"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted"><sup _ngcontent-ng-c2700604988="" class="superscript"></sup></source-footnote></span></p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1483, 787, '<p>The Ultrasonic Testing (UT) certificate is a statutory document that proves the structural thickness of the vessel''s hull plates has been measured and verified against safety margins against corrosion</p>', '<p><span data-path-to-node="3,0,0,0">The ship management must immediately trace the original or certified true copy of the latest Ultrasonic Testing (UT) gauging report from the class society or approved service supplier</span><span data-path-to-node="3,0,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted"><sup _ngcontent-ng-c2700604988="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="3,0,0,2">. A digital or physical copy must be dispatched and placed inside the vessel''s statutory document file</span></p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1484, 787, '<p>A Chart List (or Chart Catalogue) is an essential navigational index used by the deck officers to ensure that all nautical charts required for the intended voyage are onboard, updated, and corrected to the latest Notices to Mariners</p>', '<p><span data-path-to-node="5,0,0,0">The Second Officer must compile, verify, and print an updated Chart List / Inventory Catalogue appropriate for the current and subsequent voyage routes</span><span data-path-to-node="5,0,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted"><sup _ngcontent-ng-c2700604988="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="5,0,0,2">. Any missing or outdated charts identified from the list must be ordered and updated to the latest Notices to Mariners immediately</span></p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1485, 787, '<p>International maritime regulations require a clear, step-by-step graphical or written procedure to be posted inside the steering gear room and bridge, showing how to switch from the main steering system to the emergency steering system</p>', '<p><span data-path-to-node="7,0,0,0">A clear, step-by-step graphical changeover manual detailing the procedures to switch from the main bridge steering to the emergency steering gear must be printed, laminated, and permanently posted in prominent locationsâspecifically inside the Steering Gear Room and on the Navigation Bridge</span><span data-path-to-node="7,0,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted"><sup _ngcontent-ng-c2700604988="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="7,0,0,2">. The crew should also conduct a brief drill to ensure familiarity</span></p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1486, 787, '<p>Zinc anodes are sacrificial metals welded to the underwater hull to protect the ship''s steel plates from galvanic corrosion. Surveyor inspection is required to check their depletion rate (how much of the anode is left)</p>', '<p><span data-path-to-node="7,0,0,0">Because the zinc anodes could not be visually verified due to being submerged, their condition must be assessed during the next scheduled underwater inspection or dry-docking</span><span data-path-to-node="7,0,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted"><sup _ngcontent-ng-c2700604988="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="7,0,0,2">.&nbsp;</span></p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1487, 787, '<p><span data-path-to-node="3,0,0,0">&nbsp;Hold bilges collect any condensation or water leakage inside the palka. They must be clean (free of cargo residue/mud) and the suction pumps must be tested to ensure they can pump out water in an emergency</span></p>', '<span data-path-to-node="3,0,0,0">&nbsp;As the internal cargo holds, hold bilges, hatch covers, and ballast tanks could not be inspected due to the vessel being laden, a supplementary internal inspection must be scheduled</span><span data-path-to-node="3,0,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted"><sup _ngcontent-ng-c2700604988="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="3,0,0,2">. The ship management must arrange for the surveyor to re-inspect these areas immediately after the current cargo has been fully discharged at the next port</span><span data-path-to-node="3,0,0,3"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted"><sup _ngcontent-ng-c2700604988="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="3,0,0,4">.</span>', NULL, 10, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1488, 787, '<p>The structural frames, bulkheads, and tank top plates inside the cargo holds must be visually checked for cracks, heavy deformation, or structural damage caused by cargo operations (impact from grabs/excavators)</p>', '<p><span data-path-to-node="3,0,0,0">As the internal cargo holds, hold bilges, hatch covers, and ballast tanks could not be inspected due to the vessel being laden, a supplementary internal inspection must be scheduled</span><span data-path-to-node="3,0,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted"><sup _ngcontent-ng-c2700604988="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="3,0,0,2">. The ship management must arrange for the surveyor to re-inspect these areas immediately after the current cargo has been fully discharged at the next port</span><span data-path-to-node="3,0,0,3"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted"><sup _ngcontent-ng-c2700604988="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="3,0,0,4">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c1005750260=""></sources-carousel-inline></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1489, 787, '<p>These are specialized tests used to verify the absolute weather-tightness of the hatch covers. A hose test uses high-pressure water, while an ultrasonic test uses sound waves to detect microscopic gaps in the seals</p>', '<p><span data-path-to-node="5,0,0,0">Since the weather-tightness of the hatch covers and the integrity of the rubber seals could not be tested, a proper <i data-path-to-node="5,0,0,0" data-index-in-node="132">Hose Test</i> or <i data-path-to-node="5,0,0,0" data-index-in-node="145">Ultrasonic Leak Test</i> must be performed alongside the post-discharge inspection</span><span data-path-to-node="5,0,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted"><sup _ngcontent-ng-c2700604988="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="5,0,0,2">. This is critical to ensure that the cargo will be protected from water ingress during future voyages in heavy weather</span><span data-path-to-node="5,0,0,3"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted"><sup _ngcontent-ng-c2700604988="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="5,0,0,4">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c1005750260=""></sources-carousel-inline></p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1490, 787, '<p>Hatch covers prevent seawater from entering the cargo holds. The rubber sealings (packings) must be checked for elasticity, cracks, or missing segments to ensure a watertight seal</p>', '<p><span data-path-to-node="5,0,0,0">Since the weather-tightness of the hatch covers and the integrity of the rubber seals could not be tested, a proper <i data-path-to-node="5,0,0,0" data-index-in-node="132">Hose Test</i> or <i data-path-to-node="5,0,0,0" data-index-in-node="145">Ultrasonic Leak Test</i> must be performed alongside the post-discharge inspection</span><span data-path-to-node="5,0,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted"><sup _ngcontent-ng-c2700604988="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="5,0,0,2">. This is critical to ensure that the cargo will be protected from water ingress during future voyages in heavy weather</span></p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1491, 787, '<p>Ballast tanks are internal spaces filled with seawater to manage the ship''s stability. Surveyors must enter these confined spaces to check for internal structural cracking, heavy rust scale, or coating breakdown</p>', '<p><span data-path-to-node="3,0,0,0">As the internal cargo holds, hold bilges, hatch covers, and ballast tanks could not be inspected due to the vessel being laden, a supplementary internal inspection must be scheduled</span><span data-path-to-node="3,0,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted"><sup _ngcontent-ng-c2700604988="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="3,0,0,2">. The ship management must arrange for the surveyor to re-inspect these areas immediately after the current cargo has been fully discharged at the next port</span><span data-path-to-node="3,0,0,3"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c2700604988="" class="ng-star-inserted"><sup _ngcontent-ng-c2700604988="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="3,0,0,4">.</span></p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1492, 814, '<p>The absence of the Class Certificate means the vessel cannot legally prove its structural integrity and compliance with international maritime safety standards</p>', '<p>Provide and place the valid, official Class Certificate onboard the vessel immediately.</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1493, 814, '<p>Without the Ultrasonic Thickness (UT) Test Certificate, there is no verified record of the hull''s actual steel thickness, making it impossible to confirm if the vessel''s structure has wasted beyond safe operational limits.</p>', '<p>Locate and place the Ultrasonic Thickness (UT) Test Certificate onboard for surveyor verification.</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1494, 814, '<p>A malfunctioning radar severely reduces situational awareness, increasing the risk of collision, especially in low visibility or heavy traffic.&nbsp;</p>', '<p>Repair or replace the damaged Radar unit to fully operational status, and provide a new official Log Book onboard</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1495, 814, '<p>Lacking Notice to Mariners (NTM) updates for a year means the crew is unaware of recent navigational hazards, changes in buoyage, or altered channels, posing a direct threat to safe navigation</p>', '<p>Obtain and compile all missing Notice to Mariners (NTM) bulletins from the past 12 months</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1496, 814, '<p>Navigating with outdated charts means the vessel may be relying on obsolete hydrographic data, significantly increasing the risk of grounding or entering restricted zones.</p>', '<p>Procure, update, and maintain all required nautical charts to the latest editions</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1497, 814, '<p>The absence of emergency steering procedures delays the crew''s response during a sudden steering failure, which could lead to a total loss of vessel control during a crisis.</p>', '<p>Prepare and visibly post clear emergency steering instructions in the steering gear room and navigation bridge.</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1498, 814, '<p>Uncovered drains at save-alls allow debris to block the drainage system or can cause accidental oil spills directly into the sea if the containment overflows</p>', '<p>Fabricate and install proper drain covers for all save-alls to prevent debris accumulation and accidental spills.</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1499, 814, '<p>Without scupper plugs, the crew cannot seal the deck during oil transfer (bunkering) or cargo operations, risking immediate marine pollution in the event of an accidental deck spill.</p>', '<p>Supply the missing scupper plugs to ensure the deck can be properly sealed during bunkering or cargo operations</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1500, 814, '<p>Because the anodes are fully submerged, their depletion rate cannot be monitored. If the zinc anodes are completely wasted, the hull will suffer accelerated galvanic corrosion</p>', '<p>Arrange an underwater camera inspection (UWILD) by certified divers or defer the inspection to the next scheduled dry-docking.</p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1501, 814, '<p>Active corrosion on the forecastle and side decks weakens the localized steel structure. Over time, this compromises the vesselâs watertight integrity and overall structural strength</p>', '<p>Perform descaling (chipping/grinding), apply rust primer, and repaint all corroded areas on the forecastle and both side decks</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1502, 814, '<p>Permanently sealed access manholes prevent mandatory internal inspections, leaving potential internal structural wastage, severe corrosion, or structural buckling completely undetected</p>', '<p>Unseal and re-open the ballast tank access manholes to allow for mandatory internal safety inspections</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1503, 833, '<p>The vessel has never received any Notice to Mariners (NTM) Bulletins on board. This lack of updated navigational safety information means the crew may be unaware of recent maritime hazards, changes in buoyage, or temporary routing alterations.</p>', '<p>The shipowner or management must promptly subscribe to or establish a reliable channel to receive regular NTM Bulletins on board. The crew must maintain a proper logbook to record each bulletin''s receipt and update relevant nautical publications accordingly.</p>', 'Please refer to the attached document', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1504, 833, '<p>The mandatory List of Charts required for the vessel''s trading area is not available on board. Without this list, proper passage planning and verification of mandatory chart coverage cannot be effectively performed.</p>', '<p>Provide an official and updated List of Charts suitable for the vesselâs operational routes. Ensure that all charts listed therein are present, physically available on the bridge, and corrected up to the latest edition.</p>', 'Please refer to the attached video', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1505, 833, '<p>The newly installed Echo Sounder unit experienced a system error and is not working / cannot be switched on. The equipment had remained untested since its post-docking installation until its initial operational test during this survey.</p>', '<p>Arrange for a qualified marine electronics service technician to investigate the error, rectify the power/system failure, and successfully commission the unit to ensure accurate depth soundings are available on the bridge.</p>', 'Please refer to the attached video', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1506, 833, '<p>The dedicated SOPEP (Shipboard Oil Pollution Emergency Plan) locker is not available on board the vessel, leaving the crew without a centralized, designated station to respond to unexpected oil pollution emergencies.</p>', '<p>Fabricate or supply a clearly marked, dedicated SOPEP locker on board. It must be placed in an easily accessible location on deck and stocked with standard oil spill response equipment.</p>', 'Pleas refer to the attached photo', 10, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1507, 833, '<p>Save-all arrangements (such as drip trays or containment coamings) are not available on board. This increases the risk of minor fuel or oil leaks from deck machinery and air vents draining directly into the sea.</p>', '<p>Install or place functional save-alls / drip trays underneath high-risk areas, including fuel oil tank air vents, bunkering manifolds, and hydraulic deck machinery, to securely contain any localized oil leakage</p>', 'Please refer to the attached photo', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1508, 833, '<p>The condition, wastage rate, and secure attachment of the hull''s cathodic protection (Zinc Anodes) could not be verified or inspected because they were completely submerged under water at the time of the survey.</p>', '<p>The operational status of the sacrificial anodes should be closely monitored. It is recommended to perform a visual underwater diver inspection or verify their condition during the next convenient shallow-water mooring or cleaning interval.</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1509, 833, '<p>Oil absorbent materials (such as pads, booms, or pillows) are completely unavailable on board, compromising the vessel''s capability to mitigate and clean up minor oil spills on deck.</p>', '<p>Supply an adequate quantity of marine-grade oil absorbent pads and materials to the vessel. These should be safely stored inside the newly designated SOPEP locker for immediate deployment during an emergency.</p>', 'Please reefer to the attached photo', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1510, 833, '<p>All watertight doors on board are currently in an incomplete condition as they do not have their respective rubber seals fitted, which directly compromises the vessel''s weather-tight and watertight integrity.</p>', '<p>Procure and install new, marine-grade rubber seals for every watertight door on board. Upon installation, conduct a chalk test or a water hose test to verify that a secure, watertight seal is achieved.</p>', 'Please refer to the attached Photo and video', 7, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1511, 802, '<p><span style="color: rgb(33, 37, 41);">the chart number 61, 78, 104 is outdated</span></p>', '<p><span style="color: rgb(33, 37, 41);">the chart number 61, 78, 104 is should be updated</span></p>', 'Kindly refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1512, 802, '<p><span style="color: rgb(33, 37, 41);">Save alls on mooring windlass at the poopdeck was not installed</span></p>', '<p>The save alls should be installed properly on the mooring windlass at the poopdeck</p>', 'Kindly refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1513, 802, '<p><span style="color: rgb(33, 37, 41);">Ballast manhole cover no 2P was found leaked</span></p>', '<p>The ballast manhole cover must be opened, the rubber gasket must be replaced with the new one, and refited the mahole cover</p>', 'Kindly refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1514, 802, '<p><span style="color: rgb(33, 37, 41);">coaming at escape hatch opening was wasted and broken</span></p>', '<p><span style="color: rgb(33, 37, 41);">coaming at escape hatch opening must be cropped and renewed</span></p>', 'Kindly refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1515, 799, '<p>The primary Class Certificate was missing from the vessel during inspection because it is currently held by the shipâs agent for port clearance administrative purposes</p>', '<p><span data-path-to-node="14,0,1,1,0,0">The Master must ensure the agent returns the original certificate as soon as port clearance is completed</span><span data-path-to-node="14,0,1,1,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="14,0,1,1,0,2">. Keep a valid copy or official agent receipt onboard in the interim</span></p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1516, 799, '<p><span data-path-to-node="14,1,1,0,0,0">&nbsp;Certificates of Competency (COC) for the ship''s officers could not be produced onboard due to ongoing administrative clearance handled by the agent</span><span data-path-to-node="14,1,1,0,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="14,1,1,0,0,2">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c667180327=""></sources-carousel-inline></p>', '<p><span data-path-to-node="14,1,1,1,0,0">Maintain a dedicated file containing digital or printed copies of all officers'' certificates of competency onboard for immediate verification</span><span data-path-to-node="14,1,1,1,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"></sup></source-footnote></span></p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1517, 799, '<p>The latest Ultrasonic Thickness (UT) gauging report was unavailable onboard as it remains within the documentation bundle held by the agent</p>', '<p><span data-path-to-node="14,2,1,1,0,0">Request a copy of the UT certificate from the company management or agent to be kept onboard as a structural integrity reference</span><span data-path-to-node="14,2,1,1,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="14,2,1,1,0,2">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c667180327=""></sources-carousel-inline></p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1518, 799, '<p><span data-path-to-node="17,0,1,0,0,0">Notice to Mariners (NTM) bulletins for chart corrections are missing</span><span data-path-to-node="17,0,1,0,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="17,0,1,0,0,2">. The vessel is exposed to navigational risks due to relying on unupdated charts</span><span data-path-to-node="17,0,1,0,0,3"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="17,0,1,0,0,4"></span></p>', '<p><span data-path-to-node="17,0,1,1,0,0">&nbsp;Immediately raise a company requisition to supply the latest NTM updates (printed or digital formats) prior to vessel departure</span><span data-path-to-node="17,0,1,1,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="17,0,1,1,0,2">.</span><sources-carousel-inline ng-version="0.0.0-PLACEHOLDER" _nghost-ng-c667180327=""></sources-carousel-inline></p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1519, 799, '<p>&nbsp;The official catalogue or list of nautical charts required for the vessel''s operational trading route was missing from the bridge</p>', '<p><span data-path-to-node="17,1,1,1,0,0">Compile and establish a formalized list of charts matching the active voyage requirements and verify chart availability</span><span data-path-to-node="17,1,1,1,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"></sup></source-footnote></span></p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1520, 799, '<p><span data-path-to-node="17,2,1,0,0,0">Visual posters illustrating step-by-step instructions for emergency steering changeover are missing from the bridge and engine room</span><span data-path-to-node="17,2,1,0,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="17,2,1,0,0,2">. This is a statutory safety non-compliance</span></p>', '<p>Print, laminate, and permanently post clear emergency steering changeover procedures near the steering console on the bridge and inside the steering gear room</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1521, 799, '<p><span data-path-to-node="17,3,1,0,0,0">Scupper plugs used for sealing deck drains were missing</span><span data-path-to-node="17,3,1,0,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="17,3,1,0,0,2">. This creates a pollution risk if a minor spill occurs during cargo or bunkering operations</span><span data-path-to-node="17,3,1,0,0,3"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="17,3,1,0,0,4"></span></p>', '<p><span data-path-to-node="17,3,1,1,0,0">&nbsp;Supply a complete new set of scupper plugs matching the dimensions and quantity of the ship''s deck scuppers</span><span data-path-to-node="17,3,1,1,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="17,3,1,1,0,2"></span></p>', NULL, 10, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1522, 799, '<p><span data-path-to-node="20,0,1,0,0,0">The hull plating at the starboard bow sustained a structural tear and physical damage</span><span data-path-to-node="20,0,1,0,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="20,0,1,0,0,2">. Repairs were actively ongoing during the survey inspection</span></p>', '<p><span data-path-to-node="20,0,1,1,0,0">Complete the plate welding repairs using approved marine-grade procedures</span><span data-path-to-node="20,0,1,1,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="20,0,1,1,0,2">. The final repair must be inspected and cleared by the attending Class Surveyor before departure</span><span data-path-to-node="20,0,1,1,0,3"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="20,0,1,1,0,4"></span></p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1523, 799, '<p>The structural door between the accommodation area and the engine room is degraded, showing heavy corrosion at the bottom section, compromising fire/smoke boundaries</p>', '<p>Repair the damaged door mechanisms/hinges, chip away the rust, weld an insert/doubler plate if required, and apply a fresh coat of marine paint</p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1524, 799, '<p>&nbsp;Internal structural frames within the cargo holds exhibit bending and physical deformation caused by mechanical impacts during cargo operations</p>', '<p><span data-path-to-node="20,2,1,1,0,0">Schedule structural steel repairs (straightening or renewal of bent frames) during the next convenient dry-docking or extended port stay</span><span data-path-to-node="20,2,1,1,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="20,2,1,1,0,2">.</span></p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1525, 799, '<p>Surface rust and minor localized corrosion were observed across several areas of the steel hatch covers</p>', '<p><span data-path-to-node="20,3,1,1,0,0">Direct the ship''s crew to carry out routine maintenance, including chipping, applying anti-corrosive primer, and repainting affected areas to arrest further corrosion</span><span data-path-to-node="20,3,1,1,0,1"><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><source-footnote _nghost-ng-c3458427909="" class="ng-star-inserted"><sup _ngcontent-ng-c3458427909="" class="superscript"><!----></sup></source-footnote><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----></span><span data-path-to-node="20,3,1,1,0,2">.</span></p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1526, 873, '<p>Interior of Holds (Cargo Oil Tank for Tanker) was not inspected.</p>', '<p>It is recommended that the internal condition of the holds/cargo oil tanks be inspected at the next available opportunity when access is possible and the spaces are gas-free.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1527, 873, '<p>Ballast pressure test was not inspected.</p>', '<p>It is recommended that the ballast tanks be pressure tested once the ballast system has been confirmed ready for operation.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1528, 873, '<p>Scupper plugs were not available on board.</p>', '<p>It is recommended that suitable scupper plugs be provided and maintained on board.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1529, 873, '<p>NTM was not available on board.</p>', '<p>It is recommended that the latest Notice to Mariners (NTM) be made available and maintained on board.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1530, 873, '<p><span xss=removed>The changeover instructions for emergency steering were not available on board.</span></p>', '<p>It is recommended that the emergency steering changeover instructions be provided and maintained on board.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1531, 775, '<p><span xss=removed>Cargo hold bilges were not inspected due to cargo operations.</span></p>', '<p><span data-start="198" data-end="266">Inspect the cargo hold bilges at the next available opportunity.</span></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1532, 775, '<p><span xss=removed>The hose test was not carried out due to cargo operations.</span></p>', '<p>Carry out the hatch cover hose test at the next available opportunity.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1533, 775, '<p><span xss=removed>Scupper plugs were not available on board.</span></p>', '<p>It is recommended to provide suitable scupper plugs on board.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1534, 775, '<p><span xss=removed>Oil absorbents were not available on board.</span></p>', '<p>It is recommended to provide oil absorbents on board.</p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1535, 775, '<p><span xss=removed>NTM was not available on board.</span></p>', '<p>It is recommended that the latest Notices to Mariners (NTM) be maintained on board.</p>', 'Please refer to the attachment', 14, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1536, 874, '<p><span xss=removed>The scupper plug was not available.</span></p>', '<p>The scupper plugs were to be supplied</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1537, 874, '<p><span xss=removed>The bunkering connection valve was found damaged.</span></p>', '<p>The bunkering connection valve must be repaired</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1538, 874, '<p><span xss=removed>The emergency generator was under replacement and was not operational at the time of the survey.</span></p>', '<p>The emergency generator must be repaired / replaced</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1539, 887, '<p>Radar was found inoperative and could not be switched on</p>', '<p>The radar must be repaired until it works properly</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1540, 887, '<p>The vessel was found not equipped with an echo sounder</p>', '<p>The vessel must be equipped with an echo sounder, refer to SOLAS chapter V regulation 19 number 2.3</p>', NULL, 120, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1541, 887, 'SOPEP locker was found not completed with its contents', '<p>The SOPEP locker should be completed with all required equipment and contents</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1542, 887, '<p>The bunkering connections, windlass machinery, and fuel air vents were found not provided with save-alls.</p>', '<p>Provide suitable save-alls for the bunkering connections, windlass machinery, and fuel air vents, as applicable, to prevent oil or fuel leakage.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1543, 887, '<p>Scupper plugs were not available on board</p>', '<p><span xss=removed>The scupper plugs were to be supplied</span></p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1544, 887, '<p>Oil absorbents were not available on board</p>', '<p><span xss=removed>Oil absorbents were to be supplied</span></p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1545, 853, '<p>The Deck Officer such as Shipâs Master, Chieff Officer, and Second Officer hold of ANT IV-M, meanwhile as per Minimum Safe Manning Document issued by the Directorate General of Sea Transportation on July 21, 2026, the minimum the Shipâs Master, Chieff Officer, and Second Officer hold of ANT II.</p>', '<p>To meet requirement as per Minimum Safe Manning document, we recommended the shipâs owner to change the ship''s master and deck officers as soon as posible and/or latest 3 (three) months.</p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1546, 853, '<p>RADAR (s) with ARPA operational was not available on board.Â Â Â Â Â </p>', '<p>The ship''s owner have to equip the navigation equipment with RADAR with ARPA operational.Â </p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1547, 853, '<p>Record of Magnetic Compas Deviation and noted that the last updated on November 24, 2023.</p>', '<p>The ship''s owner must update the Record of Magnetic Compass Deviation.</p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1548, 853, '<p>Berita Pelaut Indonesia (BPI) was not updated.</p>', 'The ship''s owner must have an updated the BPI document and the ship''s crew update the charts.', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1549, 853, '<p>The charts were not an update.</p>', '<p>The deck officer must update the charts as per BPI document.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1550, 853, '<p>The SOPEP box contained Sawdust in bags only.</p>', '<p>The ship''s owner must complete the tools and equipments of SOPEP</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1551, 853, '<ul><li>Bunker connections/station is in slightly dirty condition.</li><li>No marking for bungkering valve and capacity.</li></ul>', '<ul><li>The ship''s crew must clean the bunker connections/station.</li><li>The ship''s crew must mark for the bungkering valve and capacity.</li></ul>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1552, 853, '<p>No marking of fuel air vents and sounding pipes.</p>', '<p>The ship''s crew must mark the fuel air vents and sounding pipes.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1553, 853, '<p>Save-alls of bunker connections/station found slightly dirty.</p>', '<p>The ship''s crew must clean the save-allsÂ <span xss=removed>bunker connections/station.</span></p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1554, 853, '<p>Scupper plugs were not available onboard.</p>', '<p>The ship''s owner must equip the ship with scrupper plugs.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1555, 853, '<p>Oil Absorbents are not available on board.</p>', '<p>The ship''s owner must equip the vessel withÂ <span xss=removed>Oil Absorbents.</span></p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1556, 853, '<ul><li>The holdâs bilge was found contain residual water and remnants of previous cargo.</li><li>The suction test could not be carried out as the bilge line was not functioning.</li></ul>', '<ul><li>The ship''s crew must clean the hold''s bilge.</li><li>The ship''s crew must repair the bilge line and kept maintenance.Â </li></ul>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1557, 943, '<p><span data-path-to-node="3,0,2,0,0,0">Absence of spare parts inventory makes it impossible to verify stock availability for essential machinery maintenance</span><span data-path-to-node="3,0,2,0,0,2"></span></p>', '<p>Conduct a complete physical inventory audit and establish an up-to-date spare parts logbook onboard.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1558, 943, '<p>Maintenance routines have not been logged for several months, risking undetected equipment degradation</p>', '<p>Update all maintenance records immediately and resume regular logging per the vessel''s management system</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1559, 943, '<p>Â Lack of a master PMS list leaves the crew without standard maintenance guidelines and schedules</p>', '<p>Supply the approved PMS master document onboard and brief the engineering team on its implementation</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1560, 943, '<p><span data-path-to-node="12,3,2,0,0,0">Lack of stability tracking jeopardizes safe loading limits and vessel equilibrium</span><span data-path-to-node="12,3,2,0,0,1">-</span><span data-path-to-node="12,3,2,0,0,2">.</span><sources ng-version="0.0.0-PLACEHOLDER" nghost-ng-c4136037586=""></sources></p>', '<p>Calculate trim, list, and draft conditions prior to departure and maintain stability calculation sheets onboard</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1561, 943, '<p>Malfunctioning mooring bollard compromises safe securing during mooring operations</p>', '<p>Inspect foundation, weldments, and fairleads of the aft bollard; repair or reinforce structural anchorage</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1562, 943, '<p><span data-path-to-node="6,3,2,0,0,0">Unverified lifting equipment poses mechanical failure risks during cargo/stores handling</span><span data-path-to-node="6,3,2,0,0,2"></span></p>', '<p>Inspect all lifting gear, obtain valid load test certificates, and maintain a dedicated maintenance register</p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1563, 943, '<p><span data-path-to-node="6,2,2,0,0,0">Insufficient cathodic protection accelerates steel corrosion inside ballast tanks</span><sources ng-version="0.0.0-PLACEHOLDER" nghost-ng-c4136037586=""></sources></p>', '<p>Calculate total required protection area and install additional zinc anodes inside all ballast tanks.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1564, 943, '<p>Severe structural deterioration threatens hull integrity, while blocked access on Tank No. 1 prevents full evaluation</p>', '<p><span data-path-to-node="6,1,2,2,0,0">Relocate heavy items (pipes) to clear Tank No. 1 access</span><span data-path-to-node="6,1,2,2,0,2">Â perform Ultrasonic Thickness Measurement (UTM) and crop/renew defective internal plating and frames</span></p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1565, 943, '<p><span data-path-to-node="6,0,2,0,0,0">Structural damage to deck railings and ladder corrosion create fall hazards for the crew</span><span data-path-to-node="6,0,2,0,0,2"></span></p>', '<p>Straighten or replace bent/missing handrails and treat corrosion on the accommodation ladder with proper coating</p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1566, 943, '<p>Absence of draft records hampers accurate monitoring of vessel loading, stability, and trim</p>', '<p>Provide updated draft tables and maintain daily logging of vessel draft marks.</p>', NULL, 10, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1567, 943, '<p>Accumulated oily water presents a marine pollution risk and violates MARPOL Annex I regulations</p>', '<p>Transfer oily bilge water to slop tanks and process via OWS (<i data-path-to-node="9,5,2,2,0" data-index-in-node="82">Oil Filtering Equipment</i>) or discharge to reception facilities</p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1568, 943, '<p><span data-path-to-node="15,2,2,0,0,0">Active fuel cargo prevented internal structural assessment of cargo tanks</span></p>', '<p>Plan internal tank cleaning and gas-freeing for inspection once cargo discharge is completed</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1569, 943, '<p>Operating machinery without manuals increases the risk of improper maintenance and breakdowns</p>', '<p>Request technical manuals from manufacturers and store complete hard/soft copies in the engine office.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1570, 943, '<p><span data-path-to-node="12,0,2,0,0,0">Lack of emergency power backup poses extreme safety risks during main power failures</span></p>', '<p>Â Install an approved Emergency Generator set connected to the emergency switchboard as required by regulations</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1571, 943, '<p><span data-path-to-node="12,1,2,0,0,0">Without written procedures, crew response during total power loss may be delayed or incorrect</span><sources ng-version="0.0.0-PLACEHOLDER" nghost-ng-c4136037586=""></sources></p>', '<p>Post clear, step-by-step blackout recovery procedures near the main switchboard and bridge.</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1572, 943, '<p><span data-path-to-node="9,2,2,0,0,0">Â Lack of oil samples prevents testing to verify lube oil degradation or mechanical wear</span></p>', '<p>Draw fresh lube oil samples from main/auxiliary engines and send them for laboratory analysis</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1573, 943, '<p><span data-path-to-node="15,1,2,0,0,0">Hull plating below waterline could not be visually evaluated during anchorage survey</span></p>', '<p>Arrange an In-Water Survey (IWS) by certified divers or schedule full inspection during next drydocking</p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1574, 943, '<p><span data-path-to-node="9,10,2,0,0,0">Continuous lube oil leakage causes oil loss, fire hazards, and dirty engine surfaces</span></p>', '<p>Renew damaged packing/gaskets on AE 3 and clean surrounding area.</p>', NULL, 10, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1575, 943, '<p><span data-path-to-node="9,9,2,0,0,0">Absence of a watertight barrier reduces vessel survivability in the event of compartment flooding</span><span data-path-to-node="9,9,2,0,0,2"></span></p>', '<p>Install a certified watertight door meeting class/SOLAS requirements at the engine room bulkhead</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1576, 943, '<p>Direct local control increases noise/heat exposure for duty engineers during operations</p>', '<p>Ensure local control station instrumentation and safety cut-outs are fully functional and well-protected</p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1577, 943, '<p>Active coolant leaks may cause engine overheating or flooding in the lower engine room</p>', '<p>Replace mechanical seals/gaskets on the seawater pump and verify suction/discharge pressures.</p>', NULL, 20, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1578, 943, '<p><span data-path-to-node="9,6,2,0,0,0">Unpurified fuel/lube oil leads to accelerated engine wear, injector damage, and failure risks</span><span data-path-to-node="9,6,2,0,0,2"></span></p>', '<p>Overhaul fuel/lube oil purifiers, replace worn bowls/seals, and test under load.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1579, 943, '<p>Accumulated oily water presents a marine pollution risk and violates MARPOL Annex I regulations</p>', '<p>Transfer oily bilge water to slop tanks and process via OWS (<i data-path-to-node="9,5,2,2,0" data-index-in-node="82">Oil Filtering Equipment</i>) or discharge to reception facilities</p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1580, 943, '<p>Inability to measure operating temperatures prevents early detection of machinery overheating</p>', '<p>Supply calibrated portable/fixed thermometers for critical machinery monitoring points</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1581, 943, '<p><span data-path-to-node="9,0,2,0,0,0">Non-standard pump arrangement may cause excessive vibration damage or maintenance access issues</span><span data-path-to-node="9,0,2,0,0,2"></span></p>', '<p>Verify pump foundation integrity against engine vibration and ensure compliance with maker specifications</p>', NULL, 20, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1582, 943, '<p><span data-path-to-node="9,3,2,0,0,0">Impaired communication between Bridge and Engine Room is a critical operational safety risk</span><span data-path-to-node="9,3,2,0,0,2"></span></p>', '<p>Troubleshoot wiring/handsets and restore reliable internal communication immediately.</p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1583, 943, '<p><span data-path-to-node="12,2,2,0,0,0">Uncalibrated compass data can lead to serious navigational calculation errors</span><sources ng-version="0.0.0-PLACEHOLDER" nghost-ng-c4136037586=""></sources></p>', '<p>Perform compass adjustment by an authorized compass adjuster and issue a valid deviation card.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1584, 943, '<p><span data-path-to-node="5,0,0,0">The cleanliness of the cargo hold is compromised due to oily water accumulation</span><span data-path-to-node="5,0,0,2">, which presents a risk of cargo contamination and indicates inadequate cargo hold bilge management</span></p>', '<p><span data-path-to-node="5,1,0,0">Thoroughly clean, degrease, and dry the cargo hold surfaces and bilges.</span><span data-path-to-node="5,1,0,2">Â Dispose of the oily mixture in compliance with MARPOL regulations before loading the next cargo</span><sources ng-version="0.0.0-PLACEHOLDER" nghost-ng-c4136037586=""></sources></p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1585, 952, 'Charts No. 104 and 103 were found not updated.', 'The charts need to be updated with the latest edition.', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1586, 952, '<p>SOPEP locker was found not completed with its contens.</p>', '<p><span xss=removed>The SOPEP locker should be completed with all required equipment and contents.</span></p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1587, 952, '<p>The bunkering connections, windlass machinery, and fuel air vents were found not provided with save-alls.</p>', '<p><span xss=removed>Provide suitable save-alls for the bunkering connections, windlass machinery, and fuel air vents, as applicable, to prevent oil or fuel leakage.</span></p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1588, 952, '<p>Scupper plugs were not available on board.</p>', '<p><span xss="removed">The scupper plugs to be supplied.</span></p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1589, 952, '<p><span xss="removed">Oil absorbents were not available on board.</span></p>', '<p><span xss="removed">Oil absorbents to be supplied.</span></p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1590, 952, '<p>Ballast tank manhole cover No. 2P was found leaking.</p>', '<p>The ballast tank manhole cover rubber gasket needs to be changed.</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1591, 952, '<p>The rubber gasket of the watertight door was found damaged and missing.</p>', '<p>The watertight door needs to be fitted with a new rubber gasket.</p>', 'Please refer to the attachment', 30, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1592, 905, '<p>Deviation of gyro compass found expire, last adjusted on OctoberÂ <span xss=removed>23, 2021.</span></p>', '<p>The ship''s owner must update the record of gyro compass deviation.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1593, 905, '<p>The telephones in engine room and steering room were not functioningÂ </p>', '<p>The ship''s owner must rectify the function of telephones in engine room and steering roomÂ </p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1594, 905, '<p>The hose test was carried out and found leaking to theÂ <span xss=removed>cargo hold.Â </span></p>', '<p>The ship''s owner must provide the new terpaulin<span xss=removed>Â regularly to avoidÂ </span><span xss=removed>water leakage to cargo hold.</span></p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1595, 905, '<p>Several watertight door marking were not painted.</p>', '<p>The ship''s crew must paint the marking on several watertight doors.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1596, 905, '<p>Oil Absorbents were not available on board.Â </p>', '<p>The ship''s owner must equip the vessel with oil absorbents.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1597, 905, '<p>Scupper plugs were not available onboard.</p>', '<p><span xss=removed>The ship''s owner must equip the vessel with scupper plugs.</span></p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1598, 905, '<p>Save-alls bar plate on mooring winch and windlass on forwardÂ <span xss=removed>found not available.</span></p><div><br></div>', '<p>The ship''s owner must install the save-all bar plate on forward mooring winch and windlass.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1599, 905, '<p>- The marking on Fuel Air Vents were not painted.</p><p>- The wire meshes were missing.</p><p>- Some cover of fuel air vent were missing.Â </p><div><br></div>', '<p>- The ship''s crew must paint the marking on Fuel Air Vents.</p><p>- The ship''s owner and crew must provide and install some wire meshes.Â </p><p>-Â <span xss=removed>The ship''s owner and crew must provide and install</span><span xss=removed>Â s</span><span xss=removed>ome cover of fuel air vents.</span></p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1600, 905, '<p>The markings on bunkering connection were not painted.</p><div><br></div>', '<p>The ship''s crew must paint the marking on bunkering connections.</p><div><br></div>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1601, 905, '<p>SOPEP Locker was marked with âSOPEPâ but withoutÂ <span xss=removed>SOPEP Equipment like Oil absorbent pads/sorbent, Oil boom,Â </span><span xss=removed>Dispersant, Shovel, Bucket, Broom, PPE (Personal ProtectiveÂ </span><span xss=removed>Equipment).</span></p><div><br></div>', '<p>The ship''s owner must complete the tools and equipment of SOPEP.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1602, 905, '<p>Block Diagram Instruction or Emergency Steering OperationalÂ <span xss=removed>Procedure for change procedures from auto to manual steering andÂ </span><span xss=removed>status of the steering gear power units was not displayed on bridge.</span></p><div><br></div>', '<p>The ship''s crew must provide and display the change procedure on the bridge.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1603, 905, '<p>The Shipâs charts had not been updated to the latest availableÂ <span xss=removed>editions, last update in 2014.</span></p>', '<p>The ship''s owner must provide the latest update of chart.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1604, 905, '<p>The Notice to Mariners was not available on board.</p>', '<p>The ship''s owner must provide NTM onboard regularly.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1605, 905, '<p>All ballast tanks were full of water during the empty hold andÂ <span xss=removed>the ballast water was to be discharged and will be removedÂ </span><span xss=removed>once berthing at the port. Accordingly, an internal inspectionÂ </span><span xss=removed>of the ballast tank structures could not be carried out at theÂ </span><span xss=removed>time of our inspection.Â </span></p>', '<div>The internal structure of ballast tanks was not inspected.Â </div><div><br></div>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1606, 630, '<p>Class certificate was found not available on board</p>', '<p>To be provided for review</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1607, 630, '<p>Means of communication of engine room to bridge was found out of order</p>', '<p>To be repaired</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1608, 630, '<ul><li>Save-alls of bunker manifolds were found heavy corroded and holed</li><li>Save-alls were found not fitted at fuel-oil air vents on the port and starboard sides, hydraulic operating handle of hatch covers, aft and forward winch</li></ul>', '<p>To be repaired and fitted</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1609, 630, '<p>Cargo hold bilges (P & S) were found dirty with cargo residue. Suction test has been carried out and found in working order.</p>', '<p>To be cleaned up</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1610, 630, '<ul><li>Hatch cover panels were found rusty</li><li>Almost Packing channels of hatch cover panels were found heavy corroded</li><li>Almost rubber gasket of hatch covers was found missing</li></ul>', '<p>To be chipped/ painted, repaired and fitted</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1611, 630, '<p>Magnetic compass was found bubble and a valid deviation card not available on board</p>', '<p>To be repaired and adjusted</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1612, 630, '<ul><li>Weather tight door of E/R and store outside accommodation were found corroded at lower part</li><li>All weather tight door was found without Open/ Close marking</li></ul>', '<p>To be repaired and marked</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1613, 630, '<p>The latest Notices to Mariners (NTM) were found not available on board, last supplied 20 March 2019</p>', '<p>To be supplied regularly</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1614, 630, '<ul><li>Main deck on the port and starboard side was found rusty, oily and dirty</li><li>Almost hatch coaming structure was found heavy rusty/ corroded</li><li>Hydraulic pipe of anchor winch, hatch covers and derricks were found leakages</li><li>Derrick deck was found oily</li><li>Drums of anchor winch were found heavy rusty</li><li>Forward lower deck (hydraulic pump room) was found flooded with hydraulic oil</li><li>Doubler was found fitted at aft starboard side main deck</li><li>Bulwark at forward area was found partly corroded</li></ul>', '<ul><li>Main deck on the port and starboard side to be cleaned up, chipped and paintedÂ </li><li>Almost hatch coaming structure to be repaired/ chipped and painted</li><li>Hydraulic pipe of anchor winch, hatch covers and derricks to be repaired</li><li>Derrick deck to be cleaned up</li><li>Drums of anchor winch to be chipped and painted</li><li>Forward lower deck (hydraulic pump room) to be cleaned up</li><li>Doubler to be cropped and replated</li><li>Bulwark to be repaired</li></ul>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1615, 630, '<p>The nautical charts had not been corrected using the latest available Notice to Mariners (NTM)</p>', '<p>To be corrected</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1616, 630, '<ul><li>Forward hull was found dented and crack</li><li>Hull was found oil stained on several places</li><li>Hull was found marine growth below water line</li></ul>', '<ul><li>Forward hull to be repaired</li><li>Hull to be cleaned up, scraped/ blasted and painted</li></ul>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1617, 630, '<p>SOPEP locker and equipment were found not available</p>', '<p>To be provided</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1618, 630, '<p>Oil absorbents were found not available</p>', '<p>To be provided</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1619, 630, '<p>Echo sounder was found not available</p>', '<p>To be provided</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1620, 630, '<p>Scupper plugs were found not available</p>', '<p>To be provided</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1621, 630, '<p>One of fuel-oil air vent on port side main deck was found corroded and without vent head</p>', '<p>To be repaired and provided</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1622, 630, '<p>UTM Report was found not available</p>', '<p>To be provided for review</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1623, 630, '<p>Bunker manifolds were found obstructed with foreign materials</p>', '<p>To be cleaned up</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1624, 943, '<p>The internal steel structure and protective coating of the cargo tanks/holds could not be visually inspected during the survey due to the presence of cargo (Fuel Oil & BSO) on board while the vessel was afloat at anchor.</p>', '<p>Perform a full internal visual inspection, thickness measurement (UTM), and coating assessment of all cargo tanks upon completion of cargo discharge and tank cleaning/gas-freeing. Ensure historical drydock and tank inspection reports are kept on board and readily available for verification in the interim.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1625, 943, '<p>Â Internal toe brackets within the cargo tanks could not be verified for structural defects, cracking, or corrosion due to cargo on board and restricted internal access.</p>', '<p>Conduct a close-up internal inspection of all internal cargo tank toe brackets, web frames, and structural connection points once the tanks are empty, cleaned, and certified safe for entry. Any identified structural cracks or severe wastage must be repaired/re-welded in accordance with Classification Society standards.</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1626, 899, '<p><span data-path-to-node="4,1,1,0,0,0">The physical Ultrasonic Thickness (UT) Test certificate was not available onboard as it is held by the head office</span><span data-path-to-node="4,1,1,0,0,2">. This presents an administrative non-compliance during PSC or Vetting inspections.</span></p>', '<p>The head office must immediately send an official printed copy or an attested digital copy of the UT Test Certificate onboard to be kept in the vessel''s documentation file.</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1627, 899, '<p><span data-path-to-node="8,1,1,0,0,0">Â Drip trays / Save-Alls are missing under the bunker manifold piping system</span><span data-path-to-node="8,1,1,0,0,2">. This presents a severe risk of marine oil pollution during bunkering operations (non-compliance under MARPOL Annex I)</span></p>', '<p>Supply and install standard Save-All trays underneath the bunker manifold piping prior to conducting any bunkering or cargo transfer operations.</p>', NULL, 10, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1628, 899, '<p><span data-path-to-node="4,1,1,0,0,0">Â Inspection of the Zinc Anodes could not be performed to determine their wear condition and effectiveness as they were submerged in water</span><sources ng-version="0.0.0-PLACEHOLDER" nghost-ng-c2708753768=""></sources></p>', '<p>Conduct a visual re-inspection of the Zinc Anodes once the water is pumped out to ensure their depletion rate does not exceed 50% and replace them if necessary.</p>', NULL, 120, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1629, 899, '<p><span data-path-to-node="12,1,1,0,0,0">Structural cracks and corrosion were observed on the access ladders from the main deck to the accommodation area on both Port and Starboard sides</span><span data-path-to-node="12,1,1,0,0,2">, posing an immediate personal injury hazard to crew members</span></p>', '<p>Perform rust chipping/grinding, re-weld and gouge the cracked structural members, renew steel or insert doubler plates where necessary, and apply anti-corrosive coating.</p>', NULL, 20, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1630, 899, '<p><span data-path-to-node="16,1,1,0,0,0">The rubber sealing gasket on the Port side Slop Tank manhole cover is missing</span><span data-path-to-node="16,1,1,0,0,2">. This creates a risk of gas vapor leakage, liquid seepage, and ingress of seawater into the tank</span></p>', '<p>Install a new oil-resistant rubber gasket on the Port side Slop Tank manhole cover and securely tighten all cover bolts to restore gas-tight and watertight integrity.</p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1631, 899, '<p><span data-path-to-node="20,1,1,0,0,0">The pressure test gauge/indicator for the ballast tanks is inoperative</span><span data-path-to-node="20,1,1,0,0,2">, preventing accurate monitoring and verification of tank tightness during pressure testing</span></p>', '<p>Repair, recalibrate, or replace the defective pressure indicator with a new, certified, and fully functional gauge</p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1632, 899, '<p>The overall internal structural condition of the ballast tanks (frame thickness, cracks, and corrosion severity) could not be inspected as the tanks were full of ballast water and entry was restricted due to side-mounted manhole covers</p>', '<p>De-ballast the tanks, ventilate to ensure safe entry conditions (Gas-Free Certificate issued), and schedule a follow-up internal inspection to verify the structural integrity of the frames and tank plating</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1633, 899, '<p><span data-path-to-node="8,0,1,0,0,2"><span data-path-to-node="8,1,1,0,0,0" xss=removed>The internal cleanliness of the Slop Tank and its pump suction capability test could not be verified because the tank contained water during the survey</span>.</span></p>', '<p>Empty and dry the Slop Tank, then conduct a functional suction test on the slop pumping system to ensure it is free from blockages and operating normally.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1634, 944, '<p><span data-path-to-node="3,0,1,0,0,0">The Ultrasonic Thickness (UT) gauging certificate is missing onboard, preventing verification of the hull and deck plating thickness compliance with class rules</span></p>', '<p>Conduct a full UT thickness measurement of the hull structure and place the valid original certificate onboard</p>', NULL, 10, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1635, 944, '<p>Nautical publications and Notices to Mariners (NTM) are outdated, posing navigational hazards due to un updated nautical charts</p>', '<p><span data-path-to-node="6,1,1,0,0,0">Obtain and supply the latest weekly/monthly Notices to Mariners onboard and update all relevant navigational charts immediately</span></p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1636, 944, '<p><span data-path-to-node="9,0,1,0,0,0">The depth sounding equipment is malfunctioning, compromising safe navigation in shallow waters and port approaches</span><span data-path-to-node="9,0,1,0,0,2"></span></p>', '<p><span data-path-to-node="9,1,1,0,0,0">Troubleshoot, repair, or replace the Echo Sounder transducer/display unit and verify functionality with a sea trial test</span></p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1637, 944, '<p><span data-path-to-node="12,0,1,0,0,0">Absence of mandatory operational instructions for emergency steering changeover violates SOLAS requirements and risks delayed crew response during steering failure</span></p>', '<p>Post clear, durable, and approved emergency steering changeover instruction diagrams at the steering gear compartment and bridge</p>', NULL, 5, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1638, 944, '<p>Faded identification and minor corrosion on the SOPEP storage locker impair rapid access during an oil spill emergency</p>', 'De rust, repaint, and clearly re-label the SOPEP locker with high-visibility reflective stenciling', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1639, 944, '<p>Missing deck scupper plugs prevent immediate sealing of deck drains during oil transfer operations, breaching MARPOL Annex I</p>', '<p><span data-path-to-node="18,1,1,0,0,0">Supply a complete set of correct-sized mechanical or expandable rubber scupper plugs for all main deck scuppers</span><sources ng-version="0.0.0-PLACEHOLDER" nghost-ng-c1714849028=""></sources></p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1640, 944, '<p>Sand is an unacceptable and non-compliant substitute for approved oil spill response absorbents under the vessel''s SOPEP plan</p>', '<p><span data-path-to-node="21,1,1,0,0,0">Remove sand and replenish the SOPEP locker with approved oil-absorbent pads, rolls, and containment booms</span></p>', NULL, 7, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1641, 944, '<p>Submerged hull anodes prevented assessment of cathodic protection effectiveness against underwater hull corrosion</p>', '<p>Â Inspect zinc anode condition during dry-docking or via underwater diver survey, and renew anodes depleted by more than 50%</p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1642, 944, '<p><span data-path-to-node="24,0,1,0,0,0">Severe structural degradation across main decks, bulwarks, bow/aft railings, accommodation ladder, deck piping, bollards, and winch motor jeopardizes vessel seaworthiness, crew safety, and mooring operations</span></p>', '<p><span data-path-to-node="24,1,1,0,0,0">Perform immediate dry-docking to crop and renew severely thinned/holed plating, repair bulwarks, replace accommodation ladder plates, overhaul bollards/piping, and re-install the starboard winch motor</span><span data-path-to-node="24,1,1,0,0,2"></span></p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1643, 944, '<p>Structural cracks and thinned plates on the upper starboard cargo hold bulkhead compromise transverse bulkhead strength and risk cargo contamination/water ingress</p>', '<p><span data-path-to-node="27,1,1,0,0,0">Crop out cracked and thinned bulkhead plating and weld new insert plates of approved thickness and steel grade</span></p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1644, 944, '<p><span data-path-to-node="30,0,1,0,0,0">Corroded hatch cover plates and damaged or missing rubber packing seals destroy weather-tightness, exposing cargo to sea wash</span><sources ng-version="0.0.0-PLACEHOLDER" nghost-ng-c1714849028=""></sources></p>', '<p><span data-path-to-node="30,1,1,0,0,0">Repair corroded hatch cover plating and completely replace all damaged/missing rubber packing seals followed by a chalk or hose test</span></p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1645, 944, '<p>Severe rust scaling, damaged protective coating, and corroded structural frames in Ballast Tanks No. 3 & 4 weaken internal hull strength. Tanks No. 1, 2, and 5 remained uninspected due to ballast water presence</p>', '<p><span data-path-to-node="33,1,1,0,0,0">De-scale, grit-blast, and re-coat internal structures of Tanks No. 3 & 4. Pump out Tanks No. 1, 2, and 5 to perform complete internal structural inspections</span></p>', NULL, 60, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1646, 944, '<p><span data-path-to-node="36,0,1,0,0,0">An non-operational emergency generator leaves the vessel without emergency power for critical safety, steering, and navigation systems during main power failure</span><sources ng-version="0.0.0-PLACEHOLDER" nghost-ng-c1714849028=""></sources></p>', '<p><span data-path-to-node="36,1,1,0,0,0">Expedite emergency generator repairs, perform load testing, and confirm automatic start and switchboard connection functionality</span><span data-path-to-node="36,1,1,0,0,2"></span></p>', NULL, 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1647, 990, '<p>Officer certificates was not available on board.</p>', '<p>The office certificatesÂ  must be available on board.</p>', NULL, 15, NULL, 'Approve', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1648, 990, '<p>The crew cannot mentionded the date of latest special survey</p>', '<p>The owner must sending the latest date of special survey</p>', NULL, 5, NULL, 'Decline', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1649, 919, '<p><span xss=removed>Stability booklet not available on board.</span></p>', '<p>It is recommended that a valid and approved Stability Booklet be provided and maintained on board</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1650, 919, '<p><span xss=removed>Alarms for engine room bilges was not available on board.</span></p>', '<p>It is recommended that the vessel be provided with a <span data-start="75" data-end="149">properly functioning engine room bilge high-level alarm system/sensors</span></p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1651, 919, '<p><span xss=removed>Stability calculation at the time of departure and on arrival not available on board.</span></p>', '<p>It is recommended that <span data-start="45" data-end="113" xss=removed>stability calculations for both departure and arrival conditions</span> be prepared and maintained on board.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1652, 919, '<p><span xss=removed>Emergency light was not available in the crew accomodation.</span></p>', '<p>It is recommended that <span data-start="45" data-end="111" xss=removed>emergency lighting be provided in the crew accommodation areas</span> and maintained in proper working condition</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1653, 919, '<p><span xss=removed>Escape routes not posted in the crew accomodation.</span></p>', '<p>It is recommended that <span data-start="45" data-end="138">escape route plans be posted in conspicuous locations within the crew accommodation areas.</span></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1654, 919, '&nbsp;Fire hose locker and hose were not in satisfactory conditions.&nbsp;&nbsp;', '<p>It is recommended that the <span data-start="49" data-end="143" xss=removed>fire hose lockers and fire hoses be properly maintained and kept in satisfactory condition</span>, with hoses, nozzles, and spanners properly stowed and readily available for immediate use in case of fire.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1655, 919, '<p><span xss=removed>Black out procedure was not posted on board.</span></p>', '<p>It is recommended that the <span data-start="49" data-end="125" xss=removed>blackout recovery procedure be posted in a conspicuous location on board.</span></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1656, 919, '<p>Emergency fire pump was not available on board.Â Â </p>', '<p>It is recommended that a <span data-start="47" data-end="112" xss=removed>properly functioning emergency fire pump be provided on board</span> and maintained in operational condition</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1657, 919, '<p><span xss=removed>Fire main hydrants in poor condition.</span></p>', '<p>It is recommended that the <span data-start="49" data-end="148">fire main hydrants and fire hoses be properly maintained and restored to satisfactory condition.</span></p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1658, 919, '<p><span xss=removed>Smoke detector alarm was not available on board.</span></p>', '<p>It is recommended that <span data-start="45" data-end="157">smoke detectors and associated alarm systems be provided on board and maintained in proper working condition.</span></p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1659, 919, '<p><span xss=removed>No record for testing steering gear.</span></p>', '<p>It is recommended that <span data-start="45" data-end="158">theÂ test results properly recorded and maintained on board for verification.</span></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1660, 919, '<p><span xss=removed>Insulation mats were not available on board.</span></p>', '<p>It is recommended that <span data-start="45" data-end="142" xss=removed>properly rated electrical insulating mats be provided and maintained in appropriate locations.</span></p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1661, 919, '<p><span xss=removed>Thermometer to measure temperature in the engine room was not available on board.</span></p>', '<p>It is recommended that a <span data-start="47" data-end="102" xss=removed>suitable thermometer be provided in the engine room</span> and maintained in good working condition</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1662, 919, '<p><span xss=removed>The company not issue guidelines on the stowage plans.</span></p>', '<p>It is recommended that the <span data-start="49" data-end="116" xss=removed>company provide clear guidelines for container stowage planning</span>, including relevant procedures and instructions, and ensure that the guidelines are properly communicated and understood by the responsible crew.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1663, 919, '<p><span xss=removed>Emergency lighting in the engine room was not available on board.</span></p>', '<p>It is recommended that <span data-start="45" data-end="98" xss=removed>emergency lighting be provided in the engine room</span> and maintained in proper working condition</p>', NULL, 28, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1664, 919, '<p><span xss=removed>Telephone in engine room was not work properly.</span></p>', '<p>It is recommended that the <span data-start="49" data-end="157" xss=removed>telephone communication system in the engine room be repaired and maintained in proper working condition</span></p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1665, 919, '<p><span xss=removed>Lubricants Oil Analysis record was not available on board.</span></p>', '<p>It is recommended that <span data-start="45" data-end="141">lubricating oil analysis be carried out where applicable for vessels fitted with a sump tank</span>, and the corresponding analysis reports/records be properly maintained on board for monitoring the condition of the lubricating oil and machinery.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1666, 919, '<p><span xss=removed>Record of Calibration of the Lubrication Oil Pressure was not available on board.</span></p>', '<p>It is recommended that the <span data-start="596" data-end="737" data-is-only-node="">lubricating oil pressure sensor be periodically calibrated, where applicable, and the calibration records be properly maintained on board</span></p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1667, 919, '<p><span xss=removed>Manufacturer''s manuals and service bulletins were not available on board.</span></p>', '<p>It is recommended that <span data-start="45" data-end="153" xss=removed>the relevant manufacturer''s manuals and applicable service bulletins be provided and maintained on board</span>, particularly for critical machinery and equipment</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1668, 919, '<p><span xss=removed>No PMS is available on board. Therefore there is no PMS list or reminder system for pending items.</span></p>', '<p>It is recommended that a <span data-start="47" data-end="129" xss=removed>proper Planned Maintenance System &#40;PMS&#41; be established and maintained on board</span>, covering the vesselâs machinery and equipment, with maintenance schedules, completed tasks, and reminders for pending/overdue items properly recorded and monitored.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1669, 919, '<p><span xss=removed>No PMS is available on board. Therefore, overdue maintenance is not tracked through PMS.</span></p>', '<p>It is recommended that a <span data-start="47" data-end="142">Planned Maintenance System &#40;PMS&#41; be implemented to monitor and track maintenance activities.</span></p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1670, 919, '<p><span xss=removed>Planned Maintenance System was not available on board.</span></p>', '<p>It is recommended that a <span data-start="47" data-end="156" xss=removed>Planned Maintenance System &#40;PMS&#41; be established and maintained on board, including all critical equipment</span>, with appropriate maintenance intervals and records to ensure their reliability and operational readiness.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1671, 919, '<p>It is recommended that <span data-start="45" data-end="138">sufficient zinc anodes be installed in the ballast tanks and maintained in good condition.</span></p>', '<p><span xss=removed>Ballast tanks are not fitted with a sufficient number of zinc anode.</span></p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1672, 919, '<p><span xss=removed>The last page of the logbook is not filled out properly</span></p>', '<p>It is recommended that the <span data-start="49" data-end="112" xss=removed>last page of the logbook be properly maintained and updated</span>, including records of accidents, important information regarding the vesselâs condition, spare parts replacement, and other relevant events, as applicable.</p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1673, 919, '<p><span xss=removed>Seals were not available on hatch covers.</span></p>', '<p>It is recommended that <span data-start="45" data-end="118" xss=removed>proper hatch cover seals be provided and maintained in good condition.</span></p>', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1674, 919, '<p><span xss="removed">Emergency power sources were available and working properly. However, emergency lighting not available on board.</span></p>', 'It is recommended that emergency lighting to be provided and maintained in proper working condition', NULL, 21, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1675, 909, '<p>We noted that the Deck Officer such as Shipâs Master hold ofÂ  ANT III, Chieff Officer, and Second Officer hold of ANT V, Chief Engineer holld of ATT IV, Second and Third Engineer hold of ATT V, meanwhile as per Minimum Safe Manning Document issued by the Directorate General of Sea Transportation on May 22, 2026, the minimum the Shipâs Master hold of ATT II, Chieff Officer hold of ANT II, the Chief Engineer hold of ATT III.</p>', '<p><span xss=removed>To meet requirement as per Minimum Safe Manning document, we recommended the shipâs owner to change the ship''s master, chief officer and chief engineer as soon as posible and/or latest 3 (three) months.</span></p>', NULL, 90, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1676, 909, '<ul xss="removed"><li>The cargo hold bilge well are dirty and remain of water.</li><li>Sunction test using portable pump.</li></ul>', '<ul><li>The ship''s crew must cleaned and dried the bilge well.</li><li>The ship''s crew mustcheck and repair the bilge line.Â </li></ul>', 'Cargo hold bilge has been cleaned and dried. Please refer to the attachment', 45, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1677, 909, 'The deviation card is not available.', '<p>The ship''s owner must provied the deviation card on board.</p>', 'Deviation card has been provided. Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1678, 909, '<p>The BPI is not available.</p>', '<p>The ship''s owner have to complete the document.</p>', 'BPI has been provided. Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1679, 909, '<p>There is no record.</p>', '<p>The ship''s owner have to complete the document.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1680, 909, '<p>The cargo hold bilges are dirty and remain of water.</p>', '<p>The ship''s crew have to clean and dry the bilge well.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1681, 909, '<p><span xss=removed>The emergency steering procedure is not available in engine room.</span></p>', '<p>The ship''s owner have to complete the document.</p>', 'Emergency steering procedure has been provided. Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1682, 909, '<p><span xss=removed>The vessel condition is not recorded.</span></p>', '<p>The ship''s crew have to record the vessel condition.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1683, 909, '<p>The charts are not update.</p>', '<p>The ship''s crew have to update the charts as per BPI.</p>', 'Chart has been updated. Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1684, 909, '<p>There is no stability calculation.</p>', '<p>The ship''s crew have to calculate the stabilty prior to departure and arrival.</p>', 'Stability calculation has been provided. Please refer to the attachment', 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1685, 909, '<p><span xss=removed>The thermometer in engine room was broken.</span></p>', '<p>The ship''s owner have to change the thermometer.</p>', 'Thermometer in engine room has been changed. Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1686, 909, '<p><span xss=removed>The passage plan is not available.</span></p>', '<p>The ship''s crew have to make and record a passage plan prior to departure.</p>', 'Passage plan has been provided. Please refer to the attachment', 15, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1687, 909, '<p><span xss=removed>The emergency steering is not available in bridge.</span></p>', '<p>The ship''s owner/crew have to complete the document.</p>', 'Emergency steering procedure has been provided. Please refer to the attachment', 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
