INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1718, 932, '<p>Leakage was observed from the manhole cover gasket during the pressure test.</p>', '<p>The manhole cover gasket must be repaired/replaced.</p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1719, 851, '<p><span xss=removed>Class certificates were not available on board as it was currently being endorsed by BKI for the annual survey.</span></p>', '<p>It is recommended that the updated Class Certificates be obtained from BKI and maintained on board upon completion of the annual survey.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1720, 851, '<p><span xss=removed>Cargo hold bilge was found to be partially flooded with water and a suction test could not be carried out as the bilge water was discharge directly overboard.</span></p>', '<p><div class="z-0 flex min-h-[46px] justify-start"></div><div aria-hidden="true" class="pointer-events-none -mb-px h-px w-full opacity-0"></div></p><div class="flex max-w-full flex-col gap-4 [&>div:has([data-free-thinking-preview-answer=true])+:is(.text-message,.relative:has(>.text-message))]:-mt-2 grow"><div data-message-author-role="assistant" data-message-id="2636ceda-7700-4b5c-adf0-8c958a81bb89" dir="auto" data-message-model-slug="gpt-5-6-mini" class="min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&]:mt-1" data-turn-start-message="true" tabindex="0"><div class="flex w-full flex-col gap-1 empty:hidden"><div class="LR5Y_W_content markdown prose dark:prose-invert wrap-break-word w-full dark markdown-new-styling"><p dir="auto" data-start="0" data-end="107" data-is-last-node="" data-is-only-node="" class="PDq2pG_selectionAnchorContainer"><span data-start="0" data-end="107" data-is-last-node="" data-is-only-node="">It is recommended to carry out a suction test on the cargo hold bilge after the bilge is dry and clean.</span><span aria-hidden="true" class="PDq2pG_selectionAnchor"></span></p></div></div></div></div>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1721, 851, '<p><span xss=removed>SOPEP locker was not available on board.</span></p>', '<p>It is recommended to provide and maintain a designated SOPEP locker complete with its contents on board.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1722, 851, '<p>Oil absorbents were not available on board.Â Â </p>', '<p>It is recommended to provide sufficient oil absorbent materials on board and keep them readily available for use.</p>', NULL, 14, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1723, 970, '<p><span xss="removed">SOPEP locker was found not completed with its contents.</span></p>', '<p><span xss="removed">The SOPEP locker should be completed with all required equipment and contents.</span></p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1724, 970, '<p><span xss="removed">The forward windlass machinery and fuel air vent were not provided with save-alls.</span></p>', '<p><span xss="removed">Provide suitable save-alls for the forward windlass machinery and fuel air vents, as applicable, to prevent oil or fuel leakage.</span></p>', NULL, 75, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1725, 970, '<p><span xss="removed">Oil absorbents were not available on board.</span></p>', '<p><span xss="removed">Oil absorbents were to be supplied.</span></p>', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1726, 970, '<p><span xss=removed>The watertight doors and hatches to the cargo hold were found with partially missing rubber gasket.</span></p>', 'The watertight doors and hatches to the cargo hold should be provided with complete and effective rubber seal arrangement.&nbsp;', NULL, 30, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1727, 970, '<p xss="removed">Doubling Plate was found between cargo hold No. 2 and the engine room.</p><p xss="removed">Doubling Plate was found on the tween deck of cargo hold No. 1.</p><p xss="removed">Small holes were found on the tween deck and the stiffeners of cargo hold No. 1.</p>', '<p>The existing doubling plate should be cropped and removed, and the affected area should be renewed with new steel plating as its original.</p><p>The affected tween deck and stiffeners of cargo hold No. 1 should be cropped and renewed as necessary.</p>', NULL, 75, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1728, 970, '<p xss="removed"><span xss=removed>During the ballast tanks pressure test, leakage was found in the cargo hold No. 1 (on the inner bottom plate and the air vent pipe of ballast No. 1P)</span></p>', '<p>The leakage point in the cargo hold No. 1 on the inner bottom plate and the air vent pipe of ballast No. 1P should be repaired and renewed as necessary to ensure watertight integrity. And the repair areas should be pressure test to confirm the effectiveness.</p>', NULL, 75, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO survey_defects (id, survey_id, explanation, recommendation_rectification, rectification_owner, rectification_time_days, remark_defect, status, source, created_at, updated_at) VALUES (1729, 970, '<p xss="removed">Ballast tanks No. 1P, 1S, 2P, and 2S were found generally corroded with wastages at several places.</p><p xss="removed">The zinc anode in ballast tank No. 1P and 2P were found substantially consumed.</p>', '<p>The ballast tanks No. 1P, 1S, 2P, and 2S that were found corroded and wastages at several places should be cropped and renewed.</p><p>The ballast tanks that were found with substantially consumed zinc anode should be installed with new zinc anode.</p>', NULL, 75, NULL, 'Outstanding', 'hasil_survey', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
